export const PUBLIC_DOMAIN_HYMNS: PublicDomainHymnEntry[] = [{"title": "All People That On Earth Do Dwell", "sectionId": 1, "wordsCredit": "William Kethe, circa 1561, alt", "verses": ["All people that on earth do dwell, sing to the Lord with cheerful voice. Serve him with fear, his praise forth tell, come ye before him and rejoice!", "Know that the Lord is God indeed; Without our aid he did us make; We are His flock, he doth us feed, And for His sheep He doth us take.", "O enter then his gates with praise, Approach with joy his courts unto: Praise, laud, and bless his Name always, For it is seemly so to do.", "For why? The Lord our God is good, His mercy is forever sure: His truth at all times firmly stood, And shall from age to age endure."], "scriptureLinks": [{"label": "Ps 33:1-9", "chapterId": "PSA-33", "verseNumber": 1}, {"label": "1Chr 16:8-14", "chapterId": "1CH-16", "verseNumber": 8}, {"label": "Ps 5:11-12", "chapterId": "PSA-5", "verseNumber": 11}], "musicCredit": "'Old 100th' Genevan Psalter, attr. Louis Bourgeois, c. 1551", "number": 1}, {"title": "For The Beauty Of The Earth", "sectionId": 1, "wordsCredit": "Folliot S. Pierpoint, 1864", "verses": ["For the beauty of the earth For the glory of the skies, For the love which from our birth Over and around us lies. Lord of all, to Thee we raise, This our hymn of grateful praise.", "For the beauty of each hour, Of the day and of the night, Hill and vale, and tree and flow'r, Sun and moon, and stars of light. Lord of all, to Thee we raise, This our hymn of grateful praise.", "For the joy of ear and eye, For the heart and mind's delight, For the mystic harmony Linking sense to sound and sight. Lord of all, to Thee we raise, This our hymn of grateful praise.", "For the joy of human love, Brother, sister, parent, child, Friends on earth and friends above, For all gentle thoughts and mild. Lord of all, to Thee we raise, This our hymn of grateful praise.", "For Thy Church, that evermore Lifteth holy hands above, Off'ring up on every shore Her pure sacrifice of love. Lord of all, to Thee we raise, This our hymn of grateful praise.", "For the martyrs' crown of light, For Thy prophets' eagle eye, For Thy bold confessors' might, For the lips of infancy.", "For Thy virgins' robes of snow, For Thy maiden mother mild, For Thyself, with hearts aglow, Jesu, Victim undefiled.", "For each perfect gift of Thine, To our race so freely given, Graces human and divine, Flowers of earth and buds of Heaven."], "scriptureLinks": [{"label": "Is 6:3", "chapterId": "ISA-6", "verseNumber": 3}, {"label": "Ps 95:1-6", "chapterId": "PSA-95", "verseNumber": 1}, {"label": "Ps 33:1-6", "chapterId": "PSA-33", "verseNumber": 1}], "musicCredit": "'Dix' Conrad Kocher, 1838", "number": 2}, {"title": "Hallelujah, Praise Jehovah, O My Soul", "sectionId": 1, "wordsCredit": "Psalm 146. Translated by United Presbyterian Board of Publication, 1909", "verses": ["Hallelujah, praise Jehovah, O my soul, Jehovah praise; I will sing the glorious praises Of my God through all my days. Put no confidence in princes, Nor for help on man depend; He shall die, to dust returning, And his purposes shall end.", "Happy is the man that chooses Israel's God to be his aid; He is blest whose hope of blessing On the Lord his God is stayed. Heav'n and earth the Lord created, Seas and all that they contain; He delivers from oppression, Righteousness He will maintain.", "Food He daily gives the hungry, Sets the mourning pris'ner free, Raises those bowed down with anguish, Makes the sightless eye to see. Well Jehovah loves the righteous, And the stranger He befriends, Helps the fatherless and widow, Judgment on the wicked sends.", "Hallelujah, praise Jehovah, O my soul, Jehovah praise; I will sing the glorious praises Of my God through all my days. Over all God reigns forever, Through all ages He is King; Unto Him, your God, O Zion, Joyful hallelujahs sing."], "scriptureLinks": [{"label": "Ps 146:1-10", "chapterId": "PSA-146", "verseNumber": 1}], "altTitle": "Hallelujah, Praise Jehovah [Psalm 146]", "musicCredit": "'Ripley (Gregorian)' from a Gregorian Chant", "number": 3}, {"title": "Hark the Sound of Holy Voices", "sectionId": 1, "wordsCredit": "Christopher Wordsworth, 1862", "verses": ["Hark the sound of holy voices, chanting at the crystal sea Halleluia! Halleluia! Halleluia! Lord to Thee. Multitude which none can number, like the stars in glory stand Clothed in white apparel, holding palms of vict'ry in their hand.", "Patriarch and holy prophet, who prepared the way for Christ, King, Apostle, Saint, and Martyr Confessor, Evangelist, Saintly Maiden, godly Matron, Widows who have watched to prayer, Joined in holy concert singing to the Lord of all are there.", "They have come from tribulation, and have washed their robes in Blood, Washed them in the Blood of Jesus; tried they were, and firm they stood; Mocked, imprisoned, stoned, tormented, sawn asunder, slain with sword, They have conquered Death and Satan, by the might of Christ the Lord.", "Marching with Thy Cross their banner they have triumphed following Thee the Captain of Salvation, Thee their Savior and their King; Gladly, Lord, with Thee they suffered; gladly, Lord, with Thee they died; And by death to Life immortal they were born, and glorified.", "Now they reign in heav'nly glory, now they walk in golden light, Now they drink, as from a river, holy bliss and infinite; Love and Peace they taste forever, and all Truth and Knowledge see In the beatific vision of the Blessèd Trinity.", "God of God, the One-begotten, Light of Light, Emmanuel, In whose Body joined together all the saints forever dwell, Pour upon us of Thy fullness, that we may forevermore God the Father, God the Son, and God the Holy Ghost adore."], "scriptureLinks": [{"label": "Rev 7:9-12", "chapterId": "REV-7", "verseNumber": 9}, {"label": "Rev 4:2-11", "chapterId": "REV-4", "verseNumber": 2}, {"label": "Rev 22:1-5", "chapterId": "REV-22", "verseNumber": 1}], "musicCredit": "'O Durchbrecher' Johann Anastasius Freylinghausen, 1704", "number": 4}, {"title": "In His Temple Now Behold Him", "sectionId": 1, "wordsCredit": "verses 1-3, Henry J. Pye, 1851. verse 4, William Cooke, 1853", "verses": ["In His temple now behold Him, See the long expected Lord; Ancient prophets had foretold Him; God has now fulfilled His word. Now to praise Him, His redeemèd Shall break forth with one accord.", "In the arms of her who bore Him, Virgin pure, behold Him lie, While his agèd saints adore Him Ere in faith and hope they die. Hallelujah! Hallelujah! Lo, th'incarnate God most high.", "Jesus, by Thy presentation, Thou, who didst for us endure, Make us see our great salvation, Seal us with Thy promise sure. And present us in Thy glory To Thy Father, cleansed and pure.", "Prince and Author of salvation, Be Thy boundless love our theme! Jesus, praise to Thee be given By the world Thou didst redeem. With the Father and the Spirit, Lord of majesty supreme!"], "scriptureLinks": [{"label": "Lk 2:22-38", "chapterId": "LUK-2", "verseNumber": 22}], "musicCredit": "'Westminster Abbey' Henry Purcell, circa 1692", "number": 5}, {"title": "Isaiah, Mighty Seer, In Days of Old", "sectionId": 1, "wordsCredit": "Martin Luther, 1526 as the Sanctus of the German Mass, after Is 6:1-4. Translation composite", "verses": ["Isaiah, mighty seer, in days of old The Lord of all in Spirit did behold High on a lofty throne, in splendor bright, With flowing train that filled the Temple quite. Above the throne were stately seraphim, Six wings had they, these messengers of Him. With twain they veiled their faces, as was meet, With twain in reverent awe they hid their feet, And with the other twain aloft they soared, One to the other called and praised the Lord: \"Holy is God, the Lord of Sabaoth! Holy is God, the Lord of Sabaoth! Holy is God, the Lord of Sabaoth! Behold, His glory filleth all the earth!\" The beams and lintels trembled at the cry, And clouds of smoke enwrapped the throne on high."], "scriptureLinks": [{"label": "Is 6:1-4", "chapterId": "ISA-6", "verseNumber": 1}, {"label": "Rev 4:8", "chapterId": "REV-4", "verseNumber": 8}], "altTitle": "These Things the Seer Isaiah did Befall or Isaiah 'twas the Prophet", "musicCredit": "'Jesaia Dem Propheten das Geschah' Martin Luther, 1526 in the German Mass", "number": 6}, {"title": "O Day of Rest And Gladness", "sectionId": 1, "wordsCredit": "Christopher Wordsworth, 1862", "verses": ["O day of rest and gladness, o day of joy and light, O balm of care and sadness, most beautiful, most bright: On thee, the high and lowly, through ages joined in tune, Sing holy, holy, holy, to the great God Triune.", "On thee, at the creation, the light first had its birth; On thee, for our salvation, Christ rose from depths of earth; On thee, our Lord, victorious, the Spirit sent from heaven, And thus on thee, most glorious, a triple light was given.", "Thou art a port, protected from storms that round us rise; A garden, intersected with streams of paradise; Thou art a cooling fountain in life's dry, dreary sand; From thee, like Pisgah's mountain, we view our promised land.", "Thou art a holy ladder, where angels go and come; Each Sunday finds us gladder, nearer to heaven, our home; A day of sweet refection, thou art a day of love, A day of resurrection from earth to things above.", "Today on weary nations the heavenly manna falls; To holy convocations the silver trumpet calls, Where Gospel light is glowing with pure and radiant beams, And living water flowing, with soul refreshing streams.", "New graces ever gaining from this our day of rest, We reach the rest remaining to spirits of the blessed. To Holy Ghost be praises, to Father, and to Son; The church her voice upraises to Thee, blessed Three in One."], "scriptureLinks": [{"label": "Ex 20:10", "chapterId": "EXO-20", "verseNumber": 10}, {"label": "Gen 2:2-3", "chapterId": "GEN-2", "verseNumber": 2}, {"label": "Mk 2:23-28", "chapterId": "MRK-2", "verseNumber": 23}], "musicCredit": "'Woodbird' or 'Es Flog Ein Kleins Waldvögelein' traditional German found in \"Memminger Tabulaturbuche\", 17th Century", "number": 7}, {"title": "O Lord of Heav'n and Earth and Sea", "sectionId": 1, "wordsCredit": "Christopher Wordsworth, 1863", "verses": ["O Lord of Heav'n and earth and sea, To Thee all praise and glory be; How shall we show our love to Thee, Who givest all?", "The golden sunshine, vernal air, Sweet flow'rs and fruits, Thy love declare; Where harvests ripen, Thou art there, Who givest all.", "For peaceful homes and healthful days, For all the blessings earth displays, We owe Thee thankfulness and praise, Who givest all.", "Thou didst not spare Thine only Son, But gav'st Him for a world undone, And freely, with that blessèd One, Thou givest all.", "Thou giv'st the Spirit's blessèd dow'r, Spirit of life and love and pow'r, And dost His sev'nfold graces show'r Upon us all.", "For souls redeemed, for sins forgiv'n, For means of grace and hopes of Heav'n, Father, all praise to Thee be giv'n, Who givest all.", "We lose what on ourselves we spend, We have as treasure without end Whatever, Lord, to Thee we lend, Who givest all.", "To Thee, from Whom we all derive Our life, our gifts, our power to give: O may we ever with Thee live, Who givest all."], "scriptureLinks": [{"label": "Acts 14:15", "chapterId": "ACT-14", "verseNumber": 15}, {"label": "Rom 8:32", "chapterId": "ROM-8", "verseNumber": 32}, {"label": "Ps 145:15-19", "chapterId": "PSA-145", "verseNumber": 15}], "musicCredit": "'Es Ist Kein Tag' Johann D. Meyer, 1692", "number": 8}, {"title": "O Lord We Praise Thee", "sectionId": 1, "wordsCredit": "Martin Luther, 1524. Translation composite", "verses": ["O Lord, we praise Thee, bless Thee, and adore Thee, In thanksgiving bow before Thee Thou with Thy body and Thy blood didst nourish Our weak souls that they may flourish: O Lord, have mercy! May Thy body, Lord, born of Mary, That our sins and sorrows did carry, And Thy blood for us plead In all trial, fear, and need: O Lord, have mercy!", "Thy holy body into death was given, Life to win for us in heaven. No greater love than this to Thee could bind us; May this feast thereof remind us! O Lord, have mercy! Lord, Thy kindness did so constrain Thee That Thy blood should bless and sustain me. All our debt Thou hast paid; Peace with God once more is made: O Lord, have mercy.", "May God bestow on us His grace and favor To please Him with our behavior And live as brethren here in love and union Nor repent this blest Communion! O Lord, have mercy! Let not Thy good Spirit forsake us; Grant that heav'nly— minded He make us; Give Thy Church, Lord, to see Days of peace and unity: O Lord, have mercy!"], "scriptureLinks": [{"label": "Ps 51:15", "chapterId": "PSA-51", "verseNumber": 15}, {"label": "1Cor 11:23-26", "chapterId": "1CO-11", "verseNumber": 23}, {"label": "Mt 26:26-28", "chapterId": "MAT-26", "verseNumber": 26}], "altTitle": "May God be Praised Henceforth and Blest Forever or Let God Be Blest", "musicCredit": "'Gott Sei Gelobet und Gebenedeiet' or 'Enchiridion' or 'Gud Være Lovet Evig Nu' traditional German c. 1400 found in Klug's Geistliche Lieder, Wittenberg, 1533", "number": 9}, {"title": "Take My Life And Let It Be", "sectionId": 1, "wordsCredit": "Frances R. Havergal, 1874", "verses": ["Take my life, and let it be consecrated, Lord, to Thee. Take my moments and my days; let them flow in ceaseless praise.", "Take my hands, and let them move at the impulse of Thy love. Take my feet, and let them be swift and beautiful for Thee.", "Take my voice, and let me sing always, only, for my King. Take my lips, and let them be filled with messages from Thee.", "Take my silver and my gold; not a mite would I withhold. Take my intellect, and use every pow'r as Thou shalt choose.", "Take my will, and make it Thine; it shall be no longer mine. Take my heart, it is Thine own; it shall be Thy royal throne.", "Take my love, my Lord, I pour at Thy feet its treasure store. Take myself, and I will be ever, only, all for Thee."], "scriptureLinks": [{"label": "Rom 12:1-2", "chapterId": "ROM-12", "verseNumber": 1}, {"label": "Rom 6:13", "chapterId": "ROM-6", "verseNumber": 13}, {"label": "1Cor 6:20", "chapterId": "1CO-6", "verseNumber": 20}], "musicCredit": "'Mozart' Wolfgang Amadeus Mozart (1756-1791)", "number": 10}, {"title": "The God of Abraham Praise", "sectionId": 1, "wordsCredit": "Daniel ben Judah, circa 1400. Paraphrased by Thomas Olivers, circa 1765", "verses": ["The God of Abr'ham praise, Who reigns enthroned above; Ancient of everlasting days, and God of Love; Jehovah, great I AM! by earth and Heav'n confessed; I bow and bless the sacred Name forever blessed.", "The God of Abr'ham praise, at Whose supreme command From earth I rise and seek the joys at His right hand; I all on earth forsake, its wisdom, fame, and pow'r; And Him my only Portion make, my Shield and Tow'r.", "The God of Abr'ham praise, Whose all sufficient grace Shall guide me all my happy days, in all my ways. He calls a worm His friend, He calls Himself my God! And He shall save me to the end, thro' Jesus' blood.", "He by Himself has sworn; I on His oath depend, I shall, on eagle wings upborne, to Heav'n ascend. I shall behold His face; I shall His pow'r adore, And sing the wonders of His grace forevermore.", "Tho' nature's strength decay, and earth and hell withstand, To Canaan's bounds I urge my way, at His command. The wat'ry deep I pass, with Jesus in my view; And thro' the howling wilderness my way pursue.", "The goodly land I see, with peace and plenty bless'd; A land of sacred liberty, and endless rest. There milk and honey flow, and oil and wine abound, And trees of life forever grow with mercy crowned.", "There dwells the Lord our King, the Lord our righteousness, Triumphant o'er the world and sin, the Prince of peace; On Sion's sacred height His kingdom still maintains, And glorious with His saints in light forever reigns.", "He keeps His own secure, He guards them by His side, Arrays in garments, white and pure, His spotless bride: With streams of sacred bliss, with groves of living joys - With all the fruits of Paradise, He still supplies.", "Before the great Three-One they all exulting stand; And tell the wonders He hath done, through all their land: The list'ning spheres attend, and swell the growing fame; And sing, in songs which never end, the wondrous Name.", "The God Who reigns on high the great archangels sing, And \"Holy, holy, holy!\" cry, \"Almighty King! Who was, and is, the same, and evermore shall be: Jehovah - Father - great I AM, we worship Thee!\"", "Before the Savior's face the ransomed nations bow; O'erwhelmed at His almighty grace, forever new: He shows His prints of love - they kindle to a flame! And sound thro' all the worlds above the slaughtered Lamb.", "The whole triumphant host give thanks to God on high; \"Hail, Father, Son, and Holy Ghost,\" they ever cry. Hail, Abraham's God, and mine! (I join the heav'nly lays,) All might and majesty are Thine, and endless praise."], "scriptureLinks": [{"label": "Ex 3:14-15", "chapterId": "EXO-3", "verseNumber": 14}, {"label": "1Chr 29:18", "chapterId": "1CH-29", "verseNumber": 18}], "musicCredit": "'Yigdal' or 'Leoni' Traditional Hebrew", "number": 11}, {"title": "We Gather Together", "sectionId": 1, "wordsCredit": "Anonymous circa 1597. Translated Theodore Baker, 1894", "verses": ["We gather together to ask the Lord's blessing; He chastens and hastens His will to make known. The wicked oppressing now cease from distressing. Sing praises to His Name; He forgets not His own.", "Beside us to guide us, our God with us joining, Ordaining, maintaining His kingdom divine; So from the beginning the fight we were winning; Thou, Lord, were at our side, all glory be Thine!", "We all do extol Thee, Thou Leader triumphant, And pray that Thou still our Defender will be. Let Thy congregation escape tribulation; Thy Name be ever praised! O Lord, make us free!"], "scriptureLinks": [{"label": "Jn 11:52", "chapterId": "JHN-11", "verseNumber": 52}, {"label": "Jer 10:23-24", "chapterId": "JER-10", "verseNumber": 23}, {"label": "Jer 30:11", "chapterId": "JER-30", "verseNumber": 11}], "musicCredit": "'Kremser' Traditional Dutch circa 1597", "number": 12}, {"title": "A Child of The King", "sectionId": 2, "wordsCredit": "Harriet E. Buell, 1877, alt", "verses": ["My Father is rich in houses and lands, He holdeth the wealth of the world in His hands! Of rubies and diamonds of silver and gold His coffers are full,— He has riches untold.", "My Father's own Son, the Savior of men, Once wander'd o'er earth as the poorest of men, But now He is reigning forever on high, And will give me a home in heaven by and by.", "I once was an outcast stranger on earth, A sinner by choice, and an alien by birth! But I've been adopted, my name's written down,— An heir to a mansion, a robe, and a crown.", "A tent or a cottage, why should I care? They're building a palace for me over there! Tho' exiled from home, yet, still I may sing: All glory to God, I'm the child of a King."], "scriptureLinks": [{"label": "Rom 8:14-17", "chapterId": "ROM-8", "verseNumber": 14}, {"label": "2Cor 5:1-9", "chapterId": "2CO-5", "verseNumber": 1}, {"label": "Jn 14:1-6", "chapterId": "JHN-14", "verseNumber": 1}], "altTitle": "My Father is Rich in Houses and Lands", "musicCredit": "'Binghamton' John Bunnell Sumner, 1877", "refrain": "I'm a child of the King, a child of the King: With Jesus my Savior I'm a child of the King.", "number": 13}, {"title": "A Mighty Fortress Is Our God", "sectionId": 2, "wordsCredit": "Martin Luther, 1529. Translation Frederic Henry Hedge, 1853", "verses": ["A mighty fortress is our God, a bulwark never failing; Our helper He, amid the flood of mortal ills prevailing: For still our ancient foe doth seek to work us woe; His craft and pow'r are great, and, armed with cruel hate, On earth is not his equal.", "Did we in our own strength confide, our striving would be losing; Were not the right Man on our side, the Man of God's own choosing: Dost ask who that may be? Christ Jesus, it is He; Lord Sabaoth, His name, from age to age the same, And He must win the battle.", "And though this world, with devils filled, should threaten to undo us, We will not fear, for God hath willed His truth to triumph through us: The Prince of Darkness grim, we tremble not for him; His rage we can endure, for lo, his doom is sure, One little word shall fell him.", "That word above all earthly pow'rs, no thanks to them, abideth; The Spirit and the gifts are ours through Him who with us sideth: Let goods and kindred go, this mortal life also; The body they may kill: God's truth abideth still, His kingdom is forever."], "scriptureLinks": [{"label": "2Sam 22:2-3", "chapterId": "2SA-22", "verseNumber": 2}, {"label": "Ps 18:1-2", "chapterId": "PSA-18", "verseNumber": 1}, {"label": "1Cor 15:55-57", "chapterId": "1CO-15", "verseNumber": 55}], "musicCredit": "'Ein Feste Burg (Isorhythmic)' Martin Luther, 1529", "number": 14}, {"title": "A Mighty Fortress Is Our God", "sectionId": 2, "wordsCredit": "Martin Luther, 1529. Translation composite circa 1868 Pennsylvania Lutheran Church Book", "verses": ["A mighty Fortress is our God, A trusty Shield and Weapon; He helps us free from every need That hath us now o'ertaken. The old evil Foe Now means deadly woe; Deep guile and great might Are his dread arms in fight; On Earth is not his equal.", "With might of ours can naught be done, Soon were our loss effected; But for us fights the Valiant One, Whom God Himself elected. Ask ye, Who is this? Jesus Christ it is. Of Sabaoth Lord, And there's none other God; He holds the field forever.", "Though devils all the world should fill, All eager to devour us. We tremble not, we fear no ill, They shall not overpower us. This world's prince may still Scowl fierce as he will, He can harm us none, He's judged; the deed is done; One little word can fell him.", "The Word they still shall let remain Nor any thanks have for it; He's by our side upon the plain With His good gifts and Spirit. And take they our life, Goods, fame, child and wife, Let these all be gone, They yet have nothing won; The Kingdom ours remaineth."], "scriptureLinks": [{"label": "2Sam 22:2-3", "chapterId": "2SA-22", "verseNumber": 2}, {"label": "Ps 18:1-2", "chapterId": "PSA-18", "verseNumber": 1}, {"label": "1Cor 15:55-57", "chapterId": "1CO-15", "verseNumber": 55}], "musicCredit": "'Ein Feste Burg (Rhythmic)' Martin Luther, 1529", "number": 15}, {"title": "Almighty God Your Word Is Cast", "sectionId": 2, "wordsCredit": "John Cawood, 1816", "verses": ["Almighty God, Your Word is cast Like seed into the ground; Now let the dew of Heav'n descend, And righteous fruits abound.", "Let not the foe of Christ and man This holy seed remove, But give it root in ev'ry heart To bring forth fruits of love.", "Let not the world's deceitful cares The rising plant destroy. But let it yield a hundredfold The fruits of peace and joy.", "Nor let Your Word so kindly sent To raise us to Your throne Return to You, and sadly tell That we reject Your Son.", "Oft as the precious seed is sown, Your quick'ning grace bestow, That all whose souls the truth receive, Its saving power may know.", "Great God, come down and on Your Word Your mighty power bestow, That all who hear the joyful sound, Your saving grace may know."], "scriptureLinks": [{"label": "Lk 8:4-15", "chapterId": "LUK-8", "verseNumber": 4}, {"label": "Mk 4:3-8", "chapterId": "MRK-4", "verseNumber": 3}, {"label": "Mt 13:3-9", "chapterId": "MAT-13", "verseNumber": 3}], "musicCredit": "'St. Anne' William Croft, 1708", "number": 16}, {"title": "Come, Thou Almighty King", "sectionId": 2, "wordsCredit": "Anonymous, 1757", "verses": ["Come, Thou almighty King, Help us Thy Name to sing, Help us to praise! Father all glorious O'er all victorious, Come and reign over us, Ancient of days!", "Come, Thou Incarnate Word, Gird on Thy mighty sword; Our prayer attend! Come, and Thy people bless; Come give Thy Word success; 'Stablish Thy righteousness, Savior and Friend!", "Come Holy Comforter, Thy sacred witness bear, In this glad hour! Thou who almighty art, Now rule in every heart, And ne'er from us depart, Spirit of pow'r!", "To Thee, great One in Three, The highest praises be, Hence evermore; Thy sovereign majesty May we in glory see, And to eternity Love and adore."], "scriptureLinks": [{"label": "Rev 22:6", "chapterId": "REV-22", "verseNumber": 6}, {"label": "1Tim 6:15-16", "chapterId": "1TI-6", "verseNumber": 15}, {"label": "Jn 1:14", "chapterId": "JHN-1", "verseNumber": 14}], "musicCredit": "'Italian Hymn' Felice de Giardini, 1769", "number": 17}, {"title": "God the Father Be Our Stay", "sectionId": 2, "wordsCredit": "15th Century Litany, adapted by Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["God the Father, be our Stay, When hell's dread pow'rs assail us; Cleanse us from our sins, we pray, Nor in our last hour fail us.", "Jesus Christ be Thou our Stay, When hell's dread pow'rs assail us; Cleanse us from our sins, we pray, Nor in our last hour fail us.", "Holy Ghost, be Thou our Stay, When hell's dread pow'rs assail us; Cleanse us from our sins, we pray, Nor in our last hour fail us.", "1(alt).~Triune God, be Thou our Stay, When hell's dread pow'rs assail us; Cleanse us from our sins, we pray, Nor in our last hour fail us."], "scriptureLinks": [{"label": "Mt 6:7-13", "chapterId": "MAT-6", "verseNumber": 7}, {"label": "Ps 31:1-3", "chapterId": "PSA-31", "verseNumber": 1}, {"label": "Eph 6:10-17", "chapterId": "EPH-6", "verseNumber": 10}], "altTitle": "God the Father With Us Stay or God the Father With Us Be", "musicCredit": "'Gott Der Vater, Wohn Uns Bei' from Walter's Geistliche Gesangbüchlein, 1524", "refrain": "Keep us from the Evil One; Firm in the faith abiding, In Christ our Savior hiding, And heartily confiding. Let us put God's armor on: With all true Christians running Our heav'nly race and shunning The devil's wiles and cunning. Amen, Amen, this be done, So sing we, Hallelujah!", "number": 18}, {"title": "God, Whose Almighty Word", "sectionId": 2, "wordsCredit": "John Marriott, 1813", "verses": ["God, whose almighty word Chaos and darkness heard And took their flight: Hear us, we humble pray, And where the Gospel day Sheds not its glorious ray, Let there be light!", "Lord, who once came to bring, On your redeeming wing, Healing and sight, Health to the sick in mind, Sight to the inly blind: Oh, now to humankind Let there be light!", "Spirit of truth and love, Life giving, holy dove, Speed forth your flight; Move on the water's face, Bearing the lamp of grace, And in earth's darkest place Let there be light!", "Holy and blessed three, Glorious Trinity, Wisdom, love, might! Boundless as ocean's tide, Rolling in fullest pride, Through the earth, far and wide, Let there be light!"], "scriptureLinks": [{"label": "Mt 4:16", "chapterId": "MAT-4", "verseNumber": 16}, {"label": "Mt 10:26-27", "chapterId": "MAT-10", "verseNumber": 26}, {"label": "Jn 1:4-5", "chapterId": "JHN-1", "verseNumber": 4}], "musicCredit": "'Italian Hymn' Felice de Giardini, 1769", "number": 19}, {"title": "How Can I Keep from Singing?", "sectionId": 2, "wordsCredit": "unclear whether anonymous Quaker text or F. J. Hartley before 1869 or Robert Lowry, 1869", "verses": ["My life flows on in endless song; Above earth's lamentation. I catch the sweet, though faroff hymn that hails a new creation; Through all the tumult and the strife, I hear that music ringing; It finds an echo in my soul... How can I keep from singing?", "What though my joys and comforts die? The Lord my Savior liveth; What though the darkness gather round? Songs in the night he giveth; No storm can shake my inmost calm, While to that refuge clinging; Since Christ is Lord of heav'n and earth, How can I keep from singing?", "I lift my eyes; the cloud grows thin; I see the blue above it; And day by day this pathway smooths, since first I learned to love it; The peace of Christ makes fresh my heart, a fountain ever springing; All things are mine since I am His... How can I keep from singing?"], "scriptureLinks": [{"label": "Ps 71:22-24", "chapterId": "PSA-71", "verseNumber": 22}, {"label": "Ps 57:7-11", "chapterId": "PSA-57", "verseNumber": 7}, {"label": "Ps 5:11-12", "chapterId": "PSA-5", "verseNumber": 11}], "altTitle": "My Life Flows On in Endless Song", "musicCredit": "'How Can I Keep from Singing' or 'Endless Song' or 'Singing' or 'My Life Flows On' Robert Lowry, 1869", "number": 20}, {"title": "I'm But A Stranger Here", "sectionId": 2, "wordsCredit": "Thomas Rawson Taylor, 1836", "verses": ["I'm but a stranger here, Heav'n is my home; Earth is a desert drear, Heav'n is my home. Danger and sorrow stand round me on every hand; Heav'n is my fatherland, Heav'n is my home.", "What though the tempest rage, Heav'n is my home; Short is my pilgrimage, Heav'n is my home; Time's wild and wintry blast soon shall be over past; I shall reach home at last, Heav'n is my home.", "There at my Savior's side Heav'n is my home; I shall be glorified, Heav'n is my home. There are the good and blest, those I loved most and best; There, too, I soon shall rest, Heav'n is my home.", "Therefore I murmur not, Heav'n is my home; Whate'er my earthly lot, Heav'n is my home; And I shall surely stand there at my Lord's right hand. Heav'n is my fatherland, Heav'n is my home."], "scriptureLinks": [{"label": "Heb 11:16", "chapterId": "HEB-11", "verseNumber": 16}, {"label": "2Cor 5:1-10", "chapterId": "2CO-5", "verseNumber": 1}, {"label": "Jn 14:1-7", "chapterId": "JHN-14", "verseNumber": 1}], "musicCredit": "'St. Edmund (Sullivan)' Arthur Seymour Sullivan, 1872", "number": 21}, {"title": "Let Children Hear The Mighty Deeds", "sectionId": 2, "wordsCredit": "Isaac Watts, 1719", "verses": ["Let children hear the mighty deeds Which God performed of old; Which in our younger years we saw, And which our fathers told.", "He bids us make His glories known, His works of pow'r and grace; And we'll convey His wonders down Through every rising race.", "Our lips shall tell them to our sons, And they again to theirs; That generations yet unborn May teach them to their heirs.", "Thus shall they learn in God alone Their hope securely stands, That they may ne'er forget His work But practice His commands."], "scriptureLinks": [{"label": "Ps 78:5-8", "chapterId": "PSA-78", "verseNumber": 5}, {"label": "Deut 4:9-10", "chapterId": "DEU-4", "verseNumber": 9}, {"label": "Deut 6:7", "chapterId": "DEU-6", "verseNumber": 7}], "musicCredit": "'Lea' James Lea Summers, (1837-1881)", "number": 22}, {"title": "Lord of Life, All Praise Excelling", "sectionId": 2, "wordsCredit": "Clement C. Moore, 1808", "verses": ["Lord of life, all praise excelling, Thou, in glory unconfined, Deignst to make Thy humble dwelling With the poor of humble mind. As Thy love, through all creation, Beams like Thy diffusive light; So the high and humble station Both are equal in Thy sight.", "Thus Thy care, for all providing, Warmed Thy faithful prophet's tongue; Who, the lot of all deciding, To Thy chosen Israel sung. When Thy harvest yields Thee pleasure, Thou the golden sheaf shalt bind; To the poor belongs the treasure Of the scattered ears behind.", "Still we read Thy Word declaring Mercy, Lord, Thine own decree; Mercy ev'ry sorrow sharing, Warms the heart resembling Thee. Still the orphan and the stranger, Still the widow owns Thy care; Screened by Thee in ev'ry danger, Heard by Thee in ev'ry prayer."], "scriptureLinks": [{"label": "Mt 5:2-12", "chapterId": "MAT-5", "verseNumber": 2}, {"label": "Lk 6:20-23", "chapterId": "LUK-6", "verseNumber": 20}, {"label": "Ps 68:4-5", "chapterId": "PSA-68", "verseNumber": 4}], "musicCredit": "'HyFrydol' Rowland H. Prichard, 1830", "number": 23}, {"title": "Now the Light Has Gone Away", "sectionId": 2, "wordsCredit": "Frances Ridley Havergal, 1869", "verses": ["Now the light has gone away; Father, listen while I pray, Asking Thee to watch and keep And to send me quiet sleep.", "Jesus, Savior, wash away All that has been wrong today; Help me every day to be Good and gentle, more like Thee.", "Let my near and dear ones be Always near and dear to Thee. Oh, bring me and all I love To Thy happy home above.", "Now my evening praise I give; Thou didst die that I might live. All my blessings come from Thee; Oh, how good Thou art to me!", "Thou, my best and kindest Friend, Thou wilt love me to the end. Let me love Thee more and more, Always better than before."], "scriptureLinks": [{"label": "Ps 4:8", "chapterId": "PSA-4", "verseNumber": 8}, {"label": "Ps 16:7", "chapterId": "PSA-16", "verseNumber": 7}, {"label": "1 Jn 1:7-9", "chapterId": "1JN-1", "verseNumber": 7}], "musicCredit": "'Müde bin ich, geh zur Ruh' from Liederbuch für Kleinkinder-Schulen, 1842", "number": 24}, {"title": "O Father, All Creating", "sectionId": 2, "wordsCredit": "John Ellerton, 1876", "verses": ["O Father, all creating, Whose wisdom, love, and pow'r First bound two lives together In Eden's primal hour, Today to these Thy children Thy earliest gifts renew: A home by Thee made happy, A love by Thee kept true.", "O Savior, Guest most bounteous Of old in Galilee, Vouchsafe today Thy presence With these who call on Thee; Their store of earthly gladness Transform to heav'nly wine, And teach them, in the tasting To know the gift is Thine.", "O Spirit of the Father, Breathe on them from above, So mighty in Thy pureness, So tender in Thy love; That, guarded by Thy presence, From sin and strife kept free, Their lives may own Thy guidance, Their hearts be rul'd by Thee.", "Except Thou build it, Father, The house is built in vain; Except Thou, Savior, bless it, The joy will turn to pain; But naught can break the union Of hearts in Thee made one, And love Thy Spirit hallow'd Is endless love begun."], "scriptureLinks": [{"label": "Gen 2:18-25", "chapterId": "GEN-2", "verseNumber": 18}, {"label": "Jn 2:1-12", "chapterId": "JHN-2", "verseNumber": 1}, {"label": "Mal 2:15", "chapterId": "MAL-2", "verseNumber": 15}], "musicCredit": "'Aurelia' Samuel Sebastian Wesley, 1864", "number": 25}, {"title": "Of The Father's Love Begotten", "sectionId": 2, "wordsCredit": "Aurelius Prudentius Clemens, 5th Century. Verses 1, 4-8 translated by John Mason Neale, 1854. Verses 2-3, 9 translated by Henry Williams Baker, 1859", "verses": ["Of the Father's love begotten Ere the worlds began to be, He is Alpha and Omega, He the source, the ending He, Of the things that are, that have been, And that future years shall see, Evermore and evermore!", "At His Word they were created; He commanded; it was done: Heav'n and earth and depths of ocean In their threefold order one; All that grows beneath the shining Of the moon and burning sun, Evermore and evermore!", "He is found in human fashion, Death and sorrow here to know, That the race of Adam's children, Doomed by law to endless woe, May not henceforth die and perish In the dreadful gulf below, Evermore and evermore!", "Oh that birth forever blessèd! When the virgin, full of grace, By the Holy Ghost conceiving, Bare the Savior of our race; And the Babe, the world's Redeemer, First revealed His sacred face, Evermore and evermore!", "O ye heights of heav'n adore Him; Angel hosts, His praises sing; Pow'rs, dominions, bow before Him, and extol our God and King: Let no tongue on earth be silent, Every voice in concert ring, Evermore and evermore!", "He is here, Whom seers in old time Chanted of, while ages ran; Whom the writings of the prophets Promised since the world began: Then foretold, now manifested, to receive the praise of man, Evermore and evermore!", "Righteous Judge of souls departed, Righteous King of them that live, On the Father's throne exalted None in might with Thee may strive; Who at last in vengeance coming Sinners from Thy face shalt drive, Evermore and evermore!", "Thee let old men, Thee let young men, Thee let choirs of infants sing; Thee the matrons and the virgins, And the children answering: Let their guileless songs re-echo, And the heart its music bring, Evermore and evermore!", "Christ, to Thee with God the Father, And, O Holy Ghost, to Thee, Hymn and chant with high thanksgiving, And unwearied praises be: Honor, glory, and dominion, And eternal victory, Evermore and evermore!"], "scriptureLinks": [{"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Acts 13:32-39", "chapterId": "ACT-13", "verseNumber": 32}, {"label": "Rev 1:8", "chapterId": "REV-1", "verseNumber": 8}], "musicCredit": "'Divinum Mysterium' or 'Corde Natus' Latin Plainsong, 13th Century", "number": 26}, {"title": "Of The Father's Love Begotten", "sectionId": 2, "wordsCredit": "Aurelius Prudentius Clemens, 5th Century. Verses 1, 4-8 translated by John Mason Neale, 1854. Verses 2-3, 9 translated by Henry Williams Baker, 1859", "verses": ["Of the Father's love begotten Ere the worlds began to be, He is Alpha and Omega, He the source, the ending He, Of the things that are, that have been, And that future years shall see, Evermore and evermore!", "At His Word they were created; He commanded; it was done: Heav'n and earth and depths of ocean In their threefold order one; All that grows beneath the shining Of the moon and burning sun, Evermore and evermore!", "He is found in human fashion, Death and sorrow here to know, That the race of Adam's children, Doomed by law to endless woe, May not henceforth die and perish In the dreadful gulf below, Evermore and evermore!", "Oh that birth forever blessèd! When the virgin, full of grace, By the Holy Ghost conceiving, Bare the Savior of our race; And the Babe, the world's Redeemer, First revealed His sacred face, Evermore and evermore!", "O ye heights of heav'n adore Him; Angel hosts, His praises sing; Pow'rs, dominions, bow before Him, and extol our God and King: Let no tongue on earth be silent, Every voice in concert ring, Evermore and evermore!", "He is here, Whom seers in old time Chanted of, while ages ran; Whom the writings of the prophets Promised since the world began: Then foretold, now manifested, to receive the praise of man, Evermore and evermore!", "Righteous Judge of souls departed, Righteous King of them that live, On the Father's throne exalted None in might with Thee may strive; Who at last in vengeance coming Sinners from Thy face shalt drive, Evermore and evermore!", "Thee let old men, Thee let young men, Thee let choirs of infants sing; Thee the matrons and the virgins, And the children answering: Let their guileless songs re-echo, And the heart its music bring, Evermore and evermore!", "Christ, to Thee with God the Father, And, O Holy Ghost, to Thee, Hymn and chant with high thanksgiving, And unwearied praises be: Honor, glory, and dominion, And eternal victory, Evermore and evermore!"], "scriptureLinks": [{"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Acts 13:32-39", "chapterId": "ACT-13", "verseNumber": 32}, {"label": "Rev 1:8", "chapterId": "REV-1", "verseNumber": 8}], "musicCredit": "'Divinum Mysterium (Isorythmic)' or 'Corde Natus (Isorythmic)' or 'Corde Natus No. 2'Latin Plainsong, 13th Century", "number": 27}, {"title": "Praise To The Lord, The Almighty", "sectionId": 2, "wordsCredit": "Joachim Neander, 1680. Translated by Catherine Winkworth, 1863", "verses": ["Praise to the Lord, the Almighty, the King of creation! O my soul, praise Him, for He is thy health and salvation! All ye who hear, now to His temple draw near; Praise Him in glad adoration.", "Praise to the Lord, Who o'er all things so wondrously reigneth, Shelters thee under His wings, yea, so gently sustaineth! Hast thou not seen how thy desires have been Granted in what He ordaineth", "Praise to the Lord, Who hath fearfully, wondrously, made thee; Health hath vouchsafed and, when heedlessly falling, hath stayed thee. What need or grief ever hath failed of relief? Wings of His mercy did shade thee.", "Praise to the Lord, Who doth prosper thy work and defend thee; Surely His goodness and mercy here daily attend thee. Ponder anew what the Almighty can do, If with His love He befriend thee.", "Praise to the Lord, Who, when tempests their warfare are waging, Who, when the elements madly around thee are raging, Biddeth them cease, turneth their fury to peace, Whirlwinds and waters assuaging.", "Praise to the Lord, Who, when darkness of sin is abounding, Who, when the godless do triumph, all virtue confounding, Sheddeth His light, chaseth the horrors of night, Saints with His mercy surrounding.", "Praise to the Lord, O let all that is in me adore Him! All that hath life and breath, come now with praises before Him. Let the Amen sound from His people again, Gladly for aye we adore Him."], "scriptureLinks": [{"label": "Ps 150:1-2", "chapterId": "PSA-150", "verseNumber": 1}, {"label": "Ps 23:6", "chapterId": "PSA-23", "verseNumber": 6}], "musicCredit": "'Lobe den Herren' from Ander Theil des Erneuerten Gesangbuch, 1665", "number": 28}, {"title": "The Lord's My Shepherd", "sectionId": 2, "wordsCredit": "Psalm 23 from the Scottish Psalter, 1650 alt. by James Leith Macbeth Bain, 1915", "verses": ["The Lord's my shepherd I'll not want, He makes me down to lie In pastures green He leadeth me The quiet waters by. He leadeth me, He leadeth me, The quiet waters by, In pastures green He leadeth me The quiet waters by.", "My soul He doth restore again, And me to walk doth make. Within the paths of blessedness, E'en for His Own Name's sake; His Own Name's sake, His Own Name's sake, E'en for His Own Name's sake; Within the paths of blessedness, E'en for His Own Name's sake.", "Yea, though I walk in death's dark vale, Yet will I fear no ill, For Thou art with me, and Thy rod And staff me comfort still; I'll fear no ill, I'll fear no ill, Yet will I fear no ill, For Thou art with me, and Thy rod And staff me comfort still.", "My table Thou hast furnished well In presence of my foes; My head Thou dost with oil anoint, And my cup overflows; It overflows, It overflows, And my cup overflows; My head Thou dost with oil anoint, And my cup overflows.", "Goodness and mercy all my days Will surely follow me: And in my Father's heart always My dwelling place shall be; My dwelling place, My dwelling place, My dwelling place shall be, And in my Father's heart always My dwelling place shall be."], "scriptureLinks": [{"label": "Ps 23:1-6", "chapterId": "PSA-23", "verseNumber": 1}, {"label": "Jn 10:11-15", "chapterId": "JHN-10", "verseNumber": 11}, {"label": "Rev 7:17", "chapterId": "REV-7", "verseNumber": 17}], "musicCredit": "'Marosa' or 'Brother James` Air' James Leith Macbeth Bain, 1915, alt", "number": 29}, {"title": "Within the Father's House", "sectionId": 2, "wordsCredit": "James Russell Woodford, 1863", "verses": ["Within the Father's house The Son hath found His home; And to His temple suddenly The Lord of Life hath come.", "The doctors of the law Gaze on the wondrous child, And marvel at His gracious words Of wisdom undefiled.", "Yet not to them is giv'n The mighty truth to know, To lift the fleshly veil which hides Incarnate God below.", "The secret of the Lord Escapes each human eye, And faithful pond'ring hearts await The full epiphany.", "Lord, vis-it Thou our souls, And teach us by Thy grace Each dim revealing of Thyself With loving awe to trace;", "Till from our darkened sight The cloud shall pass away, And on the cleansèd soul shall burst The everlasting day.", "Till we behold Thy face, And know, as we are known, Thee, Father, Son, and Holy Ghost, Co-equal Three in One."], "scriptureLinks": [{"label": "Lk 2:41-51", "chapterId": "LUK-2", "verseNumber": 41}, {"label": "Mal 3:1", "chapterId": "MAL-3", "verseNumber": 1}, {"label": "Jn 2:17", "chapterId": "JHN-2", "verseNumber": 17}], "musicCredit": "'Franconia' Johann Balthasar König, 1738", "number": 30}, {"title": "'Take Up Thy Cross', the Savior Said", "sectionId": 3, "wordsCredit": "Charles W. Everest, 1833", "verses": ["\"Take up thy cross,\" the Savior said, \"If thou wouldst My disciple be; Deny thyself, the world forsake, And humbly follow after Me.\"", "Take up thy cross, let not its weight Fill thy weak spirit with alarm; His strength shall bear thy spirit up, And brace thy heart and nerve thine arm.", "Take up thy cross, nor heed the shame, Nor let thy foolish pride rebel; Thy Lord for thee the cross endured, And saved thy soul from death and hell.", "Take up thy cross then in His strength, And calmly sin's wild deluge brave, 'Twill guide thee to a better home, It points to glory o'er the grave.", "Take up thy cross and follow Christ, Nor think til death to lay it down; For only those who bear the cross May hope to wear the glorious crown.", "To Thee, great Lord, the One in Three, All praise forevermore ascend: O grant us in our home to see The heavenly life that knows no end."], "scriptureLinks": [{"label": "Mk 8:34", "chapterId": "MRK-8", "verseNumber": 34}, {"label": "Mt 11:28-30", "chapterId": "MAT-11", "verseNumber": 28}], "musicCredit": "'Nun Lasst Uns Den Leib Begraben' George Rhau, 1544", "number": 31}, {"title": "A Hymn of Glory Let Us Sing", "sectionId": 3, "wordsCredit": "The Venerable Bede, 735. Translation composite of Elizabeth Rundle Charles, 1858 and Benjamin Webb, 1854", "verses": ["A hymn of glory let us sing! New hymns throughout the world shall ring: Alleluia! Alleluia! Christ by a way none ever trod, Ascends unto the throne of God.", "The angels say to the elev'n, \"Why stand ye gazing into heav'n?\" Alleluia! Alleluia! This is the Savior This is He! Jesus has triumphed gloriously.", "Again shall ye behold Him so As ye today have seen Him go; Alleluia! Alleluia! Calm soaring through the radiant sky, Mounting its dazzling summits high.", "May our affections there do tend, And with unwearied hearts ascend, Alleluia! Alleluia! Toward Thy kingdom's throne where Thou As in our faith are seated now.", "Be Thou our present joy O Lord! Who will be ever our reward, Alleluia! Alleluia! And, as the countless ages flee, May all our glory be in Thee!", "O risen Christ ascended Lord. All praise to Thee let earth accord, Alleluia! Alleluia! Who are while endless ages run, With Father and with Spirit One."], "scriptureLinks": [{"label": "Acts 1:10-11", "chapterId": "ACT-1", "verseNumber": 10}], "altTitle": "Sing We Triumphant Hymns of Praise", "musicCredit": "'Lasst Uns Erfreuen' from Geistliche Kirchengesäng, Köln, 1623", "refrain": "Alleluia! Alleluia! Alleluia! Alleluia! Alleluia!", "number": 32}, {"title": "All Glory, Laud, and Honor", "sectionId": 3, "wordsCredit": "Theodulf of Orleans, circa 820. Translated by John Mason Neale, 1851", "verses": ["All glory, laud and honor, To Thee, Redeemer, King, To Whom the lips of children Made sweet hosannas ring. 1. Thou art the King of Israel, Thou David's royal Son, Who in the Lord's Name com est, The King and Blessed One.", "All glory, laud and honor, To Thee, Redeemer, King, To Whom the lips of children Made sweet hosannas ring. 2. The company of angels Are praising Thee on High, And mortal men and all things Created make reply.", "All glory, laud and honor, To Thee, Redeemer, King, To Whom the lips of children Made sweet hosannas ring. 3. The people of the Hebrews With palms before Thee went; Our prayer and praise and anthems Before Thee we present.", "All glory, laud and honor, To Thee, Redeemer, King, To Whom the lips of children Made sweet hosannas ring. 4. To Thee, before Thy passion, They sang their hymns of praise; To Thee, now high exalt ed, Our melody we raise.", "All glory, laud and honor, To Thee, Redeemer, King, To Whom the lips of children Made sweet hosannas ring. 5. Thou didst accept their praises; Accept the prayers we bring, Who in all good delight est, Thou good and gracious King."], "scriptureLinks": [{"label": "Mt 21:9", "chapterId": "MAT-21", "verseNumber": 9}, {"label": "Ps 148", "chapterId": "PSA-31", "verseNumber": 8}, {"label": "1Tim 1:17", "chapterId": "1TI-1", "verseNumber": 17}], "musicCredit": "'Valet Will Ich Dir Geben' or 'St. Theodulph' Melchior Teschner, 1615", "number": 33}, {"title": "All Hail The Power Of Jesus' Name", "sectionId": 3, "wordsCredit": "Edward Perronet, 1780", "verses": ["All hail the pow'r of Jesus' Name! Let angels prostrate fall; Bring forth the royal diadem, and crown Him Lord of all. Bring forth the royal diadem, and crown Him Lord of all.", "Let highborn seraphs tune the lyre, and as they tune it, fall Before His face Who tunes their choir, and crown Him Lord of all. Before His face Who tunes their choir, and crown Him Lord of all.", "Crown Him, ye morning stars of light, who fixed this floating ball; Now hail the strength of Israel's might, and crown Him Lord of all. Now hail the strength of Israel's might, and crown Him Lord of all.", "Crown Him, ye martyrs of your God, who from His altar call; Extol the Stem of Jesse's Rod, and crown Him Lord of all. Extol the Stem of Jesse's Rod, and crown Him Lord of all.", "Ye seed of Israel's chosen race, ye ransomed from the fall, Hail Him Who saves you by His grace, and crown Him Lord of all. Hail Him Who saves you by His grace, and crown Him Lord of all.", "Hail Him, ye heirs of David's line, whom David Lord did call, The God incarnate, Man divine, and crown Him Lord of all, The God incarnate, Man divine, and crown Him Lord of all.", "Sinners, whose love can ne'er forget the wormwood and the gall, Go spread your trophies at His feet, and crown Him Lord of all. Go spread your trophies at His feet, and crown Him Lord of all.", "Let every tribe and every tongue before Him prostrate fall And shout in universal song the crownèd Lord of all. And shout in universal song the crownèd Lord of all."], "scriptureLinks": [{"label": "Phil 2:9-11", "chapterId": "PHP-2", "verseNumber": 9}, {"label": "Rev 5:9-14", "chapterId": "REV-5", "verseNumber": 9}, {"label": "Heb 2:9", "chapterId": "HEB-2", "verseNumber": 9}], "musicCredit": "'Coronation' Oliver Holden, 1793", "number": 34}, {"title": "All Praise to Jesus' Hallowed Name", "sectionId": 3, "wordsCredit": "verse 1, ancient German. verses 2-7, Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["All praise to Jesus' hallowed Name Who of virgin pure became True man for us! The angels sing As the glad news to earth they bring. Hallelujah!", "Th'Eternal Father's only Son For a manger leaves His throne Disguised in our poor flesh and blood See now the everlasting Good. Hallelujah!", "He whom the world could not inwrap Yonder lies in Mary's lap; He is become an infant small, Who by His might upholdeth all. Hallelujah!", "Th'Eternal Light, come down from heav'n, Hath to us new sunshine giv'n; It shineth in the midst of night, And maketh us the sons of light. Hallelujah!", "The Father's Son, God ever— blest, In the world became a guest; He leads us from this vale of tears, And makes us in his kingdom heirs. Hallelujah!", "He came to earth so mean and poor, Man to pity and restore, And make us rich in heaven above, Equal with angels through his love.", "All this He did to show His grace To our poor and sinful race; For this let Christendom adore And praise His name for evermore."], "scriptureLinks": [{"label": "Jn 1:14", "chapterId": "JHN-1", "verseNumber": 14}, {"label": "Lk 2:7-14", "chapterId": "LUK-2", "verseNumber": 7}, {"label": "Is 9:2", "chapterId": "ISA-9", "verseNumber": 2}], "altTitle": "All Praise to Thee, O Jesus Christ or O Jesus Christ, All Praise to Thee or We Praise You, Jesus at Your Birth or All Praise to Thee, Eternal Lord", "musicCredit": "'Gelobet Seist Du' ancient German found in Walter's Geistliche Gesangbüchlein, 1524", "number": 35}, {"title": "Alleluia, Sing To Jesus!", "sectionId": 3, "wordsCredit": "William Chatterton Dix, 1867", "verses": ["Alleluia! sing to Jesus! His the scepter, His the throne. Alleluia! His the triumph, His the victory alone. Hark! the songs of peaceful Zion thunder like a mighty flood. Jesus out of every nation has redeemed us by His blood.", "Alleluia! not as orphans are we left in sorrow now; Alleluia! He is near us, faith believes, nor questions how; Though the cloud from sight received Him when the forty days were o'er Shall our hearts forget His promise, \"I am with you evermore\"?", "Alleluia! bread of angels, Thou on earth our food, our stay; Alleluia! here the sinful flee to Thee from day to day: Intercessor, Friend of sinners, Earth's Redeemer, plead for me, Where the songs of all the sinless sweep across the crystal sea.", "Alleluia! King eternal, Thee the Lord of lords we own; Alleluia! born of Mary, Earth Thy footstool, Heaven Thy throne: Thou within the veil hast entered, robed in flesh our great High Priest; Thou on earth both priest and victim in the Eucharistic feast."], "scriptureLinks": [{"label": "Is 66:1", "chapterId": "ISA-66", "verseNumber": 1}, {"label": "Rom 15:9", "chapterId": "ROM-15", "verseNumber": 9}, {"label": "Jas 5:13", "chapterId": "JAS-5", "verseNumber": 13}], "musicCredit": "'HyFrydol' Rowland H. Prichard, 1830", "number": 36}, {"title": "And Can It Be", "sectionId": 3, "wordsCredit": "Charles Wesley, 1738", "verses": ["And can it be that I should gain An interest in the Savior's blood? Died He for me, who caused His pain? For me, who Him to death pursued? Amazing love! How can it be, That Thou, my God, shouldst die for me?", "'Tis mystery all: th'Immortal dies: Who can explore His strange design? In vain the firstborn seraph tries To sound the depths of love divine. 'Tis mercy all! Let earth adore, Let angel minds inquire no more.", "He left His Father's throne above So free, so infinite His grace? Emptied Himself of all but love, And bled for Adam's helpless race: 'Tis mercy all, immense and free, For O my God, it found out me!", "Long my imprisoned spirit lay, Fast bound in sin and nature's night; Thine eye diffused a quick'ning ray? I woke, the dungeon flamed with light; My chains fell off, my heart was free, I rose, went forth, and followed Thee.", "Still the small inward voice I hear, That whispers all my sins forgiv'n; Still the atoning blood is near, That quenched the wrath of hostile Heav'n. I feel the life His wounds impart; I feel the Savior in my heart.", "No condemnation now I dread; Jesus, and all in Him, is mine; Alive in Him, my living Head, And clothed in righteousness divine, Bold I approach th'eternal throne, And claim the crown, through Christ my own."], "scriptureLinks": [{"label": "Rom 5:8-10", "chapterId": "ROM-5", "verseNumber": 8}, {"label": "Eph 3:8-12", "chapterId": "EPH-3", "verseNumber": 8}, {"label": "Acts 12:7", "chapterId": "ACT-12", "verseNumber": 7}], "musicCredit": "'Fillmore' Jeremiah Ingalls (1764-1828)", "number": 37}, {"title": "Angels From the Realms of Glory", "sectionId": 3, "wordsCredit": "James Montgomery, 1816", "verses": ["Angels from the realms of glory, Wing your flight o'er all the earth; Ye who sang creation's story Now proclaim Messiah's birth. Come and worship, come and worship, Worship Christ, the newborn King.", "Shepherds, in the field abiding, Watching o'er your flocks by night, God with us is now residing; Yonder shines the infant light: Come and worship, come and worship, Worship Christ, the newborn King.", "Sages, leave your contemplations, Brighter visions beam afar; Seek the great Desire of nations; Ye have seen His natal star. Come and worship, come and worship, Worship Christ, the newborn King.", "Saints, before the altar bending, Watching long in hope and fear; Suddenly the Lord, descending, In His temple shall appear. Come and worship, come and worship, Worship Christ, the newborn King.", "Sinners, wrung with true repentance, Doomed for guilt to endless pains, Justice now revokes the sentence, Mercy calls you; break your chains. Come and worship, come and worship, Worship Christ, the newborn King.", "Though an Infant now we view Him, He shall fill His Father's throne, Gather all the nations to Him; Every knee shall then bow down:", "All creation, join in praising God, the Father, Spirit, Son, Evermore your voices raising To th'eternal Three in One."], "scriptureLinks": [{"label": "Lk 2:6-20", "chapterId": "LUK-2", "verseNumber": 6}, {"label": "Mt 2:1-11", "chapterId": "MAT-2", "verseNumber": 1}], "musicCredit": "'Regent Square' Henry Smart, 1867", "number": 38}, {"title": "Beautiful Savior", "sectionId": 3, "wordsCredit": "German Jesuits, published 1677. Translated by Joseph A. Seiss, 1873", "verses": ["Beautiful Savior, King of Creation Son of God and Son of Man! Truly I'd love Thee, truly I'd serve Thee, Light of my soul, my joy, my crown.", "Fair are the meadows, Fair are the woodlands, Robed in the flow'rs of blooming spring; Jesus is fairer, Jesus is purer, He makes our sorr'wing spirit sing.", "Fair is the sunshine, Fair is the moonlight, Bright the sparkling stars on high; Jesus shines brighter, Jesus shines purer Than all the angels in the sky.", "Beautiful Savior, Lord of the nations, Son of God and Son of Man! Glory and honor, Praise, adoration Now and forevermore be Thine!"], "scriptureLinks": [{"label": "So 6:10", "chapterId": "SNG-6", "verseNumber": 10}, {"label": "Mt 6:29", "chapterId": "MAT-6", "verseNumber": 29}], "altTitle": "Fairest Lord Jesus", "musicCredit": "'Crusader`s Hymn' Silesian folk song, 1842", "number": 39}, {"title": "Behold, A Host, Arrayed in White", "sectionId": 3, "wordsCredit": "Hans Adolf Brorson, circa 1760. Translation composite", "verses": ["Behold a host, arrayed in white, Like thousand snow clad mountains bright, With palms they stand. Who is this band Before the throne of light? Lo, these are they of glorious fame Who from the great affliction came And in the flood of Jesus' blood Are cleansed from guilt and blame. Now gathered in the holy place Their voices they in worship raise, Their anthems swell where God doth dwell, Mid angels song of praise.", "Despised and scorned, they sojourned here; But now, how glorious they appear! Those martyrs stand a priestly band, God's throne forever near. So oft, in troubled days gone by, In anguish they would weep and sigh. At home above the God of Love For aye their tears shall dry. They now enjoy their Sabbath rest, The paschal banquet of the blest; The Lamb, their Lord, at festal board Himself is Host and Guest.", "Then hail, ye mighty legions, yea, All hail! Now safe and blest for aye, And praise the Lord, who with His Word Sustained you on the way. Ye did the joys of earth disdain, Ye toiled and sowed in tears and pain. Farewell, now bring your sheaves and sing Salvation's glad refrain. Swing high your palms, lift up your song, Yea, make it myriad voices strong. Eternally shall praise to Thee, God, and the Lamb belong."], "scriptureLinks": [{"label": "Rev 7:9-17", "chapterId": "REV-7", "verseNumber": 9}, {"label": "Heb 9:14", "chapterId": "HEB-9", "verseNumber": 14}, {"label": "1 Jn 1:7", "chapterId": "1JN-1", "verseNumber": 7}], "musicCredit": "'Den Store Hvide Flok' or 'Great White Host' traditional Norwegian, 17th cent", "number": 40}, {"title": "Beneath The Cross Of Jesus", "sectionId": 3, "wordsCredit": "Elizabeth C. Clephane, 1868", "verses": ["Beneath the cross of Jesus I fain would take my stand, The shadow of a mighty rock within a weary land; A home within the wilderness, a rest upon the way, From the burning of the noontide heat, and the burden of the day.", "O safe and happy shelter, O refuge tried and sweet, O trysting place where Heaven's love and Heaven's justice meet! As to the holy patriarch that wondrous dream was giv'n, So seems my Savior's cross to me, a ladder up to heav'n.", "There lies beneath its shadow but on the further side The darkness of an awful grave that gapes both deep and wide And there between us stands the cross two arms outstretched to save A watchman set to guard the way from that eternal grave.", "Upon that cross of Jesus mine eye at times can see The very dying form of One Who suffered there for me; And from my stricken heart with tears two wonders I confess; The wonders of redeeming love and my unworthiness.", "I take, O cross, thy shadow for my abiding place; I ask no other sunshine than the sunshine of His face; Content to let the world go by to know no gain or loss, My sinful self my only shame, my glory all the cross."], "scriptureLinks": [{"label": "Pr 14:26", "chapterId": "PRO-14", "verseNumber": 26}, {"label": "1Cor 1:17-18", "chapterId": "1CO-1", "verseNumber": 17}, {"label": "Gal 6:14", "chapterId": "GAL-6", "verseNumber": 14}], "musicCredit": "'St. Christopher' Frederick C. Maker, 1881", "number": 41}, {"title": "Blind Bartimaeus", "sectionId": 3, "wordsCredit": "Henry Wadsworth Longfellow, alt, 1842", "verses": ["Blind Bartimaeus at the gates Of Jericho in darkness waits: He hears the crowd; he hears a breath say \"It is Christ of Nazareth!\" And calls in tones of agony, \"O Jesus, Jesus pity me!\"", "The thronging multitudes in-crease \"Blind Bartimaeus, hold thy peace!\" But still, above the noisy crowd, The blind man's cry is shrill and loud: Until they say, \"He calleth thee; Courage! arise! He calleth thee!\"", "Then saith the Christ, as silent stands The crowd, \"What wilt thou at My hands?\" And he replies, \"O give me light! Rabbi, restore the blind man's sight.\" And Jesus answers, \"Go thy way, Thy faith, thy faith hath savèd thee.\"", "Ye that hath eyes and cannot see, In darkness and in misery, Recall those mighty voices three— \"O Jesus, Jesus pity me!\" \"Courage! arise! He calleth thee!\" \"Thy faith, thy faith hath savèd thee.\""], "scriptureLinks": [{"label": "Mk 10:46-52", "chapterId": "MRK-10", "verseNumber": 46}, {"label": "Lk 18:35-43", "chapterId": "LUK-18", "verseNumber": 35}, {"label": "Phil 4:5-7", "chapterId": "PHP-4", "verseNumber": 5}], "musicCredit": "'Fillmore' Jeremiah Ingalls (1764-1828)", "number": 42}, {"title": "Christ Arose", "sectionId": 3, "wordsCredit": "Robert Lowry, 1874", "verses": ["Low in the grave He lay Jesus my Savior! Waiting the coming day- Jesus my Lord!", "Vainly they watch His bed- Jesus my Savior! Vainly they seal the dead- Jesus my Lord!", "Death cannot keep his prey- Jesus my Savior! He tore the bars away- Jesus my Lord!"], "scriptureLinks": [{"label": "Jn 2:19-22", "chapterId": "JHN-2", "verseNumber": 19}, {"label": "Mt 28:6", "chapterId": "MAT-28", "verseNumber": 6}], "musicCredit": "'Christ Arose' Robert Lowry, 1874", "refrain": "Up from the grave He arose, With a mighty triumph o'er His foes; He arose a Victor from the dark domain, And He lives forever with His saints to reign. He arose! He arose! Hallelujah! Christ arose! He arose! He arose!", "number": 43}, {"title": "Come, Thou Long-Expected Jesus", "sectionId": 3, "wordsCredit": "Charles Wesley, 1745", "verses": ["Come, Thou long expected Jesus Born to set Thy people free; From our fears and sins release us, Let us find our rest in Thee. Israel's Strength and Consolation, Hope of all the earth Thou art; Dear Desire of every nation, Joy of every longing heart.", "Born Thy people to de liver, Born a child and yet a King, Born to reign in us forever, Now Thy gracious kingdom bring. By Thine own eternal Spirit Rule in all our hearts alone; By Thine all sufficient merit, Raise us to Thy glorious throne."], "scriptureLinks": [{"label": "Is 9:6", "chapterId": "ISA-9", "verseNumber": 6}, {"label": "Lk 1:67-75", "chapterId": "LUK-1", "verseNumber": 67}, {"label": "Is 61:1-2", "chapterId": "ISA-61", "verseNumber": 1}], "altTitle": "Hail, Thou Long-Expected Jesus", "musicCredit": "'Jefferson' from \"Southern Harmony\", 1835, alt", "number": 44}, {"title": "Come, Your Hearts and Voices Raising", "sectionId": 3, "wordsCredit": "Paul Gerhardt, 1667. Translation composite", "verses": ["Come, your hearts and voices raising, Christ the Lord with gladness praising; Loudly sing His love amazing, Worthy folk of Christendom.", "Sin and death may well be groaning, Satan now may well be moaning; We, our full salvation owning, Cast our every care away.", "See how God, for us providing, Gave His Son and life abiding; He our weary steps is guiding From earth's woe to heav'nly joy.", "Christ, from heav'n to us descending And in love our race befriending, In our need His help extending, Saved us from the wily Foe.", "Jacob's Star in all its splendor Beams with comfort sweet and tender, Forcing Satan to surrender, Breaking all the pow'rs of hell.", "From the bondage that oppressed us, From sin's fetters that possessed us, From the grief that sore distressed us, We, the captives, now are free.", "Oh, the joy beyond expressing When by faith we grasp this blessing And to Thee we come confessing, That our freedom thou hast wrought!", "Gracious Child, we pray Thee, hear us, From Thy lowly manger cheer us, Gently lead us and be near us Till we join the angelic choir."], "scriptureLinks": [{"label": "Lk 2:15", "chapterId": "LUK-2", "verseNumber": 15}, {"label": "Lk 1:68-71", "chapterId": "LUK-1", "verseNumber": 68}, {"label": "Is 61:1", "chapterId": "ISA-61", "verseNumber": 1}], "altTitle": "Come and Christ the Lord Be Praising or Come and Let Us Christ Revere Now or Come Unite in Praise and Singing", "musicCredit": "'Quem Pastores' German, 1410", "number": 45}, {"title": "Dear Christians, One and All Rejoice", "sectionId": 3, "wordsCredit": "Martin Luther, 1523. Translated by Richard Massie, 1854, alt", "verses": ["Dear Christians, one and all rejoice, With exultation springing, And with united heart and voice And holy rapture singing, Proclaim the wonders God hath done, How his right arm the vict'ry won; Right dearly it hath cost him.", "Fast bound in Satan's chains I lay. Death brooded darkly o'er me; Sin was my torment night and day, Therein my mother bore me. Deeper and deeper still I fell, Life was become a living hell, So firmly sin possessed me.", "My good works could avail me naught, For they with sin were stainéd; Freewill against God's judgment fought, And dead to good remainéd. Grief drove me to despair, and I Had nothing left me but to die, To hell I fast was sinking.", "God saw, in his eternal grace, My sorrow out of measure; He thought upon his tenderness To save was his good pleasure. He turn'd to me a Father's heart— Not small the cost to heal my smart He gave his best and dearest.", "He spake to his beloved Son: 'Tis time to take compassion; Then go, bright jewel of my crown, And bring to man salvation; From sin and sorrow set him free, Slay bitter death for him, that he May live with thee forever.", "The Son delighted to obey, And born of Virgin mother, Awhile on this low earth did stay That he might be my brother. His mighty power he hidden bore, A servant's form like mine he wore, To bind the devil captive.", "To me he spake : cling fast to me, Thou'lt win a triumph worthy: I wholly give myself for thee, I strive and wrestle for thee; For I am thine, thou mine also; And where I am thou art. The foe Shall never more divide us.", "For he shall shed my precious blood, Me of my life bereaving; All this I suffer for thy good; Be steadfast and believing. My life from death the day shall win, My righteousness shall bear thy sin, So art thou blest forever.", "Now to my Father I depart, From earth to heaven ascending; Thence heavenly wisdom to impart, The Holy Spirit sending. He shall in trouble comfort thee, Teach thee to know and follow me, And to the truth conduct thee.", "What I have done and taught, do thou To do and teach endeavor; So shall my kingdom flourish now, And God be praised forever. Take heed lest men with base alloy The heavenly treasure should destroy. This counsel I bequeath thee."], "scriptureLinks": [{"label": "1 Pt 1:6-9", "chapterId": "1PE-1", "verseNumber": 6}, {"label": "1 Jn 4:14", "chapterId": "1JN-4", "verseNumber": 14}, {"label": "Ps 98:1-3", "chapterId": "PSA-98", "verseNumber": 1}], "musicCredit": "'Es ist Gewisslich an der Zeit' from Klug's Geistliche Lieder, Wittenberg, 1533", "number": 46}, {"title": "Dear Christians, One and All Rejoice", "sectionId": 3, "wordsCredit": "Martin Luther, 1523. Translated by Richard Massie, 1854, alt", "verses": ["Dear Christians, one and all rejoice, With exultation springing, And with united heart and voice And holy rapture singing, Proclaim the wonders God hath done, How his right arm the vict'ry won; Right dearly it hath cost him.", "Fast bound in Satan's chains I lay. Death brooded darkly o'er me; Sin was my torment night and day, Therein my mother bore me. Deeper and deeper still I fell, Life was become a living hell, So firmly sin possessed me.", "My good works could avail me naught, For they with sin were stainéd; Freewill against God's judgment fought, And dead to good remainéd. Grief drove me to despair, and I Had nothing left me but to die, To hell I fast was sinking.", "God saw, in his eternal grace, My sorrow out of measure; He thought upon his tenderness To save was his good pleasure. He turn'd to me a Father's heart— Not small the cost to heal my smart He gave his best and dearest.", "He spake to his beloved Son: 'Tis time to take compassion; Then go, bright jewel of my crown, And bring to man salvation; From sin and sorrow set him free, Slay bitter death for him, that he May live with thee forever.", "The Son delighted to obey, And born of Virgin mother, Awhile on this low earth did stay That he might be my brother. His mighty power he hidden bore, A servant's form like mine he wore, To bind the devil captive.", "To me he spake : cling fast to me, Thou'lt win a triumph worthy: I wholly give myself for thee, I strive and wrestle for thee; For I am thine, thou mine also; And where I am thou art. The foe Shall never more divide us.", "For he shall shed my precious blood, Me of my life bereaving; All this I suffer for thy good; Be steadfast and believing. My life from death the day shall win, My righteousness shall bear thy sin, So art thou blest forever.", "Now to my Father I depart, From earth to heaven ascending; Thence heavenly wisdom to impart, The Holy Spirit sending. He shall in trouble comfort thee, Teach thee to know and follow me, And to the truth conduct thee.", "What I have done and taught, do thou To do and teach endeavor; So shall my kingdom flourish now, And God be praised forever. Take heed lest men with base alloy The heavenly treasure should destroy. This counsel I bequeath thee."], "scriptureLinks": [{"label": "1 Pt 1:6-9", "chapterId": "1PE-1", "verseNumber": 6}, {"label": "1 Jn 4:14", "chapterId": "1JN-4", "verseNumber": 14}, {"label": "Ps 98:1-3", "chapterId": "PSA-98", "verseNumber": 1}], "musicCredit": "'Nun Freut Euch' attr. Martin Luther from Etlich Christlich Lider, Wittenberg, 1524", "number": 47}, {"title": "From All Thy Saints in Warfare", "sectionId": 3, "wordsCredit": "Horatio Nelson, 1864", "verses": ["From all Thy saints in warfare, for all Thy saints at rest To Thee O blessed Jesus, all praises be addressed. Thou, Lord didst win the battle that they might conquerors be; Their crowns of living glory are lit with rays from Thee.", "2—18.~Insert appropriate verse (from below)", "Apostles, prophets, martyrs, and all the sacred throng, Who wear the spotless raiment, who raise the ceaseless song; For these, passed on before us, Savior, we Thee adore, And, walking in their footsteps, would serve Thee more and more.", "Δ Then praise we God the Father, and praise we God the Son, And God the Holy Spirit, eternal Three in One; Till all the ransomed number fall down before the throne, And honor, pow'r, and glory ascribe to God alone.", "Praise, Lord, for Thine apostle, The first to welcome Thee, The first to lead his brother The very Christ to see. With hearts for Thee made ready, Watch we throughout the year, Forward to lead our brethren To own Thine advent near.", "All praise for Thine apostle, Whose short-lived doubtings prove Thy perfect twofold nature, The fullness of Thy love. On all who wait Thy coming Shed forth Thy peace, O Lord, And grant us faith to know Thee, True man, true God, adored.", "Praise for the first of martyrs, Who saw Thee ready stand To aid in midst of torments, To plead at God's right hand. Share we with him, if summoned By death our Lord to own, On earth the faithful witness, In heaven the martyr's crown.", "Praise for the loved disciple, Exile on Patmos' shore; Praise for the faithful record He to Thy Godhead bore, Praise for the mystic vision Through him to us revealed. May we, in patience waiting, With Thine elect be sealed.", "Praise for Thine infant martyrs, By Thee with tenderest love Called early from the warfare To share the rest above. O Rachel! cease thy weeping: They rest from pains and cares. Lord, grant us hearts as guileless And crowns as bright as theirs.", "Praise for the light from Heaven, Praise for the voice of awe, Praise for the glorious vision The persecutor saw. Thee, Lord, for his conversion, We glorify today; So lighten all our darkness With Thy true Spirit's ray.", "Lord, Thine abiding presence Directs the wondrous choice For one in place of Judas The faithful now rejoice. Thy Church from false apostles Forevermore defend, And by Thy parting promise Be with her to the end.", "For him, O Lord, we praise Thee, The weak by grace made strong, Whose labors and whose Gospel Enrich our triumph song. May we in all our weakness Find strength from Thee supplied, And all, as fruitful branches, In Thee, the Vine, abide.", "All praise for Thine apostle, Blest guide to Greek and Jew, And him surnamed Thy brother Keep us Thy brethren true, And grant us grace to know Thee, The Way, the Truth, the Life; To wrestle with temptations Till victors in the strife.", "The Son of Consolation, Moved by Thy law of love, Forsaking earthly treasures, Sought riches from above. As earth now teems with increase, Let gifts of grace descend, That Thy true consolations May through the world extend.", "We praise Thee for the Baptist, Forerunner of the Word, Our true Elias, making A highway for the Lord. Of prophets last and greatest, We saw Thy dawning ray: Make us the rather blessed Who love Thy glorious day.", "Praise for Thy great apostle, The eager and the bold; Thrice falling, yet repentant, Thrice charged to keep Thy fold. Lord, make Thy pastors faithful To guard their flocks from ill, And grant them dauntless courage, With humble, earnest will.", "For him, O Lord, we praise Thee, Who, slain by Herod's sword Drank of Thy cup of suffering, Fulfilling thus Thy word. Curb we all vain impatience To read Thy veiled decree, And count it joy to suffer, If so brought nearer Thee.", "All praise for Thine apostle, The faithful, pure, and true, Whom underneath the fig tree Thine eye all seeing knew. Like him may we be guileless, True Israelites indeed, That Thy abiding presence Our longing souls may feed.", "Praise, Lord, for Him whose Gospel Thy human life declared, Who, worldly gains forsaking, Thy path of suffering shared. From all unrighteous Mammon O give us hearts set free, That we, whate'er our calling, May rise and follow Thee.", "For that \"beloved physician,\" All praise, whose Gospel shows The healer of the nations, The sharer of our woes. Thy wine and oil, O Savior, And bruised hearts deign to pour, And with true balm of Gilead Anoint us evermore.", "Praise, Lord, for Thine apostles, Who sealed their faith today: One love, one zeal impelled them To tread the sacred way. May we with zeal as earnest The faith of Christ maintain, And, bound in love as brethren, At length Thy rest attain."], "scriptureLinks": [{"label": "Heb 12:1-2", "chapterId": "HEB-12", "verseNumber": 1}, {"label": "Heb 6:11-12", "chapterId": "HEB-6", "verseNumber": 11}, {"label": "Heb 13:7", "chapterId": "HEB-13", "verseNumber": 7}], "altTitle": "By All Your Saints in Warfare", "musicCredit": "'Kings Lynn' Traditional English", "number": 48}, {"title": "Go To Dark Gethsemane", "sectionId": 3, "wordsCredit": "James Montgomery, 1820", "verses": ["Go to dark Gethsemane, ye that feel the tempter's pow'r; Your Redeemer's conflict see, watch with Him one bitter hour, Turn not from His griefs away; learn from Jesus Christ to pray.", "Follow to the judgment hall, view the Lord of Life arraigned; O the wormwood and the gall! O the pangs His soul sustained! Shun not suff'ring, shame, or loss; learn from Christ to bear the cross.", "Calv'ry's mournful mountain climb; there, adoring at His feet, Mark that miracle of time, God's own sacrifice complete. \"It is finished!\" hear Him cry; learn from Jesus Christ to die.", "Early hasten to the tomb where they laid His breathless clay; All is solitude and gloom. Who has taken Him away? Christ is ris'n! He meets our eyes; Savior, teach us so to rise."], "scriptureLinks": [{"label": "Mt 26:36-68", "chapterId": "MAT-26", "verseNumber": 36}, {"label": "27:31-56", "chapterId": "MAT-27", "verseNumber": 31}, {"label": "28:1-10", "chapterId": "MAT-28", "verseNumber": 1}], "musicCredit": "'Gethsemane' or 'Petra' Richard Redhead, 1853", "number": 49}, {"title": "God Himself is Present", "sectionId": 3, "wordsCredit": "Gerhard Tersteegen, 1729. Translated by Frederick W. Foster and John Miller, 1789, alt", "verses": ["God Himself is present: Let us now adore Him, And with awe appear before Him. God is in His temple, all within keep silence, Prostrate lie with deepest reverence. Him alone God we own, Him our God and Savior; Praise His name forever.", "God Himself is present: Hear the harps resounding! See the crowds the throne surrounding! \"Holy, holy, holy\", hear the hymn ascending, Angels, saints, their voices blending! Bow Thine ear to us here: Hear, O Christ, the praises That Thy Church now raises.", "O Thou fount of blessing, Purify my spirit; Trusting only in Thy merit, Like the holy angels Who behold Thy glory, May I ceaselessly adore Thee, Let Thy will Ever still Rule Thy Church terrestrial, As the hosts celestial."], "scriptureLinks": [{"label": "Hab 2:20", "chapterId": "HAB-2", "verseNumber": 20}, {"label": "2Sam 22:7", "chapterId": "2SA-22", "verseNumber": 7}, {"label": "Ps 48:9-10", "chapterId": "PSA-48", "verseNumber": 9}], "altTitle": "God Himself is With Us or God Reveals His Presence or Lo! God Is Here", "musicCredit": "'Wunderbarer König' or 'Arnsberg' or 'Groeningen' Joachim Neander, 1680", "number": 50}, {"title": "Hallelujah, What a Savior!", "sectionId": 3, "wordsCredit": "Philip Paul Bliss, 1875", "verses": ["Man of Sorrows! what a name For the Son of God, who came Ruined sinners to reclaim. Hallelujah! What a Savior!", "Bearing shame and scoffing rude, In my place condemned He stood; Sealed my pardon with His blood. Hallelujah! What a Savior!", "Guilty, vile, and helpless we; Spotless Lamb of God was He; \"Full atonement!\" can it be? Hallelujah! What a Savior!", "Lifted up was He to die; \"It is finished!\" was His cry; Now in Heav'n exalted high. Hallelujah! What a Savior!", "When He comes, our glorious King, All His ransomed home to bring, Then anew His song we'll sing: Hallelujah! What a Savior!"], "scriptureLinks": [{"label": "Is 53:3", "chapterId": "ISA-53", "verseNumber": 3}, {"label": "1 Jn 2:1-2", "chapterId": "1JN-2", "verseNumber": 1}, {"label": "Heb 4:14-16", "chapterId": "HEB-4", "verseNumber": 14}], "altTitle": "Man of Sorrows", "musicCredit": "'Hallelujah What a Savior' Philip Paul Bliss, 1875", "number": 51}, {"title": "Hark the Glad Sound", "sectionId": 3, "wordsCredit": "Philip Doddridge, 1735", "verses": ["Hark, the glad sound! the Savior comes! The Savior promised long; Let every heart prepare a throne, And every voice a song.", "On Him the Spirit, largely poured, Exerts its sacred Fire; Wisdom and might, and zeal and love, His holy Breast inspire.", "He comes the pris'ners to release, In Satan's bondage held; The gates of brass before Him burst, The iron fetters yield.", "He comes from thickest films of vice To clear the mental ray, And on the eyeballs of the blind To pour celestial day.", "He comes the broken heart to bind, The bleeding soul to cure; And with the treasures of His grace T'enrich the humble poor.", "His silver trumpets publish loud The jub'lee of the Lord Our debts are all remitted now Our heritage restored.", "Our glad hosannas, Prince of Peace, Thy welcome shall proclaim; And Heav'n's eternal arches ring With Thy belovèd name."], "scriptureLinks": [{"label": "Lk 4:18-19", "chapterId": "LUK-4", "verseNumber": 18}, {"label": "Is 61:1-2", "chapterId": "ISA-61", "verseNumber": 1}, {"label": "Rev 5:11-12", "chapterId": "REV-5", "verseNumber": 11}], "musicCredit": "'Chesterfield' or 'Richmond (Haweis)' or 'Spa Fields Chapel' Thomas Haweis, 1792", "number": 52}, {"title": "Hark, the Voice of Jesus Calling", "sectionId": 3, "wordsCredit": "Daniel March, 1868", "verses": ["Hark, the voice of Jesus calling, \"Who will go and work today? Fields are ripe and harvests waiting, Who will bear the sheaves away?\" Long and loud the Master calls us, Rich reward He offers free; Who will answer, gladly saying, \"Here am I, send me, send me?\"", "If you cannot cross the ocean, And the distant lands explore, You can find the lost around you, You can help them at your door; If you cannot give your thousands, You can give the widow's mite; What you truly give for Jesus, Will be precious in His sight.", "If you cannot speak like angels, If you cannot preach like Paul, You can tell the love of Jesus, You can say He died for all. If you cannot rouse the wicked, With the judgment's dread alarms, You can lead the little children To the Savior's waiting arms.", "If you cannot be the watchman, Standing high on Zion's wall, Pointing out the path to heaven, Off'ring life and peace to all, With your prayers and with your bounties You can do what heav'n demands; You can be like faithful Aaron, Holding up the prophet's hands.", "If among the older people, You may not be apt to teach, \"Feed My lambs,\" said Christ, our Shepherd, \"Place the food within their reach.\" And it may be that the children You have led with trembling hand, Will be found among your jewels, When you reach the better land.", "Let none hear you idly saying, \"There is nothing I can do.\" While the lost of earth are dying, And the Master calls for you; Take the task He gives you gladly; Let His work your pleasure be; Answer quickly when He calls you, \"Here am I, send me, send me.\""], "scriptureLinks": [{"label": "Is 6:8", "chapterId": "ISA-6", "verseNumber": 8}, {"label": "Mt 9:37-39", "chapterId": "MAT-9", "verseNumber": 37}, {"label": "20:1-16", "chapterId": "MAT-20", "verseNumber": 1}], "musicCredit": "'Galilean' Joseph Barnby, 1883", "number": 53}, {"title": "He Keeps Me Singing", "sectionId": 3, "wordsCredit": "Luther B. Bridgers, 1910", "verses": ["There's within my heart a melody Jesus whispers sweet and low, \"Fear not, I am with thee, peace, be still,\" In all of life's ebb and flow.", "All my life was wrecked by sin and strife, Discord filled my heart with pain, Jesus swept across the broken strings, Stirred the slumb'ring chords again.", "Feasting on the riches of His grace, Resting 'neath His shelt'ring wing, Always looking on His smiling face, That is why I shout and sing.", "Though sometimes He leads through waters deep, Trials fall across the way, Though sometimes the path seems rough and steep, See His footprints all the way.", "Soon He's coming back to welcome me, Far beyond the starry sky; I shall wing my flight to worlds unknown, I shall reign with Him on high."], "scriptureLinks": [{"label": "Ps 61:1-8", "chapterId": "PSA-61", "verseNumber": 1}, {"label": "40:2-3", "chapterId": "PSA-40", "verseNumber": 2}, {"label": "33:3", "chapterId": "PSA-33", "verseNumber": 3}], "musicCredit": "'He Keeps Me Singing' or 'Melody of Love' Hans Engelmann, 1903", "refrain": "Jesus, Jesus, Jesus,— Sweetest name I know, Fills my ev'ry longing, Keeps me singing as I go.", "number": 54}, {"title": "He Was Not Willing", "sectionId": 3, "wordsCredit": "Lucy R. Meyer, 1885", "verses": ["\"He was not willing that any should perish\"; Jesus enthroned in the glory above, Saw our poor fallen world, pitied our sorrows, Poured out His life for us, wonderful love! Perishing, perishing! Thronging our pathway, Hearts break with burdens too heavy to bear: Jesus would save, but there's no one to tell them, No one to lift them from sin and despair.", "\"He was not willing that any should perish\"; Clothed in our flesh with its sorrow and pain, Came He to seek the lost, comfort the mourner, Heal the heart broken by sorrow and shame. Perishing, perishing! Harvest is passing, Reapers are few and the night draweth near: Jesus is calling thee, haste to the reaping, Thou shalt have souls, precious souls for thy hire.", "Plenty for pleasure, but little for Jesus; Time for the world with its troubles and toys, No time for Jesus' work, feeding the hungry, Lifting lost souls to eternity's joys. Perishing, perishing! Hark, how they call us; Bring us your Savior, oh, tell us of Him! We are so weary, so heavily laden, And with long weeping our eyes have grown dim.", "\"He was not willing that any should perish\"; Am I His follower, and can I live Longer at ease with a soul going downward, Lost for the lack of the help I might give! Perishing, perishing! Thou wast not willing; Master, forgive, and inspire us anew; Banish our worldliness, help us to ever Live with eternity's values in view."], "scriptureLinks": [{"label": "2Pt 3:9-18", "chapterId": "2PE-3", "verseNumber": 9}, {"label": "Ps 22:14-18", "chapterId": "PSA-22", "verseNumber": 14}, {"label": "Rom 10:14-15", "chapterId": "ROM-10", "verseNumber": 14}], "musicCredit": "'He Was Not Willing' Lucy R. Meyer, 1885", "number": 55}, {"title": "Hosanna, Loud Hosanna", "sectionId": 3, "wordsCredit": "Jeanette Threlfall, 1873, alt", "verses": ["Hosanna, loud hosanna, the little children sang; Through pillared court and temple the lovely anthem rang. To Jesus, Who had blessed them close folded to His breast, The children sang their praises, the simplest and the best.", "From Olivet they followed mid an exultant crowd, The victor palm branch waving, and chanting clear and loud. The Lord of men and angels rode on in lowly state, Nor scorned that little children should on His bidding wait.", "\"Hosanna in the highest!\" that ancient song we sing, For Christ is our Redeemer, the Lord of heav'n our King. O may we ever praise Him with heart and life and voice, And in His blissful presence eternally rejoice!"], "scriptureLinks": [{"label": "Mt 21:15", "chapterId": "MAT-21", "verseNumber": 15}, {"label": "Jn 12:12-13", "chapterId": "JHN-12", "verseNumber": 12}], "musicCredit": "'Ellacombe' from Gesangbuch der Herzogl. Hofkapelle, Wurttemberg, 1784", "number": 56}, {"title": "I Am Jesus' Little Lamb", "sectionId": 3, "wordsCredit": "Henrietta L. von Hayn, 1778. Translation composite", "verses": ["I am Jesus' little lamb, Ever glad at heart I am; For my Shepherd gently guides me, Knows my need, and well provides me, Loves me ev'ry day the same, Even calls me by my name.", "Day by day, at home, away, Jesus is my Staff and Stay. When I hunger, Jesus feeds me, Into pleasant pastures leads me; When I thirst, He bids me go Where the quiet waters flow.", "Who so happy as I am, Even now the Shepherd's lamb? And when my short life is end ed, By His angel host at tend ed, He shall fold me to His breast, There within His arms to rest."], "scriptureLinks": [{"label": "Is 40:11", "chapterId": "ISA-40", "verseNumber": 11}, {"label": "Jn 10:11-15", "chapterId": "JHN-10", "verseNumber": 11}], "musicCredit": "'Weil Ich Jesu Schäflein Bin' from Bruder Choral-Buch, 1784", "number": 57}, {"title": "I Come, O Savior, To Thy Table", "sectionId": 3, "wordsCredit": "Friedrich C. Heyder, 1710. Translation composite", "verses": ["I come, O Savior, to Thy table, For weak and weary is my soul; Thou, Bread of Life, alone art able To satisfy and make me whole: Lord, may Thy body and Thy blood Be for my soul the highest good!", "Oh, grant that I in manner worthy May now approach Thy heav'nly board And, as I lowly bow before Thee, Look only unto Thee, O Lord! Lord, may Thy body and Thy blood Be for my soul the highest good!", "Unworthy though I am, O Savior, Because I have a sinful heart, Yet Thou Thy lamb wilt banish never, For Thou my faithful Shepherd art: Lord, may Thy body and Thy blood Be for my soul the highest good!", "Oh, let me loathe all sin forever As death and poison to my soul That I through willful sinning never May see Thy judgment take its toll! Lord, may Thy body and Thy blood Be for my soul the highest good!", "Thy heart is filled with fervent yearning That sinners may salvation see Who, Lord, to Thee in faith are turning; So I, a sinner, come to Thee. Lord, may Thy body and Thy blood Be for my soul the highest good!", "Weary am I and heavy laden, With sin my soul is sore opprest; Receive me graciously and gladden My heart, for I am now Thy guest.", "Thou here wilt find a heart most lowly That humbly falls before Thy feet, That duly weeps o'er sin, yet solely Thy merit pleads, as it is meet.", "By faith I call Thy holy table The testament of Thy deep love; For, lo, thereby I now am able To see how love Thy heart doth move.", "What higher gift can we inherit? It is faith's bond and solid base; It is the strength of heart and spirit, The covenant of hope and grace.", "This feast is manna, wealth abounding Unto the poor, to weak ones power, To angels joy, to hell confounding, And life for me in death's dark hour.", "Thy body, giv'n for me, O Savior, Thy blood which Thou for me didst shed, These are my life and strength forever, By them my hungry soul is fed.", "With Thee, Lord, I am now united; I live in Thee and Thou in me. No sorrow fills my soul, delighted It finds its only joy in Thee.", "Who can condemn me now? For surely The Lord is nigh, who justifies. No hell I fear, and thus securely With Jesus I to Heaven rise.", "Though death may threaten with disaster, It cannot rob me of my cheer; For He Who is of death the Master, With aid and comfort e'er is near.", "My heart has now become Thy dwelling, O blessèd, holy Trinity. With angels I, Thy praises telling, Shall live in joy eternally."], "scriptureLinks": [{"label": "1Cor 11:23-29", "chapterId": "1CO-11", "verseNumber": 23}, {"label": "Lk 22:17-20", "chapterId": "LUK-22", "verseNumber": 17}, {"label": "7:6", "chapterId": "LUK-7", "verseNumber": 6}], "musicCredit": "'Ich Sterbe Täglich' from Emskirchner Choralbuch, 1756", "number": 58}, {"title": "I Know That My Redeemer Lives", "sectionId": 3, "wordsCredit": "Samuel Medley, 1775", "verses": ["I know that my Redeemer lives; What comfort this sweet sentence gives! He lives, He lives, who once was dead; He lives, my ever living Head.", "He lives to bless me with His love, He lives to plead for me above. He lives my hungry soul to feed, He lives to help in time of need.", "He lives triumphant from the grave, He lives eternally to save, He lives all glorious in the sky, He lives exalted there on high.", "He lives to grant me rich supply, He lives to guide me with His eye, He lives to comfort me when faint, He lives to hear my soul's complaint.", "He lives to silence all my fears, He lives to wipe away my tears He lives to calm my troubled heart, He lives all blessings to impart.", "He lives, my kind, wise, heavenly Friend, He lives and loves me to the end; He lives, and while He lives, Ill sing; He lives, my Prophet, Priest, and King.", "He lives and grants me daily breath; He lives, and I shall conquer death: He lives my mansion to prepare; He lives to bring me safely there.", "He lives, all glory to His Name! He lives, my Jesus, still the same. Oh, the sweet joy this sentence gives, I know that my Redeemer lives!"], "scriptureLinks": [{"label": "Job 19:25", "chapterId": "JOB-19", "verseNumber": 25}, {"label": "Ps 104:33-34", "chapterId": "PSA-104", "verseNumber": 33}], "musicCredit": "'Duke Street' John Hatton, 1793", "number": 59}, {"title": "If God Himself Be For Me", "sectionId": 3, "wordsCredit": "Paul Gerhardt, 1656. Verses 1-3, 7-9, 11-15 Translated by Richard Massie, 1856, alt. Verses 4-6,10 Translated for Evangelical Lutheran Hymn-Book (Pittsburgh), 1907, alt", "verses": ["If God Himself be for me, I may a host defy; For when I pray, before me My foes, confounded, fly. If Christ, my Head and Master, Befriend me from above, What foe or what disaster Can drive me from His love?", "This I believe, yea, rather, Of this I make my boast, That God is my dear Father, The Friend who loves me most, And that, whate'er betide me, My Savior is at hand Through stormy seas to guide me And bring me safe to land.", "I build on this foundation, That Jesus and His blood Alone are my salvation, The true, eternal good. Without Him all that pleases Is valueless on earth; The gifts I owe to Jesus Alone my love are worth.", "My Jesus is my Splendor, My Sun, my Light, alone; Were He not my Defender Before God's awe— full throne, I never should find favor And mercy in His sight, But be destroyed forever As darkness by the light.", "He canceled my offenses, Delivered me from death; He is the Lord who cleanses My soul from sin through faith. In Him I can be cheerful, Bold, and undaunted aye; In Him I am not fearful Of God's great Judgment Day.", "Naught, naught, can now condemn me Nor set my hope aside; Now hell no more can claim me, Its fury I deride. No sentence e'er reproves me, No ill destroys my peace; For Christ, my Savior, loves me And shields me with His grace.", "His Spirit in me dwelleth, And o'er my mind He reigns. All sorrow He dispelleth And soothes away all pains. He crowns His work with blessing And helpeth me to cry, \"My Father!\" without ceasing, To Him who dwells on high.", "And when my soul is lying Weak, trembling, and opprest, He pleads with groans and sighing That cannot be exprest; But God's quick eye discerns them, Although they give no sound, And into language turns them E'en in the heart's deep ground.", "To mine His Spirit speaketh Sweet word of holy cheer, How God to him that seeketh For rest is always near And how He hath erected A city fair and new, Where what our faith expected We evermore shall view.", "In yonder home doth flourish My heritage, my lot; Though here I die and perish, My heaven shall fail me not. Though care my life oft saddens And causeth tears to flow, The light of Jesus gladdens And sweetens every woe.", "Who clings with resolution To Him whom Satan hates Must look for persecution; For him the burden waits Of mockery, shame, and losses, Heaped on his blameless head; A thousand plagues and crosses Will be his daily bread.", "From me this is not hidden, Yet I am not afraid; I leave my cares, as bidden, To whom my vows were paid. Though life and limb it cost me And everything I won, Unshaken shall I trust Thee And cleave to Thee alone.", "Though earth be rent asunder, Thou'rt mine eternally; Not fire nor sword nor thunder Shall sever me from Thee; Not hunger, thirst, nor danger, Not pain nor poverty Nor mighty princes' anger Shall ever hinder me.", "No angel and no gladness, No throne, no pomp, no show, No love, no hate, no sadness, No pain, no depth of woe, No scheme of man's contrivance, However small or great, Shall draw me from Thy guidance Nor from Thee separate.", "My heart for joy is springing And can no more be sad, 'Tis full of mirth and singing, Sees naught but sunshine glad. The Sun that cheers my spirit Is Jesus Christ, my King; That which I shall inherit Makes me rejoice and sing."], "scriptureLinks": [{"label": "Rom 8:31-39", "chapterId": "ROM-8", "verseNumber": 31}, {"label": "Ps 27:1-3", "chapterId": "PSA-27", "verseNumber": 1}, {"label": "Is 50:7-9", "chapterId": "ISA-50", "verseNumber": 7}], "musicCredit": "'Woodbird' or 'Es Flog Ein Kleins Waldvögelein' traditional German found in \"Memminger Tabulaturbuche\", 17th Century", "number": 60}, {"title": "In These Our Days So Perilous", "sectionId": 3, "wordsCredit": "Latin c. 6th century, adapted by Martin Luther, 1529. Translated to English by Richard Massie, 1854, alt", "verses": ["In these our days so perilous, Lord, peace in mercy send us; No God but Thee can fight for us, No God but Thee defend us; Thou our only God and Savior."], "scriptureLinks": [{"label": "2Thess 3:16", "chapterId": "2TH-3", "verseNumber": 16}, {"label": "Ps 35:23", "chapterId": "PSA-35", "verseNumber": 23}, {"label": "Is 31:4-5", "chapterId": "ISA-31", "verseNumber": 4}], "altTitle": "Grant Peace, We Pray, in Mercy, Lord or Grant Peace in Mercy, Lord, We Pray", "musicCredit": "'Verleih uns Frieden Gnädiglich' Martin Luther. Found in Klug's Geistliche Lieder, 1533", "number": 61}, {"title": "Jesus Christ Is Risen Today", "sectionId": 3, "wordsCredit": "14th Century Bohemian Latin carol. Stanzas 1-3 translated in John Arnold's Compleat Psalmist, 1749.Stanza 4 Charles Wesley, 1740, alt", "verses": ["Jesus Christ is ris'n today, Alleluia! Our triumphant holy day, Alleluia! Who did once, upon the cross, Alleluia! Suffer to redeem our loss, Alleluia!", "Hymns of praise then let us sing, Alleluia! Unto Christ, our heav'nly King, Alleluia! Who endured the cross and grave, Alleluia! Sinners to redeem and save, Alleluia!", "But the pain which He endured, Alleluia! Our salvation hath procured, Alleluia! Now above the sky He's king, Alleluia! Where the angels ever sing, Alleluia!", "Sing we to our God above, Alleluia! Praise eternal as His love, Alleluia! Praise Him, all you heav'nly host, Alleluia! Father, Son, and Holy Ghost, Alleluia!"], "scriptureLinks": [{"label": "Mt 28:6", "chapterId": "MAT-28", "verseNumber": 6}, {"label": "Lk 24:5-7", "chapterId": "LUK-24", "verseNumber": 5}], "musicCredit": "'Easter Hymn' from Lyra Davidica, 1708", "number": 62}, {"title": "Jesus Christ Who Came to Save", "sectionId": 3, "wordsCredit": "Martin Luther, 1524. Translated by Leonard Woolsey Bacon, 1883", "verses": ["Jesus Christ, who came to save, And overcame the grave, Is now arisen, And sin hath bound in prison. Kyri' eleison.", "Who withouten sin was found, Bore our transgression's wound. He is our Savior, And brings us to God's favor. Kyri' eleison.", "Life and mercy, sin and death, All in His hands He hath; Them He'll deliver, Who trust in Him forever. Kyri' eleison."], "scriptureLinks": [{"label": "1Cor 15:25-26", "chapterId": "1CO-15", "verseNumber": 25}, {"label": "Rom 6:4-11", "chapterId": "ROM-6", "verseNumber": 4}, {"label": "Heb 4:15-16", "chapterId": "HEB-4", "verseNumber": 15}], "altTitle": "Jesus Christ Today is Risen or Jesus Christ Our Savior True or Jesus Christ, Our Blessed Savior", "musicCredit": "'Jesus Christus Unser Heiland, Der Den Tod (Klug)' from Klug's Geistliche Lieder, Wittenberg, 1533", "number": 63}, {"title": "Jesus Grant That Balm and Healing", "sectionId": 3, "wordsCredit": "Johann Heermann, 1644. Translation composite", "verses": ["Jesus, grant that balm and healing In Thy holy wounds I find, Every hour that I am feeling, Pains of body and of mind. Should some evil thought within Tempt my treacherous heart to sin, Show the peril, and from sinning Keep me ere its first beginning.", "Should some lust or sharp temptation Prove too strong for flesh and blood, Let me think upon Thy Passion, And the breach is soon made good. Or should Satan press me hard, Let me then be on my guard, Saying, \"Christ for me was wounded,\" That the tempter flee confounded.", "If the world my heart entices On the broad and easy road With its mirth and luring vices, Let me think upon the load Thou didst carry and endure That I flee all thoughts impure, Banishing each wild emotion, Calm and blest in my devotion.", "Every wound that pains or grieves me, By Thy stripes, Lord, is made whole; When I'm faint, Thy cross revives me, Granting new life to my soul. Yea, Thy comfort renders sweet Every bitter cup I meet; For Thy all atoning Passion Has procured my soul's salvation.", "O my God, my Rock and Tower, Grant that in Thy death I trust, Knowing death has lost his power Since Thou trodd'st him in the dust. Savior, let Thine agony Ever help and comfort me; When I die, be my Protection, Light and Life and Resurrection.", "Jesus, grant that balm and healing In Thy holy wounds I find, Every hour that I am feeling, Pains of body and of mind. And when I this world must leave, Grant that, Lord, to Thee I cleave, In Thy wounds find consolation And obtain my soul's salvation"], "scriptureLinks": [{"label": "1 Pt 2:24", "chapterId": "1PE-2", "verseNumber": 24}, {"label": "Is 53:4-5", "chapterId": "ISA-53", "verseNumber": 4}, {"label": "1Cor 10:13", "chapterId": "1CO-10", "verseNumber": 13}], "musicCredit": "'Der Am Kreuz' Johann Balthasar König, 1738", "number": 64}, {"title": "Jesus Is All the World To Me", "sectionId": 3, "wordsCredit": "Will L. Thompson, 1904", "verses": ["Jesus is all the world to me, My life, my joy, my all; He is my strength from day to day, Without Him I would fall. When I am sad, to Him I go, No other one can cheer me so; When I am sad, He makes me glad, He's my friend.", "Jesus is all the world to me, my friend in trials sore; I go to Him for blessings and He gives them ov'r and o'er. He sends the sunshine and the rain, He sends the harvest's golden grain; Sunshine and rain, harvest of grain, He's my friend.", "Jesus is all the world to me, and true to Him I'll be; O how could I this friend deny, when He's so true to me? Following Him I know I'm right, He watches o'er me day and night; Following Him, by day and night, He's my friend.", "Jesus is all the world to me, I want no better friend; I trust Him now, I'll trust Him when Life's fleeting days shall end. Beautiful life with such a friend; beautiful life that has no end; Eternal life, eternal joy, He's my friend."], "scriptureLinks": [{"label": "2Cor 1:20", "chapterId": "2CO-1", "verseNumber": 20}, {"label": "Jn 15:13", "chapterId": "JHN-15", "verseNumber": 13}, {"label": "Col 3:11", "chapterId": "COL-3", "verseNumber": 11}], "number": 65}, {"title": "Jesus, In Thy Dying Woes", "sectionId": 3, "wordsCredit": "Thomas B. Pollock, 1870", "verses": ["Jesus, in Thy dying woes, Even while Thy lifeblood flows, Craving pardon for Thy foes; Hear us, holy Jesus.", "Savior, for our pardon sue, When our sins Thy pangs renew, For we know not what we do: Hear us, holy Jesus.", "O may we, who mercy need, Be like Thee in heart and deed, When with wrong our spirits bleed: Hear us, holy Jesus.", "Jesus, pitying the sighs Of the thief, who near Thee dies, Promising him paradise; Hear us, holy Jesus.", "May we, in our guilt and shame, Still Thy love and mercy claim, Calling humbly on Thy Name: Hear us, holy Jesus.", "O remember us who pine, Looking from our cross to Thine; Cheer our souls with hope divine: Hear us, holy Jesus.", "Jesus, loving to the end Her whose heart Thy sorrows rend, And Thy dearest human friend: Hear us, holy Jesus.", "May we in Thy sorrows share, And for Thee all peril dare, And enjoy Thy tender care: Hear us, holy Jesus.", "May we all Thy loved ones be, All one holy family, Loving for the love of Thee, Hear us, holy Jesus.", "Jesus, whelmed in fears unknown, With our evil left alone, While no light from Heav'n is shown: Hear us, holy Jesus.", "When we vainly seem to pray, and our hope seems far away, In the darkness be our stay. Hear us, holy Jesus.", "Though no Father seem to hear, Though no light our spirits cheer, Tell our faith that God is near: Hear us, holy Jesus.", "Jesus, in Thy thirst and pain, While Thy wounds Thy lifeblood drain, Thirsting more our love to gain: Hear us, holy Jesus.", "Thirst for us in mercy still; All Thy holy work fulfill; Satisfy Thy loving will: Hear us, holy Jesus.", "May we thirst Thy love to know; Lead us in our sin and woe Where the healing waters flow: Hear us, holy Jesus.", "Jesus, all our ransom paid, All Thy Father's will obeyed, All Thy suff'rings perfect made: Hear us, holy Jesus.", "Save us in our soul's distress, Be our help to cheer and bless, While we grow in holiness: Hear us, holy Jesus.", "Brighten all our heavenward way, With an ever holier ray, Till we pass to perfect day: Hear us, holy Jesus.", "Jesus, all Thy labor vast, All Thy woe and conflict past, Yielding up Thy soul at last: Hear us, holy Jesus.", "When the death shades round us lower, Guard us from the temper's power, Keep us in that trial hour: Hear us, holy Jesus.", "May Thy life and death supply Grace to live and grace to die, Grace to reach the home on high: Hear us, holy Jesus."], "scriptureLinks": [{"label": "Lk 23:34", "chapterId": "LUK-23", "verseNumber": 34}, {"label": "Jn 19:26-27", "chapterId": "JHN-19", "verseNumber": 26}, {"label": "Mt 27:46", "chapterId": "MAT-27", "verseNumber": 46}], "musicCredit": "'Words on the Cross - The Litany' William H. Monk, 1889", "number": 66}, {"title": "Jesus, King of Glory", "sectionId": 3, "wordsCredit": "W. Hope Davison, 1880", "verses": ["Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry. Pardon our transgressions, cleanse us from our sin, By Thy Spirit help us heav'nly life to win. Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry.", "On this day of gladness, Bending low the knee In thine earthly temple, Lord, we worship thee; Celebrate thy goodness, Mercy, grace, and truth, All thy loving guidance Of our heedless youth. Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry.", "For the little children Who have come to thee; For the glad, bright spirits Who thy glory see; For the loved ones resting In thy dear embrace; For the pure and holy Who behold thy face, Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry.", "Help us ever steadfast in the faith to be: In Thy Church's conflicts fighting valiantly. Loving Savior, strengthen these weak hearts of ours, Through Thy cross to conquer crafty evil powers. Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry.", "When the shadows lengthen, show us, Lord, Thy way; Through the darkness lead us to the heav'nly day; When our course is finished, ended all the strife, Grant us, with the faithful, palms and crowns of life. Jesus, King of glory, throned above the sky, Jesus, tender Savior, hear Thy children cry.", "For thy faithful servants Who have entered in; For thy fearless soldiers Who have conquered sin; For the countless legions Who have followed thee, Heedless of the danger, On to victory,"], "scriptureLinks": [{"label": "Heb 12:1-15", "chapterId": "HEB-12", "verseNumber": 1}, {"label": "Mt 19:28", "chapterId": "MAT-19", "verseNumber": 28}, {"label": "Ps 24:8", "chapterId": "PSA-24", "verseNumber": 8}], "musicCredit": "'St. Alban' Franz Joseph Haydn, 1774", "number": 67}, {"title": "Jesus, Thy Boundless Love To Me", "sectionId": 3, "wordsCredit": "Paul Gerhardt, 1653. Translated by John Wesley, 1739", "verses": ["Jesus, Thy boundless love to me No thought can reach, no tongue declare; Unite my thankful heart with Thee And reign without a rival there. To Thee alone, dear Lord, I live; Myself to Thee, dear Lord, I give.", "O, grant that nothing in my soul May dwell but Thy pure love alone! Oh, may Thy love possess me whole, My joy, my treasure, and my crown! All coldness from my heart remove; My every act, word, thought, be love.", "O love, how cheering is thy ray! All pain before thy presence flies; Care, anguish, sorrow, melt away Where'er thy healing beams arise. O Jesus, nothing may I see, Nothing desire or seek, but Thee!", "This love unwearied I pursue And dauntlessly to Thee aspire. Oh, may Thy love my hope renew Burn in my soul like heav'nly fire! And day and night be all my care To guard this sacred treasure there.", "My Savior, Thou Thy love to me In shame, in want, in pain, hast showed; For me, on the accursed tree, Thou pourest forth Thy guiltless blood; Thy wounds upon my heart impress, Nor aught shall the lov'd stamp efface.", "More hard than marble is my heart, And foul with sins of deepest stain; But Thou the mighty Savior art, Nor flowed thy cleansing blood in vain; Ah soften, melt this rock, and may Thy blood wash all these stains away!", "O that I, as a little child, May follow Thee, and never rest Till sweetly Thou hast breathed Thy mild And lowly mind into my breast! Nor ever may we parted be, Till I become as one with Thee.", "Still let Thy love point out my way; How wondrous things Thy love hath wrought! Still lead me, lest I go astray; Direct my word, inspire my thought; And if I fall, soon may I hear Thy voice, and know that love is near.", "In suffering be Thy love my peace, In weakness be Thy love my power; And when the storms of life shall cease, Jesus, in that important hour, In death as life be Thou my guide, And save me, Who for me hast died."], "scriptureLinks": [{"label": "Eph 3:18", "chapterId": "EPH-3", "verseNumber": 18}, {"label": "Mt 6:19-21", "chapterId": "MAT-6", "verseNumber": 19}], "musicCredit": "'Yoakley' William Yoakley, 1820", "number": 68}, {"title": "Let All Mortal Flesh Keep Silence", "sectionId": 3, "wordsCredit": "from Liturgy of St. James, 4th Century. Translated by Gerard Moultrie, 1864", "verses": ["Let all mortal flesh keep silence, And with fear and trembling stand; Ponder nothing earthly minded, For with blessing in His hand, Christ our God to earth descendeth, Our full homage to demand.", "King of kings, yet born of Mary, As of old on earth He stood, Lord of lords, in human vesture, In the body and the blood; He will give to all the faithful His own self for heav'nly food.", "Rank on rank the host of heaven Spreads its vanguard on the way, As the Light of light descendeth From the realms of endless day, That the pow'rs of hell may vanish As the darkness clears away.", "At His feet the six wingèd seraph, Cherubim with sleepless eye, Veil their faces to the presence, As with ceaseless voice they cry: Alleluia, Alleluia Alleluia, Lord Most High!"], "scriptureLinks": [{"label": "Hab 2:20", "chapterId": "HAB-2", "verseNumber": 20}, {"label": "Acts 1:10-11", "chapterId": "ACT-1", "verseNumber": 10}, {"label": "1Thess 4:16-17", "chapterId": "1TH-4", "verseNumber": 16}], "musicCredit": "'Picardy' traditional French", "number": 69}, {"title": "Let Our Gladness Have No End", "sectionId": 3, "wordsCredit": "From the Kancional, by Tobias Zavorka, 1602. Translator unknown", "verses": ["Let our gladness have no end, Hallelujah! For to earth did Christ descend.", "See, the loveliest blooming rose, Hallelujah! From the branch of Jesse grows.", "Into flesh is made the Word. Hallelujah! He, our refuge and our Lord."], "scriptureLinks": [{"label": "Rom 5:11", "chapterId": "ROM-5", "verseNumber": 11}, {"label": "Rom 8:32-33", "chapterId": "ROM-8", "verseNumber": 32}, {"label": "Jn 1:14", "chapterId": "JHN-1", "verseNumber": 14}], "musicCredit": "'Narodil se Kristus Pán' or 'Salvator Natus' 15th Century Bohemian", "refrain": "Hallelujah! On this day God gave us Christ, His Son, to save us; Christ, His Son, to save us.", "number": 70}, {"title": "Lift Up Your Heads, Ye Mighty Gates", "sectionId": 3, "wordsCredit": "Georg Weissel, 1642. Translated by Catherine Winkworth, 1855", "verses": ["Lift up your heads, ye mighty gates! Behold, the King of glory waits; The King of kings is drawing near, The Savior of the world is here; Life and salvation doth He bring, Wherefore rejoice and gladly sing: We praise Thee, Father, now! Creator, wise art Thou!", "The Lord is just, a Helper tried, Mercy is ever at His side, His kingly crown is holiness, His scepter, pity in distress, The end of all our woe He brings; Wherefore the earth is glad and sings: We praise Thee, Savior, now! Mighty in deed art Thou!", "O blest the land, the city blest, Where Christ the Ruler is confessed! O happy hearts and happy homes To whom this King in triumph comes! The cloudless Sun of joy He is, Who bringeth pure delight and bliss. O Comforter divine, What boundless grace is Thine!", "Fling wide the portals of your heart; Make it a temple, set apart From earthly use for heav'ns employ, Adorned with prayer and love and joy; So shall your Sovereign enter in, and new and nobler life begin; To Thee, O God, be praise, For Word, and deed, and grace!", "Redeemer, come! I open wide My heart to Thee; here, Lord, abide! Let me Thy inner presence feel, Thy grace and love in me reveal. Thy Holy Spirit guide us on, Until our glorious goal be won! Eternal praise and fame We offer to Thy Name."], "scriptureLinks": [{"label": "Ps 24:7", "chapterId": "PSA-24", "verseNumber": 7}, {"label": "118:19-20", "chapterId": "PSA-118", "verseNumber": 19}, {"label": "Mt 3:1-3", "chapterId": "MAT-3", "verseNumber": 1}], "musicCredit": "'Milwaukee' or 'Macht hoch die Tür (Lemke)' August Lemke, 1849", "number": 71}, {"title": "Look, Ye Saints, The Sight Is Glorious", "sectionId": 3, "wordsCredit": "Thomas Kelly, 1809", "verses": ["Look, ye saints; the sight is glorious: see the Man of Sorrows now; From the fight returned victorious, Every knee to Him shall bow: Crown Him! Crown Him! Crown Him! Crowns become the Victor's brow. Crowns become the Victor's brow.", "Crown the Savior, angels, crown Him; Rich the trophies Jesus brings; In the seat of pow'r enthrone Him, While the vault of heaven rings: Crown Him! Crown Him! Crown Him! Crown the Savior King of kings. Crown the Savior King of kings.", "Sinners in derision crowned Him, Mocking thus the Savior's claim; Saints and angels crowd around Him, Own His title, praise His Name: Crown Him! Crown Him! Crown Him! Spread abroad the Victor's fame. Spread abroad the Victor's fame.", "Hark, those bursts of acclamation! Hark those loud triumphant chords! Jesus takes the highest station; O what joy the sight affords! Crown Him! Crown Him! Crown Him! King of kings, and Lord of lords! King of kings, and Lord of lords!"], "scriptureLinks": [{"label": "Rev 4:2-11", "chapterId": "REV-4", "verseNumber": 2}, {"label": "Ps 103:17-22", "chapterId": "PSA-103", "verseNumber": 17}, {"label": "Heb 1:8-9", "chapterId": "HEB-1", "verseNumber": 8}], "musicCredit": "'Bryn Calfaria' William Owen, 1852", "number": 72}, {"title": "Lord As To Thy Dear Cross", "sectionId": 3, "wordsCredit": "John Hampden Gurney, 1838", "verses": ["Lord, as to Thy dear cross we flee, And plead to be forgiv'n, So let Thy life our pattern be, And form our souls for heav'n.", "Help us, through good report and ill, Our daily cross to bear: Like Thee, to do our Father's will, Our brethren's grief to share.", "Let grace our selfishness expel, Our earthliness refine; And kindness in our bosoms dwell, As free and true as Thine.", "If joy shall at Thy bidding fly, And grief's dark day come on, We in our turn would meekly cry, \"Father, Thy will be done.\"", "Kept peaceful in the midst of strife, Forgiving and forgiv'n, O may we lead the pilgrim's life And follow Thee to heav'n."], "scriptureLinks": [{"label": "Ps 143:8-11", "chapterId": "PSA-143", "verseNumber": 8}, {"label": "Jer 9:7", "chapterId": "JER-9", "verseNumber": 7}, {"label": "Zech 13:9", "chapterId": "ZEC-13", "verseNumber": 9}], "musicCredit": "'St. Bernard (Richardson)' or 'St. Bernard (Tochter Sion)' from Tochter Sion, Cologne, 1741", "number": 73}, {"title": "Lord Jesus Think On Me", "sectionId": 3, "wordsCredit": "Synesius of Cyrene, circa 430. Translated by Allen W. Chatfield, 1876", "verses": ["Lord Jesus, think on me And purge away my sin; From earthborn passions set me free And make me pure within.", "Lord Jesus, think on me, With many'a care oppressed; Let me Thy loving servant be And taste Thy promised rest.", "Lord Jesus, think on me Amid the battle's strife; In all my pain and misery Be Thou my Health and Life.", "Lord Jesus, think on me Nor let me go astray; Through darkness and perplexity Point Thou the heav'nly way.", "Lord Jesus, think on me When floods the tempest high; When on doth rush the enemy, O Savior, be Thou nigh!", "Lord Jesus, think on me That, when the flood is past, I may th'eternal brightness see And share Thy joy at last.", "Lord Jesus, think on me That I may sing above To Father, Spirit, and to Thee The strains of praise and love."], "scriptureLinks": [{"label": "Ps 51:6-12", "chapterId": "PSA-51", "verseNumber": 6}, {"label": "Heb 4:15-16", "chapterId": "HEB-4", "verseNumber": 15}, {"label": "Ps 119:133", "chapterId": "PSA-119", "verseNumber": 133}], "musicCredit": "'Southwell' William Daman's Psalter, 1579", "number": 74}, {"title": "Moment By Moment", "sectionId": 3, "wordsCredit": "Daniel W. Whittle, 1893", "verses": ["Dying with Jesus, by death reckoned mine; Living with Jesus, a new life divine; Looking to Jesus till glory doth shine, Moment by moment, O Lord, I am Thine. Moment by moment I'm kept in His love; Moment by moment I've life from above; Looking to Jesus till glory doth shine; Moment by moment, O Lord, I am Thine.", "Never a trial that He is not there, Never a burden that He doth not bear, Never a sorrow that He doth not share, Moment by moment, I'm under His care. Moment by moment I've life from above; Looking to Jesus till glory doth shine; Moment by moment, O Lord, I am Thine.", "Never a heartache, and never a groan, Never a teardrop and never a moan; Never a danger but there on the throne, Moment by moment He thinks of His own. Moment by moment I've life from above; Looking to Jesus till glory doth shine; Moment by moment, O Lord, I am Thine.", "Never a weakness that He doth not feel, Never a sickness that He cannot heal; Moment by moment, in woe or in weal, Jesus my Savior, abides with me still. Moment by moment I've life from above; Looking to Jesus till glory doth shine; Moment by moment, O Lord, I am Thine."], "scriptureLinks": [{"label": "Mt 28:20", "chapterId": "MAT-28", "verseNumber": 20}, {"label": "Is 27:2-3", "chapterId": "ISA-27", "verseNumber": 2}, {"label": "41:10", "chapterId": "ISA-41", "verseNumber": 10}], "musicCredit": "'Whittle' May Whittle Moody, 1893", "number": 75}, {"title": "More Love to Thee", "sectionId": 3, "wordsCredit": "Elizabeth Payson Prentis, 1856", "verses": ["More love to Thee, O Christ; More love to Thee; Hear Thou the pray'r I make On bended knee; This is my earnest plea, More love, O Christ, to Thee, More love to Thee; More love to Thee.", "Once earthly joy I craved, Sought peace and rest; Now thee alone I seek, Give what is best; This all my pray'r shall be, More love, O Christ, to Thee, More love to Thee; More love to Thee.", "Then shall my latest breath, Whisper Thy praise, This be the parting cry My heart shall raise; This still its pray'r shall be, More love, O Christ, to Thee, More love to Thee; More love to Thee."], "scriptureLinks": [{"label": "Eph 6:24", "chapterId": "EPH-6", "verseNumber": 24}, {"label": "1 Jn 4:16-21", "chapterId": "1JN-4", "verseNumber": 16}, {"label": "2Thess 3:5", "chapterId": "2TH-3", "verseNumber": 5}], "musicCredit": "'More Love to Thee' William Howard Doane, 1870", "number": 76}, {"title": "My Jesus, As Thou Wilt", "sectionId": 3, "wordsCredit": "Benjamin Schmolck, circa 1704. Translated by Jane L. Borthwick, 1854", "verses": ["My Jesus, as Thou wilt! Oh, may Thy will be mine! Into Thy hand of love I would my all resign; Through sorrow, or through joy, conduct me as Thine own, And help me still to say, my Lord, Thy will be done!", "My Jesus, as Thou wilt! If needy here and poor, Give me Thy people's bread, their portion rich and sure. The manna of Thy Word Let my soul feed upon; And if all else should fail, my Lord, thy will be done!", "My Jesus, as Thou wilt! Though seen through many'a tear, Let not my star of hope grow dim or disappear; Since Thou on earth hast wept, and sorrowed oft alone, If I must weep with Thee, my Lord, Thy will be done!", "My Jesus, as Thou wilt! All shall be well for me; Each changing future scene I gladly trust with Thee: Straight to my home above I travel calmly on, And sing, in life or death, my Lord, Thy will be done!"], "scriptureLinks": [{"label": "Mt 6:10", "chapterId": "MAT-6", "verseNumber": 10}, {"label": "Ps 40:8", "chapterId": "PSA-40", "verseNumber": 8}, {"label": "Jn 6:40", "chapterId": "JHN-6", "verseNumber": 40}], "musicCredit": "'Jewett' or 'Weber' Carl M. von Weber, 1821", "number": 77}, {"title": "My Savior's Love", "sectionId": 3, "wordsCredit": "Charles H. Gabriel, 1905", "verses": ["I stand amazed in the presence Of Jesus the Nazarene, And wonder how He could love me, A sinner, condemn'd, unclean.", "For me it was in the garden He pray'd \"Not my will, but Thine;\" He had no tears for His own griefs, But sweat drops of blood for mine.", "In pity angels beheld Him, And came from the world of light To comfort Him in the sorrows, He bore for my soul that night.", "When with the ransomed in glory His face I at last shall see, 'Twill be my joy thro' the ages, To sing of His love for me."], "scriptureLinks": [{"label": "1 Jn 4:9-10", "chapterId": "1JN-4", "verseNumber": 9}, {"label": "Lk 22:41-44", "chapterId": "LUK-22", "verseNumber": 41}, {"label": "Eph 3:14-19", "chapterId": "EPH-3", "verseNumber": 14}], "altTitle": "I Stand Amazed in the Presence", "musicCredit": "'My Savior`s Love' or 'I Stand Amazed in the Presence' Charles H. Gabriel, 1905", "refrain": "How marvelous! how wonderful! And my song shall ever be: How marvelous! how wonderful! Is my Savior's love for me!", "number": 78}, {"title": "Nearer, My God, To Thee", "sectionId": 3, "wordsCredit": "st. 1-2 by Sarah F. Adams, 1841; st. 3-5 by Hervey D. Ganse (1822-1891); st. 6 by Edward H. Bickersteth, Jr. (1825-1906)", "verses": ["Nearer, my God, to Thee, nearer to Thee! E'en though it be a cross that raiseth me, Still all my song shall be, nearer, my God, to Thee. Nearer, my God, to Thee, Nearer to Thee!", "Though like the wanderer, the sun gone down, Darkness be over me, my rest a stone. Yet in my dreams I'd be nearer, my God to Thee. Nearer, my God, to Thee, Nearer to Thee!", "Nearer, my Lord, to thee, Nearer to thee! Who to the cross didst come, Dying for me! Strengthen my willing feet, Hold me in service sweet Nearer, my God, to Thee, Nearer to Thee!", "Nearer, O Comforter, Nearer to thee! Who with my loving Lord Dwellest with me! Grant me thy fellowship! Help me each day to keep Nearer, my God, to Thee, Nearer to Thee!", "But to be nearer still, Bring me, O God, Not by the visioned steeps Angels have trod. Here where thy cross I see, Jesus, I wait for thee, Then evermore to be Nearer to Thee!", "There in my Father's home, safe and at rest, There in my Savior's love, perfectly blest; Age after age to be, nearer my God to Thee. Nearer, my God, to Thee, Nearer to Thee!"], "scriptureLinks": [{"label": "Eph 2:13-22", "chapterId": "EPH-2", "verseNumber": 13}, {"label": "Heb 7:16-19", "chapterId": "HEB-7", "verseNumber": 16}], "musicCredit": "'Bethany' Lowell Mason, 1856", "number": 79}, {"title": "No, Not One!", "sectionId": 3, "wordsCredit": "Johnson Oatman, Jr, 1894", "verses": ["There's not a friend like the lowly Jesus, No, not one! no, not one! None else could heal all our soul's diseases, No, not one! no, not one!", "No friend like Him is so high and holy, No, not one! no, not one! And yet no friend is so meek and lowly, No, not one! no, not one!", "There's not an hour that He is not near us, No, not one! no, not one! No night so dark but His love can cheer us, No, not one! no, not one!", "Did ever saint find this friend forsake him? No, not one! no, not one! Or sinner find that He would not take him? No, not one! no, not one!", "Was e'er a gift like the Savior given? No, not one! no, not one! Will He refuse us a home in heaven? No, not one! no, not one!"], "scriptureLinks": [{"label": "Jn 15:13-15", "chapterId": "JHN-15", "verseNumber": 13}, {"label": "Is 41:8-10", "chapterId": "ISA-41", "verseNumber": 8}, {"label": "Mt 11:19", "chapterId": "MAT-11", "verseNumber": 19}], "musicCredit": "'No, Not One' George Crawford Hugg, 1894", "refrain": "Jesus knows all about our struggles, He will guide till the day is done; There's not a friend like the lowly Jesus, No, not one! no, not one!", "number": 80}, {"title": "O Come O Come Emmanuel", "sectionId": 3, "wordsCredit": "various, combined by unknown author approx 12th Century, Translated by John Mason Neale, 1851", "verses": ["O come, O come, Emmanuel, And ransom captive Israel, That mourns in lonely exile here Until the Son of God appear.", "O come, Thou Wisdom from on high, Who orderest all things mightily; To us the path of knowledge show, And teach us in her ways to go.", "O come, Thou Rod of Jesse, free Thine own from Satan's tyranny; From depths of hell Thy people save, And give them vict'ry ov'r the grave.", "O come, Thou Dayspring, come and cheer Our spirits by Thine advent here; Disperse the gloomy clouds of night, And death's dark shadows put to flight.", "O come, Thou Key of David, come, And open wide our heav'nly home; Make safe the way that leads on high, And close the path to misery."], "scriptureLinks": [{"label": "Is 7:14", "chapterId": "ISA-7", "verseNumber": 14}, {"label": "11:1", "chapterId": "ISA-11", "verseNumber": 1}, {"label": "Rev 22:20", "chapterId": "REV-22", "verseNumber": 20}], "musicCredit": "'Veni Emmanuel' 15th Century French processional", "refrain": "Rejoice! Rejoice! Emmanuel shall come to thee, O Israel.", "number": 81}, {"title": "O Lord, When Condemnation", "sectionId": 3, "wordsCredit": "Justus Gesenius, 1646. Translated by William Mercer, 1857", "verses": ["O Lord, when condemnation And guilt oppress my soul, Then let Thy bitter passion The rising storm control: Remind me that Thy blood was spilt For me, O most unworthy! To take away my guilt.", "O wonder passing measure To faith's enlightened eye! For slaves it was the pleasure Of their own Lord to die! The mighty God stoops from on high For me, lost, ruined creature, And deigns as man to die.", "My sins rise up to heaven, And countless is their lost; But Christ Himself hath given, And paid the mighty cost: Since then on Him my sins were laid, Of hell and all its torments, I am no more afraid.", "Henceforth my heart shall bless Thee Whilst here its pulses move; Its songs of praise address Thee For all Thy dying love: Thy wrongs and last deep agony Shall be my meditation Till I am called to Thee.", "Lord, let Thy bitter passion My soul with strength inspire To flee with indignation All sinful, low desire: Ah! never would I, Lord, forget The greatness of that ransom Which paid my endless debt.", "Should earthly griefs assail me, If need be, shame and scorn, Let patience never fail me To bear as Thou hast borne: Grant that the world I may forsake, And Thee for my example, Oh! may I daily take.", "Still let me do to others As Thou hast done to me, And look on all as brothers, Their willing servant be: O may I never seek my own, But help as Thou hast helped, With purest love alone.", "At length when I am bidden With all things here to part, The wounds in which I'm bidden Speak peace into my heart; Relying then upon Thy blood, O give me full assurance That I shall see my God."], "scriptureLinks": [{"label": "Eph 1:7-10", "chapterId": "EPH-1", "verseNumber": 7}, {"label": "Job 33:22-28", "chapterId": "JOB-33", "verseNumber": 22}, {"label": "Rom 5:19", "chapterId": "ROM-5", "verseNumber": 19}], "altTitle": "O Lord, When My Sins Grieve Me or When Guilt and Shame Are Raising or When O'er My Sins and Sorrow or When Sorrow and Remorse", "musicCredit": "'Wenn Mein Sünd' Michael Praetorius, 1609", "number": 82}, {"title": "O Sacred Head, Now Wounded", "sectionId": 3, "wordsCredit": "Bernard of Clairvaux, 1153. Translated by James W. Alexander, 1830", "verses": ["O sacred Head, now wounded, with grief and shame weighed down, Now scornfully surrounded with thorns, Thine only crown; O sacred Head, what glory, what bliss till now was Thine! Yet, though despised and gory, I joy to call Thee mine.", "What Thou, my Lord, hast suffered, was all for sinners' gain; Mine, mine was the transgression, but Thine the deadly pain. Lo, here I fall, my Savior! 'Tis I deserve Thy place; Look on me with Thy favor, vouchsafe to me Thy grace.", "Men mock and taunt and jeer Thee, Thou noble countenance, Though mighty worlds shall fear Thee and flee before Thy glance. How art thou pale with anguish, with sore abuse and scorn! How doth Thy visage languish that once was bright as morn!", "Now from Thy cheeks has vanished their color once so fair; From Thy red lips is banished the splendor that was there. Grim death, with cruel rigor, hath robbed Thee of Thy life; Thus Thou hast lost Thy vigor, Thy strength in this sad strife.", "My burden in Thy Passion, Lord, Thou hast borne for me, For it was my transgression which brought this woe on Thee. I cast me down before Thee, wrath were my rightful lot; Have mercy, I implore Thee; Redeemer, spurn me not!", "What language shall I borrow to thank Thee, dearest friend, For this Thy dying sorrow, Thy pity without end? O make me Thine forever, and should I fainting be, Lord, let me never, never outlive my love to Thee.", "My Shepherd, now receive me; my Guardian, own me Thine. Great blessings Thou didst give me, O source of gifts divine. Thy lips have often fed me with words of truth and love; Thy Spirit oft hath led me to heavenly joys above.", "Here I will stand beside Thee, from Thee I will not part; O Savior, do not chide me! When breaks Thy loving heart, When soul and body languish in death's cold, cruel grasp, Then, in Thy deepest anguish, Thee in mine arms I'll clasp.", "The joy can never be spoken, above all joys beside, When in Thy body broken I thus with safety hide. O Lord of Life, desiring Thy glory now to see, Beside Thy cross expiring, I'd breathe my soul to Thee.", "My Savior, be Thou near me when death is at my door; Then let Thy presence cheer me, forsake me nevermore! When soul and body languish, oh, leave me not alone, But take away mine anguish by virtue of Thine own!", "Be Thou my consolation, my shield when I must die; Remind me of Thy passion when my last hour draws nigh. Mine eyes shall then behold Thee, upon Thy cross shall dwell, My heart by faith enfolds Thee. Who dieth thus dies well."], "scriptureLinks": [{"label": "Ps 22:6-8", "chapterId": "PSA-22", "verseNumber": 6}, {"label": "Is 53:4-5", "chapterId": "ISA-53", "verseNumber": 4}, {"label": "Jn 10:14-15", "chapterId": "JHN-10", "verseNumber": 14}], "musicCredit": "'Passion Chorale' or 'Herzlich Tut Mich Verlangen' Hans Leo Hassler, 1601. Adapted by J.S. Bach, 1729", "number": 83}, {"title": "O The Deep, Deep Love of Jesus", "sectionId": 3, "wordsCredit": "S. Trevor Francis, 1875", "verses": ["O the deep, deep love of Jesus, vast, unmeasured, boundless, free! Rolling as a mighty ocean in its fullness over me! Underneath me, all around me, is the current of Thy love Leading onward, leading homeward to Thy glorious rest above!", "O the deep, deep love of Jesus, spread His praise from shore to shore! How He loveth, ever loveth, changeth never, nevermore! How He watches o'er His loved ones, died to call them all His own; How for them He intercedeth, watcheth o'er them from the throne!", "O the deep, deep love of Jesus, love of every love the best! 'Tis an ocean full of blessing, 'tis a haven giving rest! O the deep, deep love of Jesus, 'tis a heav'n of heav'ns to me; And it lifts me up to glory, for it lifts me up to Thee!"], "scriptureLinks": [{"label": "Eph 3:17-18", "chapterId": "EPH-3", "verseNumber": 17}, {"label": "Rom 11:33-36", "chapterId": "ROM-11", "verseNumber": 33}, {"label": "Ps 36:6", "chapterId": "PSA-36", "verseNumber": 6}], "musicCredit": "'Ebenezer' or 'Ton-Y-Botel' Thomas J. Williams, 1890", "number": 84}, {"title": "Oh, Blest the House", "sectionId": 3, "wordsCredit": "Christoph C. L. von Pfeil, 1735. Translated by Catherine Winkworth, 1863, alt", "verses": ["Oh blest the house, whate'er befall, Where Jesus Christ is All in All; Yea, if He were not dwelling there, How poor and dark and void it were!", "Oh blest that house where faith ye find, And all within have set their mind To trust their God and serve Him still, And do in all His holy will.", "Blest, where their prayers shall daily rise As fragrant incense to the skies, While in their lives the world is taught That forms without the heart are naught.", "Blest, where the busy hands fulfil Their proper task with ready skill, While through their different works ye see One spirit run of unity.", "Blest such a house, it prospers well, In peace and joy the parents dwell, And in their children's lot is shown How richly God can bless His own.", "Then here will I and mine to-day A solemn covenant make, and say,-- Though all the world forsake Thy Word, I and my house will serve the Lord."], "scriptureLinks": [{"label": "Josh 24:15", "chapterId": "JOS-24", "verseNumber": 15}, {"label": "Acts 16:31-34", "chapterId": "ACT-16", "verseNumber": 31}, {"label": "Ps 127:1", "chapterId": "PSA-127", "verseNumber": 1}], "musicCredit": "'Wo Gott Zum Haus' from Klug's Geistliche Lieder, 1533", "number": 85}, {"title": "One Thing's Needful", "sectionId": 3, "wordsCredit": "Johann H. Schröder, 1697. Translated by Frances E. Cox, 1841, alt", "verses": ["One thing's needful: then, Lord Jesus, Keep this one thing in my mind; All beside, though first it please us, Soon a grievous yoke we find: Beneath it the heart is still fretting and striving, No true, lasting happiness ever deriving. The gain of this one thing all loss can requite And teach me in all things to find true delight.", "Soul, wilt thou this one thing find thee? Seek not midst created things; What is earthly, leave behind thee, over nature stretch thy wings; For where God and man both in One are united, With God's perfect fullness the heart is delighted; There, there is the worthiest lot and the best, My One and my All, and my Joy, and my Rest.", "How were Mary's thoughts devoted, Her eternal joy to find, As intent each word she noted, At her Savior's feet reclined: How kindled her heart, how devout was its feeling, While hearing the lessons that Christ was revealing; For Jesus all earthly concerns she forgot, And all was repaid in that one happy lot.", "Thus my longings, heav'nward tending, Jesus, rest alone on Thee; Help me, thus on Thee depending, Savior! come and dwell in me: Although all the world should forsake and forget Thee, In love I will follow Thee, ne'er will I quit Thee; For Jesus, both Spirit and life is Thy Word, And is there a joy which Thou dost not afford?", "Wisdom's highest noblest treasure, Jesus, lies conceal'd in Thee; Grant that this may still the measure Of my will and actions be: Humility there and simplicity reigning, My steps shall in wisdom for ever be training; Oh! if I of Christ have this knowledge divine, The fullness of heavenly wisdom is mine.", "Christ, Thou art the sole oblation That I'll bring before my God; In his sight I've acceptation Only through Thy streaming blood: Immaculate righteousness now I've acquired, Since Thou on the tree of the cross hast expired; The robe of salvation for ever is mine, In this shall my faith through eternity shine.", "Let my soul, in full exemption, Wake up in Thy likeness now; Thou art made to me redemption, My sanctification Thou. Whatever I need for my Journey to Heaven In Thee, I my Savior, is unto me given. Oh! let me all perishing pleasures forgo, And Thy life, O Jesus! alone let me know.", "Where should else my hopes be centered? Grace o'erwhelms me with its flood; Thou, my Savior, once hast enter'd Holiest heaven through Thy blood: Eternal redemption for sinners there finding, From hell's dark dominion my spirit unbinding, To me perfect freedom Thy entrance has brought, And childlike to cry, \"Abba, Father,\" I'm taught.", "Christ Himself, my Shepherd, feeds me, Peace and joy my spirit fill; In a pasture green He leads me Forth beside the waters still: Oh! naught to my soul is so sweet and reviving, As thus unto Jesus alone to be living; True happiness this, and this only supplies, Through faith on my Savior to fasten my eyes.", "Therefore, Jesus, my Salvation, Thou my One, my All shalt be; Prove my fix'd determination, Root out all hypocrisy: Look well if on sin's slippery paths I am hasting, And lead me, O Lord, in the way everlasting; This one thing is needful, all others are vain, I count all but loss that I Christ may obtain."], "scriptureLinks": [{"label": "Lk 10:41-42", "chapterId": "LUK-10", "verseNumber": 41}, {"label": "Mk 4:19-20", "chapterId": "MRK-4", "verseNumber": 19}, {"label": "Phil 4:5-7", "chapterId": "PHP-4", "verseNumber": 5}], "musicCredit": "'Eins ist Not' Adam Krieger (1634-1666)", "number": 86}, {"title": "Over Kidron Jesus Treadeth", "sectionId": 3, "wordsCredit": "Thomas Hansen Kingo, 1689. Translated by J. Jeffrey, before 1866", "verses": ["Over Kidron Jesus treadeth To His passion for us all; Every human eye be weeping, Tears of bitter grief let fall! Round His Spirit flock the foes, Place their shafts and bend their bows, Aiming at the Savior solely, While the world forsakes Him wholly.", "David once, with heart afflicted, Crossed the Kidron's narrow strand, Clouds of gloom and grief about him When an exile from his land. But, O Jesus, blacker now Bends the cloud above Thy brow, Hasting to death's dreary portals For the shame and sin of mortals.", "See how, anguish struck, He falleth Prostrate, and with struggling breath, Three times on His God He calleth, Praying that the bitter death And the cup of doom may go, Still He cries, in all His woe: \"Not My will, but Thine, O Father!\" And the angels round Him gather.", "See how, in that hour of darkness, Battling with the evil pow'r, Agonies untold assail Him, On His soul the arrows show'r; All the garden flow'rs are wet With the drops of bloody sweat, From His anguished frame distilling— World's redemption thus fulfilling!", "But, O flow'rs, so sadly watered By this pure and precious dew, In some blessed hour your blossoms 'Neath the olive shadows grew! Eden's garden did not bear Aught that can with you compare, For the blood, thus freely given, Makes my soul the heir of heaven.", "When as flow'rs themselves I wither, When I droop and fade like grass, When the life-streams through my pulses Dull and ever duller pass, When at last they cease to roll, Then, to cheer my sinking soul, Grace of Jesus, be Thou given- Source of triumph! pledge of heaven!"], "scriptureLinks": [{"label": "Jn 18:1", "chapterId": "JHN-18", "verseNumber": 1}, {"label": "Lk 22:39-46", "chapterId": "LUK-22", "verseNumber": 39}, {"label": "Mk 14:32-42", "chapterId": "MRK-14", "verseNumber": 32}], "altTitle": "Over Kedron Jesus Treadeth or Over Cedron Jesus Treadeth", "musicCredit": "'Over Kedron Jesus Traeder' Ludvig Mathias Lindeman", "number": 87}, {"title": "Rejoice, O Pilgrim Throng", "sectionId": 3, "wordsCredit": "Edward H. Plumptre, 1865, alt", "verses": ["Rejoice, O pilgrim throng! Rejoice, give thanks, and sing; Your festal banner wave on high, The cross of Christ your King.", "With all the angel choirs, With all the saints of earth, Pour out the strains of joy and bliss, True rapture, noblest mirth.", "With voice as full and strong As ocean's surging praise, Send forth the hymns our fathers loved, The psalms of ancient days.", "Still lift your standard high, Still march in firm array, As warriors through the darkness toil, Till dawns the golden day.", "Yes, on through life's long path, Still chanting as ye go; From youth to age, by night and day, In gladness and in woe.", "Yes onward, onward still With hymn, and chant and song, Through gate, and porch and columned aisle, The hallowed pathways throng.", "At last the march shall end; The wearied ones shall rest; The pilgrims find their Father's house, Jerusalem the bless'd.", "Then on, ye pure in heart! Rejoice, give thanks, and sing; Your festal banner wave on high, The cross of Christ your King."], "scriptureLinks": [{"label": "Ps 100:1-5", "chapterId": "PSA-100", "verseNumber": 1}, {"label": "98:4-6", "chapterId": "PSA-98", "verseNumber": 4}, {"label": "32:11", "chapterId": "PSA-32", "verseNumber": 11}], "altTitle": "Rejoice Ye Pure in Heart", "musicCredit": "'Marion' Arthur H. Messiter, 1883", "refrain": "Rejoice, rejoice, rejoice, Give thanks and sing.", "number": 88}, {"title": "Ride On! Ride On in Majesty", "sectionId": 3, "wordsCredit": "Henry Hart Milman, 1827, alt", "verses": ["Ride on! Ride on in majesty! Hark! all the tribes hosanna cry; O Savior meek pursue Thy road With palms and scattered garments strewed.", "Ride on! Ride on in majesty! In lowly pomp ride on to die: O Christ Thy triumphs now begin O'er captive death and conquered sin.", "Ride on! Ride on in majesty! The angel armies of the sky Look down with sad and wond'ring eyes Too see th'aproaching sacrifice.", "Ride on! Ride on in majesty! Thy last and fiercest strife is nigh; The Father on His sapphire throne Expects His own anointed Son.", "Ride on! Ride on in majesty! In lowly pomp ride on to die: Bow Thy meek head to mortal pain, Then take, O God, Thy pow'r and reign."], "scriptureLinks": [{"label": "Zech 9:9", "chapterId": "ZEC-9", "verseNumber": 9}, {"label": "Mt 21:6-9", "chapterId": "MAT-21", "verseNumber": 6}, {"label": "Jn 12:12-15", "chapterId": "JHN-12", "verseNumber": 12}], "musicCredit": "'Winchester New' from \"Musikalisches Handbuch\", Hamburg, 1690", "number": 89}, {"title": "Savior Of The Nations Come", "sectionId": 3, "wordsCredit": "Ambrose of Milan, c. 397. Translated to German by Martin Luther, 1524. Translated from German to English by William M. Reynolds, 1851", "verses": ["Savior of the nations, come; Virgin's Son, here make Thy home! Marvel now, O heav'n and earth, That the Lord chose such a birth.", "Not by human flesh and blood; By the Spirit of our God Was the Word of God made flesh, Woman's offspring, pure and fresh.", "Wondrous birth! O wondrous Child Of the virgin undefiled! Though by all the world disowned, Still to be in heaven enthroned.", "From the Father forth He came And returneth to the same, Captive leading death and hell High the song of triumph swell!", "Thou, the Father's only Son, Hast o'er sin the vict'ry won. Boundless shall Thy kingdom be; When shall we its glories see?", "Brightly doth Thy manger shine, Glorious is its light divine. Let not sin o'ercloud this light; Ever be our faith thus bright.", "Praise to God the Father sing, Praise to God the Son, our King, Praise to God the Spirit be Ever and eternally."], "scriptureLinks": [{"label": "Ps 67:1-2", "chapterId": "PSA-67", "verseNumber": 1}, {"label": "Jn 1:1-4", "chapterId": "JHN-1", "verseNumber": 1}, {"label": "Lk 2:30-32", "chapterId": "LUK-2", "verseNumber": 30}], "musicCredit": "'Nun Komm, Der Heiden Heiland' from Walter's Geistliche Gesangbüchlein, 1524", "number": 90}, {"title": "Savior When In Dust To Thee", "sectionId": 3, "wordsCredit": "Robert Grant, 1815, alt", "verses": ["Savior, when in dust to Thee Low we bow th'adoring knee, When, repentant, to the skies Scarce we lift our weeping eyes, O by all the pains and woes Suffered once for man below, Bending from Thy throne on high, Hear our penitential cry!", "By Thy helpless infant years, By Thy life of want and tears, By Thy days of sore distress In the savage wilderness, By the dread mysterious hour Of th'insulting tempter's pow'r, Turn, O turn a fav'ring eye, Hear our penitential cry!", "By the sacred griefs that wept O'er the grave where Laz'rus slept, By the boding tears that flowed Over Salem's loved abode, By the anguished sigh that told Treachery lurked within Thy fold, From Thy seat above the sky, Hear our penitential cry!", "By Thine hour of dire despair, By Thine agony of prayer, By the cross, the nail, the thorn, Piercing spear, and torturing scorn, By the gloom that veiled the skies O'er the dreadful sacrifice, Listen to our humble cry, Hear our penitential cry!", "By Thy deep expiring groan, By the sad sepulchral stone, By the vault whose dark abode Held in vain the rising God, O from earth to heaven restored, Mighty, reascended Lord, Listen, listen to the sigh Of our penitential cry!"], "scriptureLinks": [{"label": "Ps 39:12", "chapterId": "PSA-39", "verseNumber": 12}, {"label": "Ez 18:30-32", "chapterId": "EZK-18", "verseNumber": 30}, {"label": "Lk 18:13", "chapterId": "LUK-18", "verseNumber": 13}], "musicCredit": "'Aberystwyth (Parry)' Joseph Parry, 1879", "number": 91}, {"title": "Savior, Like A Shepherd Lead Us", "sectionId": 3, "wordsCredit": "attr. Dorothy Ann Thrupp, 1836", "verses": ["Savior, like a shepherd lead us, much we need Thy tender care; In Thy pleasant pastures feed us, for our use Thy folds prepare. Blessèd Jesus, blessèd Jesus! Thou hast bought us, Thine we are. Blessèd Jesus, blessèd Jesus! Thou hast bought us, Thine we are.", "We are Thine, Thou dost befriend us, be the guardian of our way; Keep Thy flock, from sin defend us, seek us when we go astray. Blessèd Jesus, blessèd Jesus! Hear, O hear us when we pray. Blessèd Jesus, blessèd Jesus! Hear, O hear us when we pray.", "Thou hast promised to receive us, poor and sinful though we be; Thou hast mercy to relieve us, grace to cleanse and pow'r to free. Blessèd Jesus, blessèd Jesus! We will early turn to Thee. Blessèd Jesus, blessèd Jesus! We will early turn to Thee.", "Early let us seek Thy favor, early let us do Thy will; Blessèd Lord and only Savior, with Thy love our bosoms fill. Blessèd Jesus, blessèd Jesus! Thou hast loved us, love us still. Blessèd Jesus, blessèd Jesus! Thou hast loved us, love us still."], "scriptureLinks": [{"label": "Jn 10:3", "chapterId": "JHN-10", "verseNumber": 3}, {"label": "Ps 23", "chapterId": "PSA-11", "verseNumber": 5}, {"label": "Eph 2:4-5", "chapterId": "EPH-2", "verseNumber": 4}], "musicCredit": "'Bradbury' William B. Bradbury, 1859", "number": 92}, {"title": "Savior, Who Thy Flock Art Feeding", "sectionId": 3, "wordsCredit": "William Augustus Mühlenberg, 1826", "verses": ["Savior, who Thy flock art feeding With the Shepherd's kindest care, All the feeble gently leading, While the lambs Thy bosom share.", "Now, these little ones receiving, Fold them in Thy gracious arm; There, we know, Thy Word believing, Only there secure from harm.", "Never, from Thy pasture roving, Let them be the lion's prey; Let Thy tenderness, so loving, Keep them through life's dang'rous way.", "Then within Thy fold eternal Let them find a resting place, Feed in pastures ever vernal, Drink the rivers of Thy grace."], "scriptureLinks": [{"label": "Is 40:11", "chapterId": "ISA-40", "verseNumber": 11}, {"label": "Jn 10:1-18", "chapterId": "JHN-10", "verseNumber": 1}, {"label": "Ez 34:11-24", "chapterId": "EZK-34", "verseNumber": 11}], "musicCredit": "'Batty' or 'Ringe recht' from Johann Thommen's Musicalischer Christenschatz, Basel, 1745", "number": 93}, {"title": "Shepherd of Tender Youth", "sectionId": 3, "wordsCredit": "Clement of Alexandria, ca200. Translated by Henry Martyn Dexter, 1846, alt", "verses": ["Shepherd of tender youth, Guiding in love and truth, Through devious ways! Christ, our triumphant King! We come your Name to sing, And here our children bring, To shout your praise.", "You are our holy Lord! The all subduing Word! Healer of strife! You did yourself abase, That from sin's deep disgrace You might now save our race, And give us life.", "You are our soul's High Priest! You have prepared the feast Of holy love, And in our mortal pain None calls on you in vain, Our plea do not disdain, Help from above.", "O ever be our guide, Our Shepherd and our pride, Our staff and song! Jesus! O Christ of God! By your perennial Word Lead us where you have trod, Make our faith strong.", "So now, and till we die, Sound we your praises high, And joyful sing; Infants and the glad throng Who to your Church belong, Unite to swell the song To Christ, our King."], "scriptureLinks": [{"label": "Is 40:11", "chapterId": "ISA-40", "verseNumber": 11}, {"label": "Jn 10:11-15", "chapterId": "JHN-10", "verseNumber": 11}, {"label": "Ps 23:1-6", "chapterId": "PSA-23", "verseNumber": 1}], "altTitle": "Shepherd of Eager Youth", "musicCredit": "'Italian Hymn' Felice de Giardini, 1769", "number": 94}, {"title": "Sing My Tongue, The Glorious Battle", "sectionId": 3, "wordsCredit": "Venantius Fortunatus, 569. Translated by John M. Neale, 1851", "verses": ["Sing, my tongue, the glorious battle, With completed vict'ry rife, And above the cross's trophy Tell the triumph of the strife, How the world's Redeemer conquered By surrend'ring of His Life.", "God his Maker sorely grieving That the first born Adam fell, When he ate the noxious apple Whose reward was death and hell, Noted then this wood, the ruin Of the ancient wood to quell.", "For the work of our salvation Needs would have his order so, And the multiform deceiver's Art by art would overthrow. And from thence would bring the med'cine Whence the venom of the foe.", "Wherefore, when the sacred fullness Of th'appointed time was come, This world's Maker left His Father, Left His bright and heav'nly home, And proceeded, God Incarnate, From the virgin's holy womb.", "Weeps the Infant in the manger That in Bethl'hem's stable stands; And His limbs the virgin mother Doth compose in swad dling bands, Meetly thus in linen folding Of her God the feet and hands.", "Thirty years among us dwelling, His appointed time fulfilled; Giv'n for this, He meets His Passion, For that this He freely willed; On the Cross the Lamb is lifted, On Whose Death our hope we build.", "He endured the shame and spitting. Vinegar and nails and reed; As His Blessed Side is opened, Water thence and blood proceed: Earth, and sky, and stars, and ocean, By that flood are cleansed indeed.", "Faithful Cross! above all other One and only noble Tree! None in foliage, none in blossom, None in fruit compares with Thee: Sweetest wood, and sweetest iron, Sweetest weight sustaining free.", "Bend thy boughs, O Tree of Glory! Thy relaxing sinews bend; For awhile the ancient rigour That thy birth bestowed, suspend: And the King of Heavenly Beauty On thy bosom gently tend.", "Thou alone wast counted worthy This world's ransom to uphold; For a shipwrecked world preparing Harbor, like the Ark of old; With the sacred Blood anointed From the wounded Lamb that rolled.", "Laud and honor to the Father, Laud and honor to the Son, Laud and honor to the Spirit, Ever Three and ever One: Consubstantial, co-eternal, While unending ages run."], "scriptureLinks": [{"label": "Ex 15:1-2", "chapterId": "EXO-15", "verseNumber": 1}, {"label": "Is 52:9-10", "chapterId": "ISA-52", "verseNumber": 9}, {"label": "Is 53:12", "chapterId": "ISA-53", "verseNumber": 12}], "altTitle": "Sing My Tongue the Savior's Battle", "musicCredit": "'Pange Lingua', Proper Sarum Melody, alt", "number": 95}, {"title": "Sing, O Sing, This Blessed Morn", "sectionId": 3, "wordsCredit": "Christopher Wordsworth, 1865", "verses": ["Sing, O sing, this blessed morn, Unto us a Child is born, Unto us a Son is giv'n, God Himself comes down from Heav'n. Sing, O sing, this blessed morn, Jesus Christ today is born.", "Jesus Christ, the King of kings, Maker of all worldly things, Now descends from Heav'n to Earth, To re-store us by His birth; Sing, O sing, this blessed morn, Jesus Christ today is born.", "God of God, and Light of Light, Comes with mercies infinite; Joining in a wondrous plan Heav'n to earth and God to Man; Sing, O sing, this blessed morn, Jesus Christ today is born.", "God with us, Emmanuel, Deigns for ever now to dwell; He on Adam's fallen race Sheds the fullness of His Grace; Sing, O sing, this blessed morn, Jesus Christ today is born.", "Truth and Mercy show their face, And with loving kiss embrace; Righteousness looks down from Heav'n, God is pleased and Man forgiv'n; Sing, O sing, this blessed morn, Jesus Christ today is born.", "God comes down that man may rise, Lifted far above the skies He is Son of Man, that we Sons of God in Him may be;", "Human flesh is now become Christ's abode, the Godhead's home; Royal Palace, sacred shrine For the Majesty Divine;", "Now we rise, from prison free; On we march to victory, Joyful banners are unfurled; 'Tis the Birthday of the World;", "Now behold the rising Sun Hath His glorious race begun; Now the Bridegroom from above Weds the Bride, with heavenly love;", "O renew us, Lord, we pray, With Thy Spirit day by day; That we ever one may be With the Father, and with Thee;", "Sing, O sing this blessed Morn, Jesus Christ to-day is born; Glory to the Father give, Praise the Son in whom we live; Glory to the Spirit be, Godhead One, and Persons Three."], "scriptureLinks": [{"label": "Is 9:6", "chapterId": "ISA-9", "verseNumber": 6}, {"label": "Jn 1:1-3", "chapterId": "JHN-1", "verseNumber": 1}, {"label": "8:12", "chapterId": "JHN-8", "verseNumber": 12}], "musicCredit": "'Nativity' William Henry Monk, 1865", "number": 96}, {"title": "Souls of Men! Why Will Ye Scatter", "sectionId": 3, "wordsCredit": "Frederick William Faber, 1862, alt", "verses": ["Souls of men! why will ye scatter Like a crowd of frightened sheep? Foolish hearts! why will ye wander From a love so true and deep? Was there ever kinder shepherd Half so gentle, half so sweet, As the Savior who would have us Come and gather round His feet?", "It is God: His love looks mighty, But is mighti'r than it seems; 'Tis our Father: and His fondness Goes far out beyond our dreams. There's a wideness in God's mercy, Like the wideness of the sea; There's a kindness in His justice, Which is more than liberty.", "There is no place where earth's sorrows Are more felt than up in Heav'n; There is no place where earth's failings Have such wondrous judgment giv'n. There is welcome for the sinner, Grace poured out as in a flood There is mercy with the Savior; There is healing in His blood.", "There is grace enough for thousands Of new worlds as great as this; There is room for fresh creations In that upper home of bliss. For the love of God is broader Than the measure of man's mind; And the heart of the Eternal Is most wonderfully kind.", "There is plentiful redemption In Christ's blood that has been shed; There is joy for all the members In the sorrows of the Head. Not just all we owe to Jesus; It is something more than all; Greater good because of evil, Larger mercy through the fall."], "scriptureLinks": [{"label": "Ps 103:1-22", "chapterId": "PSA-103", "verseNumber": 1}, {"label": "Ps 23:1-6", "chapterId": "PSA-23", "verseNumber": 1}, {"label": "Zech 13:7-9", "chapterId": "ZEC-13", "verseNumber": 7}], "altTitle": "There's a Wideness in God's Mercy", "musicCredit": "'In Babilone' traditional Dutch found in \"Oude en Nieuwe Hollantse Boerenlities en Contradansen\", 1710", "number": 97}, {"title": "The Church's One Foundation", "sectionId": 3, "wordsCredit": "Samuel John Stone, 1866", "verses": ["The Church's one foundation Is Jesus Christ her Lord, She is His new creation By water and the Word. From heav'n He came and sought her To be His holy bride; With His own blood He bought her And for her life He died.", "She is from every nation, Yet one o'er all the earth; Her charter of salvation, One Lord, one faith, one birth; One holy Name she blesses, Partakes one holy food, And to one hope she presses, With every grace endued.", "The Church shall never perish! Her dear Lord to defend, To guide, sustain, and cherish, Is with her to the end: Though there be those who hate her, And false sons in her pale, Against or foe or traitor She ever shall prevail.", "Though with a scornful wonder Men see her sore oppressed, By schisms rent asunder, By heresies distressed: Yet saints their watch are keeping, Their cry goes up, 'How long?' And soon the night of weeping Shall be the morn of song!", "'Mid toil and tribulation, And tumult of her war, She waits the consummation Of peace forevermore; Till, with the vision glorious, Her longing eyes are blest, And the great Church victorious Shall be the Church at rest.", "Yet she on earth hath union With God the Three in One, And mystic sweet communion With those whose rest is won, With all her sons and daughters Who, by the Master's hand Led through the deathly waters, Repose in Eden land.", "O happy ones and holy! Lord, give us grace that we Like them, the meek and lowly, On high may dwell with Thee: There, past the border mountains, Where in sweet vales the Bride With Thee by living fountains Forever shall abide!"], "scriptureLinks": [{"label": "1Cor 3:11", "chapterId": "1CO-3", "verseNumber": 11}, {"label": "Mt 27:24-25", "chapterId": "MAT-27", "verseNumber": 24}, {"label": "Lk 6:47-49", "chapterId": "LUK-6", "verseNumber": 47}], "musicCredit": "'Aurelia' Samuel Sebastian Wesley, 1864", "number": 98}, {"title": "The Grave Itself a Garden Is", "sectionId": 3, "wordsCredit": "Christopher Wordsworth, 1862, alt", "verses": ["The grave itself a garden is, Where loveliest flow'rs abound; Since Christ, our never fading Life, Sprang from that holy ground.", "O give us grace to die to sin, That we, O Lord, may have A holy, happy rest in Thee, A Sabbath in the grave.", "Thou, Lord, baptized in Thine own blood, And buried in the grave, Didst raise Thyself to endless life, Omnipotent to save.", "Baptized into Thy death we died, And buried were with Thee, That we might live with Thee to God, And ever blest might be.", "Lord, through the grave and gate of death May we, with Thee, arise To an eternal Easter day Of glory in the skies!"], "scriptureLinks": [{"label": "Rom 6:3-11", "chapterId": "ROM-6", "verseNumber": 3}, {"label": "1Cor 15:35-44", "chapterId": "1CO-15", "verseNumber": 35}, {"label": "Col 2:11-15", "chapterId": "COL-2", "verseNumber": 11}], "altTitle": "Upon the Sixth Day of the Week", "musicCredit": "'Belmont' William Gardiner, 1812", "number": 99}, {"title": "The Kingdom Satan Founded", "sectionId": 3, "wordsCredit": "Thomas Hansen Kingo, 1689. Translated by Carl Døving, 1908", "verses": ["The kingdom Satan founded Shall now be overthrown, For Christ its fall hath sounded, And through His pow'r alone Shall Satan meet his doom, And be for aye confounded; He from the souls he wounded Shall flee in fear and gloom.", "Though he would bind forever Our lips with bands of hell, Yet Christ, sent to deliver, Can loose those bands full well, That e'en the dumb may raise His voice with joy and pleasure And sing in sweetest measure To God his thanks and praise.", "O Jesus! my distresses To Thee are known full well, Thou seest how Satan presses My soul's weak citadel; His aim is to control My members and my senses, With sin and with offenses He steals into my soul.", "Anon my tongue he bindeth That God it shall not praise; Anon my eyes he blindeth To hide the light of grace; Now he my ears doth close To hinder me from hearing The Gospel's sound so cheering And soothing in my woes.", "To God I raise my crying Before the mercy seat, And on His Word relying I grace of Him entreat, That He for Jesus' sake Would cleanse my soul and spirit Through Jesus' blood and merit, And Satan's power break.", "God, let not love of sinning Thy fear drive from my breast, Lest Satan, triumph winning, Be of my heart possessed; O let Thy chas'tning rod Each day give me direction, To seek Thy sure protection And tell Thy grace abroad.", "My heart must Thou have solely, My Savior and my God! Come, Jesus, take it wholly, And make it Thine abode! Mold it to Thy control, That I, Thy Word receiving, May find, in Thee believing, Salvation for my soul."], "scriptureLinks": [{"label": "Lk 10:17-20", "chapterId": "LUK-10", "verseNumber": 17}, {"label": "Jn 12:30-32", "chapterId": "JHN-12", "verseNumber": 30}, {"label": "Rev 20:9-10", "chapterId": "REV-20", "verseNumber": 9}], "musicCredit": "'Au Meines Herzens Grunde' or 'I Døden Jesus Blunded' or 'Jeg Vil Din Pris Udsjunge', David Wolder, 1598", "number": 100}, {"title": "The Lily of the Valley", "sectionId": 3, "wordsCredit": "C. W. Fry, 1881, alt", "verses": ["I've found a friend in Jesus, He's everything to me, He's the fairest of ten thousand to my soul; The Lily of the Valley, in Him alone I see All I need to cleanse and make me fully whole. In sorrow He's my comfort, in trouble He's my stay; He tells me every care on Him to roll.", "He all my grief has taken, and all my sorrows borne; In temptation He's my strong and mighty tow'r; I'll all for Him forsake now, I'll all my idols tear From my heart for now He keeps me by His pow'r. Though all the world forsake me, and Satan tempt me sore, Through Jesus I shall safely reach the goal.", "He'll never, never leave me, nor yet forsake me here, So I live by faith and do His blessed will; A wall of fire about me, I've nothing now to fear, With His manna He my hungry soul shall fill. When crown'd at last in glory, I'll see His blessed face, Where rivers of delight shall ever roll."], "scriptureLinks": [{"label": "Hos 14:4-9", "chapterId": "HOS-14", "verseNumber": 4}, {"label": "Rev 22:16", "chapterId": "REV-22", "verseNumber": 16}, {"label": "Jn 3:29", "chapterId": "JHN-3", "verseNumber": 29}], "altTitle": "I've Found a Friend in Jesus", "musicCredit": "'Salvation' or 'The Lily of the Valley' William S. Hays, 1881", "refrain": "He's the Lily of the Valley, the Bright and Morning Star, He's the fairest of ten thousand to my soul.", "number": 101}, {"title": "The Winds and Billows Loudly Roar", "sectionId": 3, "wordsCredit": "Christopher Wordsworth, 1865", "verses": ["The winds and billows loudly roar We flounder in the deep Our bark is frail, far off the shore, And Jesus is asleep.", "\"Save us, we perish, Lord,\" they cry; To Thee we fly for aid; \"Awake! awake!\" they say; but why So faithless and afraid?", "His head is pillow'd on the stern, As Man He is asleep; As God He all things does discern, And endless vigils keep.", "He does the elements control; By His Almighty Will. The angry waves their surges roll; And at His Word are still.", "O ye, who in the Church's Bark O'er life's rough ocean sail, When all around is drear and dark, and human efforts fail,", "Touch not, with rude, irreverent hands, And coward faithlessness, Him, who the winds and waves commands; But wait in quietness.", "O never, never when distressed, To doubtful means resort; Christ's Bark, when on the billow's crest, Is safe as in the port."], "scriptureLinks": [{"label": "Mt 8:23-27", "chapterId": "MAT-8", "verseNumber": 23}, {"label": "Mk 4:35-41", "chapterId": "MRK-4", "verseNumber": 35}, {"label": "Ps 89:9", "chapterId": "PSA-89", "verseNumber": 9}], "musicCredit": "'Consolation' or 'Morning Song' John Wyeth, 1813", "number": 102}, {"title": "Though in the Midst of Life We Be", "sectionId": 3, "wordsCredit": "v.1 Medieval sequence, vs 2,3 Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["Though in midst of life we be, Snares of death surround us; Where shall we for succor flee, Lest our foes confound us? To Thee alone, our Savior. We mourn our grievous sin which hath Stirr'd the fire of Thy fierce wrath. Holy and gracious God! Holy and mighty God! Holy and all— merciful Savior! Thou eternal God! Save us, Lord, from sinking In the deep and bitter flood. Kyrie eleison.", "Whilst in midst of death we be, Hell's grim jaws o'ertake us; Who from such distress will free. Who secure will make us? Thou only, Lord, canst do it! It moves Thy tender heart to see Our great sin and misery. Holy and gracious God! Holy and mighty God! Holy and all— merciful Savior! Thou eternal God! Let not hell dismay us With its deep and burning flood. Kyrie eleison.", "Into hell's fierce agony Sin doth headlong drive us: Where shall we for succor flee, Who, O, who will hide us? Thou only, blessed Saviour. Thy precious blood was shed to win Peace and pardon for our sin. Holy and gracious God! Holy and mighty God! Holy and all— merciful Savior! Let us not, we pray, From the true faith's comfort Fall in our last need away. Kyrie eleison."], "scriptureLinks": [{"label": "1Sam 20:3", "chapterId": "1SA-20", "verseNumber": 3}, {"label": "Rom 14:7-8", "chapterId": "ROM-14", "verseNumber": 7}, {"label": "2Cor 1:9-10", "chapterId": "2CO-1", "verseNumber": 9}], "altTitle": "In the Midst of Earthly Life or In the Very Midst of Life or In the Midst of Life We Are", "musicCredit": "'Mitten wir im Leben Sind' Medieval sequence altered by Martin Luther. Found in Walter's Geistliche Gesangbüchlein, 1524", "number": 103}, {"title": "To Jordan Came Our Lord, The Christ", "sectionId": 3, "wordsCredit": "Martin Luther, 1541. Translated by Richard Massie, 1854", "verses": ["To Jordan came our Lord the Christ, To do God's pleasure willing, And there was by Saint John baptized, All righteousness fulfilling; There did He consecrate a bath To wash away transgression, And quench the bitterness of death By His own blood and passion; He would a new life give us.", "So hear ye all, and well perceive What God doth call baptism, And what a Christian should believe Who error shuns and schism: That we should water use, the Lord Declareth it His pleasure; Not simple water, but the Word And Spirit without measure; He is the true Baptizer.", "To show us this, He hath His Word With signs and symbols given; On Jordan's banks was plainly heard The Father's voice from Heaven: \"This is My well— beloved Son, In whom My soul delighteth; Hear Him.\" Yea, hear Him every one Whom He Himself inviteth, Hear and obey His teaching.", "In tender manhood Jesus straight To holy Jordan wendeth; The Holy Ghost from Heaven's gate In dovelike shape descendeth; That thus the truth be not denied, Nor should our faith e'er waver, That the Three Persons all preside, At baptism's holy laver, And dwell with the believer.", "Thus Jesus His disciples sent: Go teach ye every nation, That lost in sin they must repent; And flee from condemnation: He that believes and is baptized, Obtains a mighty blessing; A newborn man, no more he dies, Eternal life possessing, A joyful heir of Heaven.", "Who in this mercy hath not faith, Nor aught therein discerneth, Is yet in sin, condemned to death, And fire that ever burneth; His holiness avails him not, Nor aught which he is doing; His inborn sin brings all to naught, And maketh sure his ruin; Himself he cannot succor.", "The eye of sense alone is dim, And nothing sees but water; Faith sees Christ Jesus, and in Him The Lamb ordained for slaughter; She sees the cleansing fountain red With the dear blood of Jesus, Which from the sins inherited From fallen Adam frees us, And from our own misdoings."], "scriptureLinks": [{"label": "Mt 3:13-17", "chapterId": "MAT-3", "verseNumber": 13}, {"label": "Mk 1:7-11", "chapterId": "MRK-1", "verseNumber": 7}, {"label": "Lk 3:15-22", "chapterId": "LUK-3", "verseNumber": 15}], "musicCredit": "'Christ, Unser Herr' Johann Walter, 1524", "number": 104}, {"title": "Today Thy Mercy Calls Me", "sectionId": 3, "wordsCredit": "Oswald Allen, 1861, alt", "verses": ["Today Thy mercy calls me to wash away my sin; However great my trespass, whate'er I may have been; However long from mercy I may have turned away, Thy blood, O Christ, can wash me, and make me clean today.", "Today Thy gate is open, and all who enter in Shall find a Father's welcome, and pardon for their sin; The past shall be forgotten, a present joy be given; A future grace be promised, a glorious crown in Heav'n.", "Today the Father calls me, the Holy Spirit waits, The blessèd angels gather around the heav'nly gates; No question will be asked me, how often I have come; Although I oft have wandered, it is my Father's home.", "O all embracing mercy, thou ever open door, What shall I do without thee when heart and eyes run o'er? When all things seem against me, to drive me to despair, I know one gate is open, one ear will hear my prayer."], "scriptureLinks": [{"label": "Is 1:18", "chapterId": "ISA-1", "verseNumber": 18}, {"label": "Lk 15:20-24", "chapterId": "LUK-15", "verseNumber": 20}, {"label": "Heb 9:14", "chapterId": "HEB-9", "verseNumber": 14}], "altTitle": "Today Your Mercy Calls Us", "musicCredit": "'Anthes' Friedrich K. Anthes, 1847", "number": 105}, {"title": "We Know Thee Who Thou Art", "sectionId": 3, "wordsCredit": "William Bright, 1865", "verses": ["We know Thee who Thou art, Lord Jesus, Mary's Son; We know the yearnings of Thy heart To end Thy work begun.", "That sacred fount of grace, 'Mid all the bliss of Heav'n, Has joy whene'er we seek Thy face, And kneel to be forgiv'n.", "Brought home from ways perverse, At peace Thine arms within, We pray Thee, shield us from the curse Of falling back to sin.", "We dare not ask to live Henceforth from trials free; But oh! when next they tempt us, give More strength to cling to Thee.", "We know Thee who Thou art, Our own redeeming Lord; Be Thou by will, and mind, and heart, Accepted, loved, adored."], "scriptureLinks": [{"label": "Heb 2:14-15", "chapterId": "HEB-2", "verseNumber": 14}, {"label": "13:20-21", "chapterId": "HEB-13", "verseNumber": 20}, {"label": "Phil 1:6", "chapterId": "PHP-1", "verseNumber": 6}], "altTitle": "Prayer After Pardon", "musicCredit": "'Sellinge' John Pyke Hullah, 1868", "number": 106}, {"title": "Were You There?", "sectionId": 3, "wordsCredit": "African-American Spiritual, before 1899", "verses": ["Were you there when they crucified my Lord? Were you there when they crucified my Lord? Sometimes it causes me to tremble, tremble, tremble. Were you there when they crucified my Lord?", "Were you there when they nailed Him to the tree? Were you there when they nailed Him to the tree? Sometimes it causes me to tremble, tremble, tremble. Were you there when they nailed Him to the tree?", "Were you there when they pierced Him in the side? Were you there when they pierced Him in the side? Oh! Sometimes it causes me to tremble, tremble, tremble. Were you there when they pierced Him in the side?", "Were you there when the sun refused to shine? Were you there when the sun refused to shine? Sometimes it causes me to tremble, tremble, tremble. Were you there when the sun refused to shine?", "Were you there when they laid Him in the tomb? Were you there when they laid Him in the tomb? Sometimes it causes me to tremble, tremble, tremble. Were you there when they laid Him in the tomb?", "Were you there when God raised Him from the tomb? Were you there when God raised Him from the tomb? Oh! Sometimes it causes me to tremble, tremble, tremble. Were you there when God raised Him from the tomb?"], "scriptureLinks": [{"label": "Mt 27:55-56", "chapterId": "MAT-27", "verseNumber": 55}, {"label": "Jn 19:34", "chapterId": "JHN-19", "verseNumber": 34}, {"label": "Lk 23:44-45", "chapterId": "LUK-23", "verseNumber": 44}], "musicCredit": "'Were You There' African-American Spiritual, before 1899", "number": 107}, {"title": "What A Friend We Have In Jesus", "sectionId": 3, "wordsCredit": "Joseph M. Scriven, 1855", "verses": ["What a Friend we have in Jesus, all our sins and griefs to bear! What a privilege to carry everything to God in prayer! O what peace we often forfeit, O what needless pain we bear, All because we do not carry everything to God in prayer.", "Have we trials and temptations? Is there trouble anywhere? We should never be discouraged; take it to the Lord in prayer. Can we find a friend so faithful who will all our sorrows share? Jesus knows our every weakness; take it to the Lord in prayer.", "Are we weak and heavy laden, cumbered with a load of care? Precious Savior, still our refuge, take it to the Lord in prayer. Do your friends despise, forsake you? Take it to the Lord in prayer! In His arms He'll take and shield you; you will find a solace there.", "Blessed Savior, Thou hast promised Thou wilt all our burdens bear May we ever, Lord, be bringing all to Thee in earnest prayer. Soon in glory bright unclouded there will be no need for prayer Rapture, praise and endless worship will be our sweet portion there."], "scriptureLinks": [{"label": "Jn 15:13", "chapterId": "JHN-15", "verseNumber": 13}, {"label": "Mt 7:7-8", "chapterId": "MAT-7", "verseNumber": 7}, {"label": "Heb 4:15", "chapterId": "HEB-4", "verseNumber": 15}], "musicCredit": "'untitled' Charles C. Converse, 1868", "number": 108}, {"title": "What Is the World to Me?", "sectionId": 3, "wordsCredit": "Georg M. Pfefferkorn, 1667. Translated by August Crull, 1893, alt", "verses": ["What is the world to me With all its vaunted pleasure When Thou, and Thou alone, Lord Jesus, art my Treasure! Thou only, dearest Lord, My soul's Delight shalt be; Thou art my Peace, my Rest, What is the world to me!", "The world is like a cloud And like a vapor fleeting, A shadow that declines, Swift to its end retreating. My Jesus doth abide, Though all things fade and flee; My everlasting Rock, What is the world to me!", "The world seeks to be praised And honored by the mighty, Yet never once reflects That they are frail and flighty. But what I truly prize Above all things is He, My Jesus, He alone, What is the world to me!", "The world seeks after wealth And all that mammon offers, Yet never is content Though gold should fill its coffers. I have a higher good, Content with it I'll be: My Jesus is my Wealth, What is the world to me!", "The world is sorely grieved Whenever it is slighted Or when its hollow fame And honor have been blighted. Christ, Thy reproach I bear Long as it pleaseth Thee; I'm honored by my Lord, What is the world to me!", "The world with wanton pride Exalts its sinful pleasures And for them foolishly Gives up the heavenly treasures. Let others love the world With all its vanity; I love the Lord, my God, What is the world to me!", "The world abideth not; Lo, like a flash 'twill vanish; With all it gorgeous pomp Pale death it cannot banish; Its riches pass away, And all its joys must flee; But Jesus doth abide, What is the world to me!", "What is the world to me! My Jesus is my Treasure, My Life, my Health, my Wealth, My Friend, my Love, my Pleasure, My Joy, my Crown, my All, My Bliss eternally. Once more, then, I declare: What is the world to me!"], "scriptureLinks": [{"label": "Mt 6:25-34", "chapterId": "MAT-6", "verseNumber": 25}, {"label": "1 Jn 2:15-17", "chapterId": "1JN-2", "verseNumber": 15}, {"label": "Phil 3:7-9", "chapterId": "PHP-3", "verseNumber": 7}], "musicCredit": "'Was Frag Ich Nach Der Welt' Ahasverus Fritsch, 1679", "number": 109}, {"title": "When I Survey the Wondrous Cross", "sectionId": 3, "wordsCredit": "Isaac Watts, 1707", "verses": ["When I survey the wondrous cross On which the Prince of Glory died, My rich-est gain I count but loss, And pour contempt on all my pride.", "Forbid it, Lord, that I should boast, Save in the death of Christ my God! All the vain things that charm me most, I sacrifice them to His blood.", "See from His head, His hands, His feet, Sorrow and love flow mingled down! Did e'er such love and sorrow meet, Or thorns compose so rich a crown?", "His dying crimson, like a robe, Spreads o'er His body on the tree; Then I am dead to all the globe, And all the globe is dead to me.", "Were the whole realm of nature mine, That were a present far too small; Love so amazing, so divine, Demands my soul, my life, my all."], "scriptureLinks": [{"label": "Gal 6:14", "chapterId": "GAL-6", "verseNumber": 14}, {"label": "Rom 7:24", "chapterId": "ROM-7", "verseNumber": 24}], "musicCredit": "'Duke Street' John Hatton, 1793", "number": 110}, {"title": "When I Survey the Wondrous Cross", "sectionId": 3, "wordsCredit": "Isaac Watts, 1707", "verses": ["When I survey the wondrous cross On which the Prince of Glory died, My richest gain I count but loss, And pour contempt on all my pride.", "Forbid it, Lord, that I should boast, Save in the death of Christ my God! All the vain things that charm me most, I sacrifice them to His blood.", "See from His head, His hands, His feet, Sorrow and love flow mingled down! Did e'er such love and sorrow meet, Or thorns compose so rich a crown?", "His dying crimson, like a robe, Spreads o'er His body on the tree; Then I am dead to all the globe, And all the globe is dead to me.", "Were the whole realm of nature mine, That were a present far too small; Love so amazing, so divine, Demands my soul, my life, my all."], "scriptureLinks": [{"label": "Gal 6:14", "chapterId": "GAL-6", "verseNumber": 14}, {"label": "Rom 7:24", "chapterId": "ROM-7", "verseNumber": 24}], "musicCredit": "'Hamburg', Lowell Mason, 1824", "number": 111}, {"title": "When I Survey the Wondrous Cross", "sectionId": 3, "wordsCredit": "Isaac Watts, 1707", "verses": ["When I survey the wondrous cross On which the Prince of Glory died, My richest gain I count but loss, And pour contempt on all my pride.", "Forbid it, Lord, that I should boast, Save in the death of Christ my God! All the vain things that charm me most, I sacrifice them to His blood.", "See from His head, His hands, His feet, Sorrow and love flow mingled down! Did e'er such love and sorrow meet, Or thorns compose so rich a crown?", "His dying crimson, like a robe, Spreads o'er His body on the tree; Then I am dead to all the globe, And all the globe is dead to me.", "Were the whole realm of nature mine, That were a present far too small; Love so amazing, so divine, Demands my soul, my life, my all."], "scriptureLinks": [{"label": "Gal 6:14", "chapterId": "GAL-6", "verseNumber": 14}, {"label": "Rom 7:24", "chapterId": "ROM-7", "verseNumber": 24}], "musicCredit": "'O Waly Waly' or 'The Water Is Wide', traditional English", "number": 112}, {"title": "When I Survey the Wondrous Cross", "sectionId": 3, "wordsCredit": "Isaac Watts, 1707", "verses": ["When I survey the wondrous cross On which the Prince of glory died, My richest gain I count but loss, And pour contempt on all my pride.", "Forbid it, Lord, that I should boast, Save in the death of Christ my God! All the vain things that charm me most, I sacrifice them to His blood.", "See from His head, His hands, His feet, Sorrow and love flow mingled down! Did e'er such love and sorrow meet, Or thorns compose so rich a crown?", "His dying crimson, like a robe, Spreads o'er His body on the tree; Then I am dead to all the globe, And all the globe is dead to me.", "Were the whole realm of nature mine, That were a present far too small; Love so amazing, so divine, Demands my soul, my life, my all."], "scriptureLinks": [{"label": "Gal 6:14", "chapterId": "GAL-6", "verseNumber": 14}, {"label": "Rom 7:24", "chapterId": "ROM-7", "verseNumber": 24}], "musicCredit": "'Rockingham Old' Edward Miller, 1790", "number": 113}, {"title": "Where He Leads Me", "sectionId": 3, "wordsCredit": "Edward (or Ernest) William Blandy, 1890", "verses": ["I can hear my Savior calling, I can hear my Savior calling, I can hear my Savior calling, \"Take thy cross and follow, follow Me.\"", "I'll go with Him through the garden, I'll go with Him through the garden, I'll go with Him through the garden, I'll go with Him, with Him all the way.", "I'll go with Him through the judgment, I'll go with Him through the judgment, I'll go with Him through the judgment, I'll go with Him, with Him all the way.", "He will give me grace and glory, He will give me grace and glory, He will give me grace and glory, And go with me, with me all the way."], "scriptureLinks": [{"label": "Jn 12:26", "chapterId": "JHN-12", "verseNumber": 26}, {"label": "21:22", "chapterId": "JHN-21", "verseNumber": 22}, {"label": "13:37-38", "chapterId": "JHN-13", "verseNumber": 37}], "altTitle": "I Can Hear My Savior Calling or Follow All The Way", "musicCredit": "'Blandy' or 'Norris' attr. John Samuel Norris (1844-1907) or Philip Paul Bliss (1838-1876)", "refrain": "Where He leads me I will follow, Where He leads me I will follow, Where He leads me I will follow; I'll go with Him, with Him, all the way.", "number": 114}, {"title": "Whiter Than Snow", "sectionId": 3, "wordsCredit": "James Nicholson, 1872", "verses": ["Lord Jesus, I long to be perfectly whole; I want Thee forever to live in my soul, Break down ev'ry idol, cast out ev'ry foe; Now wash me and I shall be whiter than snow.", "Lord Jesus, look down from Thy throne in the skies, And help me to make a complete sacrifice; I give up myself, and whatever I know, Now wash me and I shall be whiter than snow.", "Lord Jesus, for this I most humbly entreat, I wait, blessed Lord, at Thy crucified feet, By faith, for my cleansing, I see Thy blood flow, Now wash me and I shall be whiter than snow.", "Lord Jesus, Thou seest I patiently wait, Come now, and within me a new heart create; To those who have sought Thee, Thou never said'st ``No,'' Now wash me and I shall be whiter than snow."], "scriptureLinks": [{"label": "Ps 51:1-12", "chapterId": "PSA-51", "verseNumber": 1}, {"label": "Is 1:18", "chapterId": "ISA-1", "verseNumber": 18}, {"label": "Heb 13:15", "chapterId": "HEB-13", "verseNumber": 15}], "musicCredit": "'Whiter Than Snow' William Gustavus Fischer, 1872", "refrain": "Whiter than snow, yes, whiter than snow; Now wash me, and I shall be whiter than snow.", "number": 115}, {"title": "Baptized Into Thy Name Most Holy", "sectionId": 4, "wordsCredit": "Johann Jakob Rambach, 1734. Translated by Catherine Winkworth, 1863 and August Crull, 1884", "verses": ["Baptized into Thy Name most holy, O Father, Son, and Holy Ghost, I claim a place, though weak and lowly, Among Thy seed, Thy chosen host. Buried with Christ and dead to sin, Thy Spirit now shall live within.", "My loving Father, here doth take me To be henceforth His child and heir; My faithful Savior, now doth make me The fruit of all His sorrows share; My Comforter will comfort me When darkest clouds around I see.", "And I have vowed to fear and love Thee And to obey Thee, Lord, alone; I felt Thy Holy Spirit move me, I dared to pledge myself Thine own, Renouncing sin to keep the faith And war with evil unto death.", "My faithful God, Thou failest never, Thy cov'nant surely will abide; Oh, cast me not away forever Should I transgress it on my side! But if I fall hide not Thy face, Restore Thy child, Lord, by Thy Grace.", "Yes, all I am and love most dearly, To Thee I offer now the whole; O let me make my vows sincerely, Take full possession of my soul! Let naught within me, naught I own, Serve any will save Thine alone.", "Hence, Prince of darkness, hence forever, For I belong now to my God! 'Tis true, I sinned; but my dear Savior Hath cleansed me with His holy blood. Away, vain world, sin, leave me now, I turn from you; God hears my vow.", "And never let my purpose falter, O Father, Son, and Holy Ghost, But keep me faithful to Thine altar, Till Thou shalt call me from my post; So unto Thee I live and die, And praise Thee evermore on high."], "scriptureLinks": [{"label": "Mt 28:19", "chapterId": "MAT-28", "verseNumber": 19}, {"label": "Rom 6:2-4", "chapterId": "ROM-6", "verseNumber": 2}, {"label": "Gal 3:26-27", "chapterId": "GAL-3", "verseNumber": 26}], "musicCredit": "'O Dass Ich Tausend Zungen Hätte (Dretzel)' Kornelius Heinrich Dretzel, 1731", "number": 116}, {"title": "Blessed Jesus at Thy Word", "sectionId": 4, "wordsCredit": "verses 1-3, Tobias Clausnitzer, 1663. verse 4, unknown author. Translated by Catherine Winkworth, 1858", "verses": ["Blessed Jesus, at Thy Word We are gathered all to hear Thee; Let our hearts and souls be stirred Now to seek and love and fear Thee, By Thy teachings sweet and holy, Drawn from earth to love Thee solely.", "All our knowledge, sense, and sight Lie in deepest darkness shrouded, Til Thy Spirit breaks our night With the beams of truth unclouded; Thou alone to God canst win us; Thou must work all good within us.", "Glorious Lord, Thyself impart! Light of light, from God proceeding, Open Thou our ears and heart; Help us by Thy Spirit's pleading; Hear the cry Thy people raises; Hear and bless our prayers and praises.", "Father, Son, and Holy Ghost, Praise to Thee and adoration! Grant that we Thy Word may trust And obtain true consolation, While we here below must wander, Till we sing Thy praises yonder."], "scriptureLinks": [{"label": "Jn 6:67-68", "chapterId": "JHN-6", "verseNumber": 67}, {"label": "8:31-32", "chapterId": "JHN-8", "verseNumber": 31}, {"label": "Heb 4:12", "chapterId": "HEB-4", "verseNumber": 12}], "musicCredit": "'Liebster Jesu wir Sind Hier' Johann Rudolph Ahle, 1664", "number": 117}, {"title": "Come Down, O Love Divine", "sectionId": 4, "wordsCredit": "Bianco of Siena d. 1434. Translated by Richard F. Littledale, 1867", "verses": ["Come down, O love divine, seek Thou this soul of mine, And visit it with Thine own ardor glowing. O Comforter, draw near, within my heart appear, And kindle it, Thy holy flame bestowing.", "O let it freely burn, til earthly passions turn To dust and ashes in its heat consuming; And let Thy glorious light shine ever on my sight, And clothe me round, the while my path illuming.", "Let holy charity mine outward vesture be, And lowliness become mine inner clothing; True lowliness of heart, which takes the humbler part, And o'er its own shortcomings weeps with loathing.", "And so the yearning strong, with which the soul will long, Shall far outpass the pow'r of human telling; For none can guess its grace, till he become the place Wherein the Holy Spirit makes His dwelling."], "scriptureLinks": [{"label": "Acts 2:2-3", "chapterId": "ACT-2", "verseNumber": 2}, {"label": "Rom 5:5", "chapterId": "ROM-5", "verseNumber": 5}, {"label": "Ez 36:26-28", "chapterId": "EZK-36", "verseNumber": 26}], "musicCredit": "'Down Ampney' Ralph Vaughan Williams, 1906", "number": 118}, {"title": "Come Holy Spirit, Lord Our God", "sectionId": 4, "wordsCredit": "v. 1 ancient Latin. v.2-3 Martin Luther, 1524. Translated by Arthur Tozel Russell (1806-1874)", "verses": ["Come, Holy Spirit, Lord our God, And pour Thy gifts of grace abroad; Thy faithful people fill with blessing, Love's fire their hearts possessing. O Lord, Thou by Thy heav'nly Light Dost gather and in faith unite Through all the world a holy nation To sing to Thee with exultation, Hallelujah! Hallelujah!", "O, holiest Light! O Rock adored! Give us Thy light, Thy living Word, To God Himself our spirits leading, With Him as children pleading. From error, Lord, our souls defend, That they on Christ alone attend; In Him with faith unfeigned abiding, In Him with all their might confiding. Hallelujah! Hallelujah!", "O holiest Fire! O Source of rest! Grant that with joy and hope possest, And in Thy service kept forever, Naught us from Thee may sever. Lord, may Thy pow'r prepare each heart; To our weak nature strength impart, Onward to press, our foes defying, To Thee, through living and through dying. Hallelujah! Hallelujah!"], "scriptureLinks": [{"label": "Lk 11:13", "chapterId": "LUK-11", "verseNumber": 13}, {"label": "Rom 5:5", "chapterId": "ROM-5", "verseNumber": 5}, {"label": "1Cor 12:13", "chapterId": "1CO-12", "verseNumber": 13}], "altTitle": "Come Holy Ghost, God and Lord", "musicCredit": "'Komm Heiliger Geist, Herre Gott' ancient Latin found in Erfurt Enchiridion, 1524", "number": 119}, {"title": "Come, God Creator, Holy Ghost", "sectionId": 4, "wordsCredit": "variously ascribed to Ambrose, Gregory the Great, Charlemagne, or Rhabanus Maurus. Translated by Martin Luther, 1524. Translated from German to English by Leonard Woolsey Bacon, 1883", "verses": ["Come, God Creator, Holy Ghost, And visit Thou these souls of men; Fill them with graces, as Thou dost, Thy creatures make pure a gain.", "For Comforter Thy name we call. Sweet gift of God most high above, A holy unction to us all O Fount of life, Fire of love.", "Our minds illumine and refresh, Deep in our hearts let love burn bright; Thou know'st the weakness of our flesh; And strengthen us with Thy might.", "Thou with Thy wondrous sev'nfold gifts The finger art of God's right hand; The Father's Word Thou sendest swift On tongues of fire to each land.", "Drive far from us our wily foe; Grant us Thy blesséd peace within, That in Thy footsteps we may go, And shun the dark ways of sin.", "Teach us the Father well to know, Likewise His only Son our Lord, Thyself to us believing show, Spirit of both, aye adored", "Praise to the Father, and the Son Who from the dead is risen again; Praise to the Comforter be done Both now and ever. Amen."], "scriptureLinks": [{"label": "Jn 14:16", "chapterId": "JHN-14", "verseNumber": 16}, {"label": "Acts 2:1-4", "chapterId": "ACT-2", "verseNumber": 1}, {"label": "1Cor 12:7-11", "chapterId": "1CO-12", "verseNumber": 7}], "altTitle": "Creator, Spirit, Holy Dove or Come Holy Ghost, Creator Blest", "musicCredit": "'Komm, Gott Schoepfer Heiliger Geist' ancient Latin found in Erfurt Enchiridion, 1524", "number": 120}, {"title": "How Blest the Hearts", "sectionId": 4, "wordsCredit": "Christopher Wordsworth, 1865, alt", "verses": ["How blest are hearts, which Christ the Lord Couples as with a silver cord, In nuptial unity: That animated are by love And aspirations from above, O Holy Ghost, by Thee!", "When angels sang Creation's birth, Man, fashioned from the dust of earth. In Eden was alone; But God made Eve from Adam's side And brought her to him as a Bride, And willed them to be one.", "O holy wedlock ratified In Heav'n a knot for life is tied By God in Paradise! O happiness beyond compare! What tongues of Angels to declare The blessedness sufice?", "Anthems angelical were heard, When Christ, the everlasting Word To wed His Bride did come, And take that consecrated Bride, Cleansed by the lifeblood from His side, Unto Her heav'nly home.", "At Cana's feast that Heav'nly Guest Did first His Godhead manifest, And water change to wine; In wedlock tears of sorr'wring earth Are changed to wine of heav'nly mirth, By pow'r and love divine.", "Mirrored in nuptial purity The marriage of the Church we see And Christ the Bridegroom's Love; Angels look down, and anthems sing, The Holy Dove, the golden wing, Sheds blessings from above.", "Bless these Thy servants, gracious Lord, Whom Thou dost join in sweet accord, The bridegroom and the bride; In sorrow, sickness, and in health In tribulation and in wealth, Be Thou their Help and Guide!", "Be with them, Lord, as day by day They with one heart together pray, Thy Word together read, Together at Thine altar kneel, And with Thy Blood their union seal, On Thee together feed.", "May they forever have Thee near, Making them to Thyself more dear, And each to each in Thee; So, when from earthly cares released, May they at Thine own marriage feast Be blest eternally!", "To Father, whose paternal Love Sends benedictions from above, Eternal praises be; And God the Son, Incarnate Word, With Holy Spirit be adored; One God and Persons Three!"], "scriptureLinks": [{"label": "Mt 19:4-6", "chapterId": "MAT-19", "verseNumber": 4}, {"label": "Gen 2:21-24", "chapterId": "GEN-2", "verseNumber": 21}, {"label": "Eph 5:25-33", "chapterId": "EPH-5", "verseNumber": 25}], "altTitle": "How Blest Are Hearts", "musicCredit": "'Holy Matrimony' Henry Williams Baker, 1865", "number": 121}, {"title": "Jesus Loves Me", "sectionId": 4, "wordsCredit": "Anna B. Warner, 1860", "verses": ["Jesus loves me! This I know, For the Bible tells me so. Little ones to Him belong; They are weak, but He is strong.", "Jesus loves me! He who died Heaven's gate to open wide; He will wash away my sin, Let His little child come in.", "Jesus loves me! He will stay Close beside me all the way; Thou hast bled and died for me, I will henceforth live for Thee."], "scriptureLinks": [{"label": "Eph 3:17-18", "chapterId": "EPH-3", "verseNumber": 17}, {"label": "Jn 15:12-13", "chapterId": "JHN-15", "verseNumber": 12}], "musicCredit": "'untitled' by William B. Bradbury, 1862", "refrain": "Yes, Jesus loves me! Yes, Jesus loves me! Yes, Jesus loves me! The Bible tells me so.", "number": 122}, {"title": "Lord, Be Thy Word My Rule", "sectionId": 4, "wordsCredit": "Christopher Wordsworth, 1872", "verses": ["Lord, be Thy Word my rule, In it may I rejoice; Thy glory be my aim, Thy holy will my choice;", "Thy promises my hope; Thy providence my guard; Thine arm my strong support; Thyself my great reward."], "scriptureLinks": [{"label": "Ps 119:9-16", "chapterId": "PSA-119", "verseNumber": 9}, {"label": "Deut 6:6-9", "chapterId": "DEU-6", "verseNumber": 6}, {"label": "Jn 17:17", "chapterId": "JHN-17", "verseNumber": 17}], "musicCredit": "'Eden (Feilden)' Oswald Mosley Feilden, 1863", "number": 123}, {"title": "Lord, Keep Us Steadfast in Thy Word", "sectionId": 4, "wordsCredit": "Martin Luther, 1541. Translated by Catherine Winkworth, 1863", "verses": ["Lord, keep us steadfast in Thy Word; Curb those who fain by craft and sword Would wrest the kingdom from Thy Son And set at naught all He hath done.", "Lord Jesus Christ, Thy pow'r make known, For Thou art Lord of lords alone; Defend Thy Christendom that we May evermore sing praise to Thee.", "O Comforter of priceless worth, Send peace and unity on earth. Support us in our final strife And lead us out of death to life."], "scriptureLinks": [{"label": "Ps 119:5-10", "chapterId": "PSA-119", "verseNumber": 5}, {"label": "2 Jn 1:9", "chapterId": "2JN-1", "verseNumber": 9}, {"label": "Jn 8:31", "chapterId": "JHN-8", "verseNumber": 31}], "musicCredit": "'Erhalt Uns, Herr, bei deinem Wort' from Klug's \"Geistliche Lieder auffs new gebessert\", 1543", "number": 124}, {"title": "Lord, Thee I Love with All My Heart", "sectionId": 4, "wordsCredit": "Martin Schalling, circa 1571. Translated by Catherine Winkworth, 1858", "verses": ["Lord, Thee I love with all my heart; I pray Thee, ne'er from me depart; With tender mercy cheer me. Earth has no pleasure I would share, Yea, Heav'n itself were void and bare If Thou, Lord, wert not near me. And should my heart for sorrow break, My trust in Thee can nothing shake. Thou art the portion I have sought; Thy precious blood my soul has bought. Lord Jesus Christ, My God and Lord, my God and Lord, Forsake me not! I trust Thy Word.", "Yea, Lord, 'twas Thy rich bounty gave My body, soul, and all I have In this poor life of labor. Lord, grant that I in every place May glorify Thy lavish grace And serve and help my neighbor. Let no false doctrine me beguile, Let Satan not my soul defile. Give strength and patience unto me To bear my cross and follow Thee. Lord Jesus Christ, My God and Lord, my God and Lord, In death Thy comfort still afford.", "Lord, let at last Thine angels come, To Abr'am's bosom bear me home, That I may die unfearing; And in its narrow chamber keep My body safe in peaceful sleep Until Thy reappearing. And then from death awaken me, That these mine eyes with joy may see, O Son of God, Thy glorious face, My Savior and my fount of grace. Lord Jesus Christ, My prayer attend, my prayer attend, And I will praise Thee without end!"], "scriptureLinks": [{"label": "Mt 22:37", "chapterId": "MAT-22", "verseNumber": 37}, {"label": "28:20", "chapterId": "MAT-28", "verseNumber": 20}, {"label": "1 Jn 4:18-21", "chapterId": "1JN-4", "verseNumber": 18}], "musicCredit": "'Herzlich Lieb hab ich Dich O Herr' Strassburg, 1577", "number": 125}, {"title": "O Holy, Blessed Trinity", "sectionId": 4, "wordsCredit": "Martin Behm, 1608. Translated by C. H. L. Schuette, 1880", "verses": ["O Holy, Blessed Trinity, Divine, Essential Unity, God Father, Son, and Holy Ghost, Be Thou this day my Guide and Host.", "My soul and body keep from harm, O'er all I have extend Thine arm, That Satan may not cause distress Nor bring me shame or wretchedness.", "The Father's might shield me this day, The Son's pure wisdom cheer my way, The Holy Spirit's light divine Illume my heart's benighted shrine.", "My Maker, strengthen Thou my heart, O my Redeemer, help impart, Blest Comforter, keep at my side That faith and love in me abide.", "Lord, bless and keep Thou me as Thine; Lord, make Thy face upon me shine; Lord, lift Thy countenance on me And give me peace— sweet peace, from Thee."], "scriptureLinks": [{"label": "Ex 15:11-13", "chapterId": "EXO-15", "verseNumber": 11}, {"label": "Ps 25:4-6", "chapterId": "PSA-25", "verseNumber": 4}, {"label": "Num 6:24-26", "chapterId": "NUM-6", "verseNumber": 24}], "altTitle": "O Blessed Holy Trinity or O Holy, Holy, Holy Three or O Thou Most Holy Trinity", "musicCredit": "'O Heilige Dreifaltigkeit' or 'Steht Auf, Ihr Lieben Kinderlein' Nikolaus Hermann, 1558", "number": 126}, {"title": "The Comforter Has Come", "sectionId": 4, "wordsCredit": "Frank Bottome, 1890", "verses": ["O spread the tidings 'round, wherever man is found, Wherever human hearts and human woes abound; Let ev'ry Christian tongue proclaim the joyful sound: The Comforter has come!", "The long, long night is past, the morning breaks at last, And hush'd the dreadful wail and fury of the blast, As o'er the golden hills the day advances fast! The Comforter has come!", "Lo, the great King of kings, with healing in His wings, To ev'ry captive soul a full deliv'rance brings; And thro' the vacant cells the song of triumph rings; The Comforter has come!", "O boundless love divine! how shall this tongue of mine To wond'ring mortals tell the matchless grace divine; That I, a child of hell, should in His image shine! The Comforter has come!", "Sing, till the echoes fly above the vaulted sky, And all the saints above to all below reply, In strains of endless love the song that ne'er will die: The Comforter has come!"], "scriptureLinks": [{"label": "Jn 14:16", "chapterId": "JHN-14", "verseNumber": 16}, {"label": "Ps 23:4", "chapterId": "PSA-23", "verseNumber": 4}, {"label": "Is 40:1-2", "chapterId": "ISA-40", "verseNumber": 1}], "musicCredit": "'The Comforter Has Come' William J. Kirkpatrick, 1890", "refrain": "The Comforter has come, The Comforter has come! The Holy Ghost from heav'n, The Father's promise giv'n; O spread the tidings 'round, Wherever man is found: The Comforter has come!", "number": 127}, {"title": "The Day is Surely Drawing Near", "sectionId": 4, "wordsCredit": "Bartholomäus Ringwaldt, 1565. Translated by Phillip A. Peter, 1872, alt", "verses": ["The day is surely drawing near, When God's Son, the Anointed, Shall with great majesty appear, As Judge of all appointed. All mirth and laughter then shall cease When flames on flames will still increase, As Scripture truly teacheth.", "A trumpet loud shall then resound, And all the earth be shaken; Then all who in their graves are found Shall from their sleep awaken. But all that live shall in that hour, By the Almighty's boundless pow'r Be changed at His commanding.", "A book is opened then to all, A record truly telling What each hath done, both great and small, When he on earth was dwelling; And every heart be clearly seen, And all be known as they have been, In thoughts and words and actions.", "Then woe to those who scorned the Lord, And sought but carnal pleasures, Who here despised His precious Word, And loved their earthly treasures! With shame and trembling they will stand, And at the Judge's stern command To Satan be delivered.", "O Jesus, who my debt didst pay And for my sin wast smitten Within the Book of Life, oh, may My name be also written! I will not doubt; I trust in Thee, From Satan Thou hast made me free And from all condemnation.", "Therefore, my Intercessor be, And for Thy blood and merit Declare my name from judgment free, With all who life inherit; That I may see Thee face to face With all thy saints in that blest place Which Thou for us hast purchased.", "O Jesus Christ, do not delay, O hasten our salvation! We often tremble on our way In fear and tribulation. Then hear us when we cry to Thee; Come, mighty Judge, and make us free From every evil. Amen!"], "scriptureLinks": [{"label": "Rev 20:11-15", "chapterId": "REV-20", "verseNumber": 11}, {"label": "Lk 21:25-36", "chapterId": "LUK-21", "verseNumber": 25}, {"label": "Mt 25:32-46", "chapterId": "MAT-25", "verseNumber": 32}], "musicCredit": "'Es ist Gewisslich an der Zeit' from Klug's Geistliche Lieder, Wittenberg, 1533", "number": 128}, {"title": "We Now Implore God the Holy Ghost", "sectionId": 4, "wordsCredit": "v.1 ancient German. verses 2-4 Martin Luther, 1524. Translation composite", "verses": ["We now implore God the Holy Ghost For the true faith, which we need the most, That in our last moments He may befriend us And, as homeward we journey, attend us. Lord, have mercy.", "Shine in our hearts, O most precious Light, That we Jesus Christ may know aright, Clinging to our Savior, whose blood hath bought us. Who again to our homeland hath brought us. Lord, have mercy.", "Thou sacred Love, grace on us bestow, Set our hearts with heav'nly fire aglow That with hearts united we love each other, Of one mind, in peace with ev'ry brother. Lord, have mercy!", "Thou highest Comfort in ev'ry need, Grant that neither shame nor death we heed, That e'en then our courage may never fail us When the Foe shall accuse and assail us. Lord, have mercy!"], "scriptureLinks": [{"label": "Jn 14:26", "chapterId": "JHN-14", "verseNumber": 26}, {"label": "16:13-15", "chapterId": "JHN-16", "verseNumber": 13}, {"label": "Eph 4:3-6", "chapterId": "EPH-4", "verseNumber": 3}], "altTitle": "To God the Holy Spirit Let Us Pray or O Holy Ghost to Thee We Pray or Now Do We Pray God the Holy Ghost or Now Pray We All God the Comforter or Now Let Us Pray to the Holy Ghost", "musicCredit": "'Nun Bitten wir den Heiligen Geist' ancient German found in Walter's Geistliche Gesangbüchlein, 1524", "number": 129}, {"title": "Abide, O Dearest Jesus", "sectionId": 5, "wordsCredit": "Joshua Stegmann, 1628. Translated by August Crull circa 1892", "verses": ["Abide, O dearest Jesus, Among us with Thy grace, That Satan may not harm us, Nor we to sin give place.", "Abide, O dear Redeemer, Among us with Thy Word, And thus now and hereafter True peace and joy afford.", "Abide with heav'nly brightness Among us, precious Light; Thy truth direct, and keep us From error's gloomy night.", "Abide with richest blessings Among us, bounteous Lord; Let us in grace and wisdom Grow daily through Thy Word.", "Abide with Thy protection Among us, Lord, our Strength, Lest world and Satan fell us And overcome at length.", "Abide, O faithful Savior, Among us with Thy love; Grant steadfastness, and help us To reach our home above."], "scriptureLinks": [{"label": "1 Jn 4:13-16", "chapterId": "1JN-4", "verseNumber": 13}, {"label": "Mt 28:20", "chapterId": "MAT-28", "verseNumber": 20}, {"label": "Jn 1:1-14", "chapterId": "JHN-1", "verseNumber": 1}], "altTitle": "Abide with Us, Lord Jesus or Abide Among Us with Thy Grace or Abide with Us, Our Savior or Come, Abide with Thy Grace, in Our Hearts or O Savior, Go Beside us", "musicCredit": "'Christus der ist mein Leben' Melchior Vulpius, 1609", "number": 130}, {"title": "All Depends On Our Possessing", "sectionId": 5, "wordsCredit": "unknown circa 1673. Translated by Catherine Winkworth, 1858", "verses": ["All depends on our possessing God's abundant grace and blessing, Though all earthly wealth depart. He who trusts with faith unshaken In His God is not forsaken And e'er keeps a dauntless heart.", "He who hitherto hath fed me And to many joys hath led me, Is and ever shall be mine. He who did so gently school me, He who still doth guide and rule me, Will remain my Help divine.", "Many spend their lives in fretting Over trifles and in getting Things that have no solid ground. I shall strive to win a treasure That will bring me lasting pleasure And that now is seldom found.", "When with sorrow I am stricken, Hope my heart anew will quicken, All my longing shall be stilled. To His loving— kindness tender Soul and body I surrender; For in Him alone I build.", "Well He knows what best to grant me; All the longing hopes that haunt me, Joy and sorrow, have their day. I shall doubt His wisdom never, As God wills, so be it ever, I to Him commit my way.", "If on earth my days He lengthen, He my weary soul will strengthen; All my trust in Him I place. Earthly wealth is not abiding, Like a stream away is gliding; Safe I anchor in His grace."], "scriptureLinks": [{"label": "Pr 10:22", "chapterId": "PRO-10", "verseNumber": 22}, {"label": "2Cor 6:10", "chapterId": "2CO-6", "verseNumber": 10}, {"label": "Heb 10:34", "chapterId": "HEB-10", "verseNumber": 34}], "musicCredit": "'Alles ist an Gottes Segen' Johann Balthasar König, 1738", "number": 131}, {"title": "All Who Believe and Are Baptized", "sectionId": 5, "wordsCredit": "Thomas Hansen Kingo, 1689. Translation by George Alfred Taylor Rygh, 1909, alt", "verses": ["All who believe and are baptized shall see the Lord's salvation; baptized into the death of Christ, they are a new creation. through Christ's redemption they shall stand among the glorious heav'nly band of every tribe and nation.", "With one accord, O God, we pray: grant us thy Holy Spirit; look thou on our infirmity through Jesus' blood and merit. Grant us to grow in grace each day that by this sacrament we may eternal life inherit."], "scriptureLinks": [{"label": "Mk 16:16", "chapterId": "MRK-16", "verseNumber": 16}, {"label": "Rom 6:3-4", "chapterId": "ROM-6", "verseNumber": 3}, {"label": "Titus 3:4-7", "chapterId": "TIT-3", "verseNumber": 4}], "altTitle": "He That Believes and Is Baptized", "musicCredit": "'Es ist das Heil uns Kommen Her' German circa 1400 from Etlich Christlich Lider, Wittenberg, 1524", "number": 132}, {"title": "Almighty Lord, Before Thy Throne", "sectionId": 5, "wordsCredit": "Anne Steele, 1756", "verses": ["Almighty Lord Before Thy throne Thy mourning people bend: Tis on Thy grace in Christ alone Our failing hopes depend.", "Dark judgments, from Thy heavy hand, Thy dreadful pow'r display; Yet mercy spares our guilty land, And still we live to pray.", "How changed, alas! are truths divine For error guilt and shame! What imp'ous numbers, bold in sin, Disgrace the Christian name!", "O turn us, turn us, mighty Lord! Convert us by Thy grace; Then shall our hearts obey Thy Word, And see again Thy face.", "Then, should oppressing foes invade, We will not yield to fear, Secure of all sufficient aid, When God in Christ is near."], "scriptureLinks": [{"label": "Rev 3:19", "chapterId": "REV-3", "verseNumber": 19}, {"label": "Is 45:22", "chapterId": "ISA-45", "verseNumber": 22}, {"label": "2Pt 3:9", "chapterId": "2PE-3", "verseNumber": 9}], "altTitle": "For a Public Fast", "musicCredit": "'Burford (Purcell)' attr. Henry Purcell, first known printing 1718", "number": 133}, {"title": "Amazing Grace", "sectionId": 5, "wordsCredit": "John Newton, 1779. last verse author unknown, before 1829", "verses": ["Amazing grace! How sweet the sound That saved a wretch like me! I once was lost, but now am found; Was blind, but now I see.", "'Twas grace that taught my heart to fear, And grace my fears relieved; How precious did that grace appear The hour I first believed.", "Through many dangers, toils and snares, I have already come; 'Tis grace hath brought me safe thus far, And grace will lead me home.", "The Lord has promised good to me, His Word my hope secures; He will my Shield and Portion be, As long as life endures.", "Yea, when this flesh and heart shall fail, And mortal life shall cease, I shall possess, with in the veil, A life of joy and peace.", "The earth shall soon dissolve like snow, The sun forbear to shine; But God, Who called me here below, Shall be forever mine.", "When we've been there ten thousand years, Bright shining as the sun, We've no less days to sing God's praise Than when we'd first begun."], "scriptureLinks": [{"label": "Jn 9:25", "chapterId": "JHN-9", "verseNumber": 25}, {"label": "Eph 2:4-9", "chapterId": "EPH-2", "verseNumber": 4}], "musicCredit": "'New Britain' James P. Carrell and David L. Clayton, 1831", "number": 134}, {"title": "Be Still My Soul", "sectionId": 5, "wordsCredit": "Katharina A. von Schlegel, 1752. Translated by Jane L. Borthwick, 1855", "verses": ["Be still, my soul: the Lord is on thy side. Bear patiently the cross of grief or pain. Leave to thy God to order and provide; In every change, He faithful will remain. Be still, my soul: thy best, thy heav'nly Friend Through thorny ways leads to a joyful end.", "Be still, my soul: thy God doth undertake To guide the future, as He has the past. Thy hope, thy confidence let nothing shake; All now mysterious shall be bright at last. Be still, my soul: the waves and winds still know His voice Who ruled them while He dwelt below.", "Be still, my soul: when dearest friends depart, And all is darkened in the vale of tears, Then shalt thou better know His love, His heart, Who comes to soothe thy sorrow and thy fears. Be still, my soul: thy Jesus can repay From His own fullness all He takes away.", "Be still, my soul: the hour is hast'ning on When we shall be forever with the Lord. When disappointment, grief and fear are gone, Sorrow forgot, love's purest joys restored. Be still, my soul: when change and tears are past All safe and blessèd we shall meet at last.", "Be still, my soul: begin the song of praise On earth, believing, to Thy Lord on high; Acknowledge Him in all thy words and ways, So shall He view thee with a well pleased eye. Be still, my soul: the Sun of life divine Through passing clouds shall but more brightly shine."], "scriptureLinks": [{"label": "Ps 46:10", "chapterId": "PSA-46", "verseNumber": 10}, {"label": "Rom 2:3-5", "chapterId": "ROM-2", "verseNumber": 3}], "musicCredit": "'Finlandia' Jean Sibelius, 1899", "number": 135}, {"title": "Blessed Assurance", "sectionId": 5, "wordsCredit": "Fanny Crosby, 1873", "verses": ["Blessèd assurance, Jesus is mine! O what a foretaste of glory divine! Heir of salvation, purchase of God, Born of His Spirit, washed in His blood.", "Perfect submission, perfect delight, Visions of rapture now burst on my sight; Angels descending bring from above Echoes of mercy, whispers of love.", "Perfect submission, all is at rest I in my Savior am happy and blest, Watching and waiting, looking above, Filled with His goodness, lost in His love."], "scriptureLinks": [{"label": "Heb 10:21-23", "chapterId": "HEB-10", "verseNumber": 21}, {"label": "Ps 71:24", "chapterId": "PSA-71", "verseNumber": 24}, {"label": "Rom 5:1", "chapterId": "ROM-5", "verseNumber": 1}], "musicCredit": "'Blessed Assurance' or 'Assurance' Phoebe P. Knapp, 1873", "refrain": "This is my story, this is my song, Praising my Savior, all the day long; This is my story, this is my song, Praising my Savior, all the day long.", "number": 136}, {"title": "By Grace I'm Saved", "sectionId": 5, "wordsCredit": "Christian L. Scheidt, 1742. Translated by Matthias Loy, (1828-1915)", "verses": ["By grace I'm saved— grace free and boundless! My heart, believ'st thou this or not? Why tremblest thou with terror groundless? Has ever God a falsehood taught? His Word is truethen this must be: By grace there is a crown for thee.", "By grace! our works are all rejected, All claims of merit pass for naught; The mighty Savior, long expected, To us this blissful truth has brought, That He by death redeems our race, And we are saved alone by grace.", "By grace! mark well this phrase's meaning, When sin rolls sorrows o'er thy breast, When Satan threats with pride o'erweening, When troubled conscience sighs for rest: What reason ne'er can comprehend It pleases God by grace to send.", "By grace His Son, on earth appearing, Vouchsafed beneath thy woe to bend; Hadst thou, damnation justly fearing, Done aught to render Him thy friend? Was't not that He thy welfare sought, And but by grace deliv'rance wrought?", "By grace! this ground of our salvation As long as God is true endures: What saints have penned by inspiration, What God to our poor soul secures, What all our faith must rest upon, Is grace, free grace through His dear Son.", "By grace! but think not, thou who livest Securely on in godless ways, That thou, though all are called, receivest The promised rest that wakes our praise: By grace none find in heaven a place Who live in sin in hope of grace.", "By grace! They who have heard this sentence Must bid hypocrisy farewell; For only after deep repentance The soul what grace imports can tell; To sin while grace a trifle seems, To faith it bright with glory beams.", "By grace the timid hearts that languish, Find access to the Father's heart, When conflicts fierce and bitter anguish Bid all their joy and hopes depart. Where, oftimes, should I strength obtain, Bid grace my anchor not remain!", "By grace! on this in death I'll rest me, Rejoicing e'en though feeling naught; I know my sin it oft oppressed me But Him, too, who my soul hath bought: My heart exults grief flees apace Because my soul is saved by grace.", "By grace! O sin and Satan hear it! I bear my flag of faith in hand, And pass, in spite of doubts, nor fear it, The Red Sea to the promised land; I hold the word my Savior taught As certain, whether felt or not."], "scriptureLinks": [{"label": "Eph 2:4-9", "chapterId": "EPH-2", "verseNumber": 4}, {"label": "Titus 3:4-7", "chapterId": "TIT-3", "verseNumber": 4}, {"label": "Is 64:6", "chapterId": "ISA-64", "verseNumber": 6}], "musicCredit": "'O Dass Ich Tansend Zungen' Johann Balthasar König, 1738", "number": 137}, {"title": "Faith of Our Fathers", "sectionId": 5, "wordsCredit": "Frederick W. Faber, 1849. Refrain by James G. Walton, 1874", "verses": ["Faith of our fathers, living still, In spite of dungeon, fire and sword; O how our hearts beat high with joy Whene'er we hear that glorious Word!", "Faith of our fathers, we will strive To win all nations unto Thee; And through the truth that comes from God, We all shall then be truly free.", "Faith of our fathers, we will love Both friend and foe in all our strife; And preach Thee, too, as love knows how By kindly words and virtuous life."], "scriptureLinks": [{"label": "Heb 11:1-2", "chapterId": "HEB-11", "verseNumber": 1}, {"label": "1Tim 6:12", "chapterId": "1TI-6", "verseNumber": 12}, {"label": "Jude 1:3", "chapterId": "JUD-1", "verseNumber": 3}], "musicCredit": "'St. Catherine' Henri F. Hemy (1818-1888)", "refrain": "Faith of our fathers, holy faith! We will be true to thee till death.", "number": 138}, {"title": "For All The Saints", "sectionId": 5, "wordsCredit": "William W. How, 1864", "verses": ["For all the saints, who from their labors rest, Who Thee by faith before the world confessed, Thy Name, O Jesus, be forever blessed. Alleluia, Alleluia!", "Thou wast their Rock, their Fortress and their Might; Thou, Lord, their Captain in the well fought fight; Thou, in the darkness drear, their one true Light. Alleluia, Alleluia!", "For the Apostles' glorious company, Who bearing forth the Cross o'er land and sea, Shook all the mighty world, we sing to Thee: Alleluia, Alleluia!", "For the Evangelists, by whose blest word, Like fourfold streams, the garden of the Lord, Is fair and fruitful, be Thy Name adored. Alleluia, Alleluia!", "For Martyrs, who with rapture kindled eye, Saw the bright crown descending from the sky, And seeing, grasped it, Thee we glorify. Alleluia, Alleluia!", "O blest communion, fellowship divine! We feebly struggle, they in glory shine; All are one in Thee, for all are Thine. Alleluia, Alleluia!", "O may Thy soldiers, faithful, true and bold, Fight as the saints who nobly fought of old, And win with them the victor's crown of gold. Alleluia, Alleluia!", "And when the strife is fierce, the warfare long, Steals on the ear the distant triumph song, And hearts are brave, again, and arms are strong. Alleluia, Alleluia!", "The golden evening brightens in the west; Soon, soon to faithful warriors comes their rest; Sweet is the calm of paradise the blessed. Alleluia, Alleluia!", "But lo! there breaks a yet more glorious day; The saints triumphant rise in bright array; The King of glory passes on His way. Alleluia, Alleluia!", "From earth's wide bounds, from ocean's farthest coast, Through gates of pearl streams in the countless host, And singing to Father, Son and Holy Ghost: Alleluia, Alleluia!"], "scriptureLinks": [{"label": "Rev 14:13", "chapterId": "REV-14", "verseNumber": 13}, {"label": "2Tim 4:7-8", "chapterId": "2TI-4", "verseNumber": 7}], "musicCredit": "'Sine Nomine' Ralph Vaughan Williams, 1906", "number": 139}, {"title": "Glorious Things of Thee are Spoken", "sectionId": 5, "wordsCredit": "John Newton, 1779, alt", "verses": ["Glorious things of thee are spoken, Zion city of our God; He, Whose Word cannot be broken Formed thee for His Own abode: On the Rock of Ages founded, What can shake thy sure repose? With salvation's walls surrounded, Thou mayst smile at all thy foes.", "See, the streams of living waters, Springing from Eternal Love, Well supply thy sons and daughters, And all fear of want remove: Who can faint, while such a river Ever will their thirst assuage? Grace, which, like the Lord the Giver, Never fails from age to age.", "Round each habitation hov'ring, See the cloud and fire appear, For a glory and a cov'ring: Showing that the Lord is near. Thus deriving from their banner Light by night, and shade by day, Safe they feed upon the manna, Which He gives them on their way.", "Savior, if of Zion's city I, through grace, a member am, Let the world deride or pity, I will glory in Thy Name: Fading is the worldling's pleasure, All his boasted pomp and show: Solid joys and lasting treasure None but Zion's children know."], "scriptureLinks": [{"label": "Ps 87:1-7", "chapterId": "PSA-87", "verseNumber": 1}, {"label": "48:1-3", "chapterId": "PSA-48", "verseNumber": 1}, {"label": "Is 12:1-6", "chapterId": "ISA-12", "verseNumber": 1}], "musicCredit": "'Austria (Haydn)' or 'Austrian Hymn' Franz Joseph Haydn, 1797", "number": 140}, {"title": "How Firm A Foundation", "sectionId": 5, "wordsCredit": "John Rippon, 1787", "verses": ["How firm a foundation, ye saints of the Lord, Is laid for your faith in His excellent Word! What more can He say than to you He hath said, You, who unto Jesus for refuge have fled?", "In every condition, in sickness, in health; In poverty's vale, or abounding in wealth; At home and abroad, on the land, on the sea, As thy days demand, shall thy strength ever be.", "Fear not, I am with thee, O be not dismayed, For I am thy God and will still give thee aid; I'll strengthen and help thee, and cause thee to stand Upheld by My righteous, omnipotent hand.", "When through the deep waters I call thee to go, The rivers of woe shall not thee overflow; For I will be with thee, thy troubles to bless, And sanctify to thee thy deepest distress.", "When through fiery trials thy pathways shall lie, My grace, all sufficient, shall be thy supply; The flame shall not hurt thee; I only design Thy dross to consume, and thy gold to refine.", "Even down to old age all My people shall prove My sovereign, eternal, unchangeable love; And when hoary hairs shall their temples adorn, Like lambs they shall still in My bosom be borne.", "The soul that on Jesus has leaned for repose, I will not, I will not desert to its foes; That soul, though all hell should endeavor to shake, I'll never, no never, no never forsake."], "scriptureLinks": [{"label": "2Tim 2:19", "chapterId": "2TI-2", "verseNumber": 19}, {"label": "Heb 13:5", "chapterId": "HEB-13", "verseNumber": 5}, {"label": "Is 41:10", "chapterId": "ISA-41", "verseNumber": 10}], "musicCredit": "'Foundation (Funk)' or 'Protection' Joseph Funk, 1832", "number": 141}, {"title": "I Know Whom I Have Believed", "sectionId": 5, "wordsCredit": "Daniel Webster Whittle (a.k.a. Elias Nathan), 1883", "verses": ["I know not why God's wondrous grace To me He hath made known, Nor why, unworthy, Christ in love Redeemed me for His own.", "I know not how this saving faith To me He did impart, Nor how believing in His Word Wrought peace within my heart.", "I know not how the Spirit moves, Convincing us of sin, Revealing Jesus through the Word, Creating faith in Him.", "I know not what of good or ill May be reserved for me, Of weary ways or golden days, Before His face I see.", "I know not when my Lord may come, At night or noonday fair, Nor if I walk the vale with Him, Or meet Him in the air."], "scriptureLinks": [{"label": "2Tim 1:12", "chapterId": "2TI-1", "verseNumber": 12}, {"label": "Phil 3:8-11", "chapterId": "PHP-3", "verseNumber": 8}, {"label": "Jn 14:5-11", "chapterId": "JHN-14", "verseNumber": 5}], "musicCredit": "'I Know Whom I Have Believed' James McGranahan, 1892", "refrain": "But I know Whom I have believèd, And am persuaded that He is able To keep that which I've committed Unto Him against that day.", "number": 142}, {"title": "It Is Well With My Soul(When Peace Like a River)", "sectionId": 5, "wordsCredit": "Horatio G. Spafford, 1873", "verses": ["When peace, like a river, attendeth my way, When sorrows like sea billows roll; Whatever my lot, Thou has taught me to say, It is well, it is well, with my soul.", "Though Satan should buffet, though trials should come, Let this blest assurance control, That Christ has regarded my helpless estate, And hath shed His own blood for my soul.", "My sin, oh, the bliss of this glorious thought! My sin, not in part but the whole, Is nailed to the cross, and I bear it no more, Praise the Lord, praise the Lord, O my soul!", "For me, be it Christ, be it Christ hence to live: If Jordan above me shall roll, No pang shall be mine, for in death as in life Thou wilt whisper Thy peace to my soul.", "But, Lord, 'tis for Thee, for Thy coming we wait, The sky, not the grave, is our goal; Oh trump of the angel! Oh voice of the Lord! Blessèd hope, blessèd rest of my soul!", "And Lord, haste the day when my faith shall be sight, The clouds be rolled back as a scroll; The trump shall resound, and the Lord shall descend, Even so, it is well with my soul."], "scriptureLinks": [{"label": "Heb 6:17-19", "chapterId": "HEB-6", "verseNumber": 17}, {"label": "Jn 14:27-28", "chapterId": "JHN-14", "verseNumber": 27}, {"label": "Is 26:3", "chapterId": "ISA-26", "verseNumber": 3}], "musicCredit": "'It Is Well' or 'Ville Du Havre' Philip P. Bliss, 1876", "refrain": "It is well, with my soul, It is well, it is well with my soul.", "number": 143}, {"title": "Jesus Christ, Our Blessed Savior", "sectionId": 5, "wordsCredit": "John Hus (1369-1415). Expanded by Martin Luther, 1524. Translator v.4,6 by Richard Massie Other verses unknown", "verses": ["Jesus Christ, our Blessed Savior, Turned away God's wrath forever; Suff'ring pains no tongue can tell, He saved us from the pains of hell.", "To remind us that, to save us He hath died, His flesh He gave us With this bread, a quick'ning food, And with this wine, His precious blood.", "Whoso to this board repaireth, Take good heed how He prepareth; Death instead of life shall He Receive who comes unworthily.", "Praise the Father, God in heaven, Who such dainty food hath given, And for misdeeds thou hast done Gave to die His beloved Son.", "Thou shalt hold with faith unshaken, That this food is to be taken By the sick who are distressed, By those whose heart is sin— oppressed.", "To such grace and mercy turneth Every soul that truly mourneth; Art thou well? Avoid this board, Else thou reapest an ill reward.", "Christ says: \"Come ye heavy-laden, I your weary hearts will gladden; They that are yet strong and well, Despise the best physician's skill.", "Couldst thou earn thine own salvation, Useless were my death and passion; This feast is not spread for thee, If thine own helper thou wilt be.", "If thou this believest truly, And confession makest duly, Thou a welcome guest art here, This heavenly food thy soul shall cheer.", "But the fruits must not be missing, Love thy neighbor without ceasing, That true love let him receive, Which here to thee thy God doth give."], "scriptureLinks": [{"label": "Eph 5:6-14", "chapterId": "EPH-5", "verseNumber": 6}, {"label": "Rom 5:9-10", "chapterId": "ROM-5", "verseNumber": 9}, {"label": "1Cor 11:23-29", "chapterId": "1CO-11", "verseNumber": 23}], "altTitle": "Jesus Christ Our Redeemer Born or Christ Who Freed Our Souls From Danger or Jesus Christ Our God and Savior", "musicCredit": "'Jesus Christus Unser Heiland, Der Von Uns (Walter)' from Walter's Geistliche Gesangbüchlein, 1524", "number": 144}, {"title": "Jesus Christ, Our Blessed Savior", "sectionId": 5, "wordsCredit": "John Hus (1369-1415) expanded by Martin Luther, 1524. Translator v.4,6 by Richard Massie Other verses unknown", "verses": ["Jesus Christ, our Blessed Savior, Turned away God's wrath forever; Suff'ring pains no tongue can tell, He saved us from the pains of hell.", "To remind us that, to save us He hath died, His flesh He gave us With this bread, a quick'ning food, And with this wine, His precious blood.", "Whoso to this board repaireth, Take good heed how He prepareth; Death instead of life shall He Receive who comes unworthily.", "Praise the Father, God in heaven, Who such dainty food hath given, And for misdeeds thou hast done Gave to die His beloved Son.", "Thou shalt hold with faith unshaken, That this food is to be taken By the sick who are distressed, By those whose heart is sin— oppressed.", "To such grace and mercy turneth Every soul that truly mourneth; Art thou well? Avoid this board, Else thou reapest an ill reward.", "Christ says: \"Come ye heavy-laden, I your weary hearts will gladden; They that are yet strong and well, Despise the best physician's skill.", "Couldst thou earn thine own salvation, Useless were my death and passion; This feast is not spread for thee, If thine own helper thou wilt be.", "If thou this believest truly, And confession makest duly, Thou a welcome guest art here, This heavenly food thy soul shall cheer.", "But the fruits must not be missing, Love thy neighbor without ceasing, That true love let him receive, Which here to thee thy God doth give."], "scriptureLinks": [{"label": "Eph 5:6-14", "chapterId": "EPH-5", "verseNumber": 6}, {"label": "Rom 5:9-10", "chapterId": "ROM-5", "verseNumber": 9}, {"label": "1Cor 11:23-29", "chapterId": "1CO-11", "verseNumber": 23}], "altTitle": "Jesus Christ Our Redeemer Born or Christ Who Freed Our Souls From Danger or Jesus Christ Our God and Savior", "musicCredit": "'Jesus Christus Unser Heiland, Der Von Uns (Klug)' from Klug's Geistliche Lieder, Wittenberg, 1533", "number": 145}, {"title": "Just As I Am Without One Plea", "sectionId": 5, "wordsCredit": "Charlotte Elliott, 1835", "verses": ["Just as I am, without one plea, But that Thy blood was shed for me, And that Thou biddest me come to Thee, O Lamb of God, I come, I come.", "Just as I am, and waiting not To rid my soul of one dark blot, To Thee, Whose blood can cleanse each spot, O Lamb of God, I come, I come.", "Just as I am, though tossed about With many'a conflict, many'a doubt, Fightings and fears within, without, O Lamb of God, I come, I come.", "Just as I am, poor, wretched, blind; Sight riches healing of the mind, Yea, all I need, in Thee to find, O Lamb of God, I come, I come.", "Just as I am, Thou wilt receive, Wilt welcome, pardon, cleanse, relieve, Because Thy promise I believe, O Lamb of God, I come, I come.", "Just as I am, Thy love unknown Has broken every barrier down; Now to be Thine, yea Thine alone, O Lamb of God, I come, I come."], "scriptureLinks": [{"label": "Jn 1:29", "chapterId": "JHN-1", "verseNumber": 29}, {"label": "Is 53:11", "chapterId": "ISA-53", "verseNumber": 11}, {"label": "Rom 5:1", "chapterId": "ROM-5", "verseNumber": 1}], "musicCredit": "'Woodworth' William B. Bradbury, 1849", "number": 146}, {"title": "Lamp of Our Feet", "sectionId": 5, "wordsCredit": "Bernard Barton, 1826", "verses": ["Lamp of our feet! whereby we trace Our path, when wont to stray; Stream from the fount of heav'nly grace! Brook by the trav'ler's way!", "Bread of our souls! whereon we feed; True manna from on high! Our guide, and chart wherein we read Of realms beyond the sky.", "Pillar of fire— through watches dark! Or radiant cloud by day! When waves would whelm our tossing bark— Our anchor and our stay!", "Pole— star on life's tempestuous deep! Beacon! when doubts surround; Compass! by which our course we keep; Our deep sea— lead, to sound!", "Riches in poverty! our aid In every needful hour! Unshaken rock! the pilgrim's shade; The soldier's fortress tow'r.", "Our shield and buckler in the fight! Vict'ry's triumphant palm! Comfort in grief! in weakness, might! In sickness, Gilead's balm.", "Childhood's preceptor! manhood's trust! Old age's firm ally! Our hope—when we go down to dust, Of immortality.", "Pure oracles of truth divine! Unlike each fabled dream Given forth from Delphos' mystic shrine Or groves of Academe!", "Word of the ever-living God! Will of His glorious Son! Without Thee, how could earth be trod? Or Heaven itself be won?", "Yet to unfold thy hidden worth, Thy mysteries to reveal, That Spirit which first gave thee forth, Thy volume must unseal!", "And we, if we aright would learn The wisdom it imparts, Must to its heavenly teaching turn With simple, child-like hearts!"], "scriptureLinks": [{"label": "Ps 119:105", "chapterId": "PSA-119", "verseNumber": 105}, {"label": "2Pt 1:19-21", "chapterId": "2PE-1", "verseNumber": 19}, {"label": "Jn 1:1-5", "chapterId": "JHN-1", "verseNumber": 1}], "musicCredit": "'St. Agnes' John B. Dykes, 1866", "number": 147}, {"title": "Let Us Ever Walk With Jesus", "sectionId": 5, "wordsCredit": "Sigmund von Birken, 1652. Translated by J. Adam Rimbach, 1900", "verses": ["Let us ever walk with Jesus, Follow His example pure, Flee the world, which would deceive us And to sin our souls allure. Ever in His footsteps treading, Body here, yet soul above, Full of faith and hope and love, Let us do the Father's bidding. Faithful Lord, abide with me; Savior, lead, I follow Thee.", "Let us suffer here with Jesus, To His image, e'er conform; Heaven's glory soon will please us, Sunshine follow on the storm. Though we sow in tears of sorrow, We shall reap with heav'nly joy; And the fears that now annoy Shall be laughter on the morrow. Christ, I suffer here with Thee; There, oh, share Thy joy with me!", "Let us also die with Jesus. His death from the second death, From our soul's destruction, frees us, Quickens us with life's glad breath. Let us mortify, while living, Flesh and blood and die to sin; And the grave that shuts us in Shall but prove the gate to heaven. Jesus, here I die to Thee There to live eternally.", "Let us gladly live with Jesus; Since He's risen from the dead, Death and grave must soon release us. Jesus, Thou art now our Head, We are truly Thine own members; Where Thou livest, there live we. Take and own us constantly, Faithful Friend, as Thy dear brethren. Jesus, here I live to Thee, Also there eternally."], "scriptureLinks": [{"label": "1 Pt 2:21", "chapterId": "1PE-2", "verseNumber": 21}, {"label": "Jn 13:15", "chapterId": "JHN-13", "verseNumber": 15}, {"label": "Jn 11:16", "chapterId": "JHN-11", "verseNumber": 16}], "musicCredit": "'Lasset Uns Mit Jesu Ziehen (Boltze)' or 'Walk With Jesus' or 'Let Us Ever Walk With Jesus'Gabriel Gottlieb Boltze, 1788", "number": 148}, {"title": "Lo He Comes! Whom Every Nation", "sectionId": 5, "wordsCredit": "Christopher Wordsworth, 1865", "verses": ["Lo He comes! whom every nation, Taught of God, desired to see, Filled with hope and expectation That He would their Savior be. Sing, o sing with exultation, Lo! He calls us to our home; Peace, redemption, joy, salvation, Now from Heav'n to earth are come.", "See He comes! Whom kings and sages, Prophets, patriarchs of old, Disant climes and countless ages, Waited eager to behold. Sing, o sing with exultation, Haste we to our Father's home; Peace, redemption, joy, salvation, Now from Heav'n to earth are come.", "See the Lamb of God appearing, God of God, from Heav'n above; See the Heav'nly Bridegroom cheering His dear Bride with words of love! Glory to th'Eternal Father, Glory to th'Incarnate Son Glory to the Holy Spirit, Glory to the Three in One!"], "scriptureLinks": [{"label": "Rev 1:6-7", "chapterId": "REV-1", "verseNumber": 6}, {"label": "Mt 21:9", "chapterId": "MAT-21", "verseNumber": 9}, {"label": "Jer 33:14-16", "chapterId": "JER-33", "verseNumber": 14}], "musicCredit": "'Rex Gloriae' (first half) Henry Thomas Smart, 1868", "number": 149}, {"title": "Lord, Dismiss Us With Thy Blessing", "sectionId": 5, "wordsCredit": "John Fawcett, 1773; verse 3 alt. by Godfrey Thring, 1880", "verses": ["Lord, dismiss us with Thy blessing; Fill our hearts with joy and peace; Let us each Thy love possessing, Triumph in redeeming grace. O refresh us, O refresh us, Trav'ling through this wilderness.", "Thanks we give and adoration For Thy Gospel's joyful sound; May the fruits of Thy salvation In our hearts and lives abound. Ever faithful, ever faithful, To the truth may we be found.", "So that when Thy love shall call us, Savior, from the world away, Fear of death shall not appall us, Glad Thy summons to obey. May we ever, may we ever, Reign with Thee in endless day."], "scriptureLinks": [{"label": "Num 6:22-27", "chapterId": "NUM-6", "verseNumber": 22}, {"label": "1Cor 15:54-57", "chapterId": "1CO-15", "verseNumber": 54}, {"label": "Heb 9:15", "chapterId": "HEB-9", "verseNumber": 15}], "musicCredit": "'Regent Square' Henry Smart, 1867", "number": 150}, {"title": "Love Divine, All Loves Excelling", "sectionId": 5, "wordsCredit": "Charles Wesley, 1747", "verses": ["Love divine, all loves excelling, Joy of Heav'n to Earth come down! Fix in us Thy humble dwelling, All Thy faithful mercies crown. Jesus, thou art all compassion, Pure, unbounded love Thou art; Visit us with Thy salvation, Enter every trembling heart!", "Breathe, O breathe Thy loving Spirit Into ev'ry troubled breast! Let us all in Thee inherit, Let us find Thy promised rest. Take away our love of sinning, Alpha and Omega be; End of faith, as its beginning, Set our hearts at liberty.", "Come, Almighty to deliver, Let us all Thy life receive; Graciously return, and never, Never more Thy temples leave! Thee we would be always blessing, Serve Thee as Thy host above, Pray, and praise Thee without ceasing, Glory in Thy perfect love.", "Finish, then, Thy new creation, Pure and spotless let us be; Let us see Thy great salvation, Perfectly restored in Thee, Changed from glory into glory, Till in heav'n we take our place, Till we cast our crowns before Thee, Lost in wonder, love, and praise."], "scriptureLinks": [{"label": "1 Jn 4:7-19", "chapterId": "1JN-4", "verseNumber": 7}, {"label": "Jn 15:16", "chapterId": "JHN-15", "verseNumber": 16}, {"label": "Rom 5:8-10", "chapterId": "ROM-5", "verseNumber": 8}], "musicCredit": "'HyFrydol' Rowland H. Prichard, 1830", "number": 151}, {"title": "May God Bestow on Us His Grace", "sectionId": 5, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["May God bestow on us His grace, With blessings rich provide us, And may the brightness of His face To life eternal guide us That we His saving health may know, His gracious will and pleasure, And also to the heathen show Christ's riches without measure And unto God convert them.", "Thine over all shall be the praise And thanks of every nation, And all the world with joy shall raise The voice of exultation; For Thou shalt judge the earth, O Lord, Nor suffer sin to flourish; Thy people's pasture is Thy Word Their souls to feed and nourish, In righteous paths to keep them.", "Oh, let the people praise Thy worth, In all good works increasing; The land shall plenteous fruit bring forth, Thy Word is rich in blessing. May God the Father, God the Son, And God the Spirit bless us! Let all the world praise Him alone, Let solemn awe possess us. Now let our hearts say, Amen."], "scriptureLinks": [{"label": "Rev 22:21", "chapterId": "REV-22", "verseNumber": 21}, {"label": "Ps 67:1-2", "chapterId": "PSA-67", "verseNumber": 1}, {"label": "Ps 96:10-13", "chapterId": "PSA-96", "verseNumber": 10}], "altTitle": "May God Unto Us Gracious Be or Would that the Lord Would Grant Us Grace", "musicCredit": "'Es Wollt uns Gott Genædig' adapted from older German hymn by Martin Luther. Found in Erfurt Enchiridion, 1524", "number": 152}, {"title": "My Faith Looks Up To Thee", "sectionId": 5, "wordsCredit": "Ray Palmer, 1830", "verses": ["My faith looks up to Thee, Thou Lamb of Calvary, Savior divine! Now hear me while I pray, take all my guilt away, O let me from this day be wholly Thine!", "May Thy rich grace impart Strength to my fainting heart, my zeal inspire! As Thou hast died for me, O may my love to Thee, Pure warm, and changeless be, a living fire!", "While life's dark maze I tread, And griefs around me spread, be Thou my Guide; Bid darkness turn to day, wipe sorrow's tears away, Nor let me ever stray from Thee aside.", "When ends life's transient dream, When death's cold sullen stream over me roll; Blest Savior, then in love, fear and distrust remove; O bear me safe above, a ransomed soul!"], "scriptureLinks": [{"label": "2Cor 5:7", "chapterId": "2CO-5", "verseNumber": 7}, {"label": "Jn 1:29", "chapterId": "JHN-1", "verseNumber": 29}, {"label": "Heb 12:2-3", "chapterId": "HEB-12", "verseNumber": 2}], "altTitle": "My Faith Looks Trustingly", "musicCredit": "'Olivet' Lowell Mason, 1832", "number": 153}, {"title": "My Hope Is Built", "sectionId": 5, "wordsCredit": "Edward Mote, circa 1834", "verses": ["My hope is built on nothing less Than Jesus' blood and righteousness. I dare not trust the sweetest frame, But wholly trust in Jesus' Name.", "When darkness veils His lovely face, I rest on His unchanging grace. In every high and stormy gale, My anchor holds within the veil.", "His oath, His covenant, His blood, Support me in the whelming flood. When all around my soul gives way, He then is all my hope and stay.", "When He shall come with trumpet sound, Oh may I then in Him be found. Dressed in His righteousness alone, Faultless to stand before the throne."], "scriptureLinks": [{"label": "1 Pt 2:5-8", "chapterId": "1PE-2", "verseNumber": 5}, {"label": "Eph 2:19-22", "chapterId": "EPH-2", "verseNumber": 19}, {"label": "Mt 7:24-27", "chapterId": "MAT-7", "verseNumber": 24}], "altTitle": "The Solid Rock", "musicCredit": "'Melita' John Bacchus Dykes, 1861", "refrain": "On Christ the solid Rock I stand, All other ground is sinking sand.", "number": 154}, {"title": "My Soul, Now Praise Thy Maker", "sectionId": 5, "wordsCredit": "Johann Graumann, 1525. Translated by Catherine Winkworth, 1863", "verses": ["My soul, now praise thy maker! Let all within me bless His name Who maketh thee partaker Of mercies more than thou dar'st claim. Forget Him not whose meekness Still bears with all thy sin, Who healeth all thy weakness, Renews thy life within. Whose grace and care are endless And saved thee through the past; Who leaves no suff'rer friendless, But rights the wronged at last.", "He shows to man His treasure Of judgment, truth, and righteousness, His love beyond all measure, His yearning pity o'er distress, Nor treats us as we merit, But lays His anger by. The humble, contrite spirit Finds His compassion nigh; And high as Heav'n above us, As break from close of day, So far, since He doth love us, He puts our sins away.", "For as a tender father Hath pity on his children here, He in His arms will gather All who are His in childlike fear. He knows how frail our powers Who but from dust are made; We flourish like the flowers, And even so we fade; The wind but o'er them passes, And all their bloom is o'er— We wither like the grasses, Our place knows us no more.", "God's grace alone endureth, And children's children yet shall prove How He with strength assureth The hearts of all that seek His love. In Heav'n is fixed His dwelling, His rule is over all; Angels, in might excelling, Bright hosts, before Him fall. Praise Him who ever reigneth, All ye who hear His Word, Nor our poor hymns disdaineth— My soul, O praise the Lord!"], "scriptureLinks": [{"label": "Ps 103:1-22", "chapterId": "PSA-103", "verseNumber": 1}, {"label": "146:1-2", "chapterId": "PSA-146", "verseNumber": 1}, {"label": "Mk 12:30", "chapterId": "MRK-12", "verseNumber": 30}], "altTitle": "My Soul, Now Bless Thy Maker", "musicCredit": "'Nun Lob, Mein Seel' from Johannes Kugelmann`s Concentus Novi, 1540", "number": 155}, {"title": "O For A Thousand Tongues", "sectionId": 5, "wordsCredit": "Charles Wesley, 1740", "verses": ["O for a thousand tongues to sing My great Redeemer's praise, The glories of my God and King, The triumphs of His grace!", "My gracious Master and my God, Assist me to proclaim, To spread through all the earth abroad The honors of Thy name.", "Jesus! the name that charms our fears, That bids our sorrows cease; 'Tis music in the sinner's ears, 'Tis life, and health, and peace.", "He breaks the pow'r of canceled sin, He sets the prisoner free; His blood can make the foulest clean, His blood availed for me.", "He speaks, and, listening to His voice, New life the dead receive, The mournful, broken hearts rejoice, The humble poor believe.", "Hear Him, ye deaf; His praise, ye dumb, Your loosened tongues employ; Ye blind, behold your Savior come, And leap, ye lame, for joy.", "In Christ your Head, you then shall know, Shall feel your sins forgiven; Anticipate your heaven below, And own that love is heaven.", "Glory to God, and praise and love Be ever, ever given, By saints below and saints above, The church in earth and heaven.", "On this glad day the glorious Sun Of Righteousness arose; On my benighted soul He shone And filled it with repose.", "Sudden expired the legal strife, 'Twas then I ceased to grieve; My second, real, living life I then began to live.", "Then with my heart I first believed, Believed with faith divine, Power with the Holy Ghost received To call the Savior mine.", "I felt my Lord's atoning blood Close to my soul applied; Me, me He loved, the Son of God, For me, for me He died!", "I found and owned His promise true, Ascertained of my part, My pardon passed in heaven I knew When written on my heart.", "Look unto Him, ye nations, own Your God, ye fallen race; Look, and be saved through faith alone, Be justified by grace.", "See all your sins on Jesus laid: The Lamb of God was slain, His soul was once an offering made For every soul of man.", "Awake from guilty nature's sleep, And Christ shall give you light, Cast all your sins into the deep, And wash the Æthiop white.", "Harlots and publicans and thieves In holy triumph join! Saved is the sinner that believes From crimes as great as mine.", "Murderers and all ye hellish crew, Ye sons of lust and pride, Believe the Savior died for you; For me the Savior died.", "With me, your chief, ye then shall know, Shall feel your sins forgiven; Anticipate your heaven below, And own that love is heaven."], "scriptureLinks": [{"label": "Ps 96:1-3", "chapterId": "PSA-96", "verseNumber": 1}, {"label": "1 Pt 1:18-19", "chapterId": "1PE-1", "verseNumber": 18}, {"label": "Rev 5:11-13", "chapterId": "REV-5", "verseNumber": 11}], "musicCredit": "'Azmon' Carl G. Gläser, 1828", "number": 156}, {"title": "O That The Lord Would Guide My Ways", "sectionId": 5, "wordsCredit": "Isaac Watts, 1719, alt", "verses": ["O that the Lord would guide my ways To keep His statutes still! O that my God would grant me grace To know and do His will!", "O send Thy Spirit down to write Thy law upon my heart! Nor let my tongue indulge deceit, Nor act the liar's part.", "From vanity turn off mine eyes; Let no corrupt design, Nor covetous desires arise Within this soul of mine.", "Order my footsteps by Thy Word, And make my heart sincere; Let sin have no dominion, Lord, But keep my conscience clear.", "Assist my soul, too apt to stray, A stricter watch to keep; And should I e'er forget Thy way, Restore Thy wand'ring sheep.", "Make me to walk in Thy commands, 'Tis a delightful road; Nor let my head, or heart, or hands, Offend against my God."], "scriptureLinks": [{"label": "Ps 119:5", "chapterId": "PSA-119", "verseNumber": 5}, {"label": "Ez 36:25-29", "chapterId": "EZK-36", "verseNumber": 25}, {"label": "11:19-20", "chapterId": "EZK-11", "verseNumber": 19}], "musicCredit": "'Evan' or 'Eva' William H. Havergal, 1847", "number": 157}, {"title": "On My Heart Imprint Thine Image", "sectionId": 5, "wordsCredit": "Thomas Hansen Kingo, 1689. Translated by Peer Olsen Strømme, 1898, alt", "verses": ["On my heart imprint Thine image, Blessed Jesus, King of Grace That life's riches, cares, and pleasures, Have no pow'r to Thee efface; This the superscription be: Jesus crucified for me, Is my life, my hope's foundation, And my glory and salvation."], "scriptureLinks": [{"label": "2Cor 3:18", "chapterId": "2CO-3", "verseNumber": 18}, {"label": "Lk 23:38", "chapterId": "LUK-23", "verseNumber": 38}, {"label": "1Cor 15:49", "chapterId": "1CO-15", "verseNumber": 49}], "musicCredit": "'Der Am Kreuz' Johann Balthasar König, 1738", "number": 158}, {"title": "On What Has Now Been Sown", "sectionId": 5, "wordsCredit": "John Newton, 1779", "verses": ["On what has now been sown Thy blessing, Lord, bestow; The pow'r is Thine alone To make it spring and grow. Do Thou in grace the harvest raise, And Thou alone shalt have the praise.", "To Thee our wants are known, From Thee are all our pow'rs; Accept what is Thine own And pardon what is ours. Our praises, Lord, and prayers receive And to Thy Word a blessing give.", "Oh, grant that each of us Now met before Thee here May meet together thus When Thou and Thine appear And follow Thee to Heav'n, our home. E'en so, Amen, Lord Jesus, come!"], "scriptureLinks": [{"label": "Mk 4:26-29", "chapterId": "MRK-4", "verseNumber": 26}, {"label": "1Cor 3:6-7", "chapterId": "1CO-3", "verseNumber": 6}, {"label": "1Thess 3:11-13", "chapterId": "1TH-3", "verseNumber": 11}], "musicCredit": "'Darwall`s 148th' John Darwall, 1770", "number": 159}, {"title": "Open Now Thy Gates of Beauty", "sectionId": 5, "wordsCredit": "Benjamin Schmolck, 1730. Translated by Catherine Winkworth, 1863", "verses": ["Open now thy gates of beauty, Zion, let me enter there, Where my soul in joyful duty Waits for Him Who answers prayer. Oh, how blessèd is this place, Filled with solace, light and grace!", "Lord, my God, I come before Thee, Come Thou also unto me; Where we find Thee and adore Thee, There a heav'n on earth must be. To my heart, oh, enter Thou, Let it be Thy temple now!", "Here Thy praise is gladly chanted, Here Thy seed is duly sown; Let my soul, where it is planted, Bring forth precious sheaves alone, So that all I hear may be Fruitful unto life in me.", "Thou my faith increase and quicken, Let me keep Thy gift divine, Howsoe'er temptations thicken; May Thy Word still o'er me shine As my guiding star through life, As my comfort in my strife.", "Speak, O God, and I will hear Thee, Let Thy will be done indeed; May I undisturbed draw near Thee While Thou dost Thy people feed. Here of life the fountain flows, Here is balm for all our woes."], "scriptureLinks": [{"label": "Ps 100:1-5", "chapterId": "PSA-100", "verseNumber": 1}, {"label": "Ps 118:19-26", "chapterId": "PSA-118", "verseNumber": 19}, {"label": "Is 26:1-4", "chapterId": "ISA-26", "verseNumber": 1}], "musicCredit": "'Unser Herrscher' or 'Neander' Joachim Neander, 1680", "number": 160}, {"title": "Pass Me Not, O Gentle Savior", "sectionId": 5, "wordsCredit": "Fanny J. Crosby, 1868", "verses": ["Pass me not, O gentle Savior, Hear my humble cry; While on others Thou art calling, Do not pass me by.", "Let me at Thy throne of mercy Find a sweet relief, Kneeling there in deep contrition; Help my unbelief.", "3, Trusting only in Thy merit, Would I seek Thy face; Heal my wounded, broken spirit, Save me by Thy grace.", "Thou the Spring of all my comfort, More than life to me, Whom have I on earth beside Thee? Whom in Heav'n but Thee?"], "scriptureLinks": [{"label": "Mt 20:30-34", "chapterId": "MAT-20", "verseNumber": 30}, {"label": "Gen 18:1-5", "chapterId": "GEN-18", "verseNumber": 1}, {"label": "Mk 9:21-25", "chapterId": "MRK-9", "verseNumber": 21}], "musicCredit": "'Pass Me Not O Gentle Savior' William Howard Doane, 1870", "refrain": "Savior, Savior, Hear my humble cry; While on others Thou art calling, Do not pass me by.", "number": 161}, {"title": "Rescue the Perishing", "sectionId": 5, "wordsCredit": "Fanny Crosby, 1869, alt", "verses": ["Rescue the perishing, care for the dying, Snatch them in pity from sin and the grave; Weep o'er the erring one, lift up the fallen, Tell them of Jesus, the mighty to save.", "Though they are slighting Him, still He is waiting, Waiting the penitent child to receive; Plead with them earnestly, plead with them gently; He will forgive they should only believe.", "Down in the human heart, crushed by the tempter, Feelings lie buried that grace can restore; Touched by a loving heart, wakened by kindness, Chords that were broken will vibrate once more.", "Rescue the perishing, duty demands it; Strength for thy labor the Lord will provide; Back to the narrow way patiently win them; Tell the poor wand'rer a Savior has died."], "scriptureLinks": [{"label": "Jude 1:22-23", "chapterId": "JUD-1", "verseNumber": 22}, {"label": "2Cor 7:10-12", "chapterId": "2CO-7", "verseNumber": 10}, {"label": "1Tim 4:16", "chapterId": "1TI-4", "verseNumber": 16}], "musicCredit": "'Rescue the Perishing' William Howard Doane, 1870", "refrain": "Rescue the perishing, care for the dying, Jesus is merciful, Jesus will save.", "number": 162}, {"title": "Rock of Ages", "sectionId": 5, "wordsCredit": "Augustus Montague Toplady, 1776", "verses": ["Rock of Ages, cleft for me, Let me hide myself in Thee; Let the water and the blood, From Thy wounded side which flowed, Be of sin the double cure; Save from wrath and make me pure.", "Not the labor of my hands Can fulfill Thy law's demands; Could my zeal no respite know, Could my tears forever flow, All for sin could not atone; Thou must save, and Thou alone.", "Nothing in my hand I bring, Simply to the cross I cling; Naked, come to Thee for dress; Helpless look to Thee for grace; Foul, I to the fountain fly; Wash me, Savior, or I die.", "While I draw this fleeting breath, When mine eyes shall close in death, When I soar to worlds unknown, See Thee on Thy judgment throne, Rock of Ages, cleft for me, Let me hide myself in Thee."], "scriptureLinks": [{"label": "Ps 89:26", "chapterId": "PSA-89", "verseNumber": 26}, {"label": "Deut 32:1-4", "chapterId": "DEU-32", "verseNumber": 1}, {"label": "Hab 1:12", "chapterId": "HAB-1", "verseNumber": 12}], "musicCredit": "'Toplady' Thomas Hastings, 1830", "number": 163}, {"title": "Salvation Unto Us Has Come", "sectionId": 5, "wordsCredit": "Paul Speratus, 1523. Translation composite", "verses": ["Salvation unto us has come By God's free grace and favor; Good works cannot avert our doom, They help and save us never. Faith looks to Jesus Christ alone, Who did for all the world atone; He is our one Redeemer.", "What God did in His law demand And none to Him could render Caused wrath and woe on every hand For man, the vile offender. Our flesh has not those pure desires The spirit of the Law requires, And lost is our condition.", "It was a false, misleading dream That God His Law had given So sinners could themselves redeem And by their works gain Heaven. The Law is but a mirror bright To bring the inbred sin to light That lurks within our nature.", "From sin our flesh could not abstain Sin held its sway unceasing; The task was useless and in vain, Our guilt was e'er increasing. None can remove sin's poisoned dart Or purify our guileful heart? So deep is our corruption.", "Yet as the Law must be fulfilled Or we must die despairing, Christ came and hath God's anger stilled, Our human nature sharing. He hath for us the Law obeyed And thus the Father's vengeance stayed Which over us impended.", "Since Christ hath full atonement made And brought to us salvation, Each Christian therefore may be glad And build on this foundation. Thy grace alone, dear Lord, I plead, Thy death is now my life indeed, For Thou hast paid my ransom.", "Let me not doubt, but trust in Thee, Thy Word cannot be broken; Thy call rings out, \"Come unto Me!\" No falsehood hast Thou spoken. Baptized into Thy precious name, My faith cannot be put to shame, And I shall never perish.", "The Law reveals the guilt of sin And makes men conscience-stricken; The Gospel then doth enter in The sinful soul to quicken. Come to the cross, trust Christ, and live; The Law no peace can ever give, No comfort and no blessing.", "Faith clings to Jesus' cross alone And rests in Him unceasing; And by its fruits true faith is known, With love and hope increasing. Yet faith alone doth justify, Works serve thy neighbor and supply The proof that faith is living.", "All blessing, honor, thanks, and praise To Father, Son, and Spirit, The God that saved us by His grace,- All glory to His merit! O Triune God in heaven above, Who hast revealed Thy saving love, Thy blessed name be hallowed."], "scriptureLinks": [{"label": "Eph 2:1-10", "chapterId": "EPH-2", "verseNumber": 1}, {"label": "Rom 3:10-31", "chapterId": "ROM-3", "verseNumber": 10}, {"label": "5:1-11", "chapterId": "ROM-5", "verseNumber": 1}], "altTitle": "To Us Salvation Now Is Come", "musicCredit": "'Es ist das Heil uns Kommen Her' traditional German circa 1400 from Etlich Christlich Lider, Wittenberg, 1524", "number": 164}, {"title": "Stricken, Smitten, and Afflicted", "sectionId": 5, "wordsCredit": "Thomas Kelly, 1804", "verses": ["Stricken, smitten, and afflicted, See Him dying on the tree! 'Tis the Christ by man rejected; Yes, my soul, 'tis He, 'tis He! 'Tis the long expected prophet, David's Son, yet David's Lord; Proofs I see sufficient of it: 'Tis a true and faithful Word.", "Tell me, ye who hear Him groaning, Was there ever grief like His? Friends through fear His cause disowning, Foes insulting his distress: Many hands were raised to wound Him, None would interpose to save; But the deepest stroke that pierced Him Was the stroke that Justice gave.", "Ye who think of sin but lightly, Nor suppose the evil great, Here may view its nature rightly, Here its guilt may estimate. Mark the Sacrifice appointed! See Who bears the awful load! 'Tis the Word, the Lord's Anointed, Son of Man, and Son of God.", "Here we have a firm foundation, Here the refuge of the lost. Christ the Rock of our salvation, Christ the Name of which we boast. Lamb of God for sinners wounded! Sacrifice to cancel guilt! None shall ever be confounded Who on Him their hope have built."], "scriptureLinks": [{"label": "Is 53:3-6", "chapterId": "ISA-53", "verseNumber": 3}, {"label": "Acts 4:11-12", "chapterId": "ACT-4", "verseNumber": 11}, {"label": "Rom 4:25", "chapterId": "ROM-4", "verseNumber": 25}], "musicCredit": "'O Mein Jesu, Ich Muss Sterben' or 'Wo Ist Jesus, Mein Verlangen' from Geistliches Volkslied, 1850", "number": 165}, {"title": "The Gospel Shows The Father's Grace", "sectionId": 5, "wordsCredit": "Matthias Loy, 1863", "verses": ["The Gospel shows the Father's grace, Who sent his Son to save our race, Proclaims how Jesus lived and died That man might thus be justified.", "It sets the Lamb before our eyes, Who made th'atoning sacrifice, And calls the souls with guilt oppressed To come and find eternal rest.", "It brings the Savior's righteousness Our souls to robe in royal dress; From all our guilt it brings release And gives the troubled conscience peace.", "It is the pow'r of God to save From sin and Satan and the grave; It works the faith, which firmly clings To all the treasures which it brings.", "It bears to all the tidings glad And bids their hearts no more be sad; The heavy laden souls it cheers And banishes their guilty fears.", "May we in faith its tidings learn Nor thanklessly its blessings spurn; May we in faith its truth confess And praise the Lord our Righteousness!"], "scriptureLinks": [{"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Rom 1:16-17", "chapterId": "ROM-1", "verseNumber": 16}, {"label": "1 Jn 4:9-10", "chapterId": "1JN-4", "verseNumber": 9}], "musicCredit": "'Herr Jesu Christ, Dict Zu Uns Wend' from Cantionale Germanicum, Dresden, 1628", "number": 166}, {"title": "To Avert From Men God's Wrath", "sectionId": 5, "wordsCredit": "Latin c. 1400, sometimes attr. John Hus. Translated Christian Ignatius Latrobe, 1789", "verses": ["To avert from men God's wrath Jesus suffered in our stead; By an ignominious death He a full atonement made; And by His most precious blood, Brought us, sinners, nigh to God.", "That we never should forget This great Love on us bestowed, He gave us His flesh to eat, and to drink His precious blood; All who sick and needy are May receive in Him a share.", "Hither each afflicted soul May repair, though filled with grief; To the sick, not to the whole, the Physician brings relief; Fear not, therefore, but draw nigh, Christ will all your wants supply.", "He who in self— righteousness Fixes any hope or stay, Has not on a wedding dress, And with shame is sent away; To the hungry, weary heart, He will food and rest impart.", "But examine first your case, Whether you be in the faith; Do you long for pard'ning grace? Is your only hope His death? Then, howe'er your soul's oppressed, Come, you are a worthy guest.", "He who Jesus' mercy knows, Is from wrath and envy freed; Love unto our neighbor shows That we are His flock indeed; Thus we may in all our ways Show forth our Redeemer's praise."], "scriptureLinks": [{"label": "1Thess 5:9", "chapterId": "1TH-5", "verseNumber": 9}, {"label": "Eph 5:6-14", "chapterId": "EPH-5", "verseNumber": 6}, {"label": "Rom 5:9-10", "chapterId": "ROM-5", "verseNumber": 9}], "musicCredit": "'Gethsemane' or 'Petra' Richard Redhead, 1853", "number": 167}, {"title": "To God Be The Glory", "sectionId": 5, "wordsCredit": "Fanny Crosby, 1875", "verses": ["To God be the glory, great things He has done; So loved He the world that He gave us His Son Who yielded His life an atonement for sin, And opened the life gate that all may go in.", "O perfect redemption, the purchase of blood, To every believer the promise of God; The vilest offender who truly believes, That moment from Jesus a pardon receives.", "Great things He has taught us, great things He has done, And great our rejoicing through Jesus the Son; But purer, and higher, and greater will be Our wonder, our transport, when Jesus we see."], "scriptureLinks": [{"label": "Job 5:9", "chapterId": "JOB-5", "verseNumber": 9}, {"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Ps 40:5", "chapterId": "PSA-40", "verseNumber": 5}], "musicCredit": "'To God Be The Glory' William Howard Doane, 1875", "refrain": "Praise the Lord, praise the Lord, Let the earth hear His voice! Praise the Lord, praise the Lord, Let the people rejoice! O come to the Father, through Jesus the Son, And give Him the glory, great things He has done.", "number": 168}, {"title": "Alleluia, Alleluia! Hearts to Heaven and Voices Raise", "sectionId": 6, "wordsCredit": "Christopher Wordsworth, 1865", "verses": ["Alleluia, alleluia! Hearts to Heav'n and voices raise: Sing to God a hymn of gladness, sing to God a hymn of praise. He, who on the cross a Victim, for the world's salvation bled, Jesus Christ, the King of glory, now is risen from the dead.", "Now the iron bars are broken, Christ from death to life is born, Glorious life, and life immortal, on the holy Easter morn. Christ has triumphed, and we conquer by His mighty enterprise: We with Him to life eternal by His resurrection rise.", "Christ is risen, Christ, the first fruits of the holy harvest field, Which will all its full abundance at His second coming yield: Then the golden ears of harvest will their heads before Him wave, Ripened by His glorious sunshine from the furrows of the grave.", "Christ is risen, we are risen! Shed upon us heav'nly grace, Rain and dew and gleams of glory from the brightness of Thy face; That we, with our hearts in Heaven, here on earth may fruitful be, And by angel hands be gathered, and be ever, Lord, with Thee.", "Alleluia, alleluia! Glory be to God on high; Alleluia! to the Savior who has gained the victory; Alleluia! to the Spirit, fount of love and sanctity: Alleluia, alleluia! to the Triune Majesty."], "scriptureLinks": [{"label": "1Cor 15:54-57", "chapterId": "1CO-15", "verseNumber": 54}, {"label": "Is 25:7-9", "chapterId": "ISA-25", "verseNumber": 7}, {"label": "Rev 21:4", "chapterId": "REV-21", "verseNumber": 4}], "musicCredit": "'Ode to Joy' Ludwig van Beethoven; Adapted by Edward Hodges, 1824", "number": 169}, {"title": "Christ Jesus Lay In Death's Strong Bands", "sectionId": 6, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854", "verses": ["Christ Jesus lay in death's strong bands, For our offenses given; But now at God's right hand He stands, And brings us life from Heaven. Wherefore let us joyful be, And sing to God right thankfully Loud songs of Alleluia! Alleluia!", "No son of man could conquer Death, Such mischief sin had wrought us, For innocence dwelt not on earth, And therefore Death had brought us Into thralldom from of old And ever grew more strong and bold And kept us in his bondage. Alleluia!", "But Jesus Christ, God's only Son, To our low state descended, The cause of Death He has undone, His power forever ended, Ruined all his right and claim And left him nothing but the name, His sting is lost forever. Alleluia!", "It was a strange and dreadful strife When life and death contended; The victory remained with life; The reign of death was ended. Stripped of power, no more it reigns, An empty form alone remains Death's sting is lost forever! Alleluia!", "Here the true Paschal Lamb we see, Whom God so freely gave us; He died on the accursed tree So strong His love! to save us. See, His blood doth mark our door; Faith points to it, Death passes o'er, And Satan cannot harm us. Alleluia!", "So let us keep the festival Where to the Lord invites us; Christ is Himself the joy of all, The Sun that warms and lights us. By His grace He doth impart Eternal sunshine to the heart; The night of sin is ended! Alleluia!", "Then let us feast this Easter day On the true Bread of Heaven; The Word of grace hath purged away The old and wicked leaven. Christ alone our souls will feed; He is our Meat and Drink indeed; Faith lives upon no other! Alleluia!"], "scriptureLinks": [{"label": "1Cor 15:54-57", "chapterId": "1CO-15", "verseNumber": 54}, {"label": "Acts 2:24", "chapterId": "ACT-2", "verseNumber": 24}, {"label": "1Cor 5:7b", "chapterId": "1CO-5", "verseNumber": 7}], "altTitle": "In Death's Strong Bands", "musicCredit": "'Christ lag in Tobes Banden' or 'Torgau' from Walter's Geistliche Gesangbüchlein, 1524", "number": 170}, {"title": "Christ Returneth", "sectionId": 6, "wordsCredit": "H. L. Turner, 1878", "verses": ["It may be at morn, when the day is awaking, When sunlight through darkness and shadow is breaking That Jesus will come in the fullness of glory To receive from the world \"His own.\"", "It may be at midday, it may be at twilight, It may be, perchance, that the blackness of midnight Will burst into light in the blaze of His glory, When Jesus receives \"His own.\"", "While hosts cry Hosanna, from heaven descending, With glorified saints and the angels attending, With grace on His brow, like a halo of glory, Will Jesus receive \"His own.\"", "Oh, joy! oh, delight! should we go without dying, No sickness, no sadness, no dread and no crying. Caught up through the clouds with our Lord into glory, When Jesus receives \"His own.\""], "scriptureLinks": [{"label": "Acts 1:10-11", "chapterId": "ACT-1", "verseNumber": 10}, {"label": "1Cor 15:51-57", "chapterId": "1CO-15", "verseNumber": 51}, {"label": "1Thess 4:15-17", "chapterId": "1TH-4", "verseNumber": 15}], "musicCredit": "'Christ Returneth' James McGranahan, 1891", "refrain": "O Lord Jesus, how long, how long Ere we shout the glad song, Christ returneth! Hallelujah! Hallelujah! Amen. Hallelujah! Amen.", "number": 171}, {"title": "Christ The Lord Is Risen Today (Lyra)", "sectionId": 6, "wordsCredit": "Stanzas 1-7, Charles Wesley, 1739. Stanzas 8-10, 14th Century; translated in Lyra Davidica", "verses": ["Christ, the Lord, is risen today, Alleluia! Sons of men and angels say, Alleluia! Raise your joys and triumphs high, Alleluia! Sing, ye heavens, and earth, reply, Alleluia!", "Love's redeeming work is done, Alleluia! Fought the fight, the battle won, Alleluia! Lo! the Sun's eclipse is o'er, Alleluia! Lo! He sets in blood no more, Alleluia!", "Vain the stone, the watch, the seal, Alleluia! Christ hath burst the gates of hell, Alleluia! Death in vain forbids His rise, Alleluia! Christ hath opened paradise, Alleluia!", "Lives again our glorious King, Alleluia! Where, O death, is now thy sting? Alleluia! Once He died our souls to save, Alleluia! Where thy victory, O grave? Alleluia!", "Soar we now where Christ hath led, Alleluia! Following our exalted Head, Alleluia! Made like Him, like Him we rise, Alleluia! Ours the cross, the grave, the skies, Alleluia!", "Hail, the Lord of earth and Heaven, Alleluia! Praise to Thee by both be given, Alleluia! Thee we greet triumphant now, Alleluia! Hail, the resurrection, thou, Alleluia!", "King of glory, Soul of bliss, Alleluia! Everlasting life is this, Alleluia! Thee to know, Thy power to prove, Alleluia! Thus to sing and thus to love, Alleluia!", "Hymns of praise then let us sing, Alleluia! Unto Christ, our heavenly King, Alleluia! Who endured the cross and grave, Alleluia! Sinners to redeem and save. Alleluia!", "But the pains that He endured, Alleluia! Our salvation have procured, Alleluia! Now above the sky He's King, Alleluia! Where the angels ever sing. Alleluia!", "Jesus Christ is risen today, Alleluia! Our triumphant holy day, Alleluia! Who did once upon the cross, Alleluia! Suffer to redeem our loss. Alleluia!"], "scriptureLinks": [{"label": "Mt 28:5-6", "chapterId": "MAT-28", "verseNumber": 5}, {"label": "Lk 24:4-7", "chapterId": "LUK-24", "verseNumber": 4}, {"label": "1Cor 15:55-57", "chapterId": "1CO-15", "verseNumber": 55}], "musicCredit": "'Llanfair' Robert Williams, 1817", "number": 172}, {"title": "Christ The Lord Is Risen Today (Lyra)", "sectionId": 6, "wordsCredit": "Stanzas 1-7, Charles Wesley, 1739. Stanzas 8-10, 14th Century; translated in Lyra Davidica", "verses": ["\"Christ, the Lord, is risen today!\" Sons of men and angels say, Raise your joys and triumphs high, Sing, ye heavens, and earth, reply!", "Love's redeeming work is done, Fought the fight, the battle won, Lo! the Sun's eclipse is o'er, Lo! He sets in blood no more.", "Vain the stone, the watch, the seal, Christ hath burst the gates of hell! Death in vain forbids His rise, Christ hath opened paradise!", "Lives again our glorious King Where, O death, is now thy sting? Once He died our souls to save, Where thy victory, O grave?", "Soar we now where Christ hath led Following our exalted Head; Made like Him, like Him we rise, Ours the cross, the grave, the skies.", "Hail, the Lord of earth and Heaven: Praise to Thee by both be given. Thee we greet triumphant now; Hail, the resurrection, thou.", "King of glory, Soul of bliss, Everlasting life is this, Thee to know, Thy power to prove, Thus to sing and thus to love.", "Hymns of praise then let us sing Unto Christ, our heavenly King Who endured the cross and grave Sinners to redeem and save.", "But the pains that He endured Our salvation have procured. Now above the sky He's King Where the angels ever sing.", "Jesus Christ is risen today, Our triumphant holy day. Who did once upon the cross Suffer to redeem our loss."], "scriptureLinks": [{"label": "Mt 28:5-6", "chapterId": "MAT-28", "verseNumber": 5}, {"label": "Lk 24:4-7", "chapterId": "LUK-24", "verseNumber": 4}, {"label": "1Cor 15:55-57", "chapterId": "1CO-15", "verseNumber": 55}], "musicCredit": "'Orientis Partibus' or 'Redhead 45' traditional French", "number": 173}, {"title": "Crown Him With Many Crowns", "sectionId": 6, "wordsCredit": "Verses 1, 4, 5, 6 & 9: Matthew Bridges, The Passion of Jesus, 1852. verses 2 & 3: Godfrey Thring, Hymns and Sacred Lyrics, 1874", "verses": ["Crown Him with many crowns, the Lamb upon His throne. Hark! How the heav'nly anthem drowns all music but its own. Awake, my soul, and sing of Him who died for thee, And hail Him as thy matchless King through all eternity.", "Crown Him the virgin's Son, the God incarnate born, Whose arm those crimson trophies won which now His brow adorn; Fruit of the mystic rose, as of that rose the stem; The root whence mercy ever flows, the Babe of Bethlehem.", "Crown Him the Son of God, before the worlds began, And ye who tread where He hath trod, crown Him the Son of Man; Who every grief hath known that wrings the human breast, And takes and bears them for His own, that all in Him may rest.", "Crown Him the Lord of life, who triumphed o'er the grave, And rose victorious in the strife for those He came to save. His glories now we sing, Who died, and rose on high, Who died eternal life to bring, and lives that death may die.", "Crown Him the Lord of peace, Whose pow'r a scepter sways From pole to pole, that wars may cease, and all be prayer and praise. His reign shall know no end, and round His pierced feet Fair flow'rs of paradise extend their fragrance ever sweet.", "Crown Him the Lord of love, behold His hands and side, Those wounds, yet visible above, in beauty glorified. No angel in the sky can fully bear that sight, But downward bends his burning eye at mysteries so bright.", "Crown Him the Lord of Heaven, enthroned in worlds above, Crown Him the King to Whom is given the wondrous name of Love. Crown Him with many crowns, as thrones before Him fall; Crown Him, ye kings, with many crowns, for He is King of all.", "Crown Him the Lord of lords, who over all doth reign, Who once on earth, the incarnate Word, for ransomed sinners slain, Now lives in realms of light, where saints with angels sing Their songs before Him day and night, their God, Redeemer, King.", "Crown Him the Lord of years, the Potentate of time, Creator of the rolling spheres, ineffably sublime. All hail, Redeemer, hail! For Thou has died for me; Thy praise and glory shall not fail throughout eternity."], "scriptureLinks": [{"label": "Rev 19:12", "chapterId": "REV-19", "verseNumber": 12}, {"label": "5:13", "chapterId": "REV-5", "verseNumber": 13}], "musicCredit": "'Diademata' George J. Elvey, 1868", "number": 174}, {"title": "From Heaven Above To Earth I Come", "sectionId": 6, "wordsCredit": "Martin Luther, 1535. translated by Catherine Winkworth, 1855", "verses": ["From Heaven above to earth I come, To bear good news to every home; Glad tidings of great joy I bring, Whereof I now will say and sing.", "To you, this night, is born a Child Of Mary, chosen mother mild; This tender Child of lowly birth, Shall be the joy of all your earth.", "'Tis Christ our God, Who far on high Had heard your sad and bitter cry; Himself will your Salvation be, Himself from sin will make you free.", "He brings those blessings long ago Prepared by God for all below; That in His heavenly kingdom blest You may with us forever rest.", "These are the tokens ye shall mark, The swaddling clothes and manger dark; There shall ye find the young Child laid, By Whom the heav'ns and earth were made.", "Now let us all, with gladsome cheer, Follow the shepherds, and draw near To see this wondrous Gift of God, Who hath His own dear Son bestowed.", "Give heed, my heart, lift up thine eyes! What is it in yon manger lies? Who is this Child, so young and fair? The blessèd Christ Child lieth there!", "Welcome to earth, Thou noble Guest, Through Whom e'en wicked men are blest! Thou com'st to share our misery, What can we render, Lord, to Thee!", "Ah, Lord, Who hast created all, How hast Thou made Thee weak and small, To lie upon the coarse dry grass, The food of humble ox and ass.", "Were earth a thousand times as fair, Beset with gold and jewels rare, She yet were far too poor to be A narrow cradle, Lord, for Thee.", "For velvets soft and silken stuff Thou hast but hay and straw so rough, Whereon Thou King, so rich and great, As 'twere Thy heaven, art throned in state.", "Thus hath it pleased Thee to make plain The truth to us, poor fools and vain, That this world's honor, wealth and might Are naught and worthless in Thy sight.", "Ah, dearest Jesus, holy Child, Make Thee a bed, soft, undefiled, Here in my poor heart's inmost shrine, That I may evermore be Thine.", "My heart for very joy doth leap, My lips no more can silence keep, I too must sing, with joyful tongue, That sweetest ancient cradle song.", "Glory to God in highest Heaven, Who unto man His Son hath given, While angels sing, with pious mirth, A glad New Year to all the earth.", "This hymn was written by Martin Luther to teach his 3 year old son about Christmas, and became a part of the Luther family Christmas tradition. One of the adults would dress up as an angel and sing the first 5 verses to the family. The rest of the family would sing verses 6 through 15."], "scriptureLinks": [{"label": "Lk 2:6-20", "chapterId": "LUK-2", "verseNumber": 6}, {"label": "Jn 3:16-18", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Rom 5:8", "chapterId": "ROM-5", "verseNumber": 8}], "musicCredit": "'Vom Himmel Hoch' traditional German from Schumann's Geistliche Lieder, Leipzig, 1539", "number": 175}, {"title": "God, That Madest Earth and Heaven", "sectionId": 6, "wordsCredit": "verse 1, Reginald Heber, 1827. verse 2, William Mercer, 1864. verse 3, Richard Whately, 1838", "verses": ["God, that madest earth and Heaven, darkness and light; Who the day for toil hast given, for rest the night; May Thine angel guards defend us, Slumber sweet Thy mercy send us; Holy dreams and hopes attend us, all through the night.", "And when morn again shall call us, to run life's way, May we still, whate'er befall us, Thy will obey. From the pow'r of evil hide us, In the narrow pathway guide us, Nor Thy smile be e'er denied us all through the day.", "Guard us waking, guard us sleeping, and when we die, May we in Thy mighty keeping all peaceful lie; When the last dread call shall wake us, Do not Thou, our God, forsake us, But to reign in glory take us with Thee on high."], "scriptureLinks": [{"label": "Gen 1:1", "chapterId": "GEN-1", "verseNumber": 1}, {"label": "Ps 121:1-8", "chapterId": "PSA-121", "verseNumber": 1}, {"label": "Mt 11:28", "chapterId": "MAT-11", "verseNumber": 28}], "altTitle": "God, Who Madest Earth and Heaven or God, Who Made the Earth and Heaven", "musicCredit": "'Ar Hyd Y Nos' traditional Welsh", "number": 176}, {"title": "Guide Me, O Thou Great Jehovah", "sectionId": 6, "wordsCredit": "William Williams, 1745. Translated by Peter Williams, 1771", "verses": ["Guide me, O Thou great Jehovah, Pilgrim through this barren land. I am weak, but Thou art mighty; Hold me with Thy pow'rful hand. Bread of Heaven, Bread of Heaven, Feed me till I want no more; Feed me till I want no more.", "Open now the crystal fountain, Whence the healing stream doth flow; Let the fire and cloudy pillar Lead me all my journey through. Strong Deliv'rer, strong Deliv'rer, Be Thou still my Strength and Shield; Be Thou still my Strength and Shield.", "Lord, I trust Thy mighty power, Wondrous are Thy works of old; Thou deliver'st Thine from thralldom, Who for naught themselves had sold: Thou didst conquer, Thou didst conquer, Sin, and Satan and the grave, Sin, and Satan and the grave.", "When I tread the verge of Jordan, Bid my anxious fears subside; Death of deaths, and hell's destruction, Land me safe on Canaan's side. Songs of praises, songs of praises, I will ever give to Thee; I will ever give to Thee.", "Musing on my habitation, Musing on my heav'nly home, Fills my soul with holy longings: Come, my Jesus, quickly come; Vanity is all I see; Lord, I long to be with Thee! Lord, I long to be with Thee!"], "scriptureLinks": [{"label": "Ex 15:13", "chapterId": "EXO-15", "verseNumber": 13}, {"label": "Ex 13:21-22", "chapterId": "EXO-13", "verseNumber": 21}, {"label": "Jn 6:32-35", "chapterId": "JHN-6", "verseNumber": 32}], "musicCredit": "'Cwm Rhondda' John Hughes, 1907", "number": 177}, {"title": "Heavenly Father Send Thy Blessing", "sectionId": 6, "wordsCredit": "Christopher Wordsworth, 1863", "verses": ["Heav'nly Father, send Thy blessing On Thy children gathered here, May they all, Thy Name confessing, Be to Thee forever dear; May they be, like Joseph, loving, Dutiful, and chaste, and pure; And their faith, like David, proving, Steadfast unto death endure.", "Holy Savior, who in meekness Didst vouchsafe a child to be, Guide their steps, and help their weakness, Bless and make them like to Thee; Bear Thy lambs, when they are weary, In Thine arms and at Thy breast; Through life's desert, dry and dreary, Bring them to Thy heav'nly rest.", "Spread Thy golden pinions o'er them, Holy Spirit, from above, Guide them, lead them, go before them, Give them peace, and joy, and love; Thy true temples, Holy Spirit, May they with Thy glory shine, And immortal bliss inherit, And for evermore be Thine."], "scriptureLinks": [{"label": "Lk 11:13", "chapterId": "LUK-11", "verseNumber": 13}, {"label": "Mt 19:13-15", "chapterId": "MAT-19", "verseNumber": 13}, {"label": "Mt 21:15-16", "chapterId": "MAT-21", "verseNumber": 15}], "musicCredit": "'Ripley (Gregorian)' from a Gregorian Chant", "number": 178}, {"title": "Holy God, We Praise Thy Name", "sectionId": 6, "wordsCredit": "attr. Ignaz Franz, 1774. Translated by Clarence A. Walworth, 1858", "verses": ["Holy God, we praise Thy Name; Lord of all, we bow before Thee! All on earth Thy scepter claim, All in Heaven above adore Thee; Infinite Thy vast do main, Everlasting is Thy reign.", "Hark! the loud celestial hymn Angel choirs above are raising, Cherubim and seraphim, In unceasing chorus praising; Fill the heavens with sweet ac cord: Holy, holy, holy, Lord.", "Lo! the apostolic train Join the sacred Name to hallow; Prophets swell the loud refrain, And the white robed martyrs follow; And from morn to set of sun, Through the Church the song goes on.", "Holy Father, Holy Son, Holy Spirit, Three we name Thee; While in essence only One, Undivided God we claim Thee; And a doring bend the knee, While we own the mystery."], "scriptureLinks": [{"label": "Ps 103:3", "chapterId": "PSA-103", "verseNumber": 3}, {"label": "Heb 13:15", "chapterId": "HEB-13", "verseNumber": 15}, {"label": "Rev 4-6", "chapterId": "REV-13", "verseNumber": 4}], "musicCredit": "'Te Deum' or 'Hursley' or 'Grosser Gott, wir Loben Dich' from Katholisches Gesangbuch, Maria Theresa, 1774", "number": 179}, {"title": "Immortal, Invisible, God Only Wise", "sectionId": 6, "wordsCredit": "Walter Chalmers Smith, 1876", "verses": ["Immortal, invisible, God only wise, In light inaccessible hid from our eyes, Most blessèd, most glorious, the Ancient of Days, Almighty, victorious, Thy great Name we praise.", "Unresting, unhasting, and silent as light, Nor wanting, nor wasting, Thou rulest in might; Thy justice, like mountains, high soaring above Thy clouds, which are fountains of goodness and love.", "To all, life Thou givest, to both great and small; In all life Thou livest, the true life of all; We blossom and flourish as leaves on the tree, And wither and perish but naught changeth Thee.", "Great Father of glory, pure Father of light, Thine angels adore Thee, all veiling their sight; But of Thy rich graces this grace, Lord, impart Take the veil from our face, the vile from our heart.", "All laud we would render; O help us to see 'Tis only the splendor of light hideth Thee, And so let Thy glory, almighty, impart, Through Christ in His story, Thy Christ to the heart."], "scriptureLinks": [{"label": "1Tim 1:17", "chapterId": "1TI-1", "verseNumber": 17}, {"label": "Rom 1:20", "chapterId": "ROM-1", "verseNumber": 20}], "musicCredit": "'St. Denio' or 'Joanna' or 'Palestrina' traditional Welsh found in \"Caniadau y Cyssegr\" by John Roberts, 1839", "number": 180}, {"title": "It Came Upon A Midnight Clear", "sectionId": 6, "wordsCredit": "Edmund H. Sears, 1849", "verses": ["It came upon the midnight clear, That glorious song of old, From angels bending near the earth, To touch their harps of gold; \"Peace on the earth, good will to men, From Heaven's all gracious King.\" The world in solemn stillness lay, To hear the angels sing.", "Still through the cloven skies they come With peaceful wings unfurled, And still their heavenly music floats O'er all the weary world; Above its sad and lowly plains, They bend on hov'ring wing, And ever over its Babel sounds The blessèd angels sing.", "Yet with the woes of sin and strife The world has suffered long; Beneath the angel strain have rolled Two thousand years of wrong; And man, at war with man, hears not The love— song which they bring; O hush the noise, ye men of strife And hear the angels sing.", "And ye, beneath life's crushing load, Whose forms are bending low, Who toil along the climbing way With painful steps and slow, Look now! for glad and golden hours Come swiftly on the wing. O rest beside the weary road, And hear the angels sing!", "For lo! the days are hast'ning on, By prophet— bards foretold, When with the ever circling years Comes round the age of gold; When peace shall over all the earth Its ancient splendors fling, And the whole world send back the song Which now the angels sing."], "scriptureLinks": [{"label": "Lk 2:8-14", "chapterId": "LUK-2", "verseNumber": 8}, {"label": "Is 9:1-6", "chapterId": "ISA-9", "verseNumber": 1}, {"label": "Gen 11:9", "chapterId": "GEN-11", "verseNumber": 9}], "musicCredit": "'Carol' Richard S. Willis, 1861", "number": 181}, {"title": "Jesus Came, the Heavens Adoring", "sectionId": 6, "wordsCredit": "Godfrey Thring, 1864", "verses": ["Jesus came, the heav'ns adoring, Came with peace from realms on high; Jesus came for man's redemption, Lowly came on earth to die. Alleluia! Alleluia! Came in deep humility.", "Jesus comes again in mercy, When our hearts are bowed with care; Jesus comes again in answer To an earnest, heartfelt prayer; Alleluia! Alleluia! Comes to save us from despair.", "Jesus comes to hearts rejoicing, Bringing news of sins forgiv'n; Jesus comes in sounds of gladness, Leading souls redeemed to Heav'n; Alleluia! Alleluia! Now the gate of death is riv'n.", "Jesus comes in joy and sorrow, Shares alike our hopes and fears; Jesus comes, whate'er befalls us, Glads our hearts, and dries our tears; Alleluia! Alleluia! Cheering e'en our failing years.", "Jesus comes on clouds triumphant, When the heav'ns shall pass away; Jesus comes again in glory; Let us then our homage pay, Alleluia! Alleluia! Till the dawn of endless day."], "scriptureLinks": [{"label": "Mk 13:26", "chapterId": "MRK-13", "verseNumber": 26}, {"label": "Zech 9:9", "chapterId": "ZEC-9", "verseNumber": 9}, {"label": "Lk 2:14", "chapterId": "LUK-2", "verseNumber": 14}], "musicCredit": "'Sieh, hier bin ich, Ehrenkoenig' from Geistreiches Gesangbuch Darmstadt, Germany, 1698", "number": 182}, {"title": "Jesus Sinners Doth Receive", "sectionId": 6, "wordsCredit": "Erdmann Neumeister, 1718. Translated by Henry Mills, 1845 (et al)", "verses": ["Jesus sinners doth receive; Well may we this saying ponder Who in sin's delusions live, And from God and Heaven wander: Here is hope for all who grieve— Jesus sinners doth receive.", "We deserve but grief and shame,— Yet His words, rich grace revealing, Pardon, peace, and life proclaim; Here their ills have perfect healing Who with humble hearts believe— Jesus sinners doth receive.", "As the shepherd seeks to find His lost sheep that from Him strayeth, So hath Christ each soul in mind, And for its salvation prayeth; Fain He'd have each wand'rer live: Jesus sinners doth receive.", "Come, then, all by guilt oppressed, Jesus calls, and He would make you God's own children, pure and blest, And to glory He would take you; Think on this, and well believe Jesus sinners doth receive.", "Savior, now I come to Thee: Great my sins, a weary burden! Wilt Thou mercy show to me? Can I hope to find a pardon? I will trust: my soul relieve! Me, a sinner, Lord, receive!", "Rich Thy mercy— strangely good! O how oft have I offended! But through Thy redeeming blood All my fear of wrath is ended: Yes I now can witness give: Jesus sinners doth receive!", "Now my conscience is at peace; From the Law I stand acquitted; Christ hath purchased my release, And my every sin remitted. Naught remains my soul to grieve: Jesus sinners doth receive.", "Jesus sinners doth receive! Happy in His ceaseless favor, Here for Heaven I will live, There shall live with Him forever, \"Joy in death these tidings give; Jesus sinners doth receive!\""], "scriptureLinks": [{"label": "Lk 15:1-7", "chapterId": "LUK-15", "verseNumber": 1}, {"label": "7:36-48", "chapterId": "LUK-7", "verseNumber": 36}, {"label": "19:1-10", "chapterId": "LUK-19", "verseNumber": 1}], "musicCredit": "'Meinen Jesum Lass` Ich Nicht (Darmstadt)' from Neu-verfertigtes Darmstädtiches Gesang-Buch, 1699", "number": 183}, {"title": "Joyful, Joyful, We Adore Thee", "sectionId": 6, "wordsCredit": "Henry J. van Dyke, 1907", "verses": ["Joyful, joyful, we adore Thee, God of glory, Lord of love; Hearts unfold like flowers before Thee, opening to the sun above. Melt the clouds of sin and sadness; drive the dark of doubt away; Giver of immortal gladness, fill us with the light of day!", "All Thy works with joy surround Thee, earth and heaven reflect Thy rays, Stars and angels sing around Thee, center of unbroken praise. Field and forest, vale and mountain, flowery meadow, flashing sea, Singing bird and flowing fountain call us to rejoice in Thee.", "Thou art giving and forgiving, ever blessing, ever blessed, Wellspring of the joy of living, ocean depth of happy rest! Thou our Father, Christ our Brother, all who live in love are Thine; Teach us how to love each other, lift us to the joy divine.", "Mortals, join the happy chorus, which the morning stars began; Father love is reigning o'er us, brother love binds man to man. Ever singing, march we onward, victors in the midst of strife, Joyful music leads us Sunward in the triumph song of life."], "scriptureLinks": [{"label": "Ps 71:23", "chapterId": "PSA-71", "verseNumber": 23}, {"label": "Jn 12:46", "chapterId": "JHN-12", "verseNumber": 46}], "musicCredit": "'Ode to Joy' Ludwig van Beethoven; Adapted by Edward Hodges, 1824", "number": 184}, {"title": "Lo! He Comes With Clouds Descending", "sectionId": 6, "wordsCredit": "John Cennick, 1752. Altered by Charles Wesley, 1758, alt", "verses": ["Lo! He comes with clouds descending, Once for ev'ry sinner slain; Thousand thousand saints attending, Swell the triumph of His train: Hallelujah! Hallelujah! Hallelujah! God appears on earth to reign.", "Ev'ry eye shall now behold Him Robed in dreadful majesty; Those who set at naught and sold Him, Pierced and nailed Him to the tree, Deeply wailing, deeply wailing, deeply wailing, Shall the true Messiah see.", "Ev'ry island, sea, and mountain, Heav'n and earth, shall flee away; All who hate Him must, confounded, Hear the trump proclaim the day: Come to judgment! Come to judgment! Come to judgment! Come to judgment! Come away!", "Now redemption, long expected, See in solemn pomp appear; All His saints, by man rejected, Now shall meet Him in the air: Hallelujah! Hallelujah! Hallelujah! See the day of God appear!", "Answer Thine own bride and Spirit, Hasten, Lord, the gen'ral doom! The new Heav'n and earth inherit, Take Thy pining exiles home: All creation, all creation, all creation, Travails! groans! and bids Thee come!", "The dear tokens of His passion Still His dazzling body bears; Cause of endless exultation To His ransomed worshipers; With what rapture, with what rapture, with what rapture Gaze we on those glorious scars!", "Yea, Amen! let all adore Thee, High on Thine eternal throne; Savior, take the power and glory, Claim the kingdom for Thine own; O come quickly! O come quickly! O come quickly! Everlasting God, come down!"], "scriptureLinks": [{"label": "Rev 1:7", "chapterId": "REV-1", "verseNumber": 7}, {"label": "Jn 20:24-31", "chapterId": "JHN-20", "verseNumber": 24}, {"label": "Rev 7:9-12", "chapterId": "REV-7", "verseNumber": 9}], "musicCredit": "'Helmsley' attr. Thomas Olivers, 1765", "number": 185}, {"title": "Lo, God To Heav'n Ascendeth", "sectionId": 6, "wordsCredit": "Gottfried Wilhelm Sacer, 1661. verses 1-5,7 Translated by Frances Elizabeth Cox, 1841.verse 6 translator unknown", "verses": ["Lo, God to Heav'n ascendeth! Throughout its regions vast With shouts triumphant blendeth the trumpet's thrilling blast: Sing praise to Christ the Lord; sing praise with exultation, King of each heathen nation, the God of Hosts adored!", "With joy is Heav'n resounding Christ's glad return to see; Behold the saints surrounding the Lord who set them free. Bright myriads, thronging, come; the cherub band rejoices, And loud seraphic voices Welcome Messiah home.", "No more the way is hidden, Since Christ our Head arose: No more to man forbidden The road to Heav'n that goes. Our Lord is gone before; yet here He will not leave us, And soon in Heav'n receive us and open wide the door.", "Christ is our place preparing; to Heav'n we, too, shall rise, And, joys angelic sharing, Be where our treasure lies: There may each heart be found! Where Jesus Christ has entered, There let our Hope be centered; Our course still heav'nward bound.", "May we, His servants, thither In heart and mind ascend, And let us sing together: \"We seek Thee, Christ, our friend, Thee, God's exalted Son, our Life, and Way to Heaven, To whom all pow'r is given, our Joy and Hope and Crown.\"", "Farewell with all thy treasures, O world, to falsehood giv'n! Thy dross gives no true pleasures; We seek the joys of Heav'n: The Savior is our Prize; He comforts us in sadness, And fills our hearts with gladness; to Him we lift our eyes.", "When, on our vision dawning, Will break the wished-for hour Of that all glorious morning, When Christ shall come with power? O come, thou welcome day! When we, our Savior meeting, His second advent greeting, Shall hail the heav'n-sent ray."], "scriptureLinks": [{"label": "Ps 47:1-9", "chapterId": "PSA-47", "verseNumber": 1}, {"label": "Ps 24:1-10", "chapterId": "PSA-24", "verseNumber": 1}, {"label": "Acts 1:6-11", "chapterId": "ACT-1", "verseNumber": 6}], "musicCredit": "'Von Gott will ich Nicht Lazen' Johann Crüger, 1640", "number": 186}, {"title": "Look Down, O Lord, From Heaven Behold", "sectionId": 6, "wordsCredit": "Martin Luther, 1524. Translated by Frances Elizabeth Cox, 1864", "verses": ["Look down, O Lord, from heav'n behold, And let thy pity waken! How few the flock within thy fold, Neglected and forsaken! Almost thou'lt seek for faith in vain, And those who should thy truth maintain Thy Word from us have taken.", "With frauds which they themselves invent Thy truth they have confounded; Their hearts are not with one consent On thy pure doctrine grounded; And, whilst they gleam with outward show, They lead thy people to and fro, In error's maze astounded.", "God surely will uproot all those With vain deceits who store us, With haughty tongue who God oppose, And say, \"Who'll stand before us? By right or might we will prevail; What we determine cannot fail, For who can lord it o'er us?\"", "For this, saith God, I will arise, These wolves my flock are rending; I've heard my people's bitter sighs To heav'n my throne ascending: Now will I up, and set at rest Each weary soul by fraud opprest, The poor with might defending.", "The silver sev'n times tried is pure From all adulteration; So, through God's word, shall men endure Each trial and temptation: Its worth gleams brighter through the cross, And, purified from human dross, It shines through every nation.", "Thy truth thou wilt preserve, O Lord, From this vile generation; Make us to lean upon thy word, With calm anticipation. The wicked walk on every side When, 'mid thy flock, the vile abide In pow'r and exaltation."], "scriptureLinks": [{"label": "Acts 20:28-32", "chapterId": "ACT-20", "verseNumber": 28}, {"label": "Lk 18:7-8", "chapterId": "LUK-18", "verseNumber": 7}, {"label": "1 Jn 2:18-23", "chapterId": "1JN-2", "verseNumber": 18}], "altTitle": "O God, from Heaven Look Down or O God, Look Down from Heaven and See", "musicCredit": "'Ach Gott vom Himmel' from Erfurt Enchiridion, 1524", "number": 187}, {"title": "Look Down, O Lord, From Heaven Behold", "sectionId": 6, "wordsCredit": "Martin Luther, 1524. Translated by Frances Elizabeth Cox, 1864", "verses": ["Look down, O Lord, from heav'n behold, And let thy pity waken! How few the flock within thy fold, Neglected and forsaken! Almost thou'lt seek for faith in vain, And those who should thy truth maintain Thy Word from us have taken.", "With frauds which they themselves invent Thy truth they have confounded; Their hearts are not with one consent On thy pure doctrine grounded; And, whilst they gleam with outward show, They lead thy people to and fro, In error's maze astounded.", "God surely will uproot all those With vain deceits who store us, With haughty tongue who God oppose, And say, \"Who'll stand before us? By right or might we will prevail; What we determine cannot fail, For who can lord it o'er us?\"", "For this, saith God, I will arise, These wolves my flock are rending; I've heard my people's bitter sighs To heav'n my throne ascending: Now will I up, and set at rest Each weary soul by fraud opprest, The poor with might defending.", "The silver sev'n times tried is pure From all adulteration; So, through God's word, shall men endure Each trial and temptation: Its worth gleams brighter through the cross, And, purified from human dross, It shines through every nation.", "Thy truth thou wilt preserve, O Lord, From this vile generation; Make us to lean upon thy word, With calm anticipation. The wicked walk on every side When, 'mid thy flock, the vile abide In pow'r and exaltation."], "scriptureLinks": [{"label": "Acts 20:28-32", "chapterId": "ACT-20", "verseNumber": 28}, {"label": "Lk 18:7-8", "chapterId": "LUK-18", "verseNumber": 7}, {"label": "1 Jn 2:18-23", "chapterId": "1JN-2", "verseNumber": 18}], "altTitle": "O God, from Heaven Look Down or O God, Look Down from Heaven and See", "musicCredit": "'Es ist das Heil uns Kommen Her'traditional German circa 1400 from Etlich Christlich Lider, Wittenberg, 1524", "number": 188}, {"title": "Lord God, Thy Praise We Sing - Te Deum Laudamus", "sectionId": 6, "wordsCredit": "Martin Luther, 1529 or 1531. Translated by Richard Massie, 1854", "verses": ["Lord God, Thy praise we sing; Lord God, our thanks we bring; Father in eternity, All the world worships Thee. Angels all and heav'nly host Of Thy glory loudly boast; Both Cherubim and Seraphim Sing ever with loud voice this hymn: Holy art Thou, our God! Holy art Thou, our God! Holy art Thou, our God, the Lord of Sabaoth! Thy majesty and godly might Fill the earth and all the realms of light. The twelve apostles join in song With the dear prophets' goodly throng The martyrs' noble army raise Their voice to Thee in hymns of praise. The universal Church doth Thee Throughout the world confess to be Thee, Father, on Thy highest throne, Thy worthy, true, and well belov'd Son, The Comforter, ev'n the Holy Ghost, Whereof she makes her constant boast. Thee King of all glory, Christ, we own, Th'eternal Father's eternal Son. To save mankind Thou hast not, Lord, The Virgin Mary's womb abhorred; Thou over camest death's sharp sting, Believers unto heav'n to bring; At God's right hand Thou sittest, clad In th'glory with the Father had; Thou shalt in glory come again, To judge both dead and living men. Thy servants help whom Thou, O God, Hast ransomed with that precious blood; Grant that we share the heav'nly rest With the happy saints eternally blest. Help us, O Lord, from age to age, And bless Thy chosen heritage. Nourish and keep them by Thy pow'r, And lift them up for evermore. Lord God, we praise Thee day by day, And sanctify Thy Name always. Keep us this day, and at all times, From secret sins and open crimes; For mercy only, Lord, we plead; Be merciful to our great need. Show us Thy mercy, Lord, as we Our steadfast trust repose in Thee. In Thee, Lord, have we put our trust; O never let our hope be lost! Amen. Amen."], "scriptureLinks": [{"label": "Is 38:19-20", "chapterId": "ISA-38", "verseNumber": 19}, {"label": "Is 6:1-4", "chapterId": "ISA-6", "verseNumber": 1}, {"label": "Rev 18:20", "chapterId": "REV-18", "verseNumber": 20}], "musicCredit": "'Herr Gott, dich loben wir' ancient Latin, alt by Martin Luther. Found in Klug's Gesangbuch, 1535", "number": 189}, {"title": "Lord, Enthroned in Heavenly Splendor", "sectionId": 6, "wordsCredit": "George H. Bourne, 1874, alt", "verses": ["Lord, enthroned in heav'nly splendor, First begotten from the dead, You alone, our strong Defender, Now lift up Your people's head. Alleluia! Alleluia! Alleluia! Jesus, true and living Bread! Jesus, true and living Bread!", "Here our humblest homage pay we, Here in loving reference bow; Here for faith's discernment pray we, Lest we fail to know You now. Alleluia! Alleluia! Alleluia! Thou art here, we ask not how. Thou art here, we ask not how.", "Though the lowliest form doth veil Thee As of old in Bethlehem, Here as there Thine angels hail Thee, Branch and Flow'r of Jesse's stem. Alleluia! Alleluia! Alleluia! We in worship join with them. We in worship join with them.", "Paschal Lamb, Your offering finished Once for all when You were slain, In its fullness undiminished Shall forevermore remain. Alleluia! Alleluia! Alleluia! Cleansing souls from every stain. Cleansing souls from every stain.", "Great High Priest of our profession, Through the veil Thou wentest in, By Thy mighty intercession, Grace and peace for us to win. Alleluia! Alleluia! Alleluia! Jesus, true and living Bread! Jesus, true and living Bread!", "Life imparting heavenly Manna, Smitten Rock with streaming side, Heaven and earth with loud hosanna Worship You, the Lamb Who died. Alleluia! Alleluia! Alleluia! Risen, Ascended, Glorified!"], "scriptureLinks": [{"label": "Rev 1:5-6", "chapterId": "REV-1", "verseNumber": 5}, {"label": "Jn 6:47-51", "chapterId": "JHN-6", "verseNumber": 47}, {"label": "Rev 5:11-14", "chapterId": "REV-5", "verseNumber": 11}], "musicCredit": "'Bryn Calfaria' William Owen, 1852", "number": 190}, {"title": "Our Father Thou in Heaven Above", "sectionId": 6, "wordsCredit": "Martin Luther, 1539. Translation composite", "verses": ["Our Father, Thou in heav'n above, Who biddest us to dwell in love, As brethren of one family, To cry in ev'ry need to Thee, Teach us no thoughtless word to say, But from our inmost heart to pray.", "Thy name be hallowed. Help us, Lord, In purity to keep Thy Word, That to the glory of Thy Name We walk before Thee free from blame. Let no false doctrine us pervert; All poor, deluded souls convert.", "Thy kingdom come. Thine let it be In time and in eternity. Let Thy good Spirit e'er be nigh Our hearts with graces to supply. Break Satan's pow'r, defeat his rage; Preserve Thy Church from age to age.", "Thy gracious will on earth be done As 'tis in heav'n before Thy throne; Obedience in our weal and woe And patience in all grief bestow. Curb flesh and blood and ev'ry ill That sets itself against Thy will.", "Give us this day our daily bread And let us all be clothed and fed. From war and strife be our Defense, From famine and from pestilence, That we may live in godly peace, Free from all care and avarice.", "Forgive our sins, Lord, we implore, Remove from us their burden sore, As we their trespasses forgive Who by offenses us do grieve. Thus let us dwell in charity And serve our brother willingly.", "Into temptation lead us not. When evil foes against us plot And vex our souls on every hand, Oh, give us strength that we may stand Firm in the faith, a well-armed host, Through comfort of the Holy Ghost!", "From evil, Lord, deliver us; The times and days are perilous. Redeem us from eternal death, And when we yield our dying breath, Console us, grant us calm release, And take our souls to Thee in peace.", "Amen, that is, So shall it be. Confirm our faith and hope in Thee That we may doubt not, but believe What here we ask we shall receive. Thus in Thy name and at Thy word We say: Amen. Oh, hear us, Lord! Amen."], "scriptureLinks": [{"label": "Mt 6:9-13", "chapterId": "MAT-6", "verseNumber": 9}, {"label": "Lk 11:2-4", "chapterId": "LUK-11", "verseNumber": 2}], "altTitle": "Our Father, Who from Heaven Above or Our Father in the Heaven Who Art", "musicCredit": "'Vater Unser im Himmelreich' attr. Martin Luther, found in Valentin Schumann's Geistliche Lieder, Leipzig, 1539", "number": 191}, {"title": "Praise My Soul The King Of Heaven", "sectionId": 6, "wordsCredit": "Henry F. Lyte, 1834", "verses": ["Praise, my soul, the King of heaven; To His feet thy tribute bring. Ransomed, healed, restored, forgiven, Evermore His praises sing: Alleluia! Alleluia! Praise the everlasting King.", "Praise Him for His grace and favor To our fathers in distress. Praise Him still the same as ever, Slow to chide, and swift to bless. Alleluia! Alleluia! Glorious in His faithfulness.", "Father like He tends and spares us; Well our feeble frame He knows. In His hands He gently bears us, Rescues us from all our foes. Alleluia! Alleluia! Widely yet His mercy flows.", "Frail as summer's flower we flourish, Blows the wind and it is gone; But while mortals rise and perish Our God lives unchanging on, Praise Him, Praise Him, Hallelujah Praise the High Eternal One!", "Angels, help us to adore Him; Ye behold Him face to face; Sun and moon, bow down before Him, Dwellers all in time and space. Alleluia! Alleluia! Praise with us the God of grace."], "scriptureLinks": [{"label": "Ps 103:1", "chapterId": "PSA-103", "verseNumber": 1}, {"label": "145", "chapterId": "PSA-106", "verseNumber": 43}], "musicCredit": "'Praise My Soul' or 'Lauda Anima' or 'St. Paul' John Goss, 1869", "number": 192}, {"title": "Praise The Lord, Ye Heavens Adore Him", "sectionId": 6, "wordsCredit": "verses 1-2, unknown, 1796. verse 3 Edward Osler, 1836", "verses": ["Praise the Lord, ye heav'ns, adore Him; Praise Him, angels in the height. Sun and moon, rejoice before Him; Praise Him, all ye stars of light. Praise the Lord, for He hath spoken; Worlds His mighty voice obeyed. Laws which never shall be broken For their guidance He hath made.", "Praise the Lord, for He is glorious; Never shall His promise fail. God hath made His saints victorious; Sin and death shall not prevail. Praise the God of our salvation; Hosts on high, His pow'r proclaim. Heav'n and earth and all creation, Laud and magnify His name.", "Worship, honor, glory, blessing, Lord, we offer unto Thee. Young and old, Thy praise expressing, In glad homage bend the knee. All the saints in Heav'n adore Thee; We would bow before Thy throne. As Thine angels serve before Thee, So on earth Thy will be done."], "scriptureLinks": [{"label": "Ps 148:1-14", "chapterId": "PSA-148", "verseNumber": 1}, {"label": "Rev 5:11-14", "chapterId": "REV-5", "verseNumber": 11}], "musicCredit": "'Austria (Haydn)' or 'Austrian Hymn' Franz Joseph Haydn, 1797", "number": 193}, {"title": "Silent Night", "sectionId": 6, "wordsCredit": "Josef Mohr, 1818. stanzas 1,3 Translated by John Freeman Young, 1863. stanzas 2,4 translator anonymous", "verses": ["Silent night, holy night, All is calm, all is bright Round yon virgin mother and Child. Holy Infant, so tender and mild, Sleep in heavenly peace, Sleep in heavenly peace.", "Silent night, holy night, Shepherds quake at the sight; Glories stream from heaven afar, Heavenly hosts sing Alleluia! Christ the Savior is born, Christ the Savior is born!", "Silent night, holy night, Son of God, love's pure light; Radiant beams from Thy holy face With the dawn of redeeming grace, Jesus, Lord, at Thy birth, Jesus, Lord, at Thy birth.", "Silent night, holy night Wondrous star, lend thy light; With the angels let us sing, Alleluia to our King; Christ the Savior is born, Christ the Savior is born!"], "scriptureLinks": [{"label": "Lk 2:8-9", "chapterId": "LUK-2", "verseNumber": 8}, {"label": "Col 1:12-13", "chapterId": "COL-1", "verseNumber": 12}], "musicCredit": "'Stille Nacht' Franz Xaver Gruber, 1818", "number": 194}, {"title": "The Advent of Our God", "sectionId": 6, "wordsCredit": "Charles Coffin, 1736. translated by John Chandler, 1837, alt", "verses": ["The advent of our God Shall be our theme for prayer Come, let us meet him on the road And place for Him prepare.", "The everlasting Son Incarnate stoops to be, Himself the servant's form puts on To set His people free.", "Come, Zion's daughter, rise To meet your lowly King, Nor let your faithless heart despise The peace He comes to bring.", "As judge, on clouds of light, He soon will come again And all His scattered saints unite With Him on high to reign.", "Before the dawning day Let sin be put to flight; No longer let the law hold sway, But walk in freedom's light.", "All glory to the Son Who comes to set us free, With Father, Spirit, ever One, Through all eternity."], "scriptureLinks": [{"label": "Lk 19:28-40", "chapterId": "LUK-19", "verseNumber": 28}, {"label": "Phil 2:5-11", "chapterId": "PHP-2", "verseNumber": 5}, {"label": "Eph 4:22-24", "chapterId": "EPH-4", "verseNumber": 22}], "musicCredit": "'St. Thomas' Aaron Williams, 1770", "number": 195}, {"title": "The Bridegroom Soon Will Call Us", "sectionId": 6, "wordsCredit": "Johann Walther, 1552. Translated by Matthias Loy, 1880", "verses": ["The Bridegroom soon will call us, Come, all ye wedding guests! May not His voice appall us, While slumber binds our breasts; May all our lamps be burning, And oil be found in store, That we, with Him returning, May open find the door.", "There shall we see delighted Our dear Redeemer's face, Who leads our souls benighted To glory by His grace; The patriarchs shall meet us, The prophets' holy band, Apostles, martyrs, greet us In that celestial land.", "They will not blush to own us As brothers, sisters dear, Love ever will be shown us When we with them appear; We all shall come before Him, Who for us Man became, As Lord and God adore Him, And ever bless His Name.", "Our Father, rich in blessing, Will give us crowns of gold And, to His bosom pressing, Impart a bliss untold, Will welcome with embraces Of never ending love, And deck us with His graces In blissful realms above.", "In yonder home shall never Be silent music's voice; With hearts and lips forever We shall in God rejoice; The angels shall adore Him, All saints shall sing His praise, And bring with joy before Him Their sweetest heav'nly lays.", "In mansions fair and spacious Will God the feast prepare, And ever kind and gracious, Bid us its riches share; There bliss that knows no measure From springs of love shall flow, And never changing pleasure His bounty will bestow.", "Thus God shall from all evil Forever make us free, From sin, and from the devil, From all adversity, From sickness, pain, and sadness, From troubles, cares, and fears, And grant us heavenly gladness And wipe away our tears."], "scriptureLinks": [{"label": "Mt 25:6", "chapterId": "MAT-25", "verseNumber": 6}, {"label": "Rev 21:2", "chapterId": "REV-21", "verseNumber": 2}], "musicCredit": "'Act Gott Vom Himmelreiche' or 'Ich will ein Neues Singen' or 'Praetorius 7' from Musae Sionae XII (or VII), Michael Praetorius, 1609", "number": 196}, {"title": "Wake, Awake, for Night Is Flying", "sectionId": 6, "wordsCredit": "Phillipp Nicolai, 1599. Translated by Catherine Winkworth, 1858", "verses": ["Wake, awake, for night is flying; The watchmen on the heights are crying: Awake, Jerusalem, at last! Midnight hears the welcome voices And at the thrilling cry rejoices; Come forth, ye virgins, night is past; The Bridegroom comes, awake; Your lamps with gladness take; Alleluia! And for His marriage feast prepare For ye must go and meet Him there.", "Zion hears the watchmen singing, And all her heart with joy is springing; She wakes, she rises from her gloom; For her Lord comes down all glorious, The strong in grace, in truth victorious. Her Star is ris'n, her Light is come. Ah come, Thou blessed One, God's own beloved Son: Alleluia! We follow till the halls we see Where Thou hast bid us sup with Thee", "Now let all the heav'ns adore Thee, And saints and angels sing before Thee, With harp and cymbal's clearest tone; Of one pearl each shining portal, Where we are with the choir immortal Of angels round Thy dazzling throne; Nor eye hath seen, nor ear hath yet attained to hear What there is ours, but we rejoice and sing to Thee Our hymn of joy eternally."], "scriptureLinks": [{"label": "Mt 25:6", "chapterId": "MAT-25", "verseNumber": 6}, {"label": "Rev 21:2", "chapterId": "REV-21", "verseNumber": 2}, {"label": "Mt 24:36-44", "chapterId": "MAT-24", "verseNumber": 36}], "musicCredit": "'Wachet Auf' Phillip Nicolai, 1599", "number": 197}, {"title": "We All Believe in One True God", "sectionId": 6, "wordsCredit": "Medieval text expanded by Martin Luther, 1524. Translation composite", "verses": ["We all believe in one true God, Who created earth and heaven, The Father, who to us in love Hath the right of children given. He both soul and body feedeth, All we need He doth provide us; He through snares and perils leadeth, Watching that no harm betide us. He careth for us day and night, All things are governed by His might.", "We all believe in Jesus Christ, His own Son, our Lord, possessing An equal Godhead, throne, and might, Source of every grace and blessing. Born of Mary, virgin mother, By the power of the Spirit, Made true man, our elder Brother, That the lost might life inherit; Was crucified for sinful men And raised by God to life again.", "We all confess the Holy Ghost, Who sweet grace and comfort giveth And with the Father and the Son In eternal glory liveth; Who the Church, His own creation, Keeps in unity of spirit. Here forgiveness and salvation Daily come through Jesus' merit. All flesh shall rise, and we shall be In bliss with God eternally."], "scriptureLinks": [{"label": "1 Jn 5:20", "chapterId": "1JN-5", "verseNumber": 20}, {"label": "Is 41:9-13", "chapterId": "ISA-41", "verseNumber": 9}, {"label": "Jn 1:14", "chapterId": "JHN-1", "verseNumber": 14}], "altTitle": "In One True God We All Believe", "musicCredit": "'Wir Glauben all an Einen Gott, Schoepfer' or 'Apostolic Creed' Medieval tune altered by Martin Luther. Found in Walter's Geistliche Gesangbüchlein, 1524. %", "number": 198}, {"title": "When The Roll Is Called Up Yonder", "sectionId": 6, "wordsCredit": "James Milton Black, 1893", "verses": ["When the trumpet of the Lord shall sound, and time shall be no more, And the morning breaks, eternal, bright and fair; When the saved of earth shall gather over on the other shore, And the roll is called up yonder, I'll be there.", "On that bright and cloudless morning when the dead in Christ shall rise, And the glory of His resurrection share; When His chosen ones shall gather to their home beyond the skies, And the roll is called up yonder, I'll be there.", "Let us labor for the Master from the dawn till setting sun, Let us talk of all His wondrous love and care; Then when all of life is over, and our work on earth is done, And the roll is called up yonder, I'll be there."], "scriptureLinks": [{"label": "Dan 12:1-3", "chapterId": "DAN-12", "verseNumber": 1}, {"label": "Rev 20:12-15", "chapterId": "REV-20", "verseNumber": 12}, {"label": "21:26-27", "chapterId": "REV-21", "verseNumber": 26}], "musicCredit": "'When The Roll Is Called Up Yonder' James Milton Black, 1893", "refrain": "When the roll is called up yonder, When the roll is called up yonder, When the roll is called up yonder, When the roll is called up yonder, I'll be there.", "number": 199}, {"title": "Why Should Cross and Trial Grieve Me?", "sectionId": 6, "wordsCredit": "Paul Gerhardt, 1653. Translated by John Kelly, 1867, alt", "verses": ["Why should cross and trial grieve me? Christ is near With His cheer; Never will He leave me. Who can rob me of the heaven That God's Son, For my own, To my faith hath given?", "Nought not e'en the life I'm living, Is mine own, God alone All to me is giving. Must I then His own restore Him? Though bereft Of my flesh Still shall I adore Him.", "Though a heavy cross I'm bearing, And my heart Feels the smart, Shall I be despairing? God can help me, who doth send it, He doth know All my woe And how best to end it.", "God oft gives me days of gladness, Shall I grieve If He give Seasons too of sadness? God is good, and tempers ever All my ill, And He will Wholly leave me never.", "Though united world and devil, All their pow'r Can no more Do but mock and quibble. Let them now employ their jeering, Christ will here Then appear Strike their hearts with fearing.", "True believers shrinking never, Where they dwell Should reveal Their true colors ever. When approaching death may scare them, Still should they Patient stay And with courage bear them.", "Death can never kill us even, But relief From all grief To us then is given. It doth close life's mournful story, Make a way That we may Pass to heav'nly glory.", "There I'll reap enduring pleasure, After woe Here below Suffered in large measure. Lasting good we find here never, All that earth Deems as worth Vanishes for ever.", "What is all this life possesses? But a hand Full of sand That the heart distresses. Noble gifts that pall me never, Christ so free There gives me To enjoy for ever.", "Shepherd! Lord! joy's fountain ever, Thou art mine, I am Thine, No one can us sever. I am Thine, because Thou bought me; Lost I stood, But Thy blood Free salvation brought me.", "Thou art mine; I love and own Thee, Light of joy, Ne'er shall I, From my heart dethrone Thee. Savior, let me soon behold Thee Face to face, Thy embrace May it soon enfold me!"], "scriptureLinks": [{"label": "Ps 73:23-28", "chapterId": "PSA-73", "verseNumber": 23}, {"label": "Jn 14:1-4", "chapterId": "JHN-14", "verseNumber": 1}, {"label": "2Cor 5:1-10", "chapterId": "2CO-5", "verseNumber": 1}], "altTitle": "Why Should Sorrow Ever Grieve Me?", "musicCredit": "'Ebeling' or 'Bonn' or 'Warum Sollt Ich' or 'All My Heart This Night' Johann Georg Ebeling, 1666", "number": 200}, {"title": "A Great and Mighty Wonder", "sectionId": 7, "wordsCredit": "Germanus of Constantinople (634-734). Translated by John Mason Neale, 1862", "verses": ["A great and mighty wonder, a full and holy cure: The virgin bears the Infant with virgin honor pure!", "The Word becomes incarnate and yet remains on high, And cherubim sing anthems to shepherds from the sky.", "While thus they sing your Monarch, those bright angelic bands, Rejoice, ye vales and mountains, ye oceans, clap your hands.", "Since all He comes to ransom, by all be He adored, The Infant born in Bethl'em, the Savior and the Lord.", "And idol forms shall perish, and error shall decay, And Christ shall wield His scepter, our Lord and God for aye."], "scriptureLinks": [{"label": "1Tim 3:16", "chapterId": "1TI-3", "verseNumber": 16}, {"label": "Jn 1:14-17", "chapterId": "JHN-1", "verseNumber": 14}, {"label": "Lk 2:1-20", "chapterId": "LUK-2", "verseNumber": 1}], "musicCredit": "'Es Ist Ein Ros Entsprungen (Rhythmic)' German from Köln, 1599", "refrain": "Repeat the hymn again: \"To God on high be glory And peace on earth to men!\"", "number": 201}, {"title": "A Lamb Goes Uncomplaining Forth", "sectionId": 7, "wordsCredit": "Paul Gerhardt, 1648. Translation composite", "verses": ["A Lamb goes uncomplaining forth, The guilt of all men bearing; And laden with the sins of earth, None else the burden sharing! Goes patient on, grow weak and faint, To slaughter led without complaint, That spotless life to offer; Bears shame and stripes, and wounds and death, Anguish and mockery, and saith, \"Willing all this I suffer.\"", "This Lamb is Christ, the soul's great Friend, The Lamb of God, our Savior; Him God the Father chose to send To gain for us His favor. \"Go forth, My Son,\" the Father saith, \"And free men from the fear of death, From guilt and condemnation. The wrath and stripes are hard to bear, But by Thy Passion men shall share The fruit of Thy salvation.\"", "\"Yea, Father, yea, most willingly I'll bear what Thou commandest; My will conforms to Thy decree, I do what Thou demandest.\" O wondrous Love, what hast Thou done! The Father offers up His Son! The Son, content, descendeth! O Love, how strong Thou art to save! Thou beddest Him within the grave Whose word the mountains rendeth.", "Thou lay'st Him, Love, upon the cross, With nails and spear Him bruising; Thou slay'st Him as a lamb, His loss from soul and body oozing; From body 'tis the crimson flood Of precious sacrificial blood From soul, the strength of anguish: My gain it is; sweet Lamb to Thee What can I give, whose love to me For me doth make Thee languish?", "Lord, all my life I'll cleave to Thee, Thy love fore'er beholding, Thee ever, as Thou ever me, With loving arms enfolding. Yea, Thou shalt be my Beaconlight, To guide me safe through death's dark night. And cheer my heart in sorrow; Henceforth myself and all that's mine To Thee, my Savior, I consign, From whom all things I borrow.", "From morn till eve my theme shall be Thy mercy's wondrous measure; To sacrifice myself for Thee Shall be my aim and pleasure. My stream of life shall ever be A current flowing ceaselessly, Thy constant praise outpouring. I'll treasure in my memory, O Lord, all Thou hast done for me, Thy gracious love adoring.", "Enlarge, my heart's own shrine, and swell, To thee shall now be given A treasure that doth far excel The worth of earth and heaven. Away with the Arabian gold, With treasures of an earthly mold! I've found a better jewel. My priceless treasure, Lord my God, Is Thy most holy, precious blood, Which flowed from wounds so cruel.", "This treasure ever I'll employ, This every aid shall yield me; In sorrow it shall be my joy, In conflict it shall shield me; In joy, the music of my feast, And when all else has lost its zest, This manna still shall feed me; In thirst my drink; in want my food; My company in solitude, To comfort and to lead me.", "Of death I am no more afraid, New life from Thee is flowing; Thy cross affords me cooling shade When noonday's sun is glowing. When by my grief I am oppressed, On Thee my weary soul shall rest Serenely as on pillows. Thou art my Anchor when by woe My bark is driven to and fro On trouble's surging billows.", "And when Thy glory I shall see And taste Thy kingdom's pleasure, Thy blood my royal robe shall be, My joy beyond all measure. When I appear before Thy throne, Thy righteousness shall be my crown- With these I need not hide me. And there, in garments richly wrought As Thine own bride, I shall be brought To stand in joy beside Thee."], "scriptureLinks": [{"label": "Is 53:1-12", "chapterId": "ISA-53", "verseNumber": 1}, {"label": "Ex 12:5", "chapterId": "EXO-12", "verseNumber": 5}, {"label": "Jn 1:29", "chapterId": "JHN-1", "verseNumber": 29}], "musicCredit": "'An Wasserflüssen Babylon' Wolfgang Dachstein, 1525", "number": 202}, {"title": "A Pilgrim and a Stranger", "sectionId": 7, "wordsCredit": "Paul Gerhardt, 1666. Translated by Jane Borthwick, 1858", "verses": ["A Pilgrim and a stranger, I journey here below; Far distant is my country The home to which I go. Here I must toil and travel, Oft weary and opprest, But there my God shall lead me To everlasting rest.", "I've met with storm and danger, E'en from my early years, With enemies and conflicts, With fightings and with fears. There's nothing here that tempts me To wish a longer stay, So I must hasten forwards, No halting or delay.", "It is a well worn pathway, Many have gone before: The holy saints and prophets, The patriarchs of yore. They trod the toilsome journey In patience and in faith; And them I fain would follow, Like them in life and death!", "Who would share Abr'm's blessing, Must Abr'm's path pursue, A stranger and a pilgrim, Like him, must journey through. The foes must be encountered, The dangers must be passed; Only a faithful soldier Receives the crown at last.", "So I must hasten forwards Thank God, the end will come! This land of my sojourning Is not my destined home. That ever more abideth, Jerusalem above, The everlasting city, The land of light and love.", "There still my thoughts are dwelling, 'Tis there I long to be! Come, Lord, and call Thy servant To blessedness with Thee! Come, bid my toils be ended, Let all my wanderings cease; Call from the wayside lodging, To the sweet home of peace!", "There I shall dwell forever, No more a stranger guest, With all Thy blood-bought children In everlasting rest. The pilgrim toils forgotten, The pilgrim conflicts o'er, All earthly griefs behind us, Eternal joys before!"], "scriptureLinks": [{"label": "Ps 39:12", "chapterId": "PSA-39", "verseNumber": 12}, {"label": "2Cor 5:6", "chapterId": "2CO-5", "verseNumber": 6}, {"label": "Heb 11:13", "chapterId": "HEB-11", "verseNumber": 13}], "musicCredit": "'Passion Chorale' or 'Herzlich Tut Mich Verlangen' Hans Leo Hassler, 1601. Adapted by J.S. Bach, 1729", "number": 203}, {"title": "Angels We Have Heard On High", "sectionId": 7, "wordsCredit": "French Carol; Translated by James Chadwick, 1862", "verses": ["Angels we have heard on high Sweetly singing o'er the plains, And the mountains in reply Echoing their joyous strains.", "Shepherds, why this jubilee? Why your joyous strains prolong? What the gladsome tidings be Which inspire your heav'nly song?", "Come to Bethlehem and see Christ Whose birth the angels sing; Come, adore on bended knee, Christ the Lord, the newborn King.", "See Him in a manger laid, Whom the choirs of angels praise; Mary, Joseph, lend your aid, While our hearts in love we raise."], "scriptureLinks": [{"label": "Lk 2:13-14", "chapterId": "LUK-2", "verseNumber": 13}, {"label": "Ps 95:6", "chapterId": "PSA-95", "verseNumber": 6}], "musicCredit": "'Gloria' French carol melody", "refrain": "Gloria, in excelsis Deo! Gloria, in excelsis Deo!", "number": 204}, {"title": "As With Gladness Men of Old", "sectionId": 7, "wordsCredit": "William Chatterton Dix, 1860", "verses": ["As with gladness, men of old Did the guiding star behold As with joy they hailed its light Leading onward, beaming bright So, most glorious Lord, may we Evermore be led to Thee.", "As with joyful steps they sped To that lowly manger bed There to bend the knee before Him whom Heav'n and earth adore; So may we with willing feet Ever seek Thy mercy seat.", "As they offered gifts most rare At that manger rude and bare; So may we with holy joy, Pure and free from sin's alloy, All our costliest treasures bring, Christ, to Thee, our heav'nly King.", "Holy Jesus, ev'ry day Keep us in the narrow way; And, when earthly things are past, Bring our ransomed souls at last Where they need no star to guide, Where no clouds Thy glory hide.", "In the heav'nly country bright, Need they no created light; Thou its Light, its Joy, its Crown, Thou its Sun which goes not down; There forever may we sing Alleluias to our King!"], "scriptureLinks": [{"label": "Mt 2:1-12", "chapterId": "MAT-2", "verseNumber": 1}, {"label": "Num 7:89", "chapterId": "NUM-7", "verseNumber": 89}, {"label": "Mt 7:13-14", "chapterId": "MAT-7", "verseNumber": 13}], "musicCredit": "'Dix' or 'Treuer Heiland, Wir Sind Heir' Conrad Kocher, 1838. Abridged by William Henry Monk, 1861", "number": 205}, {"title": "Breathe on Me, Breath of God", "sectionId": 7, "wordsCredit": "Edwin Hatch, 1878", "verses": ["Breathe on me, breath of God, Fill me with life anew, That I may love what Thou dost love, And do what Thou wouldst do.", "Breathe on me, breath of God, Until my heart is pure, Until with Thee I will one will, To do and to endure.", "Breathe on me, breath of God, So shall I never die, But live with Thee the perfect life Of Thine eternity."], "scriptureLinks": [{"label": "Ez 37:5-9", "chapterId": "EZK-37", "verseNumber": 5}, {"label": "Gen 2:7", "chapterId": "GEN-2", "verseNumber": 7}, {"label": "Is 42:5", "chapterId": "ISA-42", "verseNumber": 5}], "musicCredit": "'Aylesbury' or 'Wirksworth' found in John Chetham's Psalmody, 1718", "number": 206}, {"title": "Built on the Rock", "sectionId": 7, "wordsCredit": "Nikolai F. S. Grundtvig, 1857. Translated Carl Døving, 1909", "verses": ["Built on the Rock the church doth stand, Even when steeples are falling; Crumbled have spires in every land, Bells still are chiming and calling; Calling the young and old to rest, But above all the soul distressed, Longing for rest everlasting.", "Surely in temples made with hands, God, the Most High, is not dwelling; High above earth His temple stands, All earthly temples excelling; Yet He whom heav'ns cannot contain Chose to abide on earth with men, Built in our bodies His temple.", "We are God's house of living stones, Built for His own habitation; He through baptismal grace us owns, Heirs of His wondrous salvation; Were we but two His Name to tell, Yet He would deign with us to dwell, With all His grace and His favor.", "Now we may gather with our King; Ev'n in the lowliest dwelling: Praises to Him we there may bring, His wondrous mercy foretelling; Jesus His grace to us accords, Spirit and life are all His words, His truth doth hallow the temple.", "Still we our earthly temples rear, That we may herald His praises; They are the homes where He draws near And little children embraces, Beautiful things in them are said, God there with us His cov'nant made, Making us heirs of His kingdom.", "Here stands the font before our eyes Telling how God did receive us; The altar recalls Christ's sacrifice And what His table doth give us; Here sounds the Word that doth proclaim Christ yesterday, today, the same, Yea, and for aye our Redeemer.", "Grant then, O God, where'er men roam, That, when the church bells are ringing, Many in saving faith may come Where Christ His message is bringing: \"I know Mine own, Mine own know Me; Ye, not the world, My face shall see. My peace I leave with you.\""], "scriptureLinks": [{"label": "Mt 7:24-25", "chapterId": "MAT-7", "verseNumber": 24}, {"label": "Mt 16:13-18", "chapterId": "MAT-16", "verseNumber": 13}, {"label": "Eph 2:19-22", "chapterId": "EPH-2", "verseNumber": 19}], "musicCredit": "'Kirken Den Er Et Gammelt Hus' Ludvig M. Lindeman, 1840", "number": 207}, {"title": "Come Forth! Come On, with Solemn Song!", "sectionId": 7, "wordsCredit": "Christian Friedrich Heinrich Sachse, 1849. Translated by Jane Borthwick, 1855", "verses": ["Come forth! come on, with solemn song! The road is short, the rest is long! The Lord brought here, He calls away: Make no delay, This home was for a passing day.", "Here in an inn a stranger dwelt, Here joy and grief by turns he felt; Poor dwelling, now we close thy door! The task is o'er, The sojourner returns no more,", "Now of a lasting home possest, He goes to seek a deeper rest Goodnight! the day was sultry here, In toil and fear; Goodnight! the night is cool and clear.", "Chime on, ye bells! again begin, And ring the Sabbath morning in, The lab'rer's weekday work is done, The rest begun, Which Christ hath for His people won!", "Now open to us, gates of peace! Here let the pilgrim's journey cease. Ye quiet slumberers, make room In your still home, For the new stranger who has come!", "How many graves around us lie! How many homes are in the sky! Yes, for each saint doth Christ prepare A place with care: Thy home is waiting, brother, there!", "Jesus, Thou reignest, Lord alone, Thou wilt return and claim Thine own, Come quickly, Lord! return again! Amen! Amen! Thine seal us ever, now and then!"], "scriptureLinks": [{"label": "Heb 13:14", "chapterId": "HEB-13", "verseNumber": 14}, {"label": "2Cor 4:16-18", "chapterId": "2CO-4", "verseNumber": 16}, {"label": "Jn 14:1-4", "chapterId": "JHN-14", "verseNumber": 1}], "musicCredit": "'Jeg Har Min Sag Til Gud Hjemstilt' or 'My All I To My God Commend' Ludvig Mathias Lindeman, unknown date", "number": 208}, {"title": "Come, Ye Disconsolate", "sectionId": 7, "wordsCredit": "verses 1-2 Thomas Moore, 1816. Verse 3 Thomas Hastings, 1831", "verses": ["Come, ye disconsolate, wher'er ye languish; Come to the mercy seat, fervently kneel. Here bring your wounded hearts, here tell your anguish; Earth has no sorrow that Heav'n cannot heal.", "Joy of the desolate, light of the straying, Hope of the penitent, fadeless and pure, Here speaks the Comforter, tenderly saying, \"Earth has no sorrow that Heav'n cannot cure.\"", "Here see the Bread of Life; see waters flowing Forth from the throne of God, pure from above; Come to the feast of love; come, ever knowing Earth has no sorrow but Heav'n can remove."], "scriptureLinks": [{"label": "Jn 6:33-59", "chapterId": "JHN-6", "verseNumber": 33}, {"label": "7:37", "chapterId": "JHN-7", "verseNumber": 37}, {"label": "Mt 11:28-30", "chapterId": "MAT-11", "verseNumber": 28}], "musicCredit": "'Consolator (Webbe)' Samuel Webbe, 1792", "number": 209}, {"title": "Comfort, Comfort Ye My People", "sectionId": 7, "wordsCredit": "Johann Olearius (Oelschlaeger), 1671. Translated by Catherine Winkworth, 1862", "verses": ["Comfort, comfort ye My people, Speak ye peace, thus saith our God; Comfort those who sit in darkness, Mourning 'neath their sorrow's load; Speak ye to Jerusalem Of the peace that waits for them; Tell her that her sins I cover, And her warfare now is over.", "For the herald's voice is crying In the desert far and near, Bidding all men to repentance, Since the kingdom now is here. O that warning cry obey! Now prepare for God a way! Let the valleys rise to meet Him, And the hills bow down to greet Him.", "Yea, her sins our God will pardon, Blotting out each dark misdeed; All that well deserved His anger He will no more see nor heed. She has suffered many a day, Now her griefs have passed away, God will change her pining sadness Into ever springing gladness.", "Make ye straight what long was crooked, Make the rougher places plain: Let your hearts be true and humble, As befits His holy reign, For the glory of the Lord O'er the earth is shed abroad, And all flesh shall see the token That His Word is never broken."], "scriptureLinks": [{"label": "Is 40:1-8", "chapterId": "ISA-40", "verseNumber": 1}], "musicCredit": "'Freu dich sehr, o meine Seele' from Trente Quatre Pseaumes de David, Geneva, 1551", "number": 210}, {"title": "Day of Wrath, O Day of Mourning", "sectionId": 7, "wordsCredit": "Thomas of Celano, 13th Century. Translated by William J. Irons, 1848", "verses": ["Day of wrath, O day of mourning! See fulfilled the prophet's warning, Heav'n and earth in ashes burning.", "Oh, what fear man's bosom rendeth When from Heav'n the Judge descendeth On whose sentence all dependeth!", "Wondrous sound the trumpet flingeth, Through earth's sepulchers it ringeth, All before the throne it bringeth.", "Death is struck and nature quaking; All creation is awaking, To its Judge an answer making.", "Lo, the book, exactly worded, Wherein all hath been recorded; Thence shall judgment be awarded.", "When the Judge His seat attaineth And each hidden deed arraigneth, Nothing unavenged remaineth.", "What shall I, frail man, be pleading? Who for me be interceding When the just are mercy needing?", "King of majesty tremendous, Who dost free salvation send us, Fount of pity, then befriend us.", "Think, good Jesus, my salvation Caused Thy wondrous incarnation; Leave me not to reprobation!", "Faint and weary Thou hast sought me, On the cross of suff'ring bought me; Shall such grace be vainly brought me?", "Righteous Judge, for sin's pollution Grant Thy gift of absolution Ere that day of retribution!", "Guilty, now I pour my moaning, All my shame with anguish owning: Spare, O God, Thy suppliant groaning!", "From that sinful woman shriven, From the dying thief forgiven, Thou to me a hope hast given.", "Worthless are my prayers and sighing; Yet, good Lord, in grace complying, Rescue me from fires undying.", "With Thy favored sheep, oh, place me! Nor among the goats abase me, But to Thy right hand upraise me.", "While the wicked are confounded, Doomed to flames of woe unbounded, Call me, with Thy saints surrounded.", "Low I kneel with heart submission, See, like ashes, my contrition; Help me in my last condition!", "Day of sorrow, day of weeping, When, in dust no longer sleeping, Man awakes in Thy dread keeping!"], "scriptureLinks": [{"label": "Rev 6:12-17", "chapterId": "REV-6", "verseNumber": 12}, {"label": "Rev 20:11-15", "chapterId": "REV-20", "verseNumber": 11}, {"label": "Mt 24:15-28", "chapterId": "MAT-24", "verseNumber": 15}], "musicCredit": "'Dies Irae (Dykes)' John B. Dykes, 1861", "number": 211}, {"title": "Fear Not, O Little Flock", "sectionId": 7, "wordsCredit": "Attr. to King Gustavus Adolphus of Sweden (1594-1632), Jacob Fabricius (1593-1654)or Johann M. Altenburg (1584-1640). Translated by Catherine Winkworth, 1855", "verses": ["Fear not, O little flock, the foe Who madly seeks your overthrow; Dread not his rage and pow'r; What though your courage sometimes faints, His seeming triumph o'er God's saints Lasts but one little hour.", "Be of good cheer; your cause belongs To Him who can avenge your wrongs; Leave it to Him our Lord. Though hidden yet from all our eyes, He sees the Gideon who shall rise; To save us, and His word.", "As true as God's own word is true, Not earth nor hell with all their crew Against us shall prevail. A jest and by— word are they grown; God is with us, we are His own, Our vict'ry cannot fail.", "Amen, Lord Jesus, grant our prayer! Great Captain, now Thine arm make bare; Fight for us once again. So shall thy saints and martyrs raise A mighty chorus to Thy praise, World without end. Amen."], "scriptureLinks": [{"label": "Lk 12:32", "chapterId": "LUK-12", "verseNumber": 32}, {"label": "Ps 27:1-14", "chapterId": "PSA-27", "verseNumber": 1}, {"label": "1 Pt 3:13-17", "chapterId": "1PE-3", "verseNumber": 13}], "musicCredit": "'Kommt her zu mir, spricht Gottes Sohn' traditional German, 1490", "number": 212}, {"title": "From Nazareth", "sectionId": 7, "wordsCredit": "Margaret E. Sangster, 1911", "verses": ["Comes any good from Nazareth? The scornful challenge as of old Is flung on many'a jeering breath From cloistered cells and marts of gold.", "Comes any good from Nazareth? Behold, the mighty Nazarene, The Lord of life, the Lord of death, Through warring ages walks serene.", "One touch upon His garment's fringe Still heals the hurt of bitter years. Before Him yet the demons cringe, He gives the wine of joy for tears.", "O city of the Carpenter, Upon the hill slope old and gray, The world among its pain and stir Turns yearning eyes on thee today.", "For He who dwelt in Nazareth, And wrought with toil of hand and brain, Alone gives victory to faith Until the day He come again."], "scriptureLinks": [{"label": "Jn 1:43-51", "chapterId": "JHN-1", "verseNumber": 43}, {"label": "Mk 5:25-34", "chapterId": "MRK-5", "verseNumber": 25}, {"label": "1:32-34", "chapterId": "MRK-1", "verseNumber": 32}], "musicCredit": "'Puer Nobis Nascitur' Michael Praetorius, 1609", "number": 213}, {"title": "God Will Take Care of You", "sectionId": 7, "wordsCredit": "Civilla Durfee Martin, 1905", "verses": ["Be not dismayed whate'er betide, God will take care of you; Beneath His wings of love abide, God will take care of you.", "Through days of toil when heart doth fail, God will take care of you; When dangers fierce your path assail, God will take care of you.", "All you may need He will provide, God will take care of you; Nothing you ask will be denied, God will take care of you.", "No matter what may be the test, God will take care of you; Lean, weary one, upon His breast, God will take care of you."], "scriptureLinks": [{"label": "Ps 34:9-10", "chapterId": "PSA-34", "verseNumber": 9}, {"label": "Lk 12:30-32", "chapterId": "LUK-12", "verseNumber": 30}, {"label": "Rom 8:32", "chapterId": "ROM-8", "verseNumber": 32}], "musicCredit": "'Martin' Walter Stillman Martin, 1905", "refrain": "God will take care of you, through ev'ry day, o'er all the way; He will take care of you, God will take care of you.", "number": 214}, {"title": "Happy the Man Who Feareth God", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854", "verses": ["Happy the man who feareth God, Whose feet His holy ways have trod; Thine own good hand shall nourish thee, And well and happy shalt thou be.", "Thy wife shall, like a fruitful vine, Fill all thy house with clusters fine; Thy children all be fresh and sound, Like olive— plants thy table round.", "Lo! to the man these blessings cleave Who in God's holy fear doth live; From him the ancient curse hath fled By Adam's race inherited.", "Out of Mount Zion God shall send, And crown with joy thy latter end; That thou Jerusalem mayst see, In favor and prosperity.", "He shall be with thee in thy ways, And give thee health and length of days Yea, thou shalt children's children see, And peace on Israel shall be."], "scriptureLinks": [{"label": "Ps 146:5", "chapterId": "PSA-146", "verseNumber": 5}, {"label": "Job 28:28", "chapterId": "JOB-28", "verseNumber": 28}, {"label": "Acts 9:31", "chapterId": "ACT-9", "verseNumber": 31}], "altTitle": "Happy Who in God's Fear Doth Stay", "musicCredit": "'Wo Gott Zum Haus (Walter)' from Walter's Geistliche Gesangbüchlein, 1524", "number": 215}, {"title": "Happy the Man Who Feareth God", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854", "verses": ["Happy the man who feareth God, Whose feet His holy ways have trod; Thine own good hand shall nourish thee, And well and happy shalt thou be.", "Thy wife shall, like a fruitful vine, Fill all thy house with clusters fine; Thy children all be fresh and sound, Like olive— plants thy table round.", "Lo! to the man these blessings cleave Who in God's holy fear doth live; From him the ancient curse hath fled By Adam's race inherited.", "Out of Mount Zion God shall send, And crown with joy thy latter end; That thou Jerusalem mayst see, In favor and prosperity.", "He shall be with thee in thy ways, And give thee health and length of days Yea, thou shalt children's children see, And peace on Israel shall be."], "scriptureLinks": [{"label": "Ps 146:5", "chapterId": "PSA-146", "verseNumber": 5}, {"label": "Job 28:28", "chapterId": "JOB-28", "verseNumber": 28}, {"label": "Acts 9:31", "chapterId": "ACT-9", "verseNumber": 31}], "altTitle": "Happy Who in God's Fear Doth Stay", "musicCredit": "'Wo Gott Zum Haus' Klug's Geistliche Lieder, Wittenberg, 1533", "number": 216}, {"title": "He Leadeth Me", "sectionId": 7, "wordsCredit": "Joseph H. Gilmore, 1862", "verses": ["He leadeth me, O blessèd thought! O words with heav'nly comfort fraught! Whate'er I do, where'er I be Still 'tis God's hand that leadeth me.", "Sometimes mid scenes of deepest gloom, Sometimes where Eden's bowers bloom, By waters still, ov'r troubled sea, Still 'tis His hand that leadeth me.", "Lord, I would place my hand in Thine, Nor ever murmur nor repine; Content, whatever lot I see, Since 'tis my God that leadeth me.", "And when my task on earth is done, When by Thy grace the vict'ry's won, E'en death's cold wave I will not flee, Since God through Jordan leadeth me."], "scriptureLinks": [{"label": "Ps 23:1-3", "chapterId": "PSA-23", "verseNumber": 1}, {"label": "31:3", "chapterId": "PSA-31", "verseNumber": 3}, {"label": "Jn 16:13", "chapterId": "JHN-16", "verseNumber": 13}], "musicCredit": "'He Leadeth Me' William B. Bradbury, 1864", "refrain": "He leadeth me, He leadeth me, By His own hand He leadeth me; His faithful follow'r I would be, For by His hand He leadeth me.", "number": 217}, {"title": "He Who Would Valiant Be", "sectionId": 7, "wordsCredit": "John Bunyan, 1684. Modified by Percy Dearmer, 1906", "verses": ["He who would valiant be 'gainst all disaster, Let him in constancy follow the Master. There's no discouragement shall make him once relent His first avowed intent to be a pilgrim.", "Who so beset him round with dismal stories Do but themselves confound his strength the more is. No foes shall stay his might; though he with giants fight, He will make good his right to be a pilgrim.", "Since, Lord, Thou dost defend us with Thy Spirit, We know we at the end, shall life inherit. Then fancies flee away! I'll fear not what men say, I'll labor night and day to be a pilgrim."], "scriptureLinks": [{"label": "Jn 12:26", "chapterId": "JHN-12", "verseNumber": 26}, {"label": "1 Pt 2:19-24", "chapterId": "1PE-2", "verseNumber": 19}, {"label": "3:12-16", "chapterId": "1PE-3", "verseNumber": 12}], "musicCredit": "'Monks Gate' traditional English", "number": 218}, {"title": "I Bind Unto Myself Today", "sectionId": 7, "wordsCredit": "attributed to St. Patrick circa 372-466; Paraphrased by Cecil F. Alexander, 1889", "verses": ["I bind unto myself today The strong Name of the Trinity, By invocation of the same The Three in One and One in Three.", "I bind this day to me forever By power of faith, Christ's incarnation; His baptism in the Jordan river, His death on Cross for my salvation; His bursting from the spicèd tomb, His riding up the heav'nly way, His coming at the day of doom I bind unto myself today.", "I bind unto myself the power Of the great love of cherubim; The sweet \"Well done\" in judgment hour, The service of the seraphim, Confessors' faith, Apostles' word, The Patriarchs' prayers, the prophets' scrolls, All good deeds done unto the Lord And purity of virgin souls.", "I bind unto myself today The virtues of the star lit heaven, The glorious sun's life giving ray, The whiteness of the moon at even, The flashing of the lightning free, The whirling wind's tempestuous shocks, The stable earth, the deep salt sea Around the old eternal rocks.", "I bind unto myself today The power of God to hold and lead, His eye to watch, His might to stay, His ear to hearken to my need. The wisdom of my God to teach, His hand to guide, His shield to ward; The word of God to give me speech, His heav'nly host to be my guard.", "Against the demon snares of sin, The vice that gives temptation force, The natural lusts that war within, The hostile men that mar my course; Or few or many, far or nigh, In every place and in all hours, Against their fierce hostility I bind to me these holy powers.", "Against all Satan's spells and wiles, Against false words of heresy, Against the knowledge that defiles, Against the heart's idolatry, Against the wizard's evil craft, Against the death wound and the burning, The choking wave, the poisoned shaft, Protect me, Christ, till Thy returning.", "Christ be with me, Christ within me, Christ behind me, Christ before me, Christ beside me, Christ to win me, Christ to comfort and restore me. Christ beneath me, Christ above me, Christ in quiet, Christ in danger, Christ in hearts of all that love me, Christ in mouth of friend and stranger.", "I bind unto myself the Name, The strong Name of the Trinity, By invocation of the same, The Three in One and One in Three. By Whom all nature hath creation, Eternal Father, Spirit, Word: Praise to the Lord of my salvation, Salvation is of Christ the Lord."], "scriptureLinks": [{"label": "Mt 28:19", "chapterId": "MAT-28", "verseNumber": 19}, {"label": "Ps 91:4", "chapterId": "PSA-91", "verseNumber": 4}, {"label": "2Cor 13:14", "chapterId": "2CO-13", "verseNumber": 14}], "musicCredit": "'St. Patricks Breastplate' Charles V. Stanford, 1902", "number": 219}, {"title": "I Need Thee Every Hour", "sectionId": 7, "wordsCredit": "Annie Sherwood Hawks, 1872", "verses": ["I need Thee ev'ry hour, Most gracious Lord; No tender voice like Thine Can peace afford.", "I need Thee ev'ry hour, Stay Thou near by; Temptations lose their pow'r When Thou art nigh.", "I need Thee ev'ry hour, In joy or pain; Come quickly and abide, Or life is vain.", "I need Thee ev'ry hour, Teach me Thy will; And Thy rich promises In me fulfill.", "I need Thee ev'ry hour, Most Holy One; O make me Thine indeed, Thou blessed Son!"], "scriptureLinks": [{"label": "Heb 4:16", "chapterId": "HEB-4", "verseNumber": 16}, {"label": "Phil 4:6", "chapterId": "PHP-4", "verseNumber": 6}], "musicCredit": "'I Need Thee Every Hour' Robert Lowry, 1872", "refrain": "I need Thee, O I need Thee; Ev'ry hour I need Thee; O bless me now, my Savior, I come to Thee!", "number": 220}, {"title": "I Walk In Danger All The Way", "sectionId": 7, "wordsCredit": "Hans Adolf Brorson, 1734. Translated by Ditlef Georgson Ristad, 1909, alt", "verses": ["I walk in danger all the way; The thought shall never leave me That Satan, who has marked his prey, Is plotting to deceive me. This foe with hidden snares May seize me unawares If e'er I fail to watch and pray: I walk in danger all the way.", "I pass through trials all the way, With sin and ills contending; In patience I must bear each day The cross of God's own sending; Oft in adversity I know not where to flee; When storms of woe my soul dismay, I pass through trials all the way.", "Death doth pursue me all the way, Nowhere I rest securely, He comes by night, he comes by day, He takes his prey most surely; A failing breath and I In death's strong grasp may lie To face eternity for aye: Death doth pursue me all the way.", "I walk 'mongst angels all the way They shield me and befriend me; All Satan's pow'r is held at bay When heav'nly hosts attend me; They are my sure defense, All fear and sorrow, hence! Unharmed by foes, do what they may, I walk 'mongst angels all the way.", "I walk with Jesus all the way, His guidance never fails me, Within His wounds I find a stay, When Satan's pow'r assails me; And by His footsteps led, My path I safely tread, In spite of ills that threaten may, I walk with Jesus all the way.", "My walk is heav'nward all the way, Await, my soul, the morrow, When thou shalt find release for aye From all thy sin and sorrow; All worldly pomp, begone, To heav'n I now press on; For all the world I would not stay, My walk is heav'nward all the way."], "scriptureLinks": [{"label": "1 Pt 5:8", "chapterId": "1PE-5", "verseNumber": 8}, {"label": "Jas 1:12", "chapterId": "JAS-1", "verseNumber": 12}, {"label": "Jn 8:12", "chapterId": "JHN-8", "verseNumber": 12}], "musicCredit": "'Der Lieben Sonne Lich Und Pracht' or 'Ristad' from Freylinghausen's Geistreiches Gesangbuch, Halle, 1704", "number": 221}, {"title": "If God Had Not Been on Our Side", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translation composite", "verses": ["If God had not been on our side And had not come to aid us, The foes with all their pow'r and pride Would surely have dismayed us; For we, His flock, would have to fear The threat of men both far and near Who rise in might against us.", "Their furious wrath, did God permit, Would surely have consumed us And as a deep and yawning pit With life and limb entombed us. Like men o'er whom dark waters roll Their wrath would have engulfed our soul And, like a flood, o'erwhelmed us.", "Blest be the Lord, who foiled their threat That they could not devour us; Our souls, like birds, escaped their net, They could not overpow'r us. The snare is broken we are free! Our help is ever, Lord, in Thee, Who madest earth and heaven."], "scriptureLinks": [{"label": "Ps 124:1-8", "chapterId": "PSA-124", "verseNumber": 1}, {"label": "Rom 8:31-39", "chapterId": "ROM-8", "verseNumber": 31}], "altTitle": "Had God not Come, May Israel Say or Were God Not With Us At This Time", "musicCredit": "'Wär Gott nicht mit uns diese Zeit (1524)' from Walter's Geistliche Gesangbüchlein, 1524", "number": 222}, {"title": "If God Had Not Been on Our Side", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translation composite", "verses": ["If God had not been on our side And had not come to aid us, The foes with all their pow'r and pride Would surely have dismayed us; For we, His flock, would have to fear The threat of men both far and near Who rise in might against us.", "Their furious wrath, did God permit, Would surely have consumed us And as a deep and yawning pit With life and limb entombed us. Like men o'er whom dark waters roll Their wrath would have engulfed our soul And, like a flood, o'erwhelmed us.", "Blest be the Lord, who foiled their threat That they could not devour us; Our souls, like birds, escaped their net, They could not overpow'r us. The snare is broken we are free! Our help is ever, Lord, in Thee, Who madest earth and heaven."], "scriptureLinks": [{"label": "Ps 124:1-8", "chapterId": "PSA-124", "verseNumber": 1}, {"label": "Rom 8:31-39", "chapterId": "ROM-8", "verseNumber": 31}], "altTitle": "Had God not Come, May Israel Say or Were God Not With Us At This Time", "musicCredit": "'Wär Gott nicht mit uns diese Zeit (1537)' from Walter's Hymnal, 1537", "number": 223}, {"title": "In The Bleak MidWinter", "sectionId": 7, "wordsCredit": "Christina Georgina Rossetti, 1872, alt", "verses": ["In the bleak midwinter, frosty wind made moan, Earth stood hard as iron, water like a stone; Snow had fallen, snow on snow, snow on snow on snow, In the bleak midwinter, long ago.", "Our God, Heav'n cannot hold Him, nor earth sustain; Heav'n and earth shall flee away when He comes to reign. In the bleak midwinter a stable place sufficed The Lord God Almighty, Jesus Christ.", "Enough for Him, whom cherubim, worship night and day, Breastful of milk, and a mangerful of hay; Enough for Him, whom angels fall down before, Ox and ass and camel which adore.", "Angels and archangels may have gathered there, Cherubim and seraphim thronged the air; But His mother only, in her maiden bliss, Worshiped the beloved with a kiss.", "What can I give Him, poor as I am? If I were a shepherd, I would bring a lamb; If I were a Wise Man, I would do my part; Yet what can I give Him: give my heart.", "These lyrics are rather obscure, though quite beautiful. The earth (which represents all of God's promises to His People, Gen 13:14-15, Rom 4:13-17, Mt 5:5) and the water (which represents Baptism and forgiveness, Jn 3:5, Eph 5:25-27, 1Pt 3:21) are frozen and lifeless as the Law reigns alone (2Cor 3:6b), with no grace flowing before Christ. The Spirit (the wind) works in the world through the condemnation of the Law and the hope for redemption to come (frosty wind made moan, Micah 4:10, Ez 21:6-7). Then Christ humbly comes to melt the icy world in grace. This then inspires those saved, who recognize that they have nothing to give to Him, to finally, through His grace, fulfill the greatest commandment (Mt 22:37)."], "scriptureLinks": [{"label": "Lv 26:18-19", "chapterId": "LEV-26", "verseNumber": 18}, {"label": "Job 38:29-30", "chapterId": "JOB-38", "verseNumber": 29}, {"label": "Ps 147:16-20", "chapterId": "PSA-147", "verseNumber": 16}], "musicCredit": "'Cranham' Gustav Theodore Holst, 1906, alt", "number": 224}, {"title": "Jerusalem the Golden", "sectionId": 7, "wordsCredit": "Bernard of Cluny, 1146. Translated by John Mason Neale, 1858", "verses": ["Jerusalem the golden, with milk and honey blest, Beneath thy contemplation sink heart and voice oppressed. I know not, O I know not, what joys await us there, What radiancy of glory, what bliss beyond compare.", "They stand, those halls of Zion, all jubilant with song, And bright with many'an angel, and all the martyr throng; The Prince is ever in them, the daylight is serene. The pastures of the blessèd are decked in glorious sheen.", "There is the throne of David, and there, from care released, The shout of them that triumph, the song of them that feast; And they are with their Leader, who conquered in the fight, And won for them forever their gleaming robes of white.", "O sweet and blessèd country, the home of God's elect! O sweet and blessèd country, that eager hearts expect! Jesus, in mercy bring us to that dear land of rest, Who art, with God the Father, and Spirit, ever blessed.", "Brief life is here our portion, brief sorrow, short lived care; The life that knows no ending, the tearless life, is there. O happy retribution! Short toil, eternal rest; For mortals and for sinners, a mansion with the blest.", "That we should look, poor wanderers, to have our home on high! That worms should seek for dwellings beyond the starry sky! And now we fight the battle, but then shall wear the crown Of full and everlasting, and passionless renown.", "And how we watch and struggle, and now we live in hope, And Zion in her anguish with Babylon must cope; But he whom now we trust in shall then be seen and known, And they that know and see Him shall have Him for their own.", "For thee, O dear, dear country, mine eyes their vigils keep; For very love, beholding, thy happy name, they weep: The mention of thy glory is unction to the breast, And medicine in sickness, and love, and life, and rest.", "O one, O only mansion! O paradise of joy! Where tears are ever banished, and smiles have no alloy; The cross is all thy splendor, the Crucified thy praise, His laud and benediction thy ransomed people raise.", "Jerusalem the glorious! Glory of the elect! O dear and future vision that eager hearts expect! E'en now by faith I see thee, e'en here thy walls discern; To thee my thoughts are kindled, and strive, and pant, and yearn.", "Jerusalem, the only, that look'st from heaven below, In thee is all my glory, in me is all my woe! And though my body may not, my spirit seeks thee fain, Till flesh and earth return me to earth and flesh again.", "Jerusalem, exulting on that securest shore, I hope thee, wish thee, sing thee, and love thee evermore! I ask not for my merit: I seek not to deny My merit is destruction, a child of wrath am I.", "But yet with faith I venture and hope upon the way, For those perennial guerdons I labor night and day. The best and dearest Father Who made me, and Who saved, Bore with me in defilement, and from defilement laved.", "When in His strength I struggle, for very joy I leap; When in my sin I totter, I weep, or try to weep: And grace, sweet grace celestial, shall all its love display, And David's royal fountain purge every stain away.", "O sweet and blessèd country, shall I e'er see thy face? O sweet and blessèd country, shall I e'er win thy grace? I have the hope within me to comfort and to bless! O shall I e'er win the prize? O tell me, tell me, Yes!"], "scriptureLinks": [{"label": "Rev 21:18-23", "chapterId": "REV-21", "verseNumber": 18}, {"label": "2Cor 4:17-18", "chapterId": "2CO-4", "verseNumber": 17}, {"label": "Rev 7:9-17", "chapterId": "REV-7", "verseNumber": 9}], "musicCredit": "'Ewing' Alexander C. Ewing, 1853", "number": 225}, {"title": "Lord of Glory, Who Hast Bought Us", "sectionId": 7, "wordsCredit": "Eliza S. Alderson, 1864", "verses": ["Lord of Glory, who hast bought us with Thy lifeblood as the price, Never grudging for the lost ones that tremendous sacrifice; And with that hast freely given blessings countless as the sand, To th'unthankful and the evil with Thine own unsparing hand.", "Grant us hearts, dear Lord, to yield Thee gladly, freely, of Thine own. With the sunshine of Thy goodness melt our thankless hearts of stone. Till our cold and selfish natures, warmed by Thee, at length believe That more happy and more blessed 'tis to give than to receive.", "Wondrous honor hast Thou given to our humblest charity. In Thine own mysterious sentence, \"Ye have done it unto Me.\" Can it be, O gracious Master, Thou dost deign for alms to sue, Saying by Thy poor and needy, \"Give as I have given you\"", "Lord of Glory, who hast bought us with Thy lifeblood as the price, Never grudging for the lost ones that tremendous sacrifice; Give us faith, to trust Thee boldly; hope, to stay our souls on Thee; But O, best of all Thy graces, give us Thine own charity."], "scriptureLinks": [{"label": "Mt 25:40", "chapterId": "MAT-25", "verseNumber": 40}, {"label": "1 Jn 3:16-19", "chapterId": "1JN-3", "verseNumber": 16}, {"label": "Heb 13:16", "chapterId": "HEB-13", "verseNumber": 16}], "musicCredit": "'HyFrydol' Rowland H. Prichard, 1830", "number": 226}, {"title": "Lord While For All Mankind We Pray", "sectionId": 7, "wordsCredit": "John Reynell Wreford, 1837", "verses": ["Lord, while for all mankind we pray, Of every clime and coast, Oh, hear us for our native land, The land we love the most.", "Oh, guard our shores from every foe, With peace our borders bless, With prosp'rous times our cities crown, Our fields with plenteousness.", "Unite us in the sacred love Of knowledge, truth and Thee; And let our hills and valleys shout The songs of liberty.", "Here may religion, pure and mild, Smile on our Sabbath hours; And piety and virtue bless The home of us and ours.", "Lord of the nations, Thus to Thee Our country we commend; Be Thou her Refuge and her Trust, Her everlasting Friend."], "scriptureLinks": [{"label": "Rom 13:1-7", "chapterId": "ROM-13", "verseNumber": 1}, {"label": "Ps 144:15", "chapterId": "PSA-144", "verseNumber": 15}, {"label": "1Tim 2:1-4", "chapterId": "1TI-2", "verseNumber": 1}], "musicCredit": "'Nox Praecessit' John Baptiste Calkin, 1873", "number": 227}, {"title": "Lord Who Throughout These Forty Days", "sectionId": 7, "wordsCredit": "Claudia F. Hernaman, 1873", "verses": ["Lord, who throughout these forty days For us didst fast and pray, Teach us with Thee to mourn our sins And close by Thee to stay.", "As Thou with Satan didst contend, And didst the vict'ry win, O give us strength in Thee to fight, In Thee to conquer sin.", "As Thou didst hunger bear, and thirst, So teach us, gracious Lord, To die to self, and chiefly live By Thy most holy Word.", "And through these days of penitence, And through Thy passiontide, Yea, evermore in life and death, Jesus, with us abide.", "Abide with us, that so, this life Of suff'ring over past, An Easter of unending joy We may attain at last."], "scriptureLinks": [{"label": "Mt 4:1-2", "chapterId": "MAT-4", "verseNumber": 1}, {"label": "Lk 4:1-13", "chapterId": "LUK-4", "verseNumber": 1}, {"label": "Lv 9:23", "chapterId": "LEV-9", "verseNumber": 23}], "altTitle": "O Lord, Throughout These Forty Days", "musicCredit": "'St. Flavian' Day's Psalter, 1563", "number": 228}, {"title": "Lord, Who at Cana's Wedding Feast", "sectionId": 7, "wordsCredit": "Adelaide Thrupp, 1853", "verses": ["Lord, who at Cana's wedding feast Didst as a Guest appear, Thou dearer far than earthly guest, Vouchsafe Thy presence here. For holy Thou indeed dost prove The marriage vow to be, Proclaiming it a type of love Between the Church and Thee.", "The holiest vow that man can make, The golden thread in life, The bond that none may dare to break, That bindeth man and wife, Which, blest by Thee, whate'er betide, No evil shall destroy, Through careworn days each care divides And doubles every joy.", "On those who at Thine altar kneel, O Lord, Thy blessing pour, That each may wake the other's zeal To love Thee more and more. Oh, grant them here in peace to live, In purity and love, And, this world leaving, to receive A crown of life above."], "scriptureLinks": [{"label": "Jn 2:1-11", "chapterId": "JHN-2", "verseNumber": 1}, {"label": "Is 62:1-5", "chapterId": "ISA-62", "verseNumber": 1}, {"label": "Rev 19:6-9", "chapterId": "REV-19", "verseNumber": 6}], "musicCredit": "'St. Ursula' Frederick Westlake, 1863", "number": 229}, {"title": "None Other Lamb", "sectionId": 7, "wordsCredit": "Christina Rossetti, 1892", "verses": ["None other Lamb, none other name, None other hope in Heav'n or earth or sea, None other hiding place from guilt and shame, None beside Thee!", "My faith burns low, my hope burns low; Only my heart's desire cries out in me By the deep thunder of its want and woe, Cries out to Thee.", "Lord, Thou art life, though I be dead; Love's fire Thou art, however cold I be: Nor Heav'n have I, nor place to lay my head, Nor home, but Thee."], "scriptureLinks": [{"label": "Jn 1:29", "chapterId": "JHN-1", "verseNumber": 29}, {"label": "Rev 5:6", "chapterId": "REV-5", "verseNumber": 6}, {"label": "Job 40:6-14", "chapterId": "JOB-40", "verseNumber": 6}], "musicCredit": "'Rossetti' William Jeater, 1907", "number": 230}, {"title": "Not Worthy, Lord, to Gather Up the Crumbs", "sectionId": 7, "wordsCredit": "Edward Henry Bickersteth, 1872", "verses": ["Not worthy, Lord, to gather up the crumbs With trembling hand that from Thy table fall, A weary, heavy laden sinner comes To plead Thy promise and obey Thy call.", "I am not worthy to be thought Thy child, Nor sit the last and lowest at Thy board; Too long a wanderer and too oft beguiled; I only ask one reconciling word.", "One word from Thee, my Lord, one smile, one look, And I could face the cold, rough world again; And with that treasure in my heart could brook The wrath of devils and the scorn of men.", "And is not mercy Thy prerogative— Free mercy, boundless, fathomless, divine? Me, Lord, the chief of sinners, me forgive, And Thine the greater glory, only Thine.", "I hear Thy voice; Thou bid'st me come and rest; I come, I kneel, I clasp Thy piercèd feet; Thou bid'st me take my place, a welcome guest Among Thy saints, and of Thy banquet eat.", "My praise can only breathe itself in prayer, My prayer can only lose itself in Thee; Dwell Thou forever in my heart, and there, Lord, let me sup with Thee; sup Thou with me."], "scriptureLinks": [{"label": "Mt 15:22-28", "chapterId": "MAT-15", "verseNumber": 22}, {"label": "Lk 17:7-10", "chapterId": "LUK-17", "verseNumber": 7}, {"label": "7:6", "chapterId": "LUK-7", "verseNumber": 6}], "musicCredit": "'Eventide' William H. Monk, 1861", "number": 231}, {"title": "Now Thank We All Our God", "sectionId": 7, "wordsCredit": "Martin Rinkart, c.1636. Translated Catherine Winkworth, 1856", "verses": ["Now thank we all our God, with heart and hands and voices, Who wondrous things has done, in Whom this world rejoices; Who from our mothers' arms has blessed us on our way With countless gifts of love, and still is ours today.", "O may this bounteous God through all our life be near us, With ever joyful hearts and blessed peace to cheer us; And keep us in His grace, and guide us when perplexed; And free us from all ills, in this world and the next!", "All praise and thanks to God the Father now be given; The Son and Him Who reigns with Them in highest Heaven; The one eternal God, Whom earth and Heav'n adore; For thus it was, is now, and shall be evermore."], "scriptureLinks": [{"label": "2Cor 2:14", "chapterId": "2CO-2", "verseNumber": 14}, {"label": "Rom 6:7", "chapterId": "ROM-6", "verseNumber": 7}], "musicCredit": "'Nun Danket' Johann Crüger, 1647", "number": 232}, {"title": "O Lord My Soul Convicted", "sectionId": 7, "wordsCredit": "James Maxwell, 1759", "verses": ["O Lord, my soul convicted stands Of breaking all Thy ten commands: And on me justly might'st Thou pour Thy wrath in one eternal show'r.", "But thanks to God, its loud alarms Have warn'd me of approaching harms; And now, O Lord, my wants I see, Lost and undone, I come to Thee.", "I know my fig leaf righteousness Can ne'er Thy broken law redress; Yet in the gospel plan I see, There's hope of pardon e'en for me.", "There, I behold with wonder, Lord! That Christ hath to Thy law restor'd Those honors on th'atoning day, Which guilty sinners took away.", "Amazing wisdom, pow'r and love, Display'd to rebels from above! Do Thou, O Lord, my faith increase To love and trust Thy plan of grace."], "scriptureLinks": [{"label": "Mt 22:34-46", "chapterId": "MAT-22", "verseNumber": 34}, {"label": "Eph 5:15-21", "chapterId": "EPH-5", "verseNumber": 15}], "altTitle": "Here Lord My Soul Convicted", "musicCredit": "'Winchester New' from \"Musikalisches Handbuch\", Hamburg, 1690", "number": 233}, {"title": "O Lord, How Shall I Meet Thee", "sectionId": 7, "wordsCredit": "Paul Gerhardt, 1653. translator unknown", "verses": ["O Lord, how shall I meet Thee, How welcome Thee aright? All nations long to see Thee, My Hope, my heart's Delight! O kindle, Lord, most holy, Thy lamp within my breast, To do in spirit lowly All that may please Thee best.", "Thy Zion palms is strewing, And branches fresh and fair; My heart, its pow'rs renewing, An anthem shall prepare. My soul puts off her sadness Thy glories to proclaim; With all her strength and gladness She fain would serve Thy Name.", "What hast Thou left ungranted To give me glad relief? When soul and body panted In utmost depth of grief, In deepest degradation, Devoid of joy and peace, Then, Thou, my soul's Salvation, Didst come to bring release.", "I lay in fetters groaning, Thou com'st to set me free; I stood, my shame bemoaning, Thou com'st to honor me. A glory Thou dost give me, A treasure safe on high, That will not fail nor leave me As earthly riches fly.", "Love caused Thine incarnation Love brought Thee down to me; Thy thirst for my salvation Procured my liberty. O love beyond all telling, That led Thee to embrace, In love all love excelling, Our lost and fallen race!", "Rejoice, then, ye sad-hearted, Who sit in deepest gloom, Who mourn o'er joys departed, And tremble at your doom: Despair not, He is near you, Yea, standing at the door; He brings His pity near you, And bids you weep no more.", "No care nor effort either Is needed day or night, How ye may draw Him hither In your own strength and might. He comes, He comes with gladness, Moved by His love alone, To calm your fear and sadness, To Him they well are known.", "Sin's debt, that fearful burden, Let not your souls distress; Your guilt the Lord will pardon and cover with His grace. He comes, He comes procuring The peace of sin forgiv'n, To all God's sons securing Their part and lot in heav'n.", "Why should the wicked move you? Heed not their craft and spite! Your Savior who doth love you, Will scatter all their might. He comes, a King most glorious, and all His earthly foes In vain His course victorious Endeavor to oppose.", "He comes to judge the nations, A terror to His foes, A light of consolations And blessed hope to those Who love the Lord's appearing. O glorious Sun, now come, Send forth Thy beams so cheering, And guide is safely home!"], "scriptureLinks": [{"label": "Mt 21:1-9", "chapterId": "MAT-21", "verseNumber": 1}, {"label": "Ps 42:1-2", "chapterId": "PSA-42", "verseNumber": 1}], "musicCredit": "'Wie Soll ich Dich Empfange' Johann Crüger, 1653", "number": 234}, {"title": "O Lord, I Am Not Worthy", "sectionId": 7, "wordsCredit": "from Landshuter Gesangbuch, 1777. Translation unknown, before 1913", "verses": ["O Lord, I am not worthy That Thou should'st come to me, But speak the words of comfort, My spirit healed shall be.", "O Lord, Thou art all holy, The angels Thee adore; How, then, ought I sincerely My wrongs and sins deplore!", "But when Thou soon wilt enter My heart, my sinful heart, Then heal me, be my shelter, For Thou my Savior art.", "O Lord, how can I thank Thee For such a gift as this? A gift which truly filleth My soul with heav'nly bliss!", "I praise Thee, I extol Thee, I love Thee O my Sire, Till once in joy and glory, In heav'n I Thee admire."], "scriptureLinks": [{"label": "Mt 8:8", "chapterId": "MAT-8", "verseNumber": 8}, {"label": "Lk 7:6", "chapterId": "LUK-7", "verseNumber": 6}, {"label": "5:8", "chapterId": "LUK-5", "verseNumber": 8}], "musicCredit": "'Non Dignus' traditional air, before 1871", "number": 235}, {"title": "O Love, How Deep, How Broad, How High", "sectionId": 7, "wordsCredit": "Unknown, 15th Century; Translated by Benjamin Webb, 1852, alt", "verses": ["O love, how deep, how broad, how high, How passing thought and fantasy, That God, the Son of God, should take Our mortal form for mortals' sake!", "He sent no angel to our race Of higher or of lower place, But wore the robe of human frame And He Himself, to this world came.", "Nor willed He only to appear; His pleasure was to tarry here; And God and Man with man would be The space of thirty years and three.", "For us baptized, for us He bore His holy fast and hungered sore, For us temptations sharp He knew; For us the tempter overthrew.", "For us He prayed; for us He taught; For us His daily works He wrought; By words and signs and actions thus Still seeking not Himself, but us.", "For us to wicked men betrayed, Scourged, mocked, in crown of thorns arrayed, For us He bore the cross's death, For us at length gave up His breath.", "For us He rose from death again; For us He went on high to reign; For us He sent His Spirit here, To guide, to strengthen, and to cheer.", "All honor, laud, and glory be, O Jesus, virgin-born to Thee! All glory, as is ever meet To Father and to Paraclete."], "scriptureLinks": [{"label": "Eph 3:14-21", "chapterId": "EPH-3", "verseNumber": 14}, {"label": "1 Jn 4:7-10", "chapterId": "1JN-4", "verseNumber": 7}, {"label": "Rom 8:38-39", "chapterId": "ROM-8", "verseNumber": 38}], "musicCredit": "'Deo Gracias' or 'Agincourt' traditional English, circa 1415", "number": 236}, {"title": "On Jordan's Bank the Baptist's Cry", "sectionId": 7, "wordsCredit": "Charles Coffin, 1736. st. 1-3 translated by John Chandler, 1837; st 4-5 translator unknown", "verses": ["On Jordan's bank the Baptist's cry Announces that the Lord is nigh; Come, then, and hearken, for he brings Glad tidings from the King of kings!", "Then cleansed be every breast from sin; Make straight the way for God within; Prepare we in our hearts a home, Where such a mighty Guest may come.", "For Thou art our Salvation, Lord, Our Refuge, and our great Reward. Without Thy grace our souls must fade And wither like a flow'r decayed.", "Stretch forth Thine hand, to heal our sore, And make us rise and fall no more; Once more upon Thy people shine, And fill the world with love divine.", "To Him Who left the throne of Heav'n To save mankind, all praise be giv'n; Like praise be to the Father done, And Holy Spirit, Three in One."], "scriptureLinks": [{"label": "Jn 1:19-23", "chapterId": "JHN-1", "verseNumber": 19}, {"label": "Mt 3:1-12", "chapterId": "MAT-3", "verseNumber": 1}, {"label": "Mk 1:1-8", "chapterId": "MRK-1", "verseNumber": 1}], "musicCredit": "'Puer Nobis Nascitur' Michael Praetorius, 1609", "number": 237}, {"title": "Our God, Our Help In Ages Past", "sectionId": 7, "wordsCredit": "Isaac Watts, 1719", "verses": ["Our God, our help in ages past, Our hope for years to come, Our shelter from the stormy blast, And our eternal home.", "Under the shadow of Thy throne Thy saints have dwelt secure; Sufficient is Thine arm alone, And our defense is sure.", "Before the hills in order stood, Or earth received her frame, From everlasting Thou art God, To endless years the same.", "Thy Word commands our flesh to dust, 'Return, ye sons of men:' All nations rose from earth at first, And turn to earth again.", "A thousand ages in Thy sight Are like an evening gone; Short as the watch that ends the night Before the rising sun.", "The busy tribes of flesh and blood, With all their lives and cares, Are carried downwards by the flood, And lost in following years.", "Time, like an ever rolling stream, Bears all its sons away; They fly, forgotten, as a dream Dies at the opening day.", "Like flowery fields the nations stand Pleased with the morning light; The flowers beneath the mower's hand Lie withering ere 'tis night.", "Our God, our help in ages past, Our hope for years to come, Be Thou our guard while troubles last, And our eternal home."], "scriptureLinks": [{"label": "Ps 90:1", "chapterId": "PSA-90", "verseNumber": 1}, {"label": "Heb 1:1-2", "chapterId": "HEB-1", "verseNumber": 1}], "musicCredit": "'St. Anne' William Croft, 1708", "number": 238}, {"title": "Out of the Deep I Cry to Thee", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Arthur Tozer Russell (1806-1874)", "verses": ["Out of the deep I cry to Thee; O Lord God, hear my crying: Incline Thy gracious ear to me, With prayer to Thee applying. For if Thou fix Thy searching eye On all sin and iniquity, Who, Lord, can stand before Thee?", "But love and grace with Thee prevail, O God, our sins forgiving; The holiest deeds can naught avail Of all before Thee living. Before Thee none can boast him clear; Therefore must each Thy judgment fear, And live on Thy compassion.", "For this, my hope in God shall rest, Naught building on my merit; My heart confides, of Him possest, His goodness stays my spirit. His precious word assureth me; My solace, my sure Rock is he, Whereon my soul abideth.", "And though I wait the livelong night And till the morn returneth, My heart undoubting trusts His might Nor in impatience mourneth. Born of His Spirit, Israel In the right Way thus fareth well, And on his God reposeth", "What though our sins are manifold? Supreme His mercy reigneth; No limit can His hand withhold, Where evil most obtaineth. He the good Shepherd is alone, Who Israel will redeem and own, Forgiving all transgression."], "scriptureLinks": [{"label": "Ps 130", "chapterId": "PSA-130", "verseNumber": 1}, {"label": "Eph 2:8-9", "chapterId": "EPH-2", "verseNumber": 8}, {"label": "Rom 5:20-21", "chapterId": "ROM-5", "verseNumber": 20}], "altTitle": "From Depths of Woe I Cry to Thee", "musicCredit": "'Aus Tiefer Not (Luther)' or 'Af Dybsens Nød' Martin Luther from Erfurt Enchiridion, 1524", "number": 239}, {"title": "Out of the Deep I Cry to Thee", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Arthur Tozer Russell (1806-1874)", "verses": ["Out of the deep I cry to Thee; O Lord God, hear my crying: Incline Thy gracious ear to me, With prayer to Thee applying. For if Thou fix Thy searching eye On all sin and iniquity, Who, Lord, can stand before Thee?", "But love and grace with Thee prevail, O God, our sins forgiving; The holiest deeds can naught avail Of all before Thee living. Before Thee none can boast him clear; Therefore must each Thy judgment fear, And live on Thy compassion.", "For this, my hope in God shall rest, Naught building on my merit; My heart confides, of Him possest, His goodness stays my spirit. His precious word assureth me; My solace, my sure Rock is He, Whereon my soul abideth.", "And though I wait the livelong night And till the morn returneth, My heart undoubting trusts His might Nor in impatience mourneth. Born of His Spirit, Israel In the right Way thus fareth well, And on his God reposeth", "What though our sins are manifold? Supreme His mercy reigneth; No limit can His hand withhold, Where evil most obtaineth. He the good Shepherd is alone, Who Israel will redeem and own, Forgiving all transgression."], "scriptureLinks": [{"label": "Ps 130", "chapterId": "PSA-130", "verseNumber": 1}, {"label": "Eph 2:8-9", "chapterId": "EPH-2", "verseNumber": 8}, {"label": "Rom 5:20-21", "chapterId": "ROM-5", "verseNumber": 20}], "altTitle": "From Depths of Woe I Cry to Thee", "musicCredit": "'Aus Tiefer Not (Strassburg)' or 'Strassburg' from Köpfel's Gesangbuch, Strassburg, 1525", "number": 240}, {"title": "Rejoice, My Heart, Be Glad and Sing", "sectionId": 7, "wordsCredit": "Paul Gerhardt, 1653. Translation composite", "verses": ["Rejoice, my heart, be glad and sing, A cheerful trust maintain; For God, the Source of everything, Thy Portion shall remain.", "He is thy Treasure, He thy Joy, Thy Life and Light and Lord, Thy Counselor when doubts annoy, Thy Shield and great Reward.", "Why spend the day in blank despair, In restless thought the night? On thy Creator cast thy care; He makes thy burdens light.", "Did not His love and truth and pow'r Watch o'er thy childhood day? Has He not oft in threat'ning hour Turned dreaded ills away?", "His wisdom never plans in vain, Ne'er falters or mistakes; All that His counsels did ordain A happy ending makes.", "Upon thy lips, then, lay thy hand And trust His guiding love; Then like a rock thy peace shall stand Here and in heav'n above.", "O Lord I sing with lips and heart, Joy of my soul, to Thee: To Earth Thy knowledge I impart, As it is known to me.", "Thou art the Fount of grace, I know, And Spring so full and free, Whence saving health and goodness flow Each day so bounteously.", "For what have all that live and move Through this wide world below That does not from Thy bounteous love, O Heav'nly Father flow?", "Who built the lofty firmament? Who spread th'expanse of blue? By whom are to our pastures sent Refreshing rain and dew?", "Who warmeth us in cold and frost? Who shields us from the wind? Who orders it that oil and must We in their season find?", "Who is it life and health bestows? Who keeps us with His hand In golden peace, wards off war's woes From our dear native land?", "O Lord of this and all our store Thou art the author blest; Thou keepest watch before our door, While we securely rest.", "Thou feedest us from year to year, And constant dost abide; With ready help in time of fear, Thou standest at our side.", "He ever will with patience chide, His rod falls gently down, And all thy sins He casts aside And in the sea doth drown.", "When silent woe thy bosom rends, His pity sees thy grief, Supplies what to His glory tends And to thine own relief.", "He knows how oft a Christian weeps And why his tears now fall; And in the book His mercy keeps These things are noted all.", "Our deepest needs dost Thou supply, Thou giv'st what lasts for aye. Thou lead'st us to our home on high, When hence we pass away."], "scriptureLinks": [{"label": "Ps 8:1-9", "chapterId": "PSA-8", "verseNumber": 1}, {"label": "Ps 27:1-6", "chapterId": "PSA-27", "verseNumber": 1}, {"label": "Mic 7:18-19", "chapterId": "MIC-7", "verseNumber": 18}], "altTitle": "O Lord I Sing with Lips and Heart", "musicCredit": "'Ich Singe dir mit Herz' Johann Balthasar König, 1738", "number": 241}, {"title": "See, The Lord Ascends In Triumph", "sectionId": 7, "wordsCredit": "Christopher Wordsworth, 1862, alt", "verses": ["See, the Lord ascends in triumph; see the King in royal state, Riding on the clouds, His chariot, To His heav'nly palace gate. Hark! the choirs of angel voices Joyful alleluias sing, And the portals high are lifted To receive their heav'nly King.", "Who is this that comes in glory, with the trump of jubilee? Lord of battles, God of armies, He has gained the victory. He Who on the cross did suffer, He who from the grave arose, He has vanquished sin and Satan, He by death has spoiled His foes.", "While He lifts His hands in blessing, He is parted from His friends While their eager eyes behold Him, He upon the cloud ascends; He Who walked with God and pleased Him, preaching truth and doom to come, He, our Enoch, is translated to His everlasting home.", "Now our heav'nly Aaron enters, with His blood, within the veil; Joshua now is come to Canaan, and the kings before Him quail; Now He plants the tribes of Israel in their promised resting place; Now our great Elijah offers double portion of His grace.", "He has raised our human nature in the clouds to God's right hand; There we sit in heav'nly places, there with Him in glory stand: Jesus reigns, adored by angels; man with God is on the throne; Mighty Lord, in Thine ascension we by faith behold our own.", "Holy Ghost, Illuminator, shed Thy beams upon our eyes, Help us to look up with Stephen, and to see beyond the skies, Where the Son of Man in glory Standing is at God's right hand, Beck'ning on His martyr army, succoring His faithful band.", "See Him, Who is gone before us, Heav'nly mansions to prepare, See Him, who is ever pleading For us with prevailing prayer, See Him, who with sound of trumpet, and with His angelic train, Summoning the world to judgment, on the clouds will come again.", "Raise us up from earth to Heaven, give us wings of faith and love, Gales of holy aspirations wafting us to realms above; That, with hearts and minds uplifted, we with Christ our Lord may dwell, Where He sits enthroned in glory in His heav'nly Citadel.", "So at last, when He appeareth, we from out our graves may spring, With our youth renewed like eagles, flocking round our Heav'nly King. Caught up on the clouds of Heaven, and may meet Him in the air, Rise to realms where He is reigning, and may reign for ever there.", "Glory be to God the Father, Glory be to God the Son, Dying, ris'n, ascending for us, who the heav'nly realm has won; Glory to the Holy Spirit, To One God in Persons Three; Glory both in earth and Heaven, glory, endless glory, be."], "scriptureLinks": [{"label": "Ps 68:18", "chapterId": "PSA-68", "verseNumber": 18}, {"label": "Eph 4:8-15", "chapterId": "EPH-4", "verseNumber": 8}, {"label": "Acts 1:6-11", "chapterId": "ACT-1", "verseNumber": 6}], "altTitle": "See, the Conqueror Mounts in Triumph", "musicCredit": "'Rex Gloriae' Henry Thomas Smart, 1868", "number": 242}, {"title": "That Men a godly Life Might Live", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["That man a godly life might live, God did these ten commandments give By His true servant Moses, high Upon the mount Sinai. Have mercy, Lord.", "I am thy God and Lord alone, No other God besides Me own; On My great mercy venture thee, With all thy heart love thou Me. Have mercy, Lord.", "By idle word and speech profane Take not My holy Name in vain; And praise not aught as good and true But what God doth say and do. Have mercy, Lord.", "Hallow the day which God hath blest, That thou and all thy house may rest; Keep hand and heart from labor free, That God may so work in thee. Have mercy, Lord.", "Give to thy parents honor due, Be dutiful and loving too; And help them when their strength decays So shalt thou have length of days. Have mercy, Lord.", "Kill thou not out of evil will, Nor hate, nor render ill for ill; Be patient and of gentle mood, And to thy foe do thou good.", "Be faithful to thy marriage vows, Thy heart give only to thy spouse Keep thy life pure, and lest thou sin Keep thyself with discipline.", "Steal not; oppressive acts abhor; Nor wring their life-blood from the poor; But open wide thy loving hand To all the poor in the land.", "Bear not false witness, nor belie Thy neighbor by foul calumny; Defend his innocence from blame, With charity hide his shame.", "Thy neighbor's wife desire thou not, His house, nor aught that he hath got But wish that his such good may be As thy heart doth wish for thee.", "God these commandments gave, therein To show thee, son of man, thy sin, And make thee also well perceive How man for God ought to live.", "Help us, Lord Jesus Christ, for we A Mediator have in Thee; Without Thy help our works so vain Merit naught but endless pain."], "scriptureLinks": [{"label": "Ex 20:1-17", "chapterId": "EXO-20", "verseNumber": 1}, {"label": "Deut 5:6-21", "chapterId": "DEU-5", "verseNumber": 6}, {"label": "1Tim 2:5-6", "chapterId": "1TI-2", "verseNumber": 5}], "altTitle": "These Are the Holy Ten Commands", "musicCredit": "'Dies sind die heil`gen zehu Gebot' or 'In Gottes Namen fahren wir' circa1200s found in Erfurt Enchiridion, 1524", "number": 243}, {"title": "The Law Of God Is Good And Wise", "sectionId": 7, "wordsCredit": "Matthias Loy, 1863", "verses": ["The law of God is good and wise, And sets His will before our eyes, Shows us the way of righteousness, And dooms to death when we transgress.", "Its light of holiness imparts The knowledge of our sinful hearts, That we may see our lost estate And seek deliv'rance ere too late.", "To those who help in Christ have found And would in works of love abound It shows what deeds are His delight And should be done as good and right.", "When men the offered help disdain And willfully in sin remain, Its terror in their ear resounds And keeps their wickedness in bounds.", "The law is good, but since the fall Its holiness condemns us all; It dooms us for our sin to die And has no pow'r to justify."], "scriptureLinks": [{"label": "Ps 19:8", "chapterId": "PSA-19", "verseNumber": 8}, {"label": "Rom 3:19-26", "chapterId": "ROM-3", "verseNumber": 19}, {"label": "Rom 2:12", "chapterId": "ROM-2", "verseNumber": 12}], "musicCredit": "'Erhalt Uns, Herr, bei deinem Wort' from Klug's Geistliche Lieder, 1543", "number": 244}, {"title": "The Love of God", "sectionId": 7, "wordsCredit": "Frederick Martin Lehman, 1917", "verses": ["The love of God is greater far Than tongue or pen can ever tell, It goes beyond the highest star, And reaches to the lowest hell; The guilty pair, bowed down with care, God gave His Son to win; His erring child, He reconciled, And pardoned from his sin.", "When hoary time shall pass away, And earthly thrones and kingdoms fall; When men who here refuse to pray, On rocks and hills and mountains call; God's love, so sure, shall still endure, All measureless and strong; Redeeming grace to Adam's race— The saints' and angels' song.", "Could we with ink the ocean fill,And were the skies of parchment made, Were every stalk on earth a quill And every man a scribe by trade; To write the love of God above Would drain the ocean dry; Nor could the scroll contain the whole, Tho' stretched from sky to sky."], "scriptureLinks": [{"label": "Rom 8:35-39", "chapterId": "ROM-8", "verseNumber": 35}, {"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Jer 31:2-3", "chapterId": "JER-31", "verseNumber": 2}], "musicCredit": "'The Love of God' Frederick Martin Lehman, 1917", "refrain": "Oh love of God, how rich and pure! How measureless and strong! It shall forevermore endure, The saints' and angels' song.", "number": 245}, {"title": "The Mouth of Fools Doth God Confess", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["The mouth of fools doth God confess, But while their lips draw nigh Him, Their heart is full of wickedness, And all their deeds deny Him. Corrupt are they, and every one Abominable works hath done; There is not one welldoer.", "The Lord looked down from his high tow'r On all mankind below Him, To see if any owned His pow'r, And truly sought to know Him; Who all their understanding bent To search His holy Word, intent To do his will in earnest.", "But none there was who walked with God, For all aside had slidden, Delusive paths of folly trod, And followed lusts forbidden; Not one there was who practiced good, And yet they deemed, in haughty mood, Their deeds must surely please Him.", "How long, by folly blindly led, Will ye oppress the needy, And eat my people up like bread? So fierce are ye, and greedy! In God they put no trust at all, Nor will on Him in trouble call, But be their own providers.", "Therefore their heart is never still, A falling leaf dismays them; God is with him who doth His will, Who trusts him and obeys Him; But ye the poor man's hope despise, And laugh at him, e'en when he cries, That God is his sure comfort.", "Who shall to Israel's outcast race From Zion bring salvation? God will himself at length show grace, And loose the captive nation; That will he do by Christ their King; Let Jacob then be glad and sing, And Israel be joyful."], "scriptureLinks": [{"label": "Ps 53:1-6", "chapterId": "PSA-53", "verseNumber": 1}, {"label": "Lk 4:17-21", "chapterId": "LUK-4", "verseNumber": 17}, {"label": "6:39-49", "chapterId": "LUK-6", "verseNumber": 39}], "altTitle": "Although the Fools Say with Their Mouth", "musicCredit": "'Es spricht der Unweisen Mund' from Walter's Geistliche Gesangbüchlein, 1524", "number": 246}, {"title": "The People That in Darkness Sat", "sectionId": 7, "wordsCredit": "John Morison, 1781", "verses": ["The people that in darkness sat A glorious light have seen; The light has shined on them who long In shades of death have been. In shades of death have been.", "To hail Thee, Sun of Righteousness, The gath'ring nations come; They joy as when the reapers bear Their harvest treasures home. Their harvest treasures home.", "For Thou their burden dost remove And break the tyrant's rod As in the day when Midian fell Before the sword of God. Before the sword of God.", "To us a Child of hope is born, To us a Son is giv'n, And on His shoulder ever rests All pow'r in earth and heav'n. All pow'r in earth and heav'n.", "His name shall be the Prince of Peace, The Everlasting Lord, The Wonderful, the Counselor. The God by all adored. The God by all adored.", "His righteous government and power Shall over all extend; On judgment and on justice based, His reign shall have no end.", "Lord Jesus, reign in us, we pray, And make us Thine alone, Who with the Father ever art And Holy Spirit, one."], "scriptureLinks": [{"label": "Mt 4:12-17", "chapterId": "MAT-4", "verseNumber": 12}, {"label": "Is 9:2-7", "chapterId": "ISA-9", "verseNumber": 2}, {"label": "Mal 4:1-6", "chapterId": "MAL-4", "verseNumber": 1}], "musicCredit": "'Lobt Gott, ihr Christen Allzugleich' Nikolaus Hermann, 1554", "number": 247}, {"title": "The Star Proclaims the King is Here", "sectionId": 7, "wordsCredit": "Coelius Sedulius, c. 450. German version by M. Luther, 1543. English translation by John Mason Neale, 1852", "verses": ["The star proclaims the King is here; But, Herod, why this senseless fear? He takes no realms of earth away Who gives the realms of heav'nly day.", "The wiser Magi see from far And follow on His guiding star; And led by light, to light they press And by their gifts their God confess.", "Within the Jordan's crystal flood In meekness stands the Lamb of God And, sinless, sanctifies the wave, Mankind from sin to cleanse and save.", "At Cana first His pow'r is shown; His might the blushing waters own And, changing as He speaks the word, Flow wine, obedient to their Lord.", "All glory, Jesus, be to Thee For this Thy glad epiphany; Whom with the Father we adore And Holy Ghost forevermore."], "scriptureLinks": [{"label": "Mt 2:1-18", "chapterId": "MAT-2", "verseNumber": 1}, {"label": "Eph 1:9", "chapterId": "EPH-1", "verseNumber": 9}, {"label": "Jn 18:36-37", "chapterId": "JHN-18", "verseNumber": 36}], "altTitle": "Herod Why Dreadest thou a Foe? or How Vain the Cruel Herod's Fear or When Christ's Appearing Was Made Known or Why Herod Unrelenting Foe or Why Impious Herod, Shouldst Thou Fear", "musicCredit": "'Wo Gott Zum Haus' from Klug's Geistliche Lieder, Wittenberg, 1533", "number": 248}, {"title": "The Strife Is O'er, The Battle Done", "sectionId": 7, "wordsCredit": "from Symphonia Sirenum Selectarum, Köln, 1695; translated by Francis Pott, 1861", "verses": ["Alleluia, Alleluia, Alleluia.", "The strife is o'er, the battle done; The triumph of the Lord is won; O Let the song of praise be sung: Alleluia!", "The pow'rs of death have done their worst; and Jesus hath His foes dispersed; Let shouts of praise and joy outburst: Alleluia!", "On that third morn He rose again In glorious majesty to reign; O let us swell the joyful strain. Alleluia!", "He closed the yawning gates of hell; The bars from heav'ns high portals fell; Let songs of joy His triumphs tell. Alleluia!", "Lord, by the stripes which wounded Thee, From death's dread sting Thy servants free, That we may live, and sing to Thee. Alleluia!", "Alleluia, Alleluia, Alleluia."], "scriptureLinks": [{"label": "Acts 2:22-24", "chapterId": "ACT-2", "verseNumber": 22}, {"label": "Rom 5:10-11", "chapterId": "ROM-5", "verseNumber": 10}, {"label": "6:9-10", "chapterId": "ROM-6", "verseNumber": 9}], "musicCredit": "'Victory' or 'Palestrina' Giovanni P. da Palestrina, 1591", "number": 249}, {"title": "There's a Great Day Coming", "sectionId": 7, "wordsCredit": "Will L. Thompson, 1886", "verses": ["There's a great day coming, A great day coming, There's a great day coming by and by; When the saints and the sinners shall be parted right and left, Are you ready for that day to come?", "There's a bright day coming, A bright day coming, There's a bright day coming by and by; But its brightness shall only come to them that love the Lord, Are you ready for that day to come?", "There's a sad day coming, A sad day coming, There's a sad day coming by and by; When the sinner shall hear his doom, \"Depart, I know ye not,\" Are you ready for that day to come?"], "scriptureLinks": [{"label": "Mt 25:31-46", "chapterId": "MAT-25", "verseNumber": 31}, {"label": "Mt 24:36-44", "chapterId": "MAT-24", "verseNumber": 36}, {"label": "Mk 13:33-37", "chapterId": "MRK-13", "verseNumber": 33}], "musicCredit": "'Theres a Great Day Coming' Will L. Thompson, 1886", "refrain": "Are you ready? Are you ready? Are you ready for the judgment day? Are you ready? Are you ready? For the judgment day?", "number": 250}, {"title": "Thine Arm, O Lord, in Days of Old", "sectionId": 7, "wordsCredit": "Edward H. Plumptre, 1864", "verses": ["Thine arm, O Lord, in days of old, was strong to heal and save; It triumphed o'er disease and death, o'er darkness and the grave. To Thee they went, the blind, the dumb, the palsied and the lame, The leper with his tainted life, the sick with fevered frame.", "And lo! Thy touch brought life and health, gave speech, and strength and sight; And youth renewed and fear relieved owned Thee, the Lord of light; And now, O Lord, be near to bless, Almighty as of yore, In crowded street, by restless couch, as by Gennesaret's shore.", "Be Thou our great Deliverer still, Thou Lord of life and death; Restore and quicken, soothe and bless, with Thine almighty breath. To hands that work and eyes that see, give wisdom's heavenly lore, That whole and sick, and weak and strong, may praise Thee evermore."], "scriptureLinks": [{"label": "Lk 19:9-10", "chapterId": "LUK-19", "verseNumber": 9}, {"label": "Mt 9:35-36", "chapterId": "MAT-9", "verseNumber": 35}, {"label": "Jn 10:10", "chapterId": "JHN-10", "verseNumber": 10}], "altTitle": "Your Hand, O Lord, in Days of Old", "musicCredit": "'Kingsfold' traditional English", "number": 251}, {"title": "Thou, Who at Thy First Eucharist", "sectionId": 7, "wordsCredit": "William H. Turton, 1881", "verses": ["Thou, who at Thy first Eucharist didst pray That all Thy Church might be forever one, Grant us at ev'ry Eucharist to say With longing heart and soul, \"Thy will be done.\" O may we all one bread, one body be, Through this blest sacrament of unity.", "For all Thy Church, O Lord, we intercede; Make Thou our sad divisions soon to cease; Draw us the nearer each to each, we plead, By drawing all to Thee, O Prince of Peace; Thus may we all one bread, one body be, Through this blest sacrament of unity.", "We pray Thee too for wand'rers from Thy fold; O bring them back, good Shepherd of the sheep, Back to the faith which saints believed of old, Back to the Church which still that faith doth keep; Soon may we all one bread, one body be, Through this blest sacrament of unity.", "So, Lord, at length when sacraments shall cease, May we be one with all Thy Church above, One with Thy saints in one unbroken peace, One with Thy saints in one unbounded love; More blessèd still, in peace and love to be One with the Trinity in unity."], "scriptureLinks": [{"label": "Jn 17:11", "chapterId": "JHN-17", "verseNumber": 11}, {"label": "Eph 4:1-7", "chapterId": "EPH-4", "verseNumber": 1}, {"label": "1Cor 10:16-17", "chapterId": "1CO-10", "verseNumber": 16}], "altTitle": "Lord, Who the Night You Were Betrayed or At That First Eucharist", "musicCredit": "'Unde Et Memores' William Henry Monk, 1875", "number": 252}, {"title": "We Give Thee But Thine Own", "sectionId": 7, "wordsCredit": "William W. How, 1864", "verses": ["We give Thee but Thine own, Whate'er the gift may be; All that we have is Thine alone, A trust, O Lord, from Thee.", "May we Thy bounties thus As stewards true receive, And gladly, as Thou blessest us, To Thee our firstfruits give.", "O hearts are bruised and dead, And homes are bare and cold, And lambs for whom the Shepherd bled Are straying from the fold.", "To comfort and to bless, To find a balm for woe, To tend the lone and fatherless Is angels' work below.", "The captive to release, To God the lost to bring, To teach the way of life and peace? It is a Christlike thing.", "And we believe Thy Word, Though dim our faith may be; Whate'er for Thine we do, O Lord, We do it unto Thee."], "scriptureLinks": [{"label": "1Chr 29:14", "chapterId": "1CH-29", "verseNumber": 14}, {"label": "1 Jn 3:16-18", "chapterId": "1JN-3", "verseNumber": 16}, {"label": "Mt 25:40", "chapterId": "MAT-25", "verseNumber": 40}], "musicCredit": "'Energy' William H. Monk (1823-1889)", "number": 253}, {"title": "What Wondrous Love Is This?", "sectionId": 7, "wordsCredit": "Anonymous before 1811", "verses": ["What wondrous love is this; O my soul! O my soul! What wondrous love is this; O my soul! What wondrous love is this; That caused the Lord of bliss To bear the dreadful curse, For my soul, For my soul, To bear the dreadful curse, For my soul?", "When I was sinking down, sinking down, sinking down When I was sinking down, sinking down When I was sinking down, Beneath God's righteous frown, Christ laid aside His crown, For my soul! For my soul! Christ laid aside His crown, For my soul!", "Ye winged seraphs fly! Bear the news, Bear the news, Ye winged seraphs fly! Bear the news, Ye winged seraphs fly! Like comets through the sky, Fill vast eternity with the news, with the news. Fill vast eternity with the news.", "To God and to the Lamb, I will sing, I will sing, To God and to the Lamb, I will sing, To God and to the Lamb, And to the Great I AM, While millions join the theme, I will sing. I will sing. While millions join the theme, I will sing.", "Come friends of Zion's King, Join the praise, Join the praise, Come friends of Zion's King, Join the praise, Come friends of Zion's King, With hearts and voices sing, And strike each tuneful string In His praise! In His praise! And strike each tuneful string In His praise!", "Thus, while from death we're free, we'll sing on, we'll sing on, Thus, while from death we're free, we'll sing on, Thus, while from death we're free, We'll sing and joyful be, And through eternity We'll sing on.", "And when to that bright world we arise, we arise And when to that bright world we arise, When to that world we go, Free from all pain and woe, We'll join the happy throng, And sing on!"], "scriptureLinks": [{"label": "1 Jn 3:1-3", "chapterId": "1JN-3", "verseNumber": 1}, {"label": "1 Jn 4:9", "chapterId": "1JN-4", "verseNumber": 9}, {"label": "Ps 36:7", "chapterId": "PSA-36", "verseNumber": 7}], "musicCredit": "'Wondrous Love' American Folk Tune", "number": 254}, {"title": "Wilt Thou, O Man, Live Happily", "sectionId": 7, "wordsCredit": "Martin Luther, 1524. Translated by Richard Massie, 1854, alt", "verses": ["Wilt thou, O man, live happily, And dwell with God eternally, The ten commandments keep, for thus Our God Himself biddeth us. Kyr' eleison!", "I am the Lord and God! take heed No other god doth thee mislead; Thy heart shall trust alone in Me, My kingdom then thou shalt be. Kyr' eleison!", "Honor My Name in word and deed, And call on Me in time of need: Hallow the Sabbath, that I may Work in thy heart on that day. Kyr' eleison!", "Obedient always, next to Me, To father and to mother be; Kill no man: even anger dread; Keep sacred thy marriage bed. Kyr' eleison!", "Steal not, nor do thy neighbor wrong By bearing witness with false tongue; Thy neighbor's wife desire thou not, Nor grudge him aught he hath got. Kyr' eleison!"], "scriptureLinks": [{"label": "Ex 20:1-17", "chapterId": "EXO-20", "verseNumber": 1}, {"label": "Deut 5:6-21", "chapterId": "DEU-5", "verseNumber": 6}, {"label": "Ps 90:1", "chapterId": "PSA-90", "verseNumber": 1}], "altTitle": "Man, Wouldst Thou Live All Blissfully", "musicCredit": "'Mensch, Willt du Leben Seligich' attr. Martin Luther. Found in Walter's Geistliche Gesangbüchlein, 1524", "number": 255}, {"title": "'Tis Midnight and On Olive's Brow", "sectionId": 8, "wordsCredit": "William Bingham Tappan, 1822", "verses": ["'Tis midnight, and on Olive's brow The star is dimmed that lately shone; 'Tis midnight, in the garden now The suff'ring Savior prays alone.", "'Tis midnight, and from all removed Immanuel wrestles, lone, with fears; E'en the disciple whom He loved Heeds not his Master's grief and tears.", "'Tis midnight, from the heav'nly plains Are borne the songs that angels know; Unheard by mortals are the strains That sweetly soothe the Savior's woe."], "scriptureLinks": [{"label": "Mt 26:36-45", "chapterId": "MAT-26", "verseNumber": 36}, {"label": "Lk 22:39-46", "chapterId": "LUK-22", "verseNumber": 39}, {"label": "Mk 14:32-41", "chapterId": "MRK-14", "verseNumber": 32}], "musicCredit": "'St. Cross' John Bacchus Dykes, 1861", "number": 256}, {"title": "'Twas On That Dark, That Doleful Night", "sectionId": 8, "wordsCredit": "Isaac Watts, 1709", "verses": ["'Twas on that dark, that doleful night When pow'rs of earth and hell arose Against the Son of God's delight, And friends betrayed Him to His foes:", "Before the mournful scene began, He took the bread, and blessed, and brake: What love through all His actions ran! What wondrous words of grace He spake!", "\"This is My body, broke for sin; Receive and eat the living food:\" Then took the cup, and blessed the wine; \"'Tis the new cov'nant in My blood.\"", "For us His flesh with nails was torn, He bore the scourge, He felt the thorn; And justice poured upon His head Its heavy vengeance in our stead.", "For us His vital blood was spilt, To buy the pardon of our guilt, When, for black crimes of biggest size, He gave His soul a sacrifice.", "\"Do this,\" He cried, \"till time shall end, In memory of your dying friend; Meet at My table, and record The love of your departed Lord.\"", "Jesus, Thy feast we celebrate, We show Thy death, we sing Thy name, Till Thou return, and we shall eat The marriage supper of the Lamb."], "scriptureLinks": [{"label": "1Cor 11:23-26", "chapterId": "1CO-11", "verseNumber": 23}, {"label": "Rom 3:23-25", "chapterId": "ROM-3", "verseNumber": 23}, {"label": "Mt 26:26-28", "chapterId": "MAT-26", "verseNumber": 26}], "musicCredit": "'St. Cross' John Bacchus Dykes, 1861", "number": 257}, {"title": "Abide With Me", "sectionId": 8, "wordsCredit": "Henry F. Lyte, 1847", "verses": ["Abide with me; fast falls the eventide; The darkness deepens; Lord with me abide. When other helpers fail and comforts flee, Help of the helpless, O abide with me.", "Swift to its close ebbs out life's little day; Earth's joys grow dim; its glories pass away; Change and decay in all around I see; O Thou who changest not, abide with me.", "Not a brief glance I beg, a passing word; But as Thou dwell'st with Thy disciples, Lord, Familiar, condescending, patient, free. Come not to sojourn, but abide with me.", "Come not in terrors, as the King of kings, But kind and good, with healing in Thy wings, Tears for all woes, a heart for every plea? Come, Friend of sinners, and thus bide with me.", "Thou on my head in early youth didst smile; And, though rebellious and perverse meanwhile, Thou hast not left me, oft as I left Thee, On to the close, O Lord, abide with me.", "I need Thy presence every passing hour. What but Thy grace can foil the tempter's power? Who, like Thyself, my guide and stay can be? Through cloud and sunshine, Lord, abide with me.", "I fear no foe, with Thee at hand to bless; Ills have no weight, and tears no bitterness. Where is death's sting? Where, grave, thy victory? I triumph still, if Thou abide with me.", "Hold Thou Thy cross before my closing eyes; Shine through the gloom and point me to the skies. Heaven's morning breaks, and earth's vain shadows flee; In life, in death, O Lord, abide with me."], "scriptureLinks": [{"label": "Lk 24:29", "chapterId": "LUK-24", "verseNumber": 29}, {"label": "Ps 63:6-8", "chapterId": "PSA-63", "verseNumber": 6}, {"label": "73:23-26", "chapterId": "PSA-73", "verseNumber": 23}], "musicCredit": "'Eventide' William H. Monk, 1861", "number": 258}, {"title": "All Creatures of Our God and King", "sectionId": 8, "wordsCredit": "Francis of Assisi circa 1225. Translated by William H. Draper, 1919", "verses": ["All creatures of our God and King Lift up your voice and with us sing, Alleluia! Alleluia! Thou burning sun with golden beam, Thou silver moon with softer gleam! O praise Him! O praise Him! Alleluia! Alleluia! Alleluia!", "Thou rushing wind that art so strong Ye clouds that sail in Heaven along, O praise Him! Alleluia! Thou rising moon, in praise rejoice, Ye lights of evening, find a voice! O praise Him! O praise Him! Alleluia! Alleluia! Alleluia!", "Thou flowing water, pure and clear, Make music for thy Lord to hear, O praise Him! Alleluia! Thou fire so masterful and bright, That givest man both warmth and light. O praise Him! O praise Him! Alleluia! Alleluia! Alleluia!", "Dear mother earth, who day by day Unfoldest blessings on our way, O praise Him! Alleluia! The flowers and fruits that in thee grow, Let them His glory also show. O praise Him! O praise Him! Alleluia! Alleluia! Alleluia!", "And all ye men of tender heart, Forgiving others, take your part, O sing ye! Alleluia! Ye who long pain and sorrow bear, Praise God and on Him cast your care! O praise Him! O praise Him! Alleluia! Alleluia! Alleluia!", "And thou most kind and gentle Death, Waiting to hush our latest breath, O praise Him! Alleluia! Thou leadest home the child of God, And Christ our Lord the way hath trod.", "Let all things their Creator bless, And worship Him in humbleness, O praise Him! Alleluia! Praise, praise the Father, praise the Son, And praise the Spirit, Three in One!"], "scriptureLinks": [{"label": "Ps 69:34", "chapterId": "PSA-69", "verseNumber": 34}, {"label": "Ps 148", "chapterId": "PSA-76", "verseNumber": 2}], "musicCredit": "'Lasst Uns Erfreuen' from Geistliche Kirchengesäng, Köln, 1623", "number": 259}, {"title": "All My Heart This Night Rejoices", "sectionId": 8, "wordsCredit": "Paul Gerhardt, 1656. Translated by Catherine Winkworth, 1858", "verses": ["All my heart this night rejoices, As I hear, Far and near, Sweetest angel voices; \"Christ is born,\" their choirs are singing, Till the air Ev'rywhere Now with joy is ringing.", "For it dawns,— the promised morrow Of His birth Who the earth Rescues from her sorrow. God to wear our form descendeth, Of His grace To our race Here His Son He lendeth:", "Yea, so truly for us careth, That His Son All we've done As our off'ring beareth; As our Lamb who, dying for us, Bears our load, And to God Doth in peace restore us.", "Hark! a voice from yonder manger, Soft and sweet, Doth entreat, \"Flee from woe and danger; Brethren come, from all doth grieve you You are freed, All you need I will surely give you.\"", "Come then, let us hasten yonder; Here let all, Great and small, Kneel in awe and wonder. Love Him who with love is yearning; Hail the Star That from far Bright with hope is burning!", "Ye who pine in weary sadness, Weep no more, For the door Now is found of gladness. Cling to Him for He will guide you Where no cross, Pain or loss, Can again betide you.", "Hither come, ye heavy— hearted, Who for sin Deep within, Long and sore have smarted; For the poison'd wounds you're feeling Help is near, One is here Mighty for their healing!", "Hither come, ye poor and wretched; Know His will Is to fill Every hand outstretched; Here are riches without measure, Here forget All regret, Fill your hearts with treasure.", "Blessed Savior, let me find Thee! Keep Thou me Close to Thee, Cast me not behind Thee! Life of life, my heart Thou stillest, Calm I rest On Thy breast, All this void Thou fillest.", "Thee, dear Lord, with heed I'll cherish, Live to Thee, And with Thee Dying, shall not perish; But shall dwell with Thee for ever, Far on high In the joy That can alter never."], "scriptureLinks": [{"label": "Lk 2:8-15", "chapterId": "LUK-2", "verseNumber": 8}, {"label": "Is 7:14", "chapterId": "ISA-7", "verseNumber": 14}, {"label": "9:2-7", "chapterId": "ISA-9", "verseNumber": 2}], "altTitle": "All My Heart Again Rejoices", "musicCredit": "'Ebeling' or 'Bonn' or 'Warum Sollt Ich' or 'All My Heart This Night' Johann Georg Ebeling, 1666", "number": 260}, {"title": "All Praise To Thee, My God, This Night", "sectionId": 8, "wordsCredit": "Thomas Ken, circa 1674", "verses": ["All praise to Thee, my God, this night, For all the blessings of the light! Keep me, O keep me, King of kings, Beneath Thine own almighty wings.", "Forgive me, Lord, for Thy dear Son, The ill that I this day have done, That with the world, myself, and Thee, I, ere I sleep, at peace may be.", "Teach me to live, that I may dread The grave as little as my bed. Teach me to die, that so I may Rise glorious at the judgment day.", "O may my soul on Thee repose, And with sweet sleep mine eyelids close, Sleep that may me more vig'rous make To serve my God when I awake.", "When in the night I sleepless lie, My soul with heav'nly thoughts supply; Let no ill dreams disturb my rest, No pow'rs of darkness me molest.", "O when shall I, in endless day, For ever chase dark sleep away, And hymns divine with angels sing, All praise to thee, eternal King?", "Praise God, from Whom all blessings flow; Praise Him, all creatures here below; Praise Him above, ye heavenly host; Praise Father, Son, and Holy Ghost."], "scriptureLinks": [{"label": "Ps 17:8", "chapterId": "PSA-17", "verseNumber": 8}, {"label": "Ps 92:1-2", "chapterId": "PSA-92", "verseNumber": 1}, {"label": "Ps 4:8", "chapterId": "PSA-4", "verseNumber": 8}], "musicCredit": "'Tallis` Canon' Thomas Tallis, circa 1567", "number": 261}, {"title": "Angel Voices, Ever Singing", "sectionId": 8, "wordsCredit": "Francis Pott, 1861", "verses": ["Angel voices, ever singing, round Thy throne of light, Angel harps, forever ringing, rest not day or night; Thousands only live to bless Thee, and confess Thee Lord of might.", "Thou Who art beyond the farthest mortal eye can scan, Can it be that Thou regardest songs of sinful man? Can we feel that Thou art near us and wilt hear us? Yea, we can.", "Lord, we know Thy love rejoices o'er each work of Thine; Thou didst ears and hands and voices for Thy praise combine; Craftsman's art and music's measure for Thy pleasure didst design.", "Here, great God, today we offer of Thine own to Thee; And for Thine acceptance proffer, all unworthily, Hearts and minds, and hands and voices, in our choicest melody.", "Honor, glory, might and merit, Thine shall ever be, Father, Son, and Holy Spirit, blessed Trinity; Of the best that Thou hast given Earth and Heaven render Thee."], "scriptureLinks": [{"label": "Rev 5:8-14", "chapterId": "REV-5", "verseNumber": 8}, {"label": "Ps 148:1-2", "chapterId": "PSA-148", "verseNumber": 1}], "musicCredit": "'Angel Voices (Monk)' Edwin G. Monk, 1861", "number": 262}, {"title": "Awake, My Heart, With Gladness", "sectionId": 8, "wordsCredit": "Paul Gerhardt, 1648. Translated by John Kelly, 1867, alt", "verses": ["Awake, my heart, with gladness, See what today is done; How after gloom and sadness, Comes forth the glorious Sun. My Savior there was laid Where our bed must be made When to the realms of light Our spirit wings its flight.", "They in the grave did sink Him, The foe held jubilee; Before he can bethink him, Lo! Christ again is free. And \"Victory\" He cries, And waving tow'rds the skies His banner, while the field Is by the Hero held!", "Upon the grave is standing The Hero looking round; The foe, no more withstanding, His weapons on the ground Throws down, his hellish pow'r To Christ must he give o'er, And to the Victor's bands Must yield his feet and hands.", "A sight it is to gladden; And fill the heart with glee, No more affright or sadden Shall aught, or take from me My trust or fortitude, Or any precious good The Savior bought for me In sov'reign love and free.", "Hell and its prince, the devil, Of all their pow'rs are shorn; Now I am safe from evil, And sin I laugh to scorn. Grim Death with all his might Cannot my soul affright; He is a pow'rless form, Howe'er he rage and storm.", "The world against me rageth, Its fury I disdain; Though bitter war it wageth Its work is all in vain. My heart from care is free, Misfortune now is play, No trouble troubles me, And night is bright as day.", "I cleave now and forever To Christ, a member true, My Head will leave me never, Whate'er He passeth through. He treads the world beneath His feet, and conquers death And hell, and breaks sin's thrall; I'm with Him through it all.", "To halls of heavenly splendor With Him I penetrate; And trouble ne'er may hinder Nor make me hesitate. No enemy I fear, Because my Head is near; My Savior is my Shield, By Him all rage is stilled.", "He brings me to the portal That opens into bliss, Where graved in words immortal This golden scripture is: \"Who's there despised with me, Here with me crown'd shall be; Who there with Me shall die, Here's raised with me on high!\""], "scriptureLinks": [{"label": "Col 2:13-15", "chapterId": "COL-2", "verseNumber": 13}, {"label": "1Cor 15:42-58", "chapterId": "1CO-15", "verseNumber": 42}, {"label": "Rom 6:1-11", "chapterId": "ROM-6", "verseNumber": 1}], "musicCredit": "'Auf, Auf, Mein Herz mit Freuden' Johann Crüger, 1648", "number": 263}, {"title": "Awake, My Soul, And With The Sun (see also 'Praise God, From Whom All Blessings Flow')", "sectionId": 8, "wordsCredit": "Thomas Ken, 1674", "verses": ["Awake, my soul, and with the sun Thy daily stage of duty run; Shake off dull sloth, and joyful rise, To pay thy morning sacrifice.", "Thy precious time misspent, redeem, Each present day thy last esteem, Improve thy talent with due care; For the great day thyself prepare.", "By influence of Light divine Let thy own light to others shine. Reflect all Heaven's propitious ways In ardent love, and cheerful praise.", "In conversation be sincere; Keep conscience as the noontide clear; Think how all seeing God thy ways And all thy secret thoughts surveys.", "Wake, and lift up thyself, my heart, And with the angels bear thy part, Who all night long unwearied sing High praise to the eternal King.", "All praise to Thee, Who safe has kept And hast refreshed me while I slept Grant, Lord, when I from death shall wake I may of endless light partake.", "Heav'n is, dear Lord, where'er Thou art, O never then from me depart; For to my soul 'tis hell to be But for one moment void of Thee.", "Lord, I my vows to Thee renew; Disperse my sins as morning dew. Guard my first springs of thought and will, And with Thyself my spirit fill.", "Direct, control, suggest, this day, All I design, or do, or say, That all my powers, with all their might, In Thy sole glory may unite.", "I would not wake nor rise again And Heaven itself I would disdain, Wert Thou not there to be enjoyed, And I in hymns to be employed.", "Praise God, from Whom all blessings flow; Praise Him, all creatures here below; Praise Him above, ye heavenly host; Praise Father, Son, and Holy Ghost."], "scriptureLinks": [{"label": "Rom 13:11", "chapterId": "ROM-13", "verseNumber": 11}, {"label": "Ps 17:15", "chapterId": "PSA-17", "verseNumber": 15}, {"label": "Ps 148:1-2", "chapterId": "PSA-148", "verseNumber": 1}], "musicCredit": "'Old 100th' Genevan Psalter, attr. Louis Bourgeois, c. 1551", "number": 264}, {"title": "Away In A Manger", "sectionId": 8, "wordsCredit": "stanzas 1,2 anonymous published Philadelphia, 1885. stanza 3 John T. MacFarland (1851-1913)", "verses": ["Away in a manger, no crib for a bed, The little Lord Jesus laid down His sweet head. The stars in the sky looked down where He lay, The little Lord Jesus, asleep on the hay.", "The cattle are lowing, the Baby awakes, But little Lord Jesus, no crying He makes; I love Thee, Lord Jesus, look down from the sky And stay by my cradle til morning is nigh.", "Be near me, Lord Jesus, I ask Thee to stay Close by me forever, and love me, I pray; Bless all the dear children in Thy tender care, And fit us for Heaven to live with Thee there."], "scriptureLinks": [{"label": "Lk 2:7", "chapterId": "LUK-2", "verseNumber": 7}, {"label": "Lk 18:15-17", "chapterId": "LUK-18", "verseNumber": 15}], "musicCredit": "'Mueller' James R. Murray, 1887", "number": 265}, {"title": "Be Thou My Vision", "sectionId": 8, "wordsCredit": "Attr. Dallan Forgaill, 8th Century. Translated by Mary Byrne, 1905 and Eleanor Hull, 1912", "verses": ["Be Thou my Vision, O Lord of my heart; Naught be all else to me, save that Thou art. Thou my best Thought, by day or by night, Waking or sleeping, Thy presence my light.", "Be Thou my Wisdom, and Thou my true Word; I ever with Thee and Thou with me, Lord; Thou my great Father, and I Thy true son; Thou in me dwelling, and I with Thee one.", "Be Thou my battle Shield, Sword for the fight; Be Thou my Dignity, Thou my Delight; Thou my soul's Shelter, Thou my high Tower: Raise Thou me heav'nward, O Pow'r of my pow'r.", "Riches I heed not, nor man's empty praise, Thou mine Inheritance, now and always: Thou and Thou only, be first in my heart, High King of Heaven, my Treasure Thou art.", "High King of Heaven, my victory won, May I reach Heav'ns joys, O bright Heaven's Sun! Heart of my own heart, whatever befall, Still be my Vision, O Ruler of all."], "scriptureLinks": [{"label": "Jn 16:13", "chapterId": "JHN-16", "verseNumber": 13}, {"label": "Num 12:6", "chapterId": "NUM-12", "verseNumber": 6}], "musicCredit": "'Slane' Traditional Irish", "number": 266}, {"title": "Blest Be The Tie That Binds", "sectionId": 8, "wordsCredit": "John Fawcett, 1782", "verses": ["Blest be the tie that binds Our hearts in Christian love; The fellowship of kindred minds Is like to that above.", "Before our Father's throne We pour our ardent prayers; Our fears, our hopes, our aims are one Our comforts and our cares.", "We share each other's woes, Our mutual burdens bear; And often for each other flows The sympathizing tear.", "When we asunder part, It gives us inward pain; But we shall still be joined in heart, And hope to meet again.", "This glorious hope revives Our courage by the way; While each in expectation lives, And longs to see the day.", "From sorrow, toil and pain, And sin, we shall be free, And perfect love and friendship reign Through all eternity."], "scriptureLinks": [{"label": "Col 3:12-17", "chapterId": "COL-3", "verseNumber": 12}, {"label": "1 Jn 4:7-21", "chapterId": "1JN-4", "verseNumber": 7}, {"label": "Eph 4:1-6", "chapterId": "EPH-4", "verseNumber": 1}], "musicCredit": "'Boylston' Lowell Mason, 1832", "number": 267}, {"title": "Blest Be The Tie That Binds", "sectionId": 8, "wordsCredit": "John Fawcett, 1782", "verses": ["Blest be the tie that binds Our hearts in Christian love; The fellowship of kindred minds Is like to that above.", "Before our Father's throne We pour our ardent prayers; Our fears, our hopes, our aims are one Our comforts and our cares.", "We share each other's woes, Our mutual burdens bear; And often for each other flows The sympathizing tear.", "When we asunder part, It gives us inward pain; But we shall still be joined in heart, And hope to meet again.", "This glorious hope revives Our courage by the way; While each in expectation lives, And longs to see the day.", "From sorrow, toil and pain, And sin, we shall be free, And perfect love and friendship reign Through all eternity."], "scriptureLinks": [{"label": "Col 3:12-17", "chapterId": "COL-3", "verseNumber": 12}, {"label": "1 Jn 4:7-21", "chapterId": "1JN-4", "verseNumber": 7}, {"label": "Eph 4:1-6", "chapterId": "EPH-4", "verseNumber": 1}], "musicCredit": "'Dennis' Hans Georg Nägeli, circa 1828", "number": 268}, {"title": "Bonus Carol: Good King Wenceslas", "sectionId": 8, "wordsCredit": "John Mason Neale, 1853", "verses": ["Good King Wenceslas looked out on the Feast of Stephen, When the snow lay round about, deep and crisp and even. Brightly shone the moon that night, though the frost was cruel, When a poor man came in sight, gath'ring winter fuel.", "\"Hither, page, and stand by me, if thou knows't it, telling, Yonder peasant, who is he? Where and what his dwelling?\" \"Sire, he lives a good league hence, underneath the mountain, Right against the forest fence, by Saint Agnes' fountain.\"", "\"Bring me flesh and bring me wine, bring me pine logs hither, Thou and I will see him dine, when we bear them thither.\" Page and monarch, forth they went, forth they went together, Through the cold wind's wild lament and the bitter weather.", "\"Sire, the night is darker now, and the wind blows stronger, Fails my heart, I know not how; I can go no longer.\" \"Mark my footsteps, my good page, tread thou in them boldly, Thou shalt find the winter's rage freeze thy blood less coldly.\"", "In his master's steps he trod, where the snow lay dinted; Heat was in the very sod which the saint had printed. Therefore, Christian men, be sure, wealth or rank possessing, Ye who now will bless the poor shall yourselves find blessing."], "scriptureLinks": [{"label": "Lk 14:13-14", "chapterId": "LUK-14", "verseNumber": 13}, {"label": "Ps 41:1", "chapterId": "PSA-41", "verseNumber": 1}], "musicCredit": "'Tempus Adest Floridum' 13th Century spring carol; first published in the Swedish Piae Cantones, 1582", "number": 269}, {"title": "Come Thou Fount Of Every Blessing", "sectionId": 8, "wordsCredit": "Robert Robinson, 1758", "verses": ["Come, Thou Fount of every blessing, Tune my heart to sing Thy grace; Streams of mercy, never ceasing, Call for songs of loudest praise. Teach me some melodious sonnet, Sung by flaming tongues above. Praise the mount! I'm fixed upon it, Mount of Thy redeeming love.", "Sorr'wing I shall be in spirit, Till released from flesh and sin, Yet from what I do inherit, Here Thy praises I'll begin; Here I raise my Ebenezer; Here by Thy great help I've come; And I hope, by Thy good pleasure, Safely to arrive at home.", "Jesus sought me when a stranger, Wand'ring from the fold of God; He, to rescue me from danger, Interposed His precious blood; How His kindness yet pursues me Mortal tongue can never tell, Clothed in flesh, till death shall loose me I cannot proclaim it well.", "O to grace how great a debtor Daily I'm constrained to be! Let Thy goodness, like a fetter, Bind my wand'ring heart to Thee. Prone to wander, Lord, I feel it, Prone to leave the God I love; Here's my heart, O take and seal it, Seal it for Thy courts above.", "O that day when freed from sinning, I shall see Thy lovely face; Clothèd then in blood washed linen How I'll sing Thy sovereign grace; Come, my Lord, no longer tarry, Take my ransomed soul away; Send thine angels now to carry Me to realms of endless day."], "scriptureLinks": [{"label": "Ps 36:9-11", "chapterId": "PSA-36", "verseNumber": 9}, {"label": "Jn 4:13-14", "chapterId": "JHN-4", "verseNumber": 13}, {"label": "1Sam 7:3-12", "chapterId": "1SA-7", "verseNumber": 3}], "musicCredit": "'Nettleton' Asahel Nettleton, 1812", "number": 270}, {"title": "Creator of the Stars of Night", "sectionId": 8, "wordsCredit": "anonymous, 7th Century. Translated by John Mason Neale, 1852", "verses": ["Creator of the stars of night, Thy people's everlasting light, Jesu, Redeemer, save us all, And hear Thy servants when they call.", "Thou, grieving that the ancient curse Should doom to death a universe, Hast found the med'cine, full of grace, To save and heal a ruined race.", "Thou cam'st the Bridegroom of the bride, As drew the world to ev'ning tide; Proceeding from a virgin shrine, The spotless Victim all divine.", "At whose dread name, majestic now, All knees must bend, all hearts must bow; All things celestial Thee shall own, And things terrestrial, Lord alone.", "O Thou whose coming is with dread To judge and doom the quick and dead, Preserve us while we dwell below, From every insult of the foe.", "To God the Father, God the Son, And God the Spirit, Three in One, Laud, honor, might, and glory be, From age to age eternally."], "scriptureLinks": [{"label": "Eph 5:7-10", "chapterId": "EPH-5", "verseNumber": 7}, {"label": "Jn 1:1-4", "chapterId": "JHN-1", "verseNumber": 1}, {"label": "Gen 1:16-18", "chapterId": "GEN-1", "verseNumber": 16}], "musicCredit": "'Conditor Alme Siderum' Proper Sarum Melody", "number": 271}, {"title": "Creator of the Stars of Night", "sectionId": 8, "wordsCredit": "anonymous, 7th Century. Translated by John Mason Neale, 1852", "verses": ["Creator of the stars of night, Thy people's everlasting light, Jesu, Redeemer, save us all, And hear Thy servants when they call.", "Thou, grieving that the ancient curse Should doom to death a universe, Hast found the med'cine, full of grace, To save and heal a ruined race.", "Thou cam'st the Bridegroom of the bride, As drew the world to ev'ning tide; Proceeding from a virgin shrine, The spotless Victim all divine.", "At whose dread name, majestic now, All knees must bend, all hearts must bow; All things celestial Thee shall own, And things terrestrial, Lord alone.", "O Thou whose coming is with dread To judge and doom the quick and dead, Preserve us while we dwell below, From every insult of the foe.", "To God the Father, God the Son, And God the Spirit, Three in One, Laud, honor, might, and glory be, From age to age eternally."], "scriptureLinks": [{"label": "Eph 5:7-10", "chapterId": "EPH-5", "verseNumber": 7}, {"label": "Jn 1:1-4", "chapterId": "JHN-1", "verseNumber": 1}, {"label": "Gen 1:16-18", "chapterId": "GEN-1", "verseNumber": 16}], "musicCredit": "'Conditor Alme Siderum (stylized)' Proper Sarum Melody", "number": 272}, {"title": "Did You Think To Pray?", "sectionId": 8, "wordsCredit": "Mary A. Pepper Kidder, 1876", "verses": ["Ere you left your room this morning, Did you think to pray? In the name of Christ our Savior, Did you sue for loving favor, As a shield today?", "When you met with great temptation, Did you think to pray? By His dying love and merit, Did you claim the Holy Spirit As your guide and stay?", "When your heart was filled with anger, Did you think to pray? Did you plead for grace, my brother, That you might forgive another Who had crossed your way?", "When sore trials came upon you, Did you think to pray? When your soul was bowed in sorrow, Balm of Gilead did you borrow At the gates of day?"], "scriptureLinks": [{"label": "1Thess 6:17", "chapterId": "2TH-2", "verseNumber": 5}, {"label": "Ps 5:3", "chapterId": "PSA-5", "verseNumber": 3}, {"label": "Mk 11:24-25", "chapterId": "MRK-11", "verseNumber": 24}], "musicCredit": "'Stockbridge' or 'Did You Think To Pray' William Oscar Perkins, 1876", "refrain": "O how praying rests the weary! Prayer will change the night to day; So when life seems dark and dreary, Don't forget to pray.", "number": 273}, {"title": "Evening and Morning", "sectionId": 8, "wordsCredit": "Paul Gerhardt, 1666. Translated by Richard Massie, 1854", "verses": ["Evening and morning, Sunset and dawning, Wealth, peace, and gladness, Comfort in sadness, These are Thy works; all the glory be Thine! Times without number, Awake or in slumber, Thine eye observes us, From danger preserves us, Causing Thy mercy upon us to shine.", "Golden and glorious, Strong and victorious All joy and gladness, Scattering sadness, Rises the sun with his lifegiving rays; Still as the dying, My members were lying, but now upspringing, With joy I am singing, Gazing around me with wonder and praise.", "Mine eye surveyeth What God displayeth Of His great glory Spread out before me, Teaching how great are His wisdom and might; To His saints showing The home where they're going, Peacefully quitting When God sees it fitting, Earth's closing scenes, as they fade from their sight.", "Let us all singing, And to God bringing Our choicest treasure, To do Him pleasure, Offer a sacrifice sweeter than lambs. Heartfelt contrition, And cheerful submission, Songs of thanksgiving, And fruits of good living Please Him far better than incense of rams.", "All here is dying, Groaning and sighing; God does not alter, Nor His Word falter; Built like His will, on immutable ground, His love remaineth, His grace never waneth, Soothing and healing The pains we are feeling, Keeping us now and eternally sound.", "Father, O hear me: Pardon and spare me; Calm all my terrors, Blot out my errors, That by Thine eyes they may no more be scanned. Order my goings; Direct all my doings; As it may please Thee, Retain or release me; All I Commit to Thy Fatherly hand.", "Wilt Thou to try me, With all supply me, Nature requireth, Or heart desireth, Whisper this counsel of love in my breast, \"God is the greatest, The fairest, the sweetest, God is the purest, The truest, the surest, And of all treasures the noblest and best.\"", "Or should Thou give me, Wormwood to grieve me Griefs to distress me, Burdens to press me, Welcome whatever Thy Word hath decreed. My kind Physician Knows well my condition, That which will hurt me, Or heal and convert me, God will not chasten us more than we need.", "Griefs of God's sending, All have an ending; Clouds may be pouring, Wind and wave roaring, Sunshine will come when the tempest has past: Joys still increasing, And peace never ceasing, Faith lost in vision, Hope in fruition, These are the joys which I look for at last."], "scriptureLinks": [{"label": "Is 45:2-8", "chapterId": "ISA-45", "verseNumber": 2}, {"label": "Gen 1:5", "chapterId": "GEN-1", "verseNumber": 5}, {"label": "Gen 8:22", "chapterId": "GEN-8", "verseNumber": 22}], "altTitle": "Golden and Glorious or The Golden Sun or The Golden Morning", "musicCredit": "'Die Güldne Sonne' or 'Franconia (Ebeling)' or 'Philippi' Johann Georg Ebeling, 1660", "number": 274}, {"title": "Every Morning Mercies New", "sectionId": 8, "wordsCredit": "Greville Phillimore, 1863", "verses": ["Ev'ry morning mercies new Fall as fresh as morning dew; Ev'ry morning let us pay Tribute with the early day: For Thy mercies, Lord, are sure; Thy compassion doth endure.", "Still the greatness of Thy love Daily doth our sins remove; Daily, far as east from west, Lifts the burden from the breast; Gives unbought to those who pray Strength to stand in evil day.", "Let our prayers each morn prevail, That these gifts may never fail; And, as we confess the sin And the tempter's pow'r within, Feed us with the Bread of Life, Fit us for our daily strife.", "As the morning light returns, As the sun with splendor burns, Teach us still to turn to Thee, Ever blessed Trinity, With our hands our hearts to raise, In unfailing prayer and praise."], "scriptureLinks": [{"label": "Lam 3:22-23", "chapterId": "LAM-3", "verseNumber": 22}, {"label": "Ps 30:4-5", "chapterId": "PSA-30", "verseNumber": 4}, {"label": "103:8-13", "chapterId": "PSA-103", "verseNumber": 8}], "musicCredit": "'Kelso' or 'Every Morning' Edward J. Hopkins, 1872", "number": 275}, {"title": "Far, Far Away On Judea's Plains", "sectionId": 8, "wordsCredit": "John M. MacFarlane, 1869", "verses": ["Far, far away on Judea's plains, Shepherds of old heard the joyous strains: Glory to God, glory to God, Glory to God in the highest; Peace on earth, good will to men; Peace on earth, good will to men.", "Sweet are these strains of redeeming love, Message of mercy from heaven above: Glory to God, glory to God, Glory to God in the highest; Peace on earth, good will to men; Peace on earth, good will to men.", "Lord, with the angels we too would rejoice; Help us to sing with the heart and voice: Glory to God, glory to God, Glory to God in the highest; Peace on earth, good will to men; Peace on earth, good will to men.", "Hasten the time when, from every clime, Men shall unite in the strains sublime: Glory to God, glory to God, Glory to God in the highest; Peace on earth, good will to men; Peace on earth, good will to men."], "scriptureLinks": [{"label": "Lk 2:8-15", "chapterId": "LUK-2", "verseNumber": 8}, {"label": "Col 1:19-20", "chapterId": "COL-1", "verseNumber": 19}], "musicCredit": "John M. MacFarlane, 1869", "number": 276}, {"title": "From God Shall Naught Divide Me", "sectionId": 8, "wordsCredit": "Ludwig Helmbold, 1563. Translated by Catherine Winkworth, 1863", "verses": ["From God shall naught divide me, For He is true for aye, And on my path will guide me, Who else should often stray; His ever bounteous hand By night and day is heedful And gives me what is needful, Where'er I go or stand.", "If sorrow comes, He sent it In Him I put my trust; I never shall repent it, For He is true and just, And loves to bless us still; My life and soul I owe them To Him who doth bestow them, Let Him do as He will.", "Whate'er shall be His pleasure Is surely best for me; He gave His dearest treasure, That our weak hearts might see How good His will toward us; And in His Son He gave us Whate'er could bless and save us; Praise Him who loveth thus!", "O praise Him, for He never Forgets our daily need; O blest the hour whenever To Him our thoughts can speed; Yea, all the time we spend Without Him is but wasted, Till we His joy have tasted, The joy that hath no end.", "For when the world is passing With all its pomp and pride, All we were here amassing No longer may abide; But in our earthly bed, Where softly we are sleeping, God hath us in His keeping, To wake us from the dead.", "Then, though on earth I suffer Much trial, well I know I merit ways still rougher; And 'tis to heav'n I go; For Christ I know and love, To Him I now am hasting, And gladness everlasting With Him my heart shall prove.", "For such His will who made us; The Father seeks our good; The Son hath grace to aid us, And save us by His blood; His Spirit rules our ways, By faith in us abiding, To heav'n our footsteps guiding; To Him be thanks and praise."], "scriptureLinks": [{"label": "Rom 8:35-39", "chapterId": "ROM-8", "verseNumber": 35}, {"label": "Jn 3:16", "chapterId": "JHN-3", "verseNumber": 16}, {"label": "Eph 2:4-10", "chapterId": "EPH-2", "verseNumber": 4}], "altTitle": "From God Can Nothing Move Me", "musicCredit": "'Von Gott Will Ich Nicht Lassen' from Recueil de plusieurs chansons, 1557. Sometimes mislabeled as German, 1571", "number": 277}, {"title": "Gentle Mary Laid Her Child", "sectionId": 8, "wordsCredit": "Joseph S. Cook, 1919", "verses": ["Gentle Mary laid her Child lowly in a manger; There He lay, the undefiled, to the world a Stranger: Such a Babe in such a place, can He be the Savior? Ask the saved of all the race who have found His favor.", "Angels sang about His birth; wise men sought and found Him; Heaven's star shone brightly forth, glory all around Him: Shepherds saw the wondrous sight, heard the angels singing; All the plains were lit that night, all the hills were ringing.", "Gentle Mary laid her Child lowly in a manger; He is still the undefiled, but no more a stranger: Son of God, of humble birth, beautiful the story; Praise His Name in all the earth, hail the King of glory!"], "scriptureLinks": [{"label": "Lk 2:1-20", "chapterId": "LUK-2", "verseNumber": 1}, {"label": "Phil 2:5-11", "chapterId": "PHP-2", "verseNumber": 5}, {"label": "1 Jn 3:5", "chapterId": "1JN-3", "verseNumber": 5}], "musicCredit": "'Tempus Adest Floridum' 13th Century spring carol; first published in the Swedish Piae Cantones, 1582", "number": 278}, {"title": "God Bless Our Native Land", "sectionId": 8, "wordsCredit": "Siegfried August Mahlmann, 1815. Translated by Charles Timothy Brooks, 1833 and John Sullivan Dwight, 1844", "verses": ["God bless our native land! Firm may she ever stand Through storm and night; When the wild tempests rave, Ruler of wind and wave, Do Thou our country save By Thy great might.", "For her our prayer shall rise To God above the skies; On Him we wait; Thou who art ever nigh, Guarding with watchful eye, To Thee aloud we cry, God save the state!"], "scriptureLinks": [{"label": "Rom 13:1-7", "chapterId": "ROM-13", "verseNumber": 1}, {"label": "Ps 144:15", "chapterId": "PSA-144", "verseNumber": 15}, {"label": "1Tim 2:1-4", "chapterId": "1TI-2", "verseNumber": 1}], "musicCredit": "'America' or 'National Hymn' from Harmonia Anglicana, 1742", "number": 279}, {"title": "God Rest Ye Merry Gentlemen", "sectionId": 8, "wordsCredit": "Traditional English", "verses": ["God rest ye merry, gentlemen, let nothing you dismay, Remember Christ our Savior was born on Christmas Day; To save us all from Satan's pow'r when we were gone astray. O tidings of comfort and joy, comfort and joy; O tidings of comfort and joy.", "In Bethlehem, in Israel, this blessèd Babe was born, And laid within a manger upon this blessèd morn; The which His mother Mary did nothing take in scorn. O tidings of comfort and joy, comfort and joy; O tidings of comfort and joy.", "From God our heav'nly Father a blessèd angel came; And unto certain shepherds brought tidings of the same; How that in Bethlehem was born the Son of God by name. O tidings of comfort and joy, comfort and joy; O tidings of comfort and joy.", "\"Fear not, then,\" said the angel, \"Let nothing you afright This day is born a Savior of a pure Virgin bright, To free all those who trust in Him from Satan's pow'r and might.\" O tidings of comfort and joy, comfort and joy; O tidings of comfort and joy.", "The shepherds at those tidings rejoiced much in mind, And left their flocks afeeding in tempest, storm and wind, And went to Bethl'em straightaway this blessèd Babe to find. O tidings of comfort and joy, comfort and joy; O tidings of comfort and joy.", "But when to Bethlehem they came where our dear Savior lay, They found Him in a manger where oxen feed on hay; His mother Mary kneeling unto the Lord did pray.", "Now to the Lord sing praises all you within this place, And with true love and brotherhood each other now embrace; This holy tide of Christmas all others doth deface.", "God bless the ruler of this house, and send him long to reign, And many a merry Christmas may live to see again; Among your friends and kindred that live both far and near That God send you a happy new year, happy new year, And God send you a happy new year."], "scriptureLinks": [{"label": "Lk 2:10-11", "chapterId": "LUK-2", "verseNumber": 10}, {"label": "Ps 46:10", "chapterId": "PSA-46", "verseNumber": 10}], "musicCredit": "'God Rest Ye Merry Gentlemen' Traditional English", "number": 280}, {"title": "Hark! The Herald Angels Sing", "sectionId": 8, "wordsCredit": "Charles Wesley, 1739, alt", "verses": ["Hark! The herald angels sing, \"Glory to the newborn King; Peace on earth, and mercy mild, God and sinners reconciled!\" Joyful, all ye nations rise, Join the triumph of the skies; With th'angelic host proclaim, \"Christ is born in Bethlehem!\"", "Christ, by highest Heav'n adored; Christ the everlasting Lord; Late in time, behold Him come, Offspring of a virgin's womb. Veiled in flesh the Godhead see; Hail th'incarnate Deity, Pleased with us in flesh to dwell, Jesus our Emmanuel.", "Hail the heav'nly Prince of Peace! Hail the Sun of Righteousness! Light and life to all He brings, Ris'n with healing in His wings. Mild He lays His glory by, Born that man no more may die. Born to raise the sons of earth, Born to give them second birth.", "Come, Desire of nations, come, Fix in us Thy humble home; Rise, the woman's conqu'ring Seed, Bruise in us the serpent's head. Now display Thy saving power, Ruined nature now restore; Now in mystic union join Thine to ours, and ours to Thine.", "Adam's likeness, Lord, efface, Stamp Thine image in its place: Second Adam from above, Reinstate us in Thy love. Let us Thee, though lost, regain, Thee, the Life, the inner man: O, to all Thyself impart, Formed in each believing heart."], "scriptureLinks": [{"label": "Lk 2:13-14", "chapterId": "LUK-2", "verseNumber": 13}, {"label": "1Cor 15:21-22", "chapterId": "1CO-15", "verseNumber": 21}], "musicCredit": "'Mendelssohn' from 'Festgesang' Felix Mendelssohn, 1840", "refrain": "Hark! the herald angels sing, \"Glory to the newborn King!\"", "number": 281}, {"title": "Holy Ghost, with Light Divine", "sectionId": 8, "wordsCredit": "verses 1-6 Andrew Reed, 1817. verses 7-13 Samuel Longfellow, 1864", "verses": ["Holy Ghost, with light divine Shine upon this heart of mine; Chase the shades of night away, Turn the darkness into day.", "Let me see my Savior's face, Let me all His beauties trace; Show those glorious truths to me Which are only known to Thee.", "Holy Ghost, with pow'r divine Cleanse this guilty heart of mine; In Thy mercy pity me, From sin's bondage set me free.", "Holy Ghost, with joy divine Cheer this saddened heart of mine; Yield a sacred, settled peace, Let it grow and still increase.", "Holy Spirit, all divine, Dwell within this heart of mine; Cast down every idol— throne, Reign supreme, and reign alone.", "See, to Thee I yield my heart, Shed Thy life through every part; A pure temple I would be, Wholly dedicate to Thee.", "Holy Spirit, Truth divine, Dawn upon this soul of mine; Word of God and inward light Wake my spirit, clear my sight.", "Holy Spirit, Love divine, Glow within this heart of mine; Kindle every high desire; Perish self in Thy pure fire.", "Holy Spirit, Power divine Fill and nerve this will of mine; Grant that I may strongly live, Bravely bear, and nobly strive.", "Holy Spirit, Right divine, King within my conscience reign; Be my Lord, and I shall be Firmly bound, forever free.", "Holy Spirit, Peace divine, Still this restless heart of mine; Speak to calm this tossing sea, Stayed in Thy tranquility.", "Holy Spirit, Joy divine, Gladden Thou this heart of mine; In the desert ways I sing, \"Spring, O Well, forever spring.\"", "Now incline me to repent, Let me now my sins lament, Now my foul revolt deplore, Weep, believe, and sin no more."], "scriptureLinks": [{"label": "Jn 14:16-17", "chapterId": "JHN-14", "verseNumber": 16}, {"label": "Jn 4:24", "chapterId": "JHN-4", "verseNumber": 24}, {"label": "Acts 2:2-4", "chapterId": "ACT-2", "verseNumber": 2}], "musicCredit": "'Canterbury' or 'Song 13' Orlando Gibbons, 1623", "number": 282}, {"title": "Holy Spirit, Ever Dwelling", "sectionId": 8, "wordsCredit": "Timothy Rees, 1922", "verses": ["Holy Spirit, ever dwelling in the holiest realms of light Holy Spirit, ever brooding o'er a world of gloom and blight Holy Spirit, ever raising earthbound souls to glory high Living, life— imparting Spirit you we praise and magnify.", "Holy Spirit, ever breathing on the church the breath of life Holy Spirit, ever striving through your people's ceaseless strife Holy Spirit, ever forming in the church the mind of Christ In our worship we will praise you for your fruit and gifts unpriced.", "Holy Spirit, ever working through the church's ministry Quick'ning, strength'ning, and absolving setting captive sinners free Holy Spirit, ever binding age to age and soul to soul In community unending you we worship and extol."], "scriptureLinks": [{"label": "Gen 1:1-2", "chapterId": "GEN-1", "verseNumber": 1}, {"label": "1Cor 12:12-14", "chapterId": "1CO-12", "verseNumber": 12}, {"label": "Eph 3:7-9", "chapterId": "EPH-3", "verseNumber": 7}], "musicCredit": "'Ebenezer' or 'Ton-Y-Botel' Thomas J. Williams, 1890", "number": 283}, {"title": "Holy, Holy, Holy", "sectionId": 8, "wordsCredit": "Reginald Heber, 1826", "verses": ["Holy, holy, holy! Lord God Almighty! Early in the morning our song shall rise to Thee; Holy, holy, holy, merciful and mighty! God in three Persons, blessed Trinity!", "Holy, holy, holy! All the saints adore Thee, Casting down their golden crowns around the glassy sea; Cherubim and seraphim falling down before Thee, Who was, and is, and evermore shall be.", "Holy, holy, holy! though the darkness hide Thee, Though the eye of sinful man Thy glory may not see; Only Thou art holy; there is none beside Thee, Perfect in pow'r, in love, and purity.", "Holy, holy, holy! Lord God Almighty! All Thy works shall praise Thy Name, in earth, and sky, and sea; Holy, holy, holy; merciful and mighty! God in three Persons, blessed Trinity!"], "scriptureLinks": [{"label": "Rev 4:4-11", "chapterId": "REV-4", "verseNumber": 4}, {"label": "Is 6:3", "chapterId": "ISA-6", "verseNumber": 3}], "musicCredit": "'Nicaea' John Bacchus Dykes, 1861", "number": 284}, {"title": "I Heard The Bells On Christmas Day", "sectionId": 8, "wordsCredit": "Henry Wadsworth Longfellow, 1864", "verses": ["I heard the bells on Christmas day Their old familiar carols play, And wild and sweet the words repeat Of peace on earth, good will to men.", "And thought how, as the day had come, The belfries of all Christendom Had rolled along th'unbroken song Of peace on earth, good will to men.", "Till ringing, singing on its way The world revolved from night to day, A voice, a chime, a chant sublime Of peace on earth, good will to men.", "And in despair I bowed my head \"There is no peace on earth,\" I said, \"For hate is strong and mocks the song Of peace on earth, good will to men.\"", "Then pealed the bells more loud and deep: \"God is not dead, nor doth He sleep; The wrong shall fail, the right prevail With peace on earth, good will to men.\""], "scriptureLinks": [{"label": "Lk 2:13-14", "chapterId": "LUK-2", "verseNumber": 13}, {"label": "Is 41:13", "chapterId": "ISA-41", "verseNumber": 13}], "musicCredit": "'Waltham (Calkin)' John B. Calkin, 1872", "number": 285}, {"title": "I Sing the Mighty Power of God", "sectionId": 8, "wordsCredit": "Isaac Watts, 1709", "verses": ["I sing the mighty pow'r of God, That made the mountains rise; That spread the flowing seas abroad, And built the lofty skies. I sing the wisdom that ordained The sun to rule the day: The moon shines full at His command, And all the stars obey.", "I sing the goodness of the Lord, That filled the earth with food: He formed the creatures with His word, And then pronounced them good. Lord, how Thy wonders are displayed, Where'er I turn my eye; If I survey the ground I tread, Or gaze upon the sky.", "There's not a plant or flow'r below, But makes Thy glories known; And clouds arise and tempests blow, By order from Thy throne. Creatures that borrow life from Thee Are subject to Thy care: There's not a place where we can flee, But God is present there."], "scriptureLinks": [{"label": "Jer 10:10-13", "chapterId": "JER-10", "verseNumber": 10}, {"label": "Deut 32:3", "chapterId": "DEU-32", "verseNumber": 3}, {"label": "Ps 96:1-8", "chapterId": "PSA-96", "verseNumber": 1}], "musicCredit": "'Ellacombe' from Gesangbuch der Herzogl. Hofkapelle, Wurttemberg, 1784", "number": 286}, {"title": "In Peace and Joy I Now Depart", "sectionId": 8, "wordsCredit": "Martin Luther, 1524. Translated by Leonard Woolsey Bacon, 1884, alt", "verses": ["In peace and joy I now depart At God's disposing; For full of comfort is my heart, Soft reposing. So the Lord hath promised me, And death is but a slumber.", "'Tis Christ that wrought this work for me, My faithful Savior, Whom Thou hast made mine eyes to see By Thy favor. Now I know He is my Life, My Help in need and dying.", "Him Thou hast unto all set forth Their great Salvation And to His kingdom called the earth, Every nation, By Thy dear and wholesome Word, In every place resounding.", "He is the Hope and saving Light Of lands benighted; By Him are they who dwelt in night Fed and lighted. He is Is rael's Praise and Bliss, Their Joy, Reward, and Glory."], "scriptureLinks": [{"label": "Lk 2:29-32", "chapterId": "LUK-2", "verseNumber": 29}, {"label": "Gen 49:18", "chapterId": "GEN-49", "verseNumber": 18}, {"label": "Is 42:6-7", "chapterId": "ISA-42", "verseNumber": 6}], "altTitle": "The Song of Simeon: Nunc Dimitis", "musicCredit": "'Mit Fried und Freud ich Far Dahin' from Walter's Geistliche Gesangbüchlein, 1524", "number": 287}, {"title": "Jesus Shall Reign", "sectionId": 8, "wordsCredit": "Isaac Watts, 1719", "verses": ["Jesus shall reign where'er the sun Does his successive journeys run; His kingdom stretch from shore to shore Till moons shall wax and wane no more.", "For Him shall endless prayer be made, And praises throng to crown His head; His Name, like sweet perfume shall rise With every morning sacrifice.", "People and realms of every tongue Dwell on His love with sweetest song; And infant voices shall proclaim Their early blessings on His Name.", "Blessings abound where'er He reigns; The prisoner leaps to lose his chains, The weary find eternal rest, And all the sons of want are blest.", "Where He displays His healing power Death and the curse are known no more; In Him the tribes of Adam boast More blessings than their father lost.", "Let every creature rise and bring Peculiar honors to our King, Angels descend with songs again, And earth repeat the loud Amen."], "scriptureLinks": [{"label": "Zech 9:9-10", "chapterId": "ZEC-9", "verseNumber": 9}, {"label": "Ps 72:8", "chapterId": "PSA-72", "verseNumber": 8}, {"label": "Rev 22:3-5", "chapterId": "REV-22", "verseNumber": 3}], "musicCredit": "'Duke Street' John Hatton, 1793", "number": 288}, {"title": "Jesus, Tender Shepherd, Hear Me", "sectionId": 8, "wordsCredit": "Mary L. Duncan, 1839", "verses": ["Jesus, tender Shepherd, hear me; Bless Thy little lamb tonight; Through the darkness be Thou near me; Watch my sleep till morning light.", "All this day thy hand has led me, And I thank Thee for Thy care; Thou hast clothed me, warmed and fed me, Listen to my evening prayer.", "Let my sins be all forgiven; Bless the friends I love so well; Take me, when I die, to heaven, Happy there with Thee to dwell."], "scriptureLinks": [{"label": "Ps 63:8", "chapterId": "PSA-63", "verseNumber": 8}, {"label": "Jn 10:11", "chapterId": "JHN-10", "verseNumber": 11}], "musicCredit": "'Evening Prayer' John Stainer, 1898", "number": 289}, {"title": "Joy to the World", "sectionId": 8, "wordsCredit": "Isaac Watts, 1719", "verses": ["Joy to the world, the Lord is come! Let earth receive her King; Let ev'ry heart prepare Him room, And Heav'n and nature sing, And Heav'n and nature sing, And Heav'n, and Heav'n, and nature sing.", "Joy to the earth, the Savior reigns! Let men their songs employ; While fields and floods, rocks, hills and plains Repeat the sounding joy, Repeat the sounding joy, Repeat, repeat, the sounding joy.", "No more let sins and sorrows grow, Nor thorns infest the ground; He comes to make His blessings flow Far as the curse is found, Far as the curse is found, Far as, far as, the curse is found.", "He rules the world with truth and grace, And makes the nations prove The glories of His righteousness, And wonders of His love, And wonders of His love, And wonders, wonders, of His love."], "scriptureLinks": [{"label": "Lk 2:10", "chapterId": "LUK-2", "verseNumber": 10}, {"label": "Ps 97:1", "chapterId": "PSA-97", "verseNumber": 1}, {"label": "98:4-9", "chapterId": "PSA-98", "verseNumber": 4}], "musicCredit": "'Antioch' pieced together from \"Messiah\" George F. Handel, 1741", "number": 290}, {"title": "Like The Golden Sun Ascending", "sectionId": 8, "wordsCredit": "Thomas Hansen Kingo, 1689. Translated by George Alfred Taylor Rygh, 1908", "verses": ["Like the golden sun ascending, Breaking through the gloom of night, On the earth His glory spending So that darkness takes to flight; Thus my Jesus from the grave And death's dismal, dreadful cave, Rose triumphant Easter morning, At the early purple dawning.", "Thanks to Thee, O Christ victorious! Thanks to Thee, O Lord of life! Death has now no power o'er us, Thou hast conquered in the strife; Thanks because Thou didst arise And hast opened paradise! None can fully sing the glory Of the resurrection story.", "For my heart finds consolation, And my fainting soul grows brave, When I stand in contemplation, At Thy dark and dismal grave; When I see where Thou didst sleep In death's dungeon dark and deep, Yet didst break all bands asunder, Must I not rejoice and wonder?", "Though I be by sin o'ertaken, Though I lie in helplessness, Though I be by friends forsaken, And must suffer sore distress, Though I be despised, contemned, And by all the world condemned, Though the dark grave yawn before me, Yet the light of hope shines o'er me.", "Thou hast died for my transgression, All my sins on Thee were laid; Thou hast won for me salvation, On the cross my debt was paid; From the grave I shall arise, And shall meet Thee in the skies; Death itself is transitory, I shall lift my head in glory.", "Satan's arrows all lie broken, Death and hell have met their doom; Christ, Thy rising is the token: Thou hast triumphed o'er the tomb; Thou hast buried all my woe, And my cup doth overflow; By Thy resurrection glorious I shall wave my palms victorious.", "As the Son of God I know Thee, For I see Thy sovereign pow'r; Sin and death shall not o'erthrow me Even in my dying hour; For Thy resurrection is Surety for my heav'nly bliss, And my bapt'sm a reflection Of Thy death and resurrection", "Unto life Thou shalt arouse me By Thy resurrection's pow'r; Though the hideous grave shall house me, And my flesh the worms devour; Fire and water may destroy My frail body, yet with joy I shall rise as Thou hast risen From the deep sepulchral prison.", "Grant me grace, O blessed Savior, And Thy Holy Spirit send, That my walk and my behavior May be pleasing in the end; That I may not fall again Into death's grim pit and pain When by grace Thou hast received me, And from which Thou hast relieved me.", "For the joy Thy birth doth give me, For Thy holy, precious Word; For Thy baptism which doth save me, For Thy gracious festal board; For Thy death, the bitter scorn, For Thy resurrection morn, Lord I thank Thee and extol Thee, And in heav'n I shall behold Thee."], "scriptureLinks": [{"label": "Rom 6:1-11", "chapterId": "ROM-6", "verseNumber": 1}, {"label": "1Cor 15:42-49", "chapterId": "1CO-15", "verseNumber": 42}, {"label": "1 Pt 1:20-21", "chapterId": "1PE-1", "verseNumber": 20}], "musicCredit": "'Werde Munter' Johann Schop, 1642", "number": 291}, {"title": "Lo, How A Rose E'er Blooming", "sectionId": 8, "wordsCredit": "verses 1-2, 15th Century German. Translated by Theodore Baker, 1894. verses 3,4 Fridrich Layriz (1808-1859). Translated by Harriet Reynolds Krauth, 1875. verse 5, 15th Century German. Translated by John C. Mattes, 1914", "verses": ["Lo, how a Rose e'er blooming from tender stem hath sprung! Of Jesse's lineage coming, as men of old have sung. It came, a flow'ret bright, amid the cold of winter, When half spent was the night.", "Isaiah 'twas foretold it, the Rose I have in mind; With Mary we behold it, the virgin mother kind. To show God's love aright, she bore to men a Savior, When half spent was the night.", "The shepherds heard the story proclaimed by angels bright, How Christ, the Lord of glory was born on earth this night. To Bethlehem they sped and in the manger found Him, As angel heralds said.", "This Flow'r, whose fragrance tender with sweetness fills the air, Dispels with glorious splendor the darkness everywhere; True Man, yet very God, from sin and death He saves us, And lightens ev'ry load.", "O Savior, Child of Mary, who felt our human woe, O Savior, King of glory, who dost our weakness know; Bring us at length we pray, to the bright courts of Heaven, And to the endless day!"], "scriptureLinks": [{"label": "Is 11:1-10", "chapterId": "ISA-11", "verseNumber": 1}, {"label": "Mt 1:20-21", "chapterId": "MAT-1", "verseNumber": 20}, {"label": "Heb 2:14-15", "chapterId": "HEB-2", "verseNumber": 14}], "musicCredit": "'Es Ist Ein Ros Entsprungen (Rhythmic)' German from Köln, 1599", "number": 292}, {"title": "Lord Of Our Life", "sectionId": 8, "wordsCredit": "Matthäus Apelles von Löwenstern, 1644. Translated by Philip Pusey, 1840", "verses": ["Lord of our life, and God of our salvation, Star of our night, and Hope of every nation, Hear and receive Thy church's supplication, Lord God Almighty.", "See round Thine Ark the hungry billows curling! See how Thy foes their banners are unfurling! Lord, while their darts envenomed they are hurling, Thou canst preserve us.", "Lord, Thou canst help when earthly armor faileth; Lord, Thou canst save when sin itself assaileth; Lord, o'er Thy Rock nor death nor hell prevaileth; Grant us Thy peace, Lord.", "Peace, in our hearts, our evil thoughts assuaging, Peace, in Thy Church, where brothers are engaging, Peace, when the world its busy war is waging; Calm Thy foes raging!", "Grant us Thy help till backward they are driven; Grant them Thy Truth, that they may be forgiven; Grant peace on earth, and after we have striven, Peace in Thy Heaven."], "scriptureLinks": [{"label": "Ps 27:1-14", "chapterId": "PSA-27", "verseNumber": 1}, {"label": "3:3", "chapterId": "PSA-3", "verseNumber": 3}, {"label": "84:11", "chapterId": "PSA-84", "verseNumber": 11}], "musicCredit": "'Iste Confessor' or 'Rouen' from Poitiers Antiphoner, 1746", "number": 293}, {"title": "Now Praise We Christ, the Holy One", "sectionId": 8, "wordsCredit": "Coelius Sedulius, circa 450. Translated to German by Martin Luther, 1524. Translated from German to English by Richard Massie, 1854, alt", "verses": ["Now praise we Christ, the Holy One, The spotless virgin Mary's Son, Far as the blesséd sun doth shine E'en to the world's remote confine", "He, who Himself all things did make, A servant's form vouchsafed to take, That He as man mankind might win, And save His creatures from their sin.", "The grace of God, th'Almighty Lord, On the chaste mother was outpoured a virgin pure and undefiled In wondrous wise conceived a child.", "The holy maid became th'abode And temple of the living God; And she, who knew not man, was blest With God's own Word made manifest.", "The noble mother bare a Son, For so did Gabriel's promise run, Whom John confessed and leapt with joy, Ere yet the mother knew her boy.", "In a rude manger, stretched on hay, In poverty content He lay; With milk was fed the Lord of all, Who feeds the ravens when they call.", "Th' angelic choir rejoice, and raise Their voice to God in songs of praise; To humble shepherds is proclaimed The Shepherd who the world hath framed.", "Honor to Thee, O Christ, be paid, Pure offspring of a holy maid, With Father and with Holy Ghost, Till time in time's abyss be lost."], "scriptureLinks": [{"label": "Lk 1:26-31", "chapterId": "LUK-1", "verseNumber": 26}, {"label": "2:7-11", "chapterId": "LUK-2", "verseNumber": 7}, {"label": "Ps 95:1-6", "chapterId": "PSA-95", "verseNumber": 1}], "altTitle": "Jesus We Now Must Laud and Sing or From East to West", "musicCredit": "'Christum Wir Sollen Loben Schon' ancient Latin found in Erfurt Enchiridion, 1524", "number": 294}, {"title": "O Blessed Jesus This", "sectionId": 8, "wordsCredit": "Paul Gerhardt, 1656. Translated by Catherine Winkworth, 1863", "verses": ["O blessed Jesus, This Thy lowly manger is The Paradise where oft my soul would feed: Here is the place, my Lord, Where lies th'Eternal Word Clothed with our flesh, made like to us indeed.", "For He whose mighty sway The winds and seas obey, Submits to serve, and stoops to those who sin; The glorious Son of God Doth bear the mortal load Of earth and dust, like us and all our kin.", "For thus, O Good Supreme, Wilt Thou our flesh redeem, And raise it to Thy throne o'er every height: Eternal Strength, here Thou To brotherhood dost bow With transient things that pass like mists of night.", "Thy glory and Thy joy All woe and grief destroy; Thou, Heav'nly Treasure, dost all wealth restore! Thou deep and living Well! Thou great Immanuel Dost conquer sin and death for evermore!", "Then come, whoe'er thou art, O poor desponding heart, Take courage now, let this thy fears dispel, That since His Son most dear Thy God hath giv'n thee here, It cannot be but God doth love thee well.", "How often dost thou think That thou must surely sink, That hope and comfort are no more for thee; Come hither then and gaze Upon this Infant's face, And here the love of God incarnate see.", "Ah now the blessed door Stands open evermore To all the joys of this world and the next: This Babe will be our Friend, And quickly make an end Of all that faithful hearts long time hath vex'd.", "Then, earth, we care no more To seek thy richest store, If but this treasure will be still our own; And he who holds it fast, Till all this life is past, Our Lord will crown with joy before His throne."], "scriptureLinks": [{"label": "Gal 4:4-7", "chapterId": "GAL-4", "verseNumber": 4}, {"label": "Jn 1:14", "chapterId": "JHN-1", "verseNumber": 14}, {"label": "Phil 2:5-11", "chapterId": "PHP-2", "verseNumber": 5}], "altTitle": "O Jesus Christ, Thy Manger Is", "musicCredit": "'Down Ampney' Ralph Vaughan Williams, 1906", "number": 295}, {"title": "O Chief of Cities Bethlehem", "sectionId": 8, "wordsCredit": "Aurelius Clemens Prudentius (348-413). v. 1,2,4 Translated by N. B. Smithers, 1879,v. 3 Translated by C. W. Douglas, v.5 Translated by John, Marquess of Bute c. 1879", "verses": ["O chief of cities, Bethlehem, Of David's crown the fairest gem, But more to us than David's name, In you, as man, the Savior came.", "Beyond the sun in splendor bright, Above you stands a wondrous light Proclaiming from the conscious skies That here, in flesh, the Godhead lies.", "The wise men, seeing Him so fair, Bow low before Him, and with prayer Their treasured eastern gifts unfold Of incense, myrrh, and royal gold.", "The golden tribute owns Him King, But frankincense to God they bring, And last, prophetic sign, with myrrh, They shadow forth His sepulcher.", "O Jesus, whom the Gentiles see, With Father, Spirit, One in Three: To You, O God, be glory giv'n By saints on earth and saints in Heav'n."], "scriptureLinks": [{"label": "Mt 2:1-11", "chapterId": "MAT-2", "verseNumber": 1}, {"label": "Mic 5:2-4", "chapterId": "MIC-5", "verseNumber": 2}], "musicCredit": "'Puer Nobis Nascitur' Michael Praetorius, 1609", "number": 296}, {"title": "O Come, All Ye Faithful", "sectionId": 8, "wordsCredit": "John F. Wade, circa 1743. v.1-3, 6 Translated by Frederick Oakeley, 1841;v. 4, 5 Translated by William T. Brooke (1848-1917)", "verses": ["O come, all ye faithful, joyful and triumphant, O come ye, O come ye, to Bethlehem. Come and behold Him, born the King of angels; O come, let us adore Him, O come, let us adore Him, O come, let us adore Him, Christ the Lord.", "True God of true God, Light from Light Eternal, Lo, He shuns not the Virgin's womb; Son of the Father, begotten, not created; O come, let us adore Him, O come, let us adore Him, O come, let us adore Him, Christ the Lord.", "Sing, choirs of angels, sing in exultation; O sing, all ye citizens of heav'n above! Glory to God, glory in the highest; O come, let us adore Him, O come, let us adore Him, O come, let us adore Him, Christ the Lord.", "See how the shepherds, summoned to His cradle, Leaving their flocks, draw nigh to gaze; We too will thither bend our joyful footsteps; O come, let us adore Him, O come, let us adore Him, O come, let us adore Him, Christ the Lord.", "Lo! star led chieftains, Magi, Christ adoring, Offer Him incense, gold, and myrrh; We to the Christ Child bring our hearts' oblations. O come, let us adore Him, O come, let us adore Him, O come, let us adore Him, Christ the Lord.", "Child, for us sinners poor and in the manger, We would embrace Thee, with love and awe; Who would not love Thee, loving us so dearly?", "Yea, Lord, we greet Thee, born this happy morning; Jesus, to Thee be glory given; Word of the Father, now in flesh appearing.", "Adeste, fideles, laeti triumphantes; Venite, venite in Bethlehem. Natum videte Regem angelorum. Venite adoremus, venite adoremus, Venite adoremus, Dominum."], "scriptureLinks": [{"label": "Lk 2:15-16", "chapterId": "LUK-2", "verseNumber": 15}], "musicCredit": "'Adeste Fideles' or 'Portuguese Hymn' John F. Wade, 1743", "number": 297}, {"title": "O Holy Night (Soprano or Tenor with Accompaniment)", "sectionId": 8, "wordsCredit": "Placide Cappea, 1847. Translated, paraphrased, and modified by John Sullivan Dwight, 1855, alt", "verses": ["O holy night! the stars are brightly shining, It is the night of the dear Savior's birth. Long lay the world in sin and error pining, Till He appeared, and the soul felt its worth. A thrill of hope the weary world rejoices, For yonder breaks a new and glorious morn. Fall on your knees! O hear the angel voices! O night divine! O night when Christ was born! O night divine! O night, O night divine!", "Led by the light of faith serenely beaming, with glowing hearts by His cradle we stand; So, led by light of star so sweetly gleaming, The wise men come bringing gifts from the east. The King of kings lay thus in lowly manger, In all our trials born to be our Friend. He knows our need, To our weakness no stranger; Behold your King! your King before Him bend! O night divine! O night, O night divine!", "Truly He taught us to love one another; His law is love, and His gospel is peace. Chains shall He break, for the slave is our brother, And in His Name all oppression shall cease, Sweet hymns of joy a joyful chorus raise we; Let all within us praise His Holy Name; Christ is the Lord; Then ever ever praise we; His pow'r and glory evermore proclaim! O night divine! O night, O night divine!", "Note that this arrangement can be performed if needed without any of Alto, Tenor, or Bass. The Soprano can be replaced by a Tenor if needed (singing the Soprano part an octave lower)."], "scriptureLinks": [{"label": "Lk 2:9-11", "chapterId": "LUK-2", "verseNumber": 9}, {"label": "Is 61:1", "chapterId": "ISA-61", "verseNumber": 1}], "musicCredit": "'Cantique de Noël' or 'Minuit, Chrétiens!' Adolphe Adam, 1847", "number": 298}, {"title": "O Holy Night (Soprano or Tenor with Piano Doubling)", "sectionId": 8, "wordsCredit": "Placide Cappea, 1847. Translated, paraphrased, and modified by John Sullivan Dwight, 1855, alt", "verses": ["O holy night! the stars are brightly shining, It is the night of the dear Savior's birth. Long lay the world in sin and error pining, Till He appeared, and the soul felt its worth. A thrill of hope the weary world rejoices, For yonder breaks a new and glorious morn. Fall on your knees! O hear the angel voices! O night divine! O night when Christ was born!", "Led by the light of faith serenely beaming, with glowing hearts by His cradle we stand; So, led by light of star so sweetly gleaming, The wise men come bringing gifts from the east. The King of kings lay thus in lowly manger, In all our trials born to be our Friend. He knows our need, To our weakness no stranger; Behold your King! Your King before Him bend!", "Truly He taught us to love one another; His law is love, and His gospel is peace. Chains shall He break, for the slave is our brother, And in His Name all oppression shall cease, Sweet hymns of joy a joyful chorus raise we; Let all within us praise His Holy Name; Christ is the Lord; Then ever ever praise we; His pow'r and glory evermore proclaim!"], "scriptureLinks": [{"label": "Lk 2:9-11", "chapterId": "LUK-2", "verseNumber": 9}, {"label": "Is 61:1", "chapterId": "ISA-61", "verseNumber": 1}], "musicCredit": "'Cantique de Noël' or 'Minuit, Chrétiens!' Adolphe Adam, 1847", "refrain": "O night divine! O night, O night divine!", "number": 299}, {"title": "O Little Town of Bethlehem", "sectionId": 8, "wordsCredit": "Phillips Brooks, 1867", "verses": ["O little town of Bethlehem, how still we see thee lie! Above thy deep and dreamless sleep the silent stars go by. Yet in thy dark streets shineth the everlasting Light; The hopes and fears of all the years are met in thee tonight.", "For Christ is born of Mary, and gathered all above, While mortals sleep, the angels keep their watch of wond'ring love. O morning stars together, proclaim the holy birth, And praises sing to God the King, and peace to men on earth!", "How silently, how silently, the wondrous Gift is giv'n; So God imparts to human hearts the blessings of His Heav'n. No ear may hear His coming, but in this world of sin, Where meek souls will receive Him still, the dear Christ enters in.", "Where children pure and happy pray to the blessèd Child, Where misery cries out to Thee, Son of the mother mild; Where charity stands watching and faith holds wide the door, The dark night wakes, the glory breaks, and Christmas comes once more.", "O holy Child of Bethlehem, descend to us, we pray; Cast out our sin, and enter in, be born in us today. We hear the Christmas angels the great glad tidings tell; O come to us, abide with us, our Lord Emmanuel!"], "scriptureLinks": [{"label": "Mic 5:2", "chapterId": "MIC-5", "verseNumber": 2}, {"label": "Lk 2:4-16", "chapterId": "LUK-2", "verseNumber": 4}], "musicCredit": "'St. Louis' Lewis H. Redner, 1868", "number": 300}, {"title": "O Trinity of Blessed Light", "sectionId": 8, "wordsCredit": "Ambrose of Milan, 4th Century. German version by M. Luther, 1543. English translation by John Mason Neale, 1852", "verses": ["O Trinity of blessèd light, O Unity of princely might, The fiery sun now goes his way; Shed Thou within our hearts a ray.", "To Thee our morning song of praise, To Thee our evening prayer we raise; O grant us with Thy saints on high To praise Thee through eternity.", "All laud to God the Father be, All praise, eternal Son, to Thee, All glory, as is ever meet, To God the holy Paraclete."], "scriptureLinks": [{"label": "Gen 1:3", "chapterId": "GEN-1", "verseNumber": 3}, {"label": "1 Jn 1:5-7", "chapterId": "1JN-1", "verseNumber": 5}, {"label": "2Cor 4:6", "chapterId": "2CO-4", "verseNumber": 6}], "altTitle": "Thou Who Art Three in Unity", "musicCredit": "'O Lux Beata Trinitas' ancient Latin", "number": 301}, {"title": "O Wondrous Type, O Vision Fair", "sectionId": 8, "wordsCredit": "From the \"Sarum Breviary\", 1495. Translated by John Mason Neale, 1851", "verses": ["O wondrous type! O vision fair Of glory that the Church may share, Which Christ upon the mountain shows, where brighter than the sun He glows!", "From age to age the tale declare, How with the three disciples there, Where Moses and Elijah meet, The Lord holds converse high and sweet.", "The law and prophets there have place, Two chosen witnesses of grace; The Father's voice from out the cloud proclaims His only Son aloud.", "With shining face and bright array, Christ deigns to manifest today What glory shall be theirs above who joy in God with perfect love.", "And faithful hearts are raised on high by this great vision's mystery; For which in joyful strains we raise the voice of prayer, the hymn of praise.", "O Father, with th'Eternal Son, and Holy Spirit, ever One, Vouchsafe to bring us by Thy grace to see Thy glory face to face."], "scriptureLinks": [{"label": "Mk 9:2-13", "chapterId": "MRK-9", "verseNumber": 2}, {"label": "Mt 17:1-13", "chapterId": "MAT-17", "verseNumber": 1}, {"label": "Lk 9:28-36", "chapterId": "LUK-9", "verseNumber": 28}], "musicCredit": "'Deo Gracias' or 'Agincourt' traditional English, circa 1415", "number": 302}, {"title": "Praise God From Whom All Blessings Flow (Doxology; see also 'Awake, My Soul, And With The Sun')", "sectionId": 8, "wordsCredit": "Thomas Ken, 1674", "verses": ["Praise God, from Whom all blessings flow; Praise Him, all creatures here below; Praise Him above, ye heav'nly host; Praise Father, Son, and Holy Ghost."], "scriptureLinks": [{"label": "Rom 13:11", "chapterId": "ROM-13", "verseNumber": 11}, {"label": "Ps 17:15", "chapterId": "PSA-17", "verseNumber": 15}, {"label": "Ps 148:1-2", "chapterId": "PSA-148", "verseNumber": 1}], "musicCredit": "'Old 100th' Genevan Psalter, attr. Louis Bourgeois, c. 1551", "number": 303}, {"title": "See Amid the Winter's Snow", "sectionId": 8, "wordsCredit": "Edward Caswall, 1851", "verses": ["See amid the winter's snow, Born for us on earth below, See, the gentle Lamb appears, Promised from eternal years. Hail that ever blessèd morn, Hail redemption's happy dawn, Sing through all Jerusalem: Christ is born in Bethlehem.", "Lo, within a manger lies He Who built the starry skies; He Who, thronèd in height sublime, Sits amid the cherubim. Hail that ever blessèd morn, Hail redemption's happy dawn, Sing through all Jerusalem: Christ is born in Bethlehem.", "Say, you holy shepherds, say, Tell your joyful news today. Why have you now left your sheep On the lonely mountain steep? Hail that ever blessèd morn, Hail redemption's happy dawn, Sing through all Jerusalem: Christ is born in Bethlehem.", "\"As we watched at dead of night, Lo, we saw a wondrous light; Angels singing 'Peace on earth' Told us of the Savior's birth.\" Hail that ever blessèd morn, Hail redemption's happy dawn, Sing through all Jerusalem: Christ is born in Bethlehem.", "Sacred Infant, all divine, What a tender love was Thine, Thus to come from highest bliss Down to such a world as this. Hail that ever blessèd morn, Hail redemption's happy dawn, Sing through all Jerusalem: Christ is born in Bethlehem.", "Teach, O teach us, holy Child, By Thy face so meek and mild, Teach us to resemble Thee, In Thy sweet humility."], "scriptureLinks": [{"label": "Lk 2:1-20", "chapterId": "LUK-2", "verseNumber": 1}, {"label": "Jn 1:29", "chapterId": "JHN-1", "verseNumber": 29}, {"label": "Phil 2:3-8", "chapterId": "PHP-2", "verseNumber": 3}], "musicCredit": "'Humility' John Goss, 1870", "number": 304}, {"title": "Songs of Thankfulness and Praise", "sectionId": 8, "wordsCredit": "Christopher Wordsworth, 1862", "verses": ["Songs of thankfulness and praise, Jesus, Lord, to Thee we raise, Manifested by the star To the sages from afar; Branch of royal David's stem In Thy birth at Bethlehem; Anthems be to Thee addressed, God in man made manifest.", "Manifest at Jordan's stream, Prophet, Priest, and King supreme; And at Cana, wedding guest, In Thy Godhead manifest; Manifest in pow'r divine, Changing water into wine; Anthems be to Thee addressed, God in man made manifest.", "Manifest in making whole Palsied limbs and fainting soul; Manifest in valiant fight, Quelling all the devil's might; Manifest in gracious will, Ever bringing good from ill; Anthems be to Thee addressed, God in man made manifest.", "Sun and moon shall darkened be, Stars shall fall, the heav'ns shall flee, Christ will then like lightning shine, All will see His glorious sign: All will then the trumpet hear; All will see the Judge appear; Thou by all wilt be confessed, God in man made manifest.", "Grant us grace to see Thee, Lord, Mirrored in Thy holy Word; May we imitate Thee now, And be pure, as pure art Thou; That we like to Thee may be At Thy great Epiphany; And may praise Thee, ever blest, God in man made manifest."], "scriptureLinks": [{"label": "Ps 95:2", "chapterId": "PSA-95", "verseNumber": 2}, {"label": "Is 61:1-3", "chapterId": "ISA-61", "verseNumber": 1}, {"label": "1 Pt 1:20", "chapterId": "1PE-1", "verseNumber": 20}], "musicCredit": "'St. George`s Windsor', George Job Elvey, 1858", "number": 305}, {"title": "The First Noel", "sectionId": 8, "wordsCredit": "Traditional English carol, possibly dating from as early as the 13th Century", "verses": ["The first Noel the angel did say Was to certain poor shepherds in fields as they lay; In fields where they lay tending their sheep, On a cold winter's night that was so deep.", "They lookèd up and saw a star Shining in the east, beyond them far; And to the earth it gave great light, And so it continued both day and night.", "And by the light of that same star Three Wise Men came from country far; To seek for a King was their intent, And to follow the star wherever it went.", "This star drew nigh to the northwest, Over Bethlehem it took its rest; And there it did both stop and stay, Right over the place where Jesus lay.", "Then did they know assuredly Within that house the King did lie; One entered it them for to see, And found the Babe in poverty."], "scriptureLinks": [{"label": "Lk 2:8-9", "chapterId": "LUK-2", "verseNumber": 8}], "musicCredit": "'The First Noel' Traditional English carol, possibly dating from as early as the 13th Century", "refrain": "Noel, Noel, Noel, Noel, Born is the King of Israel.", "number": 306}, {"title": "The Galilean Fishers Toil", "sectionId": 8, "wordsCredit": "Christopher Wordsworth, 1865, alt", "verses": ["The Galilean fishers toil all night, and nothing take; But Jesus comes,— a wondrous spoil is lifted from the lake. Lord, when our labors are in vain and vain the help of men, When fruitless is our care and pain, Come blessed Jesus then!", "The night is dark, the surges fill the bark, the wild winds roar; But Jesus comes and all is still,— the ship is at the shore. O Lord, when storms around us howl, and all is dark and drear, In all the tempests of the soul, O blessed Jesus hear.", "A frail one, thrice denying Thee saw mercy in Thine eyes, The penitent upon the tree was borne to Paradise. In hours of sin and deep distress o show us, Lord, Thy Face, In penitential loneliness, O give us Jesus grace!", "The faithful few retire in fear to their closed upper room; But suddenly with joyful cheer they see their Master come. Lord come to us, unloose our bands and bid our terrors cease, Lift over us Thy blessed hands, Speak, holy Jesus Peace!", "In days, when faith will scarce be found, and wolves be in the fold, When sin and sorrow will abound and charity wax cold, Then hear Thy saints, who to Thee pray to bring them to their home, Hear when the Bride and Spirit say, \"Come, Blessed Jesus, Come!\""], "scriptureLinks": [{"label": "Lk 5:1-11", "chapterId": "LUK-5", "verseNumber": 1}, {"label": "23:39-43", "chapterId": "LUK-23", "verseNumber": 39}, {"label": "18:8", "chapterId": "LUK-18", "verseNumber": 8}], "altTitle": "Come Blessed Jesu Come", "musicCredit": "'Old 137th' or 'Norwich' from Day's Psalter, 1563", "number": 307}, {"title": "The King Shall Come", "sectionId": 8, "wordsCredit": "Unknown author. Translated by John Brownlie, 1907", "verses": ["The King shall come when morning dawns, And light triumphant breaks; When beauty gilds the eastern hills, And life to joy awakes.", "Not as of old a little child To bear, and fight, and die, But crowned with glory like the sun That lights the morning sky.", "O brighter than the rising morn When He, victorious, rose, And left the lonesome place of death, Despite the rage of foes.", "O brighter than that glorious morn Shall this fair morning be, When Christ, our King, in beauty comes, And we His face shall see.", "The King shall come when morning dawns, And earth's dark night is past; O haste the rising of that morn, The day that aye shall last.", "And let the endless bliss begin, By weary saints foretold, When right shall triumph over wrong, And truth shall be extolled.", "The King shall come when morning dawns, And light and beauty brings: Hail, Christ the Lord! Thy people pray, Come quickly, King of kings."], "scriptureLinks": [{"label": "Zeph 1:14", "chapterId": "ZEP-1", "verseNumber": 14}, {"label": "Rev 22:20", "chapterId": "REV-22", "verseNumber": 20}], "musicCredit": "'Consolation' or 'Morning Song' John Wyeth, 1813", "number": 308}, {"title": "Through the Night of Doubt and Sorrow", "sectionId": 8, "wordsCredit": "Bernhardt S. Ingemann, 1826. Translated by Sabine Baring-Gould, 1867", "verses": ["Through the night of doubt and sorrow Onward goes the pilgrim band, Singing songs of expectation, Marching to the Promised Land. Clear before us through the darkness Gleams and burns the guiding light: Brother clasps the hand of brother, Stepping fearless through the night.", "One the light of God's own presence, O'er His ransomed people shed, Chasing far the gloom and terror, Bright'ning all the path we tread: One the object of our journey, One the faith which never tires, One the earnest looking forward, One the hope our God inspires.", "One the strain that lips of thousands Lift as from the heart of one; One the conflict, one the peril One the march in God begun: One the gladness of rejoicing On the far eternal shore, Where the One Almighty Father Reigns in love for evermore.", "Onward, therefore, pilgrim brothers, Onward, with the cross our aid! Bear its shame, and fight its battle, Till we rest beneath its shade. Soon shall come the great awaking, Soon the rending of the tomb; Then the scatt'ring of all shadows, And the end of toil and gloom."], "scriptureLinks": [{"label": "Heb 11:13-16", "chapterId": "HEB-11", "verseNumber": 13}, {"label": "2Cor 5:1-10", "chapterId": "2CO-5", "verseNumber": 1}, {"label": "Rev 22:5", "chapterId": "REV-22", "verseNumber": 5}], "musicCredit": "'Rex Gloriae' Henry Thomas Smart, 1868", "number": 309}, {"title": "Tis Good, Lord, To Be Here", "sectionId": 8, "wordsCredit": "Joseph Armitage Robinson, 1888", "verses": ["'Tis good, Lord, to be here, Thy glory fills the night; Thy face and garments, like the sun, Shine with unborrowed light.", "'Tis good, Lord, to be here, Thy beauty to behold Where Moses and Elijah stand, Thy messengers of old.", "Fulfiller of the past, Promise of things to be, We hail Thy body glorified And our redemption see.", "Before we taste of death, We see Thy Kingdom come; We fain would hold the vision bright And make this hill our home.", "'Tis good, Lord, to be here. Yet we may not remain; But since Thou bidst us leave the mount, Come with us to the plain."], "scriptureLinks": [{"label": "Mk 9:2-13", "chapterId": "MRK-9", "verseNumber": 2}, {"label": "Mt 17:1-13", "chapterId": "MAT-17", "verseNumber": 1}, {"label": "Lk 9:28-36", "chapterId": "LUK-9", "verseNumber": 28}], "musicCredit": "'Potsdam' adapted from Johann Sebastian Bach, 1750, by John Goss, 1854", "number": 310}, {"title": "To Shepherds As They Watched By Night", "sectionId": 8, "wordsCredit": "Martin Luther, 1543. translated by Richard Massie, 1854", "verses": ["To shepherds as they watched by night Appeared a host of angels bright; Behold the tender Babe, they said, In yonder lowly manger laid.", "At Bethlehem, in David's town, As Micah did of old make known; 'Tis Jesus Christ, your Lord and King, Who doth to all salvation bring.", "Oh, then rejoice that through His Son God is with sinners now at one; Made like yourselves of flesh and blood, Your Brother is th'eternal God.", "What harm can sin and death then do? The true God now abides with you. Let hell and Satan rage and chafe, Christ is your Brother ye are safe.", "Not one He will or can forsake Who Him his confidence doth make. Let all his wiles the Tempter try, You may his utmost pow'rs defy.", "Ye shall and must at last prevail; God's own ye are, ye cannot fail. To God forever sing your praise With joy and patience all your days."], "scriptureLinks": [{"label": "Is 9:2", "chapterId": "ISA-9", "verseNumber": 2}, {"label": "Lk 2:8-15", "chapterId": "LUK-2", "verseNumber": 8}, {"label": "Mic 5:2", "chapterId": "MIC-5", "verseNumber": 2}], "musicCredit": "'Vom Himmel Hoch' traditional German from Schumann's Geistliche Lieder, Leipzig, 1539", "number": 311}, {"title": "Under His Wings", "sectionId": 8, "wordsCredit": "William Orcutt Cushing, 1896", "verses": ["Under His wings I am safely abiding, Though the night deepens and tempests are wild, Still I can trust Him; I know He will keep me, He has redeemed me, and I am His child.", "Under His wings, what a refuge in sorrow! How the heart yearningly turns to His rest! Often when earth has no balm for my healing, There I find comfort, and there I am blessed.", "Under His wings, oh, what precious enjoyment! There will I hide till life's trials are o'er; Sheltered, protected, no evil can harm me, Resting in Jesus, I'm safe evermore."], "scriptureLinks": [{"label": "Ps 17:7-9", "chapterId": "PSA-17", "verseNumber": 7}, {"label": "Mt 11:28", "chapterId": "MAT-11", "verseNumber": 28}], "musicCredit": "'Under His Wings' Ira David Sankey, 1898", "refrain": "Under His wings, under His wings, Who from His love can sever? Under His wings my soul shall abide, Safely abide forever.", "number": 312}, {"title": "What Child Is This?", "sectionId": 8, "wordsCredit": "William Chatterton Dix, 1865", "verses": ["What Child is this who, laid to rest On Mary's lap is sleeping? Whom angels greet with anthems sweet, While shepherds watch are keeping? This, this is Christ the King, Whom shepherds guard and angels sing; Haste, haste, to bring Him laud, The Babe, the Son of Mary.", "Why lies He in such mean estate, Where ox and ass are feeding? Good Christians, fear, for sinners here The silent Word is pleading. Nails, spear shall pierce Him through, The cross be borne for me, for you. Hail, hail the Word made flesh, The Babe, the Son of Mary.", "So bring Him incense, gold and myrrh, Come peasant, king to own Him; The King of kings salvation brings, Let loving hearts enthrone Him. Raise, raise a song on high, The virgin sings her lullaby. Joy, joy for Christ is born, The Babe, the Son of Mary."], "scriptureLinks": [{"label": "Lk 2:7", "chapterId": "LUK-2", "verseNumber": 7}, {"label": "Mt 2:1-11", "chapterId": "MAT-2", "verseNumber": 1}, {"label": "Phil 2:5-8", "chapterId": "PHP-2", "verseNumber": 5}], "musicCredit": "'Greensleeves' 16th Century English Traditional", "number": 313}];
